var QUESTIONS = [{"id":"A-01-01","isl":"A","lv":1,"stem":"最早提出「物質由不可再分割的原子組成」的科學家是誰？","A":"湯姆森","B":"拉塞福","C":"道耳頓","D":"門得列夫","answer":"C","explanation":"道耳頓提出原子說，認為原子不可再分割，同種元素的原子質量與性質相同。","image":""},{"id":"A-01-02","isl":"A","lv":1,"stem":"湯姆森的實驗發現了哪一種粒子？","A":"電子","B":"質子","C":"中子","D":"原子核","answer":"A","explanation":"湯姆森發現帶負電的電子，證明原子還可以再分，並提出葡萄乾布丁模型。","image":""},{"id":"A-01-03","isl":"A","lv":2,"stem":"拉塞福用 α 粒子撞擊金箔，大部分 α 粒子直接穿過。這個結果說明了什麼？","A":"原子核帶負電","B":"原子內部大部分是空的","C":"電子的質量很大","D":"原子是實心的小球","answer":"B","explanation":"大部分 α 粒子沒有碰到東西就穿過去，表示原子內部大部分是空的。","image":""},{"id":"A-01-04","isl":"A","lv":2,"stem":"同一個實驗中，少數 α 粒子以很大的角度反彈。由此可推論出什麼？","A":"金箔表面凹凸不平","B":"電子分布在原子核裡面","C":"原子中心有體積小、質量大、帶正電的原子核","D":"原子整體帶負電","answer":"C","explanation":"帶正電的 α 粒子被強烈彈回，表示碰到了體積很小、集中大部分質量且帶正電的原子核。","image":""},{"id":"A-01-05","isl":"A","lv":3,"stem":"某原子有 8 個質子和 8 個中子，這個原子有幾個電子？","A":"0 個","B":"4 個","C":"16 個","D":"8 個","answer":"D","explanation":"原子不帶電，所以電子數等於質子數，是 8 個。中子不帶電，不影響電子數。","image":""},{"id":"A-02-01","isl":"A","lv":1,"stem":"目前原子量是以哪一種原子的質量定為 12 作為比較標準？","A":"碳-12","B":"氫-1","C":"氧-16","D":"氮-14","answer":"A","explanation":"國際上以碳-12 原子的質量定為 12，其他原子和它比較，得到原子量。","image":""},{"id":"A-02-02","isl":"A","lv":1,"stem":"原子量的單位是什麼？","A":"公克","B":"毫克","C":"沒有單位","D":"公斤","answer":"C","explanation":"原子量是和碳-12 比較出來的相對質量，所以沒有單位。","image":""},{"id":"A-02-03","isl":"A","lv":2,"stem":"已知原子量 H＝1、O＝16，水（H₂O）的分子量是多少？","A":"17","B":"18","C":"32","D":"34","answer":"B","explanation":"H₂O 有 2 個氫和 1 個氧：1×2＋16＝18。","image":""},{"id":"A-02-04","isl":"A","lv":2,"stem":"已知原子量 C＝12、O＝16，二氧化碳（CO₂）的分子量是多少？","A":"28","B":"40","C":"56","D":"44","answer":"D","explanation":"CO₂ 有 1 個碳和 2 個氧：12＋16×2＝44。","image":""},{"id":"A-02-05","isl":"A","lv":3,"stem":"已知原子量 H＝1、O＝16。1 個氧原子的質量大約是 1 個氫原子的幾倍？","A":"16 倍","B":"8 倍","C":"32 倍","D":"1/16 倍","answer":"A","explanation":"原子量代表相對質量，16 ÷ 1＝16，所以氧原子約是氫原子的 16 倍重。","image":""},{"id":"A-03-01","isl":"A","lv":1,"stem":"下列哪一種物質是元素？","A":"水","B":"二氧化碳","C":"氧氣","D":"食鹽","answer":"C","explanation":"氧氣（O₂）只由氧原子組成，是元素；其他三種都由兩種以上元素組成，是化合物。","image":""},{"id":"A-03-02","isl":"A","lv":1,"stem":"下列哪一種物質是化合物？","A":"銅","B":"水","C":"氮氣","D":"鑽石","answer":"B","explanation":"水由氫和氧兩種元素組成，是化合物。鑽石只由碳原子組成，是元素。","image":""},{"id":"A-03-03","isl":"A","lv":2,"stem":"把水電解，會得到哪兩種物質？","A":"氧氣和水蒸氣","B":"氫氣和二氧化碳","C":"氮氣和氧氣","D":"氫氣和氧氣","answer":"D","explanation":"水是由氫和氧組成的化合物，電解（化學方法）可分解成氫氣和氧氣。","image":""},{"id":"A-03-04","isl":"A","lv":2,"stem":"鈉是活潑金屬，氯是有毒氣體，兩者化合成食鹽。食鹽的性質如何？","A":"和鈉、氯的性質都不同","B":"同時有鈉和氯的性質","C":"和鈉相同","D":"和氯相同","answer":"A","explanation":"化合物是全新的物質，性質和組成它的元素不同，所以食鹽可以安全食用。","image":""},{"id":"A-03-05","isl":"A","lv":3,"stem":"關於化合物的敘述，下列何者正確？","A":"可以用過濾等物理方法分離成元素","B":"只由一種原子組成","C":"組成元素之間有固定的比例","D":"沒有固定的性質","answer":"C","explanation":"化合物由兩種以上元素依固定比例化合而成，有固定性質，要用化學方法才能分解。","image":""},{"id":"A-04-01","isl":"A","lv":1,"stem":"現代週期表是依照什麼順序排列元素？","A":"原子量","B":"原子序（質子數）","C":"發現年代","D":"英文字母","answer":"B","explanation":"門得列夫最早依原子量排列，現代週期表改依原子序（質子數）由小到大排列。","image":""},{"id":"A-04-02","isl":"A","lv":1,"stem":"週期表中的「直行」稱為什麼？","A":"週期","B":"層","C":"族","D":"列","answer":"C","explanation":"直行稱為族，橫列稱為週期。","image":""},{"id":"A-04-03","isl":"A","lv":2,"stem":"同一族的元素有什麼共同特色？","A":"原子量相同","B":"在室溫下都是氣體","C":"質子數相同","D":"化學性質相似","answer":"D","explanation":"同族元素的化學性質相似，例如鹼金屬都會和水劇烈反應。","image":""},{"id":"A-04-04","isl":"A","lv":2,"stem":"下列哪一組元素都屬於鹼金屬？","A":"鋰、鈉、鉀","B":"氦、氖、氬","C":"氧、硫","D":"鐵、銅","answer":"A","explanation":"週期表最左一行（氫除外）是鹼金屬，包括鋰、鈉、鉀。氦、氖、氬是惰性氣體。","image":""},{"id":"A-04-05","isl":"A","lv":3,"stem":"霓虹燈裡的氖位在週期表最右一行，這一行元素的性質為何？","A":"非常活潑，容易燃燒","B":"都是金屬","C":"性質穩定，不容易和其他物質反應","D":"會和水劇烈反應","answer":"C","explanation":"最右一行是惰性氣體（鈍氣），性質穩定，所以常用在霓虹燈、氣球等用途。","image":""},{"id":"A-05-01","isl":"A","lv":1,"stem":"鈉的元素符號寫法，下列何者正確？","A":"NA","B":"Na","C":"na","D":"nA","answer":"B","explanation":"元素符號第一個字母大寫，第二個字母小寫，鈉寫成 Na。","image":""},{"id":"A-05-02","isl":"A","lv":1,"stem":"化學式 H₂O 代表一個水分子中有什麼？","A":"2 個水分子","B":"1 個氫原子和 2 個氧原子","C":"2 個氫原子和 1 個氧原子","D":"2 個氫原子和 2 個氧原子","answer":"C","explanation":"右下角的數字代表前面原子的個數，沒寫數字代表 1 個，所以是 2 個氫、1 個氧。","image":""},{"id":"A-05-03","isl":"A","lv":2,"stem":"3CO₂ 中總共有幾個氧原子？","A":"2 個","B":"3 個","C":"5 個","D":"6 個","answer":"D","explanation":"前面的 3 代表 3 個分子，每個 CO₂ 有 2 個氧原子，3×2＝6 個。","image":""},{"id":"A-05-04","isl":"A","lv":2,"stem":"關於 CO 和 Co，下列敘述何者正確？","A":"CO 是一氧化碳（化合物），Co 是鈷（元素）","B":"兩者是同一種物質","C":"CO 是元素","D":"Co 是化合物","answer":"A","explanation":"CO 是兩個大寫字母，代表 C 和 O 兩種元素組成的一氧化碳；Co 是一個元素符號，代表鈷。","image":""},{"id":"A-05-05","isl":"A","lv":3,"stem":"二氧化碳的化學式，下列寫法何者正確？","A":"Co₂","B":"co₂","C":"CO₂","D":"C₂O","answer":"C","explanation":"二氧化碳由 1 個碳和 2 個氧組成，C、O 都是大寫，2 寫在 O 的右下角：CO₂。","image":""},{"id":"A-06-01","isl":"A","lv":1,"stem":"有固定體積、但沒有固定形狀的是哪一種狀態？","A":"固態","B":"液態","C":"氣態","D":"三種都是","answer":"B","explanation":"液態粒子可以互相滑動，所以形狀隨容器改變，但體積固定。","image":""},{"id":"A-06-02","isl":"A","lv":1,"stem":"粒子排列最緊密、只能在原位置振動的是哪一種狀態？","A":"氣態","B":"液態","C":"固態","D":"三態都一樣","answer":"C","explanation":"固態粒子排列緊密有規則，只能在原位置振動，所以有固定形狀和體積。","image":""},{"id":"A-06-03","isl":"A","lv":2,"stem":"堵住注射筒出口推活塞，裡面的空氣可以被壓縮，原因是什麼？","A":"氣體粒子之間的距離很大","B":"氣體粒子會變小","C":"氣體粒子會消失","D":"氣體沒有質量","answer":"A","explanation":"氣體粒子間空隙很大，加壓時粒子靠近，體積就變小。粒子本身大小不變。","image":""},{"id":"A-06-04","isl":"A","lv":2,"stem":"在教室前面打開香水瓶，後面的同學過一會兒也聞得到，主要說明了什麼？","A":"香水是固體","B":"粒子會變大","C":"粒子是靜止的","D":"粒子不停地運動","answer":"D","explanation":"香水的氣體粒子不停運動，會擴散到整個教室。","image":""},{"id":"A-06-05","isl":"A","lv":3,"stem":"冰熔化成水時，水分子發生了什麼變化？","A":"分子變大了","B":"分子本身不變，改變的是分子間距離和運動方式","C":"變成另一種分子","D":"分子數目變多了","answer":"B","explanation":"狀態改變是物理變化，分子本身和數目都不變，改變的是排列、間距和運動方式。","image":""},{"id":"A-07-01","isl":"A","lv":1,"stem":"冬天浴室鏡子起霧，是水蒸氣變成小水滴，這個過程稱為什麼？","A":"熔化","B":"凝固","C":"汽化","D":"凝結","answer":"D","explanation":"氣態變成液態稱為凝結。","image":""},{"id":"A-07-02","isl":"A","lv":1,"stem":"衣櫃裡的樟腦丸放久了會變小，主要是發生了哪一種變化？","A":"昇華","B":"熔化","C":"凝結","D":"凝固","answer":"A","explanation":"樟腦丸由固態直接變成氣態，這個過程稱為昇華。","image":""},{"id":"A-07-03","isl":"A","lv":2,"stem":"在一大氣壓下，水沸騰後繼續用大火加熱，水溫會怎樣？","A":"持續上升","B":"慢慢下降","C":"維持在 100 °C","D":"先上升再下降","answer":"C","explanation":"沸騰時吸收的熱用來讓水變成水蒸氣，溫度維持在沸點 100 °C。","image":""},{"id":"A-07-04","isl":"A","lv":2,"stem":"關於蒸發和沸騰的比較，下列何者正確？","A":"蒸發只在 100 °C 發生","B":"沸騰只在液體表面發生","C":"兩者完全相同","D":"蒸發在任何溫度都能發生，而且只在液體表面","answer":"D","explanation":"蒸發在任何溫度、液體表面進行；沸騰在沸點、液體內部和表面同時進行。","image":""},{"id":"A-07-05","isl":"A","lv":3,"stem":"一大氣壓下，一杯冰水混合物持續加熱，在冰還沒完全熔化之前，溫度會保持在多少？","A":"4 °C","B":"0 °C","C":"100 °C","D":"持續上升","answer":"B","explanation":"冰熔化時溫度維持在熔點 0 °C，吸收的熱用來熔化冰，冰全部熔化後溫度才會上升。","image":""},{"id":"A-08-01","isl":"A","lv":1,"stem":"下列哪一項屬於化學性質？","A":"顏色","B":"密度","C":"可燃性","D":"熔點","answer":"C","explanation":"可燃性要經過燃燒（化學變化）才能表現，是化學性質；其他三項不改變物質就能觀察。","image":""},{"id":"A-08-02","isl":"A","lv":1,"stem":"下列哪一項屬於化學變化？","A":"鐵生鏽","B":"冰熔化","C":"糖溶於水","D":"玻璃破碎","answer":"A","explanation":"鐵生鏽產生了新物質（鐵鏽），是化學變化；其他三項都沒有新物質產生。","image":""},{"id":"A-08-03","isl":"A","lv":2,"stem":"點燃蠟燭時，下列哪一個過程屬於物理變化？","A":"燭芯燃燒","B":"產生二氧化碳","C":"產生水","D":"蠟受熱熔化成蠟油","answer":"D","explanation":"蠟熔化後還是蠟，沒有新物質產生，是物理變化；燃燒產生二氧化碳和水是化學變化。","image":""},{"id":"A-08-04","isl":"A","lv":2,"stem":"判斷一個變化是不是化學變化，最主要的依據是什麼？","A":"有沒有顏色改變","B":"有沒有新物質產生","C":"有沒有冒泡","D":"有沒有發熱","answer":"B","explanation":"顏色、冒泡、發熱只是線索，例如水沸騰也冒泡；關鍵是有沒有產生新物質。","image":""},{"id":"A-08-05","isl":"A","lv":3,"stem":"下列哪一項描述的是物理性質？","A":"鐵在潮濕空氣中會生鏽","B":"氧氣可以幫助燃燒","C":"銅可以導電","D":"木材可以燃燒","answer":"C","explanation":"導電性不需改變銅本身就能測得，是物理性質；生鏽、助燃、可燃都要經過化學變化才表現。","image":""},{"id":"A-09-01","isl":"A","lv":1,"stem":"下列哪一種是混合物？","A":"蒸餾水","B":"空氣","C":"氧氣","D":"二氧化碳","answer":"B","explanation":"空氣含有氮氣、氧氣、二氧化碳等多種物質，組成不固定，是混合物。","image":""},{"id":"A-09-02","isl":"A","lv":1,"stem":"要把泥沙從泥沙水中分離出來，最適合用哪一種方法？","A":"過濾","B":"蒸餾","C":"層析","D":"磁鐵吸引","answer":"A","explanation":"泥沙不溶於水，用濾紙過濾就能把泥沙留在濾紙上。","image":""},{"id":"A-09-03","isl":"A","lv":2,"stem":"要從海水中得到純水，最適合用哪一種方法？","A":"過濾","B":"層析","C":"磁鐵吸引","D":"蒸餾","answer":"D","explanation":"鹽溶在水裡，過濾無法分開。蒸餾讓水汽化再冷凝收集，鹽留在原燒瓶中。","image":""},{"id":"A-09-04","isl":"A","lv":2,"stem":"要分離黑色簽字筆墨水中的各種色素，最適合用哪一種方法？","A":"過濾","B":"蒸發","C":"層析","D":"磁鐵吸引","answer":"C","explanation":"不同色素在濾紙上隨溶劑移動的速度不同，會分成不同顏色的色帶，這是層析法。","image":""},{"id":"A-09-05","isl":"A","lv":3,"stem":"糖水看起來均勻透明，它屬於哪一類物質？理由是什麼？","A":"純物質，因為看起來均勻","B":"化合物，因為糖和水化合了","C":"元素，因為只有一種顏色","D":"混合物，因為糖和水的比例不固定","answer":"D","explanation":"糖水中糖和水各自保有原性質，比例可以任意改變，組成不固定，所以是混合物。外觀均勻不能用來判斷。","image":""},{"id":"A-21-01","isl":"A","lv":1,"stem":"原子的質量幾乎都集中在哪裡？","A":"電子","B":"原子核","C":"電子雲","D":"核外空間","answer":"B","explanation":"原子核含有質子和中子，質量大；電子的質量很小，可以忽略。","image":""},{"id":"A-21-02","isl":"A","lv":1,"stem":"質量數等於哪兩種粒子數目的和？","A":"質子數加電子數","B":"中子數加電子數","C":"質子數加中子數","D":"質子數減中子數","answer":"C","explanation":"質量數＝質子數＋中子數。","image":""},{"id":"A-21-03","isl":"A","lv":2,"stem":"某原子有 11 個質子、12 個中子，質量數是多少？","A":"11","B":"34","C":"12","D":"23","answer":"D","explanation":"質量數＝11＋12＝23。","image":""},{"id":"A-21-04","isl":"A","lv":2,"stem":"某原子的原子序為 17，質量數為 35，中子數是多少？","A":"52","B":"35","C":"17","D":"18","answer":"D","explanation":"中子數＝質量數－質子數＝35－17＝18。","image":""},{"id":"A-21-05","isl":"A","lv":3,"stem":"某原子不帶電，有 9 個電子、10 個中子，質量數是多少？","A":"10","B":"28","C":"19","D":"9","answer":"C","explanation":"不帶電表示質子數＝電子數＝9，質量數＝9＋10＝19。","image":""},{"id":"A-22-01","isl":"A","lv":1,"stem":"同位素是質子數相同，但哪一項不同的原子？","A":"電子數","B":"元素符號","C":"原子序","D":"中子數","answer":"D","explanation":"同位素的質子數（原子序）相同，中子數不同，所以質量數不同。","image":""},{"id":"A-22-02","isl":"A","lv":1,"stem":"氫的三種同位素（氕、氘、氚），質子數各是多少？","A":"都是 2","B":"都是 3","C":"都是 1","D":"分別是 1、2、3","answer":"C","explanation":"同位素的質子數相同，氫的質子數都是 1，差別只在中子數。","image":""},{"id":"A-22-03","isl":"A","lv":2,"stem":"碳-12 與碳-14 的差別在於？","A":"質子數不同","B":"電子數不同","C":"中子數不同","D":"元素種類不同","answer":"C","explanation":"兩者都是碳，質子數都是 6，碳-14 多了 2 個中子。","image":""},{"id":"A-22-04","isl":"A","lv":2,"stem":"同位素的化學性質幾乎相同，主要原因是？","A":"中子數相同","B":"原子量相同","C":"電子數相同","D":"質量數相同","answer":"C","explanation":"化學性質由電子決定，同位素的質子數與電子數相同，所以性質相近。","image":""},{"id":"A-22-05","isl":"A","lv":3,"stem":"氯有氯-35 和氯-37 兩種同位素，兩者中子數相差幾個？","A":"2 個","B":"17 個","C":"35 個","D":"1 個","answer":"A","explanation":"質子數都是 17，中子數分別是 18 和 20，相差 2 個。","image":""},{"id":"A-23-01","isl":"A","lv":1,"stem":"原子中的電子分布在原子核外的哪裡？","A":"質子層","B":"中子層","C":"原子核內","D":"電子殼層","answer":"D","explanation":"電子在原子核外一層一層的電子殼層中運動。","image":""},{"id":"A-23-02","isl":"A","lv":1,"stem":"第一層電子殼層最多可容納幾個電子？","A":"4 個","B":"8 個","C":"2 個","D":"18 個","answer":"C","explanation":"第一層最多 2 個，第二層和第三層（國中範圍）最多 8 個。","image":""},{"id":"A-23-03","isl":"A","lv":2,"stem":"鈉（原子序 11）的電子排布由內到外是？","A":"2、9","B":"2、7、2","C":"8、3","D":"2、8、1","answer":"D","explanation":"11 個電子依序填入：第一層 2，第二層 8，第三層 1。","image":""},{"id":"A-23-04","isl":"A","lv":2,"stem":"氯（原子序 17）最外層有幾個電子？","A":"17 個","B":"8 個","C":"5 個","D":"7 個","answer":"D","explanation":"電子排布是 2、8、7，最外層有 7 個電子。","image":""},{"id":"A-23-05","isl":"A","lv":3,"stem":"某原子有 3 層電子殼層且最外層有 8 個電子，它的原子序是？","A":"10","B":"18","C":"16","D":"28","answer":"B","explanation":"電子排布 2、8、8，共 18 個電子，原子序為 18。","image":""},{"id":"A-24-01","isl":"A","lv":1,"stem":"週期表第 1 族（氫除外）的金屬元素稱為？","A":"鹵素","B":"鹼金屬","C":"惰性氣體","D":"過渡金屬","answer":"B","explanation":"鋰、鈉、鉀等第 1 族元素稱為鹼金屬，性質很活潑。","image":""},{"id":"A-24-02","isl":"A","lv":1,"stem":"第 18 族元素又稱惰性氣體，它們的性質是？","A":"非常活潑","B":"容易生鏽","C":"很不活潑","D":"容易導電","answer":"C","explanation":"惰性氣體最外層電子已填滿，很不容易發生反應。","image":""},{"id":"A-24-03","isl":"A","lv":2,"stem":"氟、氯、溴、碘屬於同一族，這一族稱為？","A":"鹵素","B":"惰性氣體","C":"鹼土金屬","D":"鹼金屬","answer":"A","explanation":"第 17 族元素稱為鹵素，最外層有 7 個電子。","image":""},{"id":"A-24-04","isl":"A","lv":2,"stem":"同一族的元素化學性質相似，主要是因為？","A":"質子數相同","B":"中子數相同","C":"原子量相同","D":"最外層電子數相同","answer":"D","explanation":"化學性質主要由最外層電子數決定，同族元素最外層電子數相同。","image":""},{"id":"A-24-05","isl":"A","lv":3,"stem":"某元素有 3 層電子殼層，最外層有 2 個電子，位於週期表的？","A":"第 3 週期第 2 族","B":"第 3 週期第 3 族","C":"第 2 週期第 3 族","D":"第 2 週期第 2 族","answer":"A","explanation":"電子殼層數等於週期數，最外層電子數等於族數（主族），所以是第 3 週期第 2 族。","image":""},{"id":"A-25-01","isl":"A","lv":1,"stem":"原子失去電子後，會變成帶什麼電的離子？","A":"正電","B":"不帶電","C":"負電","D":"電性不變","answer":"A","explanation":"失去帶負電的電子，質子比電子多，所以帶正電，稱為陽離子。","image":""},{"id":"A-25-02","isl":"A","lv":1,"stem":"原子得到電子後形成的離子稱為？","A":"同位素","B":"陽離子","C":"分子","D":"陰離子","answer":"D","explanation":"得到電子的原子帶負電，稱為陰離子。","image":""},{"id":"A-25-03","isl":"A","lv":2,"stem":"鈉原子變成鈉離子（Na⁺），是因為？","A":"失去 1 個電子","B":"得到 1 個電子","C":"失去 1 個質子","D":"得到 1 個中子","answer":"A","explanation":"Na⁺ 帶 1 個正電，表示鈉原子失去了 1 個電子。","image":""},{"id":"A-25-04","isl":"A","lv":2,"stem":"食鹽（氯化鈉）是由什麼粒子組成的？","A":"氯化鈉分子","B":"鈉原子與氯原子","C":"鈉離子與氯離子","D":"鈉分子與氯分子","answer":"C","explanation":"氯化鈉是離子化合物，由 Na⁺ 和 Cl⁻ 以離子鍵結合。","image":""},{"id":"A-25-05","isl":"A","lv":3,"stem":"固態氯化鈉不導電，溶於水後卻能導電，原因是？","A":"分子變成原子","B":"離子能自由移動","C":"產生大量電子","D":"變成了金屬","answer":"B","explanation":"溶於水後 Na⁺ 和 Cl⁻ 可以自由移動，因此能導電。","image":""},{"id":"A-26-01","isl":"A","lv":1,"stem":"水的化學式是？","A":"H₂O","B":"H₂O₂","C":"OH","D":"HO₂","answer":"A","explanation":"1 個水分子由 2 個氫原子和 1 個氧原子組成。","image":""},{"id":"A-26-02","isl":"A","lv":1,"stem":"二氧化碳的化學式是？","A":"CO₃","B":"CO₂","C":"CO","D":"C₂O","answer":"B","explanation":"二氧化碳由 1 個碳原子和 2 個氧原子組成。","image":""},{"id":"A-26-03","isl":"A","lv":2,"stem":"氯化鈉（NaCl）中，鈉離子與氯離子的個數比是？","A":"2：1","B":"2：3","C":"1：2","D":"1：1","answer":"D","explanation":"Na⁺ 和 Cl⁻ 各帶 1 個電荷，個數比 1：1 時電荷剛好平衡。","image":""},{"id":"A-26-04","isl":"A","lv":2,"stem":"氧化鎂的化學式是 MgO，個數比是 1：1，是因為？","A":"氧比鎂活潑","B":"正負電荷剛好平衡","C":"鎂比氧重","D":"鎂有兩層電子","answer":"B","explanation":"Mg²⁺ 與 O²⁻ 電荷數相同，1：1 就能使整體不帶電。","image":""},{"id":"A-26-05","isl":"A","lv":3,"stem":"Al³⁺ 與 O²⁻ 形成的化合物，化學式是？","A":"AlO","B":"AlO₃","C":"Al₂O₃","D":"Al₃O₂","answer":"C","explanation":"2 個 Al³⁺ 共 +6，3 個 O²⁻ 共 －6，電荷平衡，所以是 Al₂O₃。","image":""},{"id":"A-27-01","isl":"A","lv":1,"stem":"密度的定義是？","A":"重量除以質量","B":"單位質量的體積","C":"單位體積的質量","D":"質量乘以體積","answer":"C","explanation":"密度＝質量÷體積。","image":""},{"id":"A-27-02","isl":"A","lv":1,"stem":"密度常用的單位是？","A":"g·cm³","B":"kg·m","C":"cm³/g","D":"g/cm³","answer":"D","explanation":"密度是質量除以體積，常用 g/cm³。","image":""},{"id":"A-27-03","isl":"A","lv":2,"stem":"某金屬塊質量 54 g、體積 20 cm³，密度是多少？","A":"0.37 g/cm³","B":"74 g/cm³","C":"2.7 g/cm³","D":"1080 g/cm³","answer":"C","explanation":"密度＝54÷20＝2.7 g/cm³。","image":""},{"id":"A-27-04","isl":"A","lv":2,"stem":"水的密度約 1 g/cm³，密度比水小又不溶於水的物體放入水中會？","A":"沉到水底","B":"一定懸浮","C":"溶解","D":"浮在水面","answer":"D","explanation":"密度比水小，浮力大於重力，會浮在水面。","image":""},{"id":"A-27-05","isl":"A","lv":3,"stem":"把一塊鐵切成兩半，其中一半的密度與原來相比？","A":"變為零","B":"不變","C":"變成兩倍","D":"變成一半","answer":"B","explanation":"密度是物質的特性，與大小、形狀無關，切開後不變。","image":""},{"id":"A-28-01","isl":"A","lv":1,"stem":"純水在一大氣壓下的沸點是？","A":"100℃","B":"0℃","C":"50℃","D":"4℃","answer":"A","explanation":"水在一大氣壓下 100℃ 沸騰。","image":""},{"id":"A-28-02","isl":"A","lv":1,"stem":"固體受熱開始變成液體時的溫度稱為？","A":"沸點","B":"燃點","C":"露點","D":"熔點","answer":"D","explanation":"固體變成液體的溫度是熔點。","image":""},{"id":"A-28-03","isl":"A","lv":2,"stem":"純物質在熔化的過程中，溫度會？","A":"持續上升","B":"持續下降","C":"保持不變","D":"忽高忽低","answer":"C","explanation":"純物質熔化時吸收的熱用來改變狀態，溫度維持在熔點。","image":""},{"id":"A-28-04","isl":"A","lv":2,"stem":"同一種純物質，樣品的多寡會影響它的熔點嗎？","A":"無法判斷","B":"不影響","C":"樣品越多越高","D":"樣品越少越高","answer":"B","explanation":"熔點是物質的特性，與量的多少無關。","image":""},{"id":"A-28-05","isl":"A","lv":3,"stem":"某物質熔點 －10℃、沸點 80℃，在 25℃ 時是什麼狀態？","A":"氣態","B":"固態","C":"固液共存","D":"液態","answer":"D","explanation":"25℃ 高於熔點、低於沸點，所以是液態。","image":""},{"id":"A-29-01","isl":"A","lv":1,"stem":"把糖溶入水中，被溶解的糖稱為？","A":"溶劑","B":"溶質","C":"結晶","D":"沉澱物","answer":"B","explanation":"被溶解的物質是溶質，用來溶解的是溶劑。","image":""},{"id":"A-29-02","isl":"A","lv":1,"stem":"糖水中的「水」稱為？","A":"結晶","B":"溶劑","C":"溶質","D":"沉澱物","answer":"B","explanation":"能溶解其他物質的稱為溶劑。","image":""},{"id":"A-29-03","isl":"A","lv":2,"stem":"重量百分濃度的計算式是？","A":"溶劑重÷溶液重×100%","B":"溶質重÷溶液重×100%","C":"溶液重÷溶質重×100%","D":"溶質重÷溶劑重×100%","answer":"B","explanation":"重量百分濃度＝溶質重÷溶液重×100%，溶液重＝溶質重＋溶劑重。","image":""},{"id":"A-29-04","isl":"A","lv":2,"stem":"20 g 食鹽溶於 80 g 水，重量百分濃度是多少？","A":"20%","B":"12.5%","C":"25%","D":"80%","answer":"A","explanation":"溶液重 100 g，20÷100×100%＝20%。","image":""},{"id":"A-29-05","isl":"A","lv":3,"stem":"要配製 10% 的食鹽水 200 g，需要食鹽多少 g？","A":"180 g","B":"2 g","C":"10 g","D":"20 g","answer":"D","explanation":"溶質重＝200×10%＝20 g。","image":""},{"id":"A-30-01","isl":"A","lv":1,"stem":"提出「原子像葡萄乾布丁，電子散布在帶正電球體中」的科學家是？","A":"門得列夫","B":"道耳頓","C":"拉塞福","D":"湯姆森","answer":"D","explanation":"湯姆森發現電子後，提出電子嵌在正電球體中的葡萄乾布丁模型。","image":""},{"id":"A-30-02","isl":"A","lv":1,"stem":"拉塞福的原子模型，認為電子像什麼一樣繞著原子核運動？","A":"行星繞太陽","B":"彈簧來回振動","C":"葡萄乾嵌布丁","D":"硬球靜止不動","answer":"A","explanation":"拉塞福模型類似行星繞太陽，原子核在中心，電子在外圍運動。","image":""},{"id":"A-30-03","isl":"A","lv":2,"stem":"拉塞福推翻湯姆森的模型，主要根據的實驗是？","A":"過濾泥沙實驗","B":"α 粒子撞擊金箔","C":"燃燒蠟燭實驗","D":"電解水實驗","answer":"B","explanation":"α 粒子撞擊金箔的結果，顯示原子中心有小而重的原子核。","image":""},{"id":"A-30-04","isl":"A","lv":2,"stem":"道耳頓原子說中，下列哪一項後來被證明不完全正確？","A":"化學反應是原子重新組合","B":"不同元素的原子性質不同","C":"原子不可再分割","D":"原子不會在反應中消失","answer":"C","explanation":"後來發現原子可再分為質子、中子與電子，所以原子不是不可分割。","image":""},{"id":"A-30-05","isl":"A","lv":3,"stem":"依據金箔實驗的結果，下列哪一項推論正確？","A":"原子大部分是空的","B":"原子是實心均勻球","C":"電子集中在中心","D":"原子核占原子大部分體積","answer":"A","explanation":"大部分 α 粒子穿過，表示原子內部大多是空的，核很小。","image":""},{"id":"A-31-01","isl":"A","lv":1,"stem":"質子帶有哪一種電性？","A":"負電","B":"不帶電","C":"正電","D":"時正時負","answer":"C","explanation":"質子帶正電，電子帶負電，中子不帶電。","image":""},{"id":"A-31-02","isl":"A","lv":1,"stem":"原子核由哪些粒子組成？","A":"中子和電子","B":"質子和中子","C":"質子和電子","D":"只有質子","answer":"B","explanation":"原子核由帶正電的質子與不帶電的中子組成。","image":""},{"id":"A-31-03","isl":"A","lv":2,"stem":"一般原子呈電中性，是因為？","A":"原子核不帶電","B":"中子數等於質子數","C":"質子數等於電子數","D":"電子數等於中子數","answer":"C","explanation":"質子的正電與電子的負電數量相等，電性互相抵消。","image":""},{"id":"A-31-04","isl":"A","lv":2,"stem":"下列哪一種粒子的質量最小？","A":"電子","B":"中子","C":"質子","D":"原子核","answer":"A","explanation":"電子的質量只有質子的千分之一左右，比質子、中子小得多。","image":""},{"id":"A-31-05","isl":"A","lv":3,"stem":"某離子帶 2+ 電荷，且有 10 個電子，它的質子數是多少？","A":"12","B":"10","C":"14","D":"8","answer":"A","explanation":"帶 2+ 表示質子比電子多 2 個，所以質子數為 10＋2＝12。","image":""},{"id":"A-32-01","isl":"A","lv":1,"stem":"原子的質量非常小，科學家用什麼來方便比較？","A":"相對質量","B":"密度","C":"顏色","D":"體積","answer":"A","explanation":"用某種原子當標準，比較各原子的相對質量，這就是原子量。","image":""},{"id":"A-32-02","isl":"A","lv":1,"stem":"以碳-12 為標準，它的原子量定為多少？","A":"1","B":"12","C":"24","D":"6","answer":"B","explanation":"碳-12 的原子量定為 12，其他原子的質量與它比較。","image":""},{"id":"A-32-03","isl":"A","lv":2,"stem":"已知原子量 H＝1、C＝12，甲烷（CH₄）的分子量是多少？","A":"13","B":"12","C":"28","D":"16","answer":"D","explanation":"12＋1×4＝16。","image":""},{"id":"A-32-04","isl":"A","lv":2,"stem":"已知原子量 N＝14、H＝1，氨（NH₃）的分子量是多少？","A":"17","B":"14","C":"18","D":"15","answer":"A","explanation":"14＋1×3＝17。","image":""},{"id":"A-32-05","isl":"A","lv":3,"stem":"已知原子量 Mg＝24、O＝16，氧化鎂（MgO）中鎂與氧的質量比是？","A":"3：2","B":"2：3","C":"3：4","D":"1：1","answer":"A","explanation":"鎂與氧原子數比 1：1，質量比為 24：16＝3：2。","image":""},{"id":"A-33-01","isl":"A","lv":1,"stem":"分子量是分子中所有原子的什麼總和？","A":"電子數","B":"原子序","C":"質子數","D":"原子量","answer":"D","explanation":"分子量就是組成分子的各原子的原子量加起來。","image":""},{"id":"A-33-02","isl":"A","lv":1,"stem":"已知原子量 O＝16，氧氣（O₂）的分子量是多少？","A":"32","B":"16","C":"8","D":"48","answer":"A","explanation":"16×2＝32。","image":""},{"id":"A-33-03","isl":"A","lv":2,"stem":"已知原子量 H＝1、O＝16，過氧化氫（H₂O₂）的分子量是？","A":"32","B":"17","C":"18","D":"34","answer":"D","explanation":"1×2＋16×2＝34。","image":""},{"id":"A-33-04","isl":"A","lv":2,"stem":"已知原子量 Ca＝40、C＝12、O＝16，碳酸鈣（CaCO₃）的式量是？","A":"84","B":"68","C":"100","D":"72","answer":"C","explanation":"40＋12＋16×3＝100。","image":""},{"id":"A-33-05","isl":"A","lv":3,"stem":"水（H₂O）中，氫與氧的質量比是多少？","A":"1：2","B":"1：16","C":"2：1","D":"1：8","answer":"D","explanation":"氫的質量為 1×2＝2，氧為 16，質量比 2：16＝1：8。","image":""},{"id":"A-34-01","isl":"A","lv":1,"stem":"下列哪一種元素是金屬？","A":"硫","B":"氧","C":"碳","D":"鐵","answer":"D","explanation":"鐵具有金屬光澤，能導電導熱，是金屬元素。","image":""},{"id":"A-34-02","isl":"A","lv":1,"stem":"下列哪一種金屬在常溫下是液態？","A":"鋁","B":"鈉","C":"溴","D":"汞","answer":"D","explanation":"汞（水銀）是常溫下唯一的液態金屬；溴雖然也是液態，但屬於非金屬。","image":""},{"id":"A-34-03","isl":"A","lv":2,"stem":"週期表中，金屬元素大多位於哪個位置？","A":"左側與中間","B":"只在最上方","C":"右上角","D":"最右一行","answer":"A","explanation":"週期表左邊與中間大多是金屬，右上方則多為非金屬。","image":""},{"id":"A-34-04","isl":"A","lv":2,"stem":"下列哪一項較符合固態非金屬（如硫）的性質？","A":"能導電導熱","B":"有金屬光澤","C":"質地硬且可延展","D":"質地脆、不易導電","answer":"D","explanation":"非金屬固體通常質地脆，也不容易導電導熱。","image":""},{"id":"A-34-05","isl":"A","lv":3,"stem":"某元素有金屬光澤、能導電、可被敲成薄片，它最可能是？","A":"金屬","B":"化合物","C":"非金屬","D":"惰性氣體","answer":"A","explanation":"這些都是金屬的典型性質：光澤、導電、延展性。","image":""},{"id":"A-35-01","isl":"A","lv":1,"stem":"氧的元素符號是什麼？","A":"Ox","B":"O","C":"Au","D":"Os","answer":"B","explanation":"氧的符號是 O，元素符號第一個字母要大寫。","image":""},{"id":"A-35-02","isl":"A","lv":1,"stem":"鐵的元素符號是什麼？","A":"Fr","B":"Fe","C":"F","D":"Ir","answer":"B","explanation":"鐵的拉丁名是 Ferrum，符號為 Fe。","image":""},{"id":"A-35-03","isl":"A","lv":2,"stem":"元素符號 Ag 代表哪一種元素？","A":"鋁","B":"氬","C":"銀","D":"金","answer":"C","explanation":"Ag 是銀，金是 Au，鋁是 Al，氬是 Ar。","image":""},{"id":"A-35-04","isl":"A","lv":2,"stem":"Cu 和 Ca 分別代表哪兩種元素？","A":"銅、鈷","B":"銅、鈣","C":"鈣、銅","D":"碳、鈣","answer":"B","explanation":"Cu 是銅，Ca 是鈣。","image":""},{"id":"A-35-05","isl":"A","lv":3,"stem":"下列元素名稱與符號配對，何者正確？","A":"鎂—Mn","B":"鋅—Sn","C":"鈉—K","D":"鉀—K","answer":"D","explanation":"鉀是 K，鈉是 Na，鎂是 Mg，鋅是 Zn。","image":""},{"id":"A-36-01","isl":"A","lv":1,"stem":"氨的化學式是什麼？","A":"N₂H","B":"NH₂","C":"N₃H","D":"NH₃","answer":"D","explanation":"1 個氨分子由 1 個氮原子和 3 個氫原子組成。","image":""},{"id":"A-36-02","isl":"A","lv":1,"stem":"甲烷的化學式是什麼？","A":"CH₄","B":"C₂H₆","C":"CO","D":"CH","answer":"A","explanation":"甲烷是天然氣的主要成分，化學式為 CH₄。","image":""},{"id":"A-36-03","isl":"A","lv":2,"stem":"過氧化氫（雙氧水）的化學式是什麼？","A":"HO","B":"H₂O₃","C":"H₂O₂","D":"H₂O","answer":"C","explanation":"過氧化氫比水多 1 個氧原子，化學式為 H₂O₂。","image":""},{"id":"A-36-04","isl":"A","lv":2,"stem":"大理石的主要成分是下列哪一種物質？","A":"小蘇打","B":"食鹽","C":"碳酸鈣","D":"酒精","answer":"C","explanation":"大理石和石灰岩的主要成分是碳酸鈣。","image":""},{"id":"A-36-05","isl":"A","lv":3,"stem":"某分子由 2 個碳原子、6 個氫原子組成，它的化學式是？","A":"C₆H₂","B":"C₂H₆","C":"2C6H","D":"H₂C₆","answer":"B","explanation":"原子數寫在元素符號右下角，碳 2 個氫 6 個，為 C₂H₆。","image":""},{"id":"A-37-01","isl":"A","lv":1,"stem":"週期表中的橫列稱為什麼？","A":"區","B":"週期","C":"層","D":"族","answer":"B","explanation":"橫列叫週期，直行叫族。","image":""},{"id":"A-37-02","isl":"A","lv":1,"stem":"現代週期表共有幾個族？","A":"18","B":"8","C":"7","D":"10","answer":"A","explanation":"現代週期表由左到右共有 18 個族。","image":""},{"id":"A-37-03","isl":"A","lv":2,"stem":"下列哪一項元素的化學性質最相似？","A":"鈉與氯","B":"碳與氧","C":"鈉與鉀","D":"鐵與氖","answer":"C","explanation":"鈉與鉀同在第 1 族，最外層電子數相同，性質相似。","image":""},{"id":"A-37-04","isl":"A","lv":2,"stem":"同一個週期的元素，有什麼共同點？","A":"電子殼層數相同","B":"原子量相同","C":"質子數相同","D":"最外層電子數相同","answer":"A","explanation":"同一週期的原子有相同的電子殼層數。","image":""},{"id":"A-37-05","isl":"A","lv":3,"stem":"某元素原子序是 12，它位於週期表的哪裡？","A":"第 3 週期第 2 族","B":"第 12 週期第 3 族","C":"第 3 週期第 12 族","D":"第 2 週期第 3 族","answer":"A","explanation":"原子序 12 的電子排布為 2、8、2，有 3 層且最外層 2 個電子。","image":""},{"id":"A-38-01","isl":"A","lv":1,"stem":"最早提出週期表的科學家是誰？","A":"牛頓","B":"門得列夫","C":"拉塞福","D":"道耳頓","answer":"B","explanation":"門得列夫在 1869 年整理出元素的週期表。","image":""},{"id":"A-38-02","isl":"A","lv":1,"stem":"門得列夫最早排列元素時，主要依據什麼？","A":"密度大小","B":"元素顏色","C":"原子量大小","D":"發現時間","answer":"C","explanation":"當時還不知道原子序，所以門得列夫依原子量排列並讓性質相似的元素同族。","image":""},{"id":"A-38-03","isl":"A","lv":2,"stem":"現代週期表改成依什麼排列元素？","A":"熔點","B":"發現年代","C":"原子量","D":"原子序","answer":"D","explanation":"科學家發現原子序（質子數）更能反映元素的性質規律。","image":""},{"id":"A-38-04","isl":"A","lv":2,"stem":"門得列夫的週期表有什麼重要貢獻？","A":"證明原子可分","B":"預測未發現的元素","C":"發現電子","D":"發明顯微鏡","answer":"B","explanation":"他在表中留下空位，預測了尚未發現元素的存在與性質。","image":""},{"id":"A-38-05","isl":"A","lv":3,"stem":"後來發現的新元素性質和門得列夫預測吻合，說明了什麼？","A":"元素永遠不會新增","B":"週期表有預測能力","C":"元素可隨意製造","D":"性質與原子序無關","answer":"B","explanation":"預測成功，表示週期表反映了元素性質的規律。","image":""},{"id":"A-39-01","isl":"A","lv":1,"stem":"原子序等於原子的什麼數目？","A":"中子數","B":"質量數","C":"質子數","D":"電子殼層數","answer":"C","explanation":"原子序就是質子數，也是中性原子的電子數。","image":""},{"id":"A-39-02","isl":"A","lv":1,"stem":"氦（原子序 2）原子的最外層有幾個電子？","A":"2","B":"8","C":"1","D":"0","answer":"A","explanation":"氦只有 2 個電子，都在第一層，已經填滿。","image":""},{"id":"A-39-03","isl":"A","lv":2,"stem":"氧（原子序 8）的電子排布由內到外是？","A":"2、8","B":"2、6","C":"6、2","D":"8","answer":"B","explanation":"第一層放 2 個，剩下 6 個放在第二層。","image":""},{"id":"A-39-04","isl":"A","lv":2,"stem":"同一週期由左到右，原子序如何變化？","A":"忽大忽小","B":"不變","C":"逐漸減少","D":"逐漸增加","answer":"D","explanation":"週期表由左到右、由上到下，原子序依序增加。","image":""},{"id":"A-39-05","isl":"A","lv":3,"stem":"某中性原子電子排布為 2、8、7，它是哪一種元素？","A":"氬","B":"氟","C":"硫","D":"氯","answer":"D","explanation":"電子總數 17，原子序 17 是氯。","image":""},{"id":"A-40-01","isl":"A","lv":1,"stem":"氣態物質的粒子間距離，和固態相比如何？","A":"略小於固態","B":"遠大於固態","C":"遠小於固態","D":"相同","answer":"B","explanation":"氣體粒子之間空隙很大，粒子運動也最自由。","image":""},{"id":"A-40-02","isl":"A","lv":1,"stem":"粒子間距離最大、運動最自由的是哪一種狀態？","A":"晶體","B":"液態","C":"氣態","D":"固態","answer":"C","explanation":"氣態粒子間吸引力很小，可以自由移動。","image":""},{"id":"A-40-03","isl":"A","lv":2,"stem":"氣體容易被壓縮，主要是因為？","A":"粒子很柔軟","B":"粒子沒有質量","C":"粒子數量很少","D":"粒子間空隙很大","answer":"D","explanation":"氣體粒子間距離大，加壓時粒子被擠得更靠近。","image":""},{"id":"A-40-04","isl":"A","lv":2,"stem":"液體會隨容器改變形狀，是因為？","A":"粒子間距離極大","B":"粒子會消失","C":"粒子能互相滑動流動","D":"粒子固定不動","answer":"C","explanation":"液體粒子仍相互靠近，但可以滑動，所以沒有固定形狀。","image":""},{"id":"A-40-05","isl":"A","lv":3,"stem":"溫度升高時，氣體粒子的運動情形是？","A":"運動加快","B":"運動變慢","C":"完全停止","D":"體積變小","answer":"A","explanation":"溫度升高表示粒子動能變大，運動更快。","image":""},{"id":"A-41-01","isl":"A","lv":1,"stem":"在一大氣壓下，純水的凝固點是攝氏幾度？","A":"0℃","B":"37℃","C":"100℃","D":"－273℃","answer":"A","explanation":"純水在一大氣壓下 0℃ 凝固，100℃ 沸騰。","image":""},{"id":"A-41-02","isl":"A","lv":1,"stem":"一般酒精溫度計是利用什麼原理製成？","A":"氣體壓力改變","B":"液體熱脹冷縮","C":"金屬導電","D":"物質顏色改變","answer":"B","explanation":"溫度升高時液體膨脹，液柱上升。","image":""},{"id":"A-41-03","isl":"A","lv":2,"stem":"絕對零度（0 K）約等於攝氏幾度？","A":"0℃","B":"－273℃","C":"273℃","D":"－100℃","answer":"B","explanation":"凱氏溫度 0 K 約等於 －273℃。","image":""},{"id":"A-41-04","isl":"A","lv":2,"stem":"體溫計不能放在滾水中消毒，主要原因是？","A":"超過量測上限會使玻璃管破裂","B":"體溫計會變重","C":"酒精會蒸發","D":"水會污染體溫計","answer":"A","explanation":"滾水溫度遠高於體溫計的最高刻度，可能使它脹破。","image":""},{"id":"A-41-05","isl":"A","lv":3,"stem":"攝氏 25℃ 換成凱氏溫度約是多少？","A":"25 K","B":"248 K","C":"373 K","D":"298 K","answer":"D","explanation":"凱氏溫度＝攝氏溫度＋273，所以約 298 K。","image":""},{"id":"A-42-01","isl":"A","lv":1,"stem":"冰熔化成水時，會吸熱還是放熱？","A":"不吸不放","B":"放熱","C":"吸熱","D":"先放後吸","answer":"C","explanation":"熔化需要吸收熱量，才能讓粒子間距離變大、可以滑動。","image":""},{"id":"A-42-02","isl":"A","lv":1,"stem":"水蒸氣凝結成小水滴時，會發生什麼事？","A":"放出熱量","B":"不吸不放","C":"溫度一定上升","D":"吸收熱量","answer":"A","explanation":"氣體凝結成液體會放熱。","image":""},{"id":"A-42-03","isl":"A","lv":2,"stem":"夏天在地上灑水可以降溫，主要原因是？","A":"水凝結會放熱","B":"水本身很冷","C":"水比空氣重","D":"水蒸發要吸收熱量","answer":"D","explanation":"水蒸發時從地面和空氣吸熱，使周圍變涼。","image":""},{"id":"A-42-04","isl":"A","lv":2,"stem":"下列哪一種變化會放出熱量？","A":"冰熔化","B":"水結成冰","C":"水蒸發","D":"乾冰昇華","answer":"B","explanation":"凝固（液變固）會放熱，其他三項都吸熱。","image":""},{"id":"A-42-05","isl":"A","lv":3,"stem":"被 100℃ 水蒸氣燙傷，比被 100℃ 熱水燙傷更嚴重，主要是因為？","A":"水蒸氣溫度更高","B":"水蒸氣有毒","C":"水蒸氣比較重","D":"水蒸氣凝結時會釋放大量熱","answer":"D","explanation":"水蒸氣凝結成水時還要額外放熱，傳給皮膚的熱量更多。","image":""},{"id":"A-43-01","isl":"A","lv":1,"stem":"加熱純物質的溫度—時間圖中，水平線段表示什麼？","A":"停止加熱","B":"狀態改變中，溫度不變","C":"溫度持續下降","D":"溫度持續上升","answer":"B","explanation":"水平段代表熔化或沸騰，此時熱量用來改變狀態而非升溫。","image":""},{"id":"A-43-02","isl":"A","lv":1,"stem":"把冰持續加熱到沸騰，過程中共發生幾次狀態變化？","A":"3 次","B":"2 次","C":"4 次","D":"1 次","answer":"B","explanation":"先由固態熔化成液態，再由液態沸騰成氣態，共 2 次。","image":""},{"id":"A-43-03","isl":"A","lv":2,"stem":"加熱冰塊，在熔化的階段，溫度大約是多少？","A":"逐漸上升","B":"0℃","C":"100℃","D":"－10℃","answer":"B","explanation":"純水熔化期間溫度維持在 0℃，直到冰全部熔化。","image":""},{"id":"A-43-04","isl":"A","lv":2,"stem":"某物質加熱時溫度一直上升，沒有水平線段，最可能是？","A":"純水","B":"純物質","C":"元素","D":"混合物","answer":"D","explanation":"混合物沒有固定的熔點和沸點，所以溫度會持續變化。","image":""},{"id":"A-43-05","isl":"A","lv":3,"stem":"100 g 和 200 g 的純水都加熱到沸騰，下列哪一項相同？","A":"吸收的熱量","B":"達到沸騰的時間","C":"沸點","D":"加熱所需時間","answer":"C","explanation":"沸點是物質的特性，不隨質量改變，在一大氣壓下都是 100℃。","image":""},{"id":"A-44-01","isl":"A","lv":1,"stem":"下列哪一項屬於物質的物理性質？","A":"腐蝕性","B":"鐵會生鏽","C":"可燃性","D":"熔點","answer":"D","explanation":"熔點可以直接測量，不需要改變物質的種類。","image":""},{"id":"A-44-02","isl":"A","lv":1,"stem":"銅線能導電，這是銅的哪一種性質？","A":"導電性","B":"可燃性","C":"延展性","D":"氧化性","answer":"A","explanation":"能讓電流通過的性質稱為導電性，屬於物理性質。","image":""},{"id":"A-44-03","isl":"A","lv":2,"stem":"下列哪一項不是物理性質？","A":"助燃性","B":"密度","C":"顏色","D":"硬度","answer":"A","explanation":"助燃性要發生燃燒反應才看得出來，屬於化學性質。","image":""},{"id":"A-44-04","isl":"A","lv":2,"stem":"外形相似的鐵片和鋁片，最簡單的分辨方法是？","A":"看顏色","B":"看是不是固體","C":"量形狀","D":"能否被磁鐵吸引","answer":"D","explanation":"鐵能被磁鐵吸引，鋁不行；兩者顏色都是銀灰色。","image":""},{"id":"A-44-05","isl":"A","lv":3,"stem":"下列哪一組全部是物理性質？","A":"酸性、硬度、導電性","B":"助燃性、密度、沸點","C":"熔點、沸點、密度","D":"可燃性、熔點、顏色","answer":"C","explanation":"可燃性、酸性、助燃性都是化學性質，只有熔點、沸點、密度全是物理性質。","image":""},{"id":"A-45-01","isl":"A","lv":1,"stem":"下列哪一項是氧氣的化學性質？","A":"無味","B":"無色","C":"助燃性","D":"沸點很低","answer":"C","explanation":"能幫助物質燃燒，要透過化學變化才看得出來，是化學性質。","image":""},{"id":"A-45-02","isl":"A","lv":1,"stem":"酒精能燃燒，這是酒精的哪一種性質？","A":"導電性","B":"可燃性","C":"熔點低","D":"延展性","answer":"B","explanation":"能燃燒的性質叫可燃性，是化學性質。","image":""},{"id":"A-45-03","isl":"A","lv":2,"stem":"下列哪一項是鐵的化學性質？","A":"可被拉成細絲","B":"容易生鏽","C":"能導電","D":"有金屬光澤","answer":"B","explanation":"生鏽時鐵變成氧化鐵，產生了新物質。","image":""},{"id":"A-45-04","isl":"A","lv":2,"stem":"食品包裝常充入氮氣，是利用氮氣的什麼性質？","A":"能助燃","B":"密度很大","C":"不易與其他物質反應","D":"容易燃燒","answer":"C","explanation":"氮氣性質穩定，可減少食物氧化變質。","image":""},{"id":"A-45-05","isl":"A","lv":3,"stem":"下列哪一項敘述同時包含物理與化學性質？","A":"蠟燭是白色固體，點燃後能燃燒","B":"鐵是銀灰色，密度較大","C":"水無色透明，沸點 100℃","D":"銅有紅色光澤，能導電","answer":"A","explanation":"白色固體是物理性質，能燃燒是化學性質。","image":""},{"id":"A-46-01","isl":"A","lv":1,"stem":"冰塊融化成水，屬於哪一種變化？","A":"不算變化","B":"化學變化","C":"核反應","D":"物理變化","answer":"D","explanation":"只有狀態改變，沒有產生新物質，屬於物理變化。","image":""},{"id":"A-46-02","isl":"A","lv":1,"stem":"木材燃燒，屬於哪一種變化？","A":"化學變化","B":"物理變化","C":"狀態變化","D":"溶解","answer":"A","explanation":"燃燒會產生灰燼、二氧化碳等新物質，是化學變化。","image":""},{"id":"A-46-03","isl":"A","lv":2,"stem":"下列哪一項是化學變化？","A":"水結成冰","B":"牛奶變酸","C":"糖溶於水","D":"玻璃破裂","answer":"B","explanation":"牛奶變酸產生了新物質，是化學變化。","image":""},{"id":"A-46-04","isl":"A","lv":2,"stem":"下列哪一項屬於物理變化？","A":"乾冰昇華","B":"米飯發霉","C":"鐵生鏽","D":"蛋煮熟","answer":"A","explanation":"乾冰由固態直接變氣態，只是狀態改變。","image":""},{"id":"A-46-05","isl":"A","lv":3,"stem":"化學變化發生後，下列哪一項一定會改變？","A":"原子的種類","B":"物質的種類","C":"原子的數目","D":"物質總質量","answer":"B","explanation":"化學變化會產生新物質，但原子種類、數目與總質量不變。","image":""},{"id":"A-47-01","isl":"A","lv":1,"stem":"下列哪一項是純物質？","A":"牛奶","B":"海水","C":"蒸餾水","D":"汽水","answer":"C","explanation":"蒸餾水只含水分子，是純物質。","image":""},{"id":"A-47-02","isl":"A","lv":1,"stem":"下列哪一項不是純物質？","A":"氧氣","B":"純金","C":"汽水","D":"蒸餾水","answer":"C","explanation":"汽水含水、糖、二氧化碳等多種成分，是混合物。","image":""},{"id":"A-47-03","isl":"A","lv":2,"stem":"關於混合物，下列何者正確？","A":"一定是化合物","B":"只能由兩種元素組成","C":"各成分保有原來的性質","D":"有固定的熔點","answer":"C","explanation":"混合物由多種物質混合，各成分仍保有原來的性質。","image":""},{"id":"A-47-04","isl":"A","lv":2,"stem":"氧氣、水、食鹽、空氣中，屬於化合物的有幾種？","A":"3 種","B":"1 種","C":"2 種","D":"4 種","answer":"C","explanation":"水與食鹽是化合物，氧氣是元素，空氣是混合物。","image":""},{"id":"A-47-05","isl":"A","lv":3,"stem":"黃銅是銅和鋅熔合而成的合金，它屬於？","A":"化合物","B":"元素","C":"混合物","D":"純物質","answer":"C","explanation":"合金由不同金屬混合而成，成分可以改變，屬於混合物。","image":""},{"id":"A-48-01","isl":"A","lv":1,"stem":"從沙和鐵粉的混合物中取出鐵粉，最簡單的方法是？","A":"蒸餾","B":"用磁鐵吸","C":"過濾","D":"結晶","answer":"B","explanation":"鐵能被磁鐵吸引，沙不行。","image":""},{"id":"A-48-02","isl":"A","lv":1,"stem":"利用沸點不同來分離酒精和水，應該使用哪一種方法？","A":"過濾","B":"蒸餾","C":"傾析","D":"磁選","answer":"B","explanation":"酒精沸點較低，先蒸發出來再冷凝收集。","image":""},{"id":"A-48-03","isl":"A","lv":2,"stem":"用篩子分開大小不同的顆粒，這種方法稱為？","A":"篩選","B":"色層分析","C":"蒸餾","D":"結晶","answer":"A","explanation":"利用顆粒大小不同來分離，稱為篩選。","image":""},{"id":"A-48-04","isl":"A","lv":2,"stem":"油和水分層後用分液漏斗分離，是利用什麼性質？","A":"顆粒大小不同","B":"互不相溶且密度不同","C":"有無磁性","D":"沸點不同","answer":"B","explanation":"油與水互不相溶，密度不同而分層，可由下方放出較重的液體。","image":""},{"id":"A-48-05","isl":"A","lv":3,"stem":"要分離食鹽、沙和鐵粉的混合物，順序最合理的是？","A":"先蒸發，再用磁鐵","B":"先磁鐵、再加水過濾、再蒸發","C":"先加水過濾，再用磁鐵","D":"只要過濾即可","answer":"B","explanation":"先用磁鐵吸出鐵粉，再加水溶解食鹽並過濾出沙，最後蒸發濾液得到食鹽。","image":""},{"id":"A-49-01","isl":"A","lv":1,"stem":"糖水屬於哪一類混合物？","A":"溶液","B":"純物質","C":"乳濁液","D":"懸浮液","answer":"A","explanation":"糖均勻溶在水中，形成透明的溶液。","image":""},{"id":"A-49-02","isl":"A","lv":1,"stem":"泥水靜置後會分層，因為它屬於？","A":"元素","B":"懸浮液","C":"純物質","D":"溶液","answer":"B","explanation":"泥沙顆粒較大，靜置會沉澱，是懸浮液。","image":""},{"id":"A-49-03","isl":"A","lv":2,"stem":"下列哪一項是溶液的特性？","A":"顆粒肉眼可見","B":"靜置後會沉澱","C":"混濁、會分層","D":"均勻、透明、不易沉澱","answer":"D","explanation":"溶液中的溶質以很小的粒子均勻分散在溶劑中。","image":""},{"id":"A-49-04","isl":"A","lv":2,"stem":"同溫度下，在飽和食鹽水中再加入食鹽，會怎樣？","A":"全部變成氣體","B":"繼續溶解","C":"不再溶解","D":"濃度繼續升高","answer":"C","explanation":"飽和溶液不能再溶解更多的溶質。","image":""},{"id":"A-49-05","isl":"A","lv":3,"stem":"50 g 的 10% 糖水中加水成 100 g，濃度變成多少？","A":"10%","B":"5%","C":"20%","D":"2.5%","answer":"B","explanation":"糖的質量 5 g 不變，5÷100＝5%。","image":""},{"id":"B-01-01","isl":"B","lv":1,"stem":"太陽能板把哪種能量轉換成電能？","A":"光能","B":"化學能","C":"聲能","D":"位能","answer":"A","explanation":"太陽能板吸收光能，轉換成電能。","image":""},{"id":"B-01-02","isl":"B","lv":1,"stem":"水力發電廠的能量轉換順序，何者正確？","A":"電能 → 動能 → 位能","B":"化學能 → 光能 → 電能","C":"熱能 → 位能 → 電能","D":"位能 → 動能 → 電能","answer":"D","explanation":"水從高處流下：位能 → 動能，推動渦輪發電機 → 電能。","image":""},{"id":"B-01-03","isl":"B","lv":2,"stem":"下列關於能量守恆的敘述，何者正確？","A":"能量可以憑空產生","B":"轉換時總能量會減少","C":"總能量不會增加也不會減少","D":"只有動能遵守能量守恆","answer":"C","explanation":"能量不會憑空產生或消失，只會轉換形式，總量不變。","image":""},{"id":"B-01-04","isl":"B","lv":2,"stem":"用手搓手覺得手變熱，主要是什麼能量轉換？","A":"熱能 → 動能","B":"動能 → 熱能","C":"電能 → 熱能","D":"光能 → 熱能","answer":"B","explanation":"摩擦讓手的動能轉換成熱能。","image":""},{"id":"B-01-05","isl":"B","lv":3,"stem":"燈泡用了 100 J 的電能，發出 10 J 的光能，其餘大多變成？","A":"熱能","B":"化學能","C":"位能","D":"消失了","answer":"A","explanation":"能量守恆：其餘 90 J 大多變成熱能散失。","image":""},{"id":"B-02-01","isl":"B","lv":1,"stem":"功的單位「焦耳」等於？","A":"牛頓 ÷ 公尺","B":"公斤 × 公尺","C":"牛頓 × 公尺","D":"瓦特 × 公尺","answer":"C","explanation":"1 J = 1 N × 1 m。","image":""},{"id":"B-02-02","isl":"B","lv":2,"stem":"用 20 N 的水平力推箱子，沿著力的方向移動 3 m，作功多少？","A":"6.7 J","B":"60 J","C":"23 J","D":"0 J","answer":"B","explanation":"W = F × S = 20 × 3 = 60 J。","image":""},{"id":"B-02-03","isl":"B","lv":2,"stem":"下列哪一個情況，人對物體有作功？","A":"把書從地上拿到桌上","B":"提著書包等公車","C":"推牆推不動","D":"頂著書本水平走路","answer":"A","explanation":"把書舉高，力向上、位移也向上，有作功。","image":""},{"id":"B-02-04","isl":"B","lv":2,"stem":"起重機 5 秒內作功 1000 J，功率是？","A":"5000 W","B":"1005 W","C":"0.005 W","D":"200 W","answer":"D","explanation":"P = W ÷ t = 1000 ÷ 5 = 200 W。","image":""},{"id":"B-02-05","isl":"B","lv":3,"stem":"把質量 2 kg 的物體等速舉高 3 m，作功多少焦耳？（g = 9.8 m/s²）","A":"6 J","B":"19.6 J","C":"58.8 J","D":"0 J","answer":"C","explanation":"物重 = 2 × 9.8 = 19.6 N，W = F × S = 19.6 × 3 = 58.8 J，這些功變成物體的重力位能。","image":""},{"id":"B-03-01","isl":"B","lv":1,"stem":"下列何者主要具有重力位能？","A":"高處的水塔裡的水","B":"在地上滾的球","C":"正在充電的手機","D":"發亮的燈泡","answer":"A","explanation":"高處的水因為位置高，具有重力位能。","image":""},{"id":"B-03-02","isl":"B","lv":2,"stem":"質量相同的兩台車，甲的速率是乙的 3 倍，甲的動能是乙的幾倍？","A":"3 倍","B":"6 倍","C":"1/3 倍","D":"9 倍","answer":"D","explanation":"動能和速率平方成正比：3² = 9 倍。","image":""},{"id":"B-03-03","isl":"B","lv":2,"stem":"2 kg 的球以 3 m/s 的速率運動，動能是？","A":"3 J","B":"6 J","C":"9 J","D":"18 J","answer":"C","explanation":"E_k = ½ × 2 × 3² = 9 J。","image":""},{"id":"B-03-04","isl":"B","lv":2,"stem":"同一本書從桌上搬到書櫃頂，它的重力位能會？","A":"變小","B":"變大","C":"不變","D":"變成 0","answer":"B","explanation":"位置變高，重力位能變大。","image":""},{"id":"B-03-05","isl":"B","lv":3,"stem":"拉開的弓把箭射出去，主要是什麼能量轉換？","A":"彈性位能 → 動能","B":"動能 → 彈性位能","C":"熱能 → 動能","D":"化學能 → 光能","answer":"A","explanation":"拉開的弓有彈性位能，放開後變成箭的動能。","image":""},{"id":"B-04-01","isl":"B","lv":1,"stem":"力學能是指哪兩種能量的和？","A":"動能與熱能","B":"位能與化學能","C":"動能與位能","D":"光能與電能","answer":"C","explanation":"力學能 = 動能 + 位能。","image":""},{"id":"B-04-02","isl":"B","lv":2,"stem":"不計摩擦，雲霄飛車在哪裡速率最快？","A":"最高點","B":"軌道最低點","C":"每一點都一樣","D":"剛出發時","answer":"B","explanation":"最低點位能最小，動能最大，所以最快。","image":""},{"id":"B-04-03","isl":"B","lv":2,"stem":"單擺從 A 點放手，不計阻力，會擺到另一邊的哪裡？","A":"和 A 一樣高","B":"比 A 高","C":"比 A 低","D":"停在最低點","answer":"A","explanation":"力學能守恆，擺回同樣的高度。","image":""},{"id":"B-04-04","isl":"B","lv":2,"stem":"球從高處落下，不計空氣阻力，落下過程中？","A":"動能減少、位能增加","B":"動能和位能都增加","C":"力學能變大","D":"動能增加、位能減少，力學能不變","answer":"D","explanation":"位能轉換成動能，總和不變。","image":""},{"id":"B-04-05","isl":"B","lv":3,"stem":"盪鞦韆時如果都不用力，為什麼會越盪越低？","A":"能量消失了","B":"位能變大了","C":"力學能因摩擦與空氣阻力變成熱能","D":"重力變小了","answer":"C","explanation":"力學能變成熱能散失，總能量仍守恆。","image":""},{"id":"B-05-01","isl":"B","lv":1,"stem":"電池使用時的能量轉換是？","A":"化學能 → 電能","B":"電能 → 化學能","C":"光能 → 電能","D":"熱能 → 化學能","answer":"A","explanation":"電池把化學能轉變成電能。","image":""},{"id":"B-05-02","isl":"B","lv":1,"stem":"暖暖包搖一搖就變熱，這是？","A":"吸熱反應","B":"物理變化","C":"沒有能量變化","D":"放熱反應","answer":"D","explanation":"鐵粉氧化放出熱，是放熱反應。","image":""},{"id":"B-05-03","isl":"B","lv":2,"stem":"要做出水果電池，下列哪一組金屬片最適合？","A":"銅片和銅片","B":"鋅片和鋅片","C":"鋅片和銅片","D":"塑膠片和銅片","answer":"C","explanation":"要兩種活性不同的金屬，鋅和銅最常用。","image":""},{"id":"B-05-04","isl":"B","lv":2,"stem":"一顆水果電池約 0.9 V，三顆串聯約多少伏特？","A":"0.3 V","B":"2.7 V","C":"0.9 V","D":"9 V","answer":"B","explanation":"串聯時電壓相加：0.9 × 3 = 2.7 V。","image":""},{"id":"B-05-05","isl":"B","lv":3,"stem":"下列哪一個是吸熱反應？","A":"硝酸銨溶於水","B":"木炭燃燒","C":"暖暖包發熱","D":"酸鹼中和","answer":"A","explanation":"硝酸銨溶解會吸熱，溫度下降，常用在冷敷包。","image":""},{"id":"B-06-01","isl":"B","lv":1,"stem":"熱的傳遞方向是？","A":"低溫 → 高溫","B":"質量大 → 質量小","C":"高溫 → 低溫","D":"固體 → 液體","answer":"C","explanation":"熱具有從高溫處傳到低溫處的趨勢。","image":""},{"id":"B-06-02","isl":"B","lv":1,"stem":"1 卡的定義是？","A":"1 公斤的水升高 1℃ 吸收的熱量","B":"1 公克的水升高 1℃ 吸收的熱量","C":"1 公克的水升高 10℃ 吸收的熱量","D":"1 公克的冰熔化吸收的熱量","answer":"B","explanation":"1 卡 = 1 g 水升高 1℃ 的熱量。","image":""},{"id":"B-06-03","isl":"B","lv":2,"stem":"200 g 的水從 25℃ 加熱到 75℃，吸收多少卡？","A":"10000 卡","B":"50 卡","C":"200 卡","D":"5000 卡","answer":"A","explanation":"H = 200 × (75 − 25) = 10000 卡。","image":""},{"id":"B-06-04","isl":"B","lv":2,"stem":"100 g 的 80℃ 熱水和 100 g 的 20℃ 冷水混合，不計散失，最後約幾 ℃？","A":"30℃","B":"60℃","C":"100℃","D":"50℃","answer":"D","explanation":"等量混合，熱水放出的熱 = 冷水吸收的熱，溫度在中間 50℃。","image":""},{"id":"B-06-05","isl":"B","lv":3,"stem":"100 g 的 90℃ 水和 200 g 的 30℃ 水混合，最後約幾 ℃？","A":"40℃","B":"60℃","C":"50℃","D":"70℃","answer":"C","explanation":"100 × (90 − T) = 200 × (T − 30)，T = 50℃。","image":""},{"id":"B-07-01","isl":"B","lv":1,"stem":"水的比熱是多少 cal/(g·℃)？","A":"1","B":"0.1","C":"0.5","D":"10","answer":"A","explanation":"1 g 水升高 1℃ 需要 1 卡，比熱是 1。","image":""},{"id":"B-07-02","isl":"B","lv":2,"stem":"同樣質量的水和鐵，吸收同樣的熱，哪一個溫度升高較多？","A":"水","B":"一樣多","C":"無法比較","D":"鐵","answer":"D","explanation":"鐵的比熱較小，溫度升高較多。","image":""},{"id":"B-07-03","isl":"B","lv":2,"stem":"比熱 0.2 cal/(g·℃) 的金屬 50 g，升高 10℃ 要吸收多少卡？","A":"10 卡","B":"500 卡","C":"100 卡","D":"2.5 卡","answer":"C","explanation":"H = 50 × 0.2 × 10 = 100 卡。","image":""},{"id":"B-07-04","isl":"B","lv":2,"stem":"為什麼汽車引擎用水來冷卻？","A":"水的比熱小","B":"水的比熱大，能吸收很多熱","C":"水很便宜","D":"水會導電","answer":"B","explanation":"水的比熱大，吸收很多熱溫度也不會升太高。","image":""},{"id":"B-07-05","isl":"B","lv":3,"stem":"晚上海邊吹陸風，原因是？","A":"陸地降溫比海水快，海面空氣較熱而上升","B":"海水降溫比陸地快","C":"月亮的引力","D":"陸地的比熱比較大","answer":"A","explanation":"陸地比熱小降溫快，海面較暖的空氣上升，陸上空氣吹向海。","image":""},{"id":"B-08-01","isl":"B","lv":1,"stem":"熱可以在真空中傳播的方式是？","A":"傳導","B":"對流","C":"輻射","D":"三種都可以","answer":"C","explanation":"輻射不需要介質。","image":""},{"id":"B-08-02","isl":"B","lv":1,"stem":"燒水時，壺底的水受熱上升、上面的冷水下降，這是？","A":"傳導","B":"對流","C":"輻射","D":"蒸發","answer":"B","explanation":"流體受熱流動形成循環，是對流。","image":""},{"id":"B-08-03","isl":"B","lv":2,"stem":"下列何者是熱的良導體？","A":"銅","B":"木頭","C":"塑膠","D":"空氣","answer":"A","explanation":"金屬是熱的良導體，銅導熱特別好。","image":""},{"id":"B-08-04","isl":"B","lv":2,"stem":"保溫瓶的真空層主要是為了阻擋？","A":"輻射","B":"只有輻射","C":"光線","D":"傳導和對流","answer":"D","explanation":"真空中沒有物質，傳導和對流都無法進行。","image":""},{"id":"B-08-05","isl":"B","lv":3,"stem":"夏天穿淺色衣服比較涼快，原因是？","A":"淺色衣服導熱快","B":"淺色衣服會對流","C":"淺色衣服反射較多輻射熱","D":"淺色衣服比較薄","answer":"C","explanation":"淺色表面反射較多輻射，吸收較少熱。","image":""},{"id":"B-09-01","isl":"B","lv":1,"stem":"鐵軌之間留有縫隙，主要原因是？","A":"熱脹冷縮","B":"方便排水","C":"節省材料","D":"減少噪音","answer":"A","explanation":"夏天鐵軌受熱膨脹，需要預留空間。","image":""},{"id":"B-09-02","isl":"B","lv":1,"stem":"下列哪一個過程需要放熱？","A":"冰熔化成水","B":"水沸騰變水蒸氣","C":"乾冰昇華","D":"水蒸氣凝結成水","answer":"D","explanation":"液化（凝結）要放熱；熔化、汽化、昇華要吸熱。","image":""},{"id":"B-09-03","isl":"B","lv":2,"stem":"加熱一杯冰水混合物，在冰全部熔化前，溫度會？","A":"持續上升","B":"持續下降","C":"維持 0℃","D":"先升後降","answer":"C","explanation":"狀態改變時溫度不變，熱用來熔化冰。","image":""},{"id":"B-09-04","isl":"B","lv":2,"stem":"為什麼冰會浮在水面上？","A":"冰比較冷","B":"冰的密度比水小","C":"冰裡面有空氣","D":"水有浮力而冰沒有","answer":"B","explanation":"水結冰體積變大，密度變小，所以浮起來。","image":""},{"id":"B-09-05","isl":"B","lv":3,"stem":"冬天湖面結冰，湖底的水大約維持幾 ℃，魚才能活下來？","A":"4℃","B":"−10℃","C":"0℃","D":"20℃","answer":"A","explanation":"4℃ 的水密度最大，沉在湖底。","image":""},{"id":"B-10-01","isl":"B","lv":1,"stem":"光合作用主要在植物細胞的哪個構造進行？","A":"細胞核","B":"粒線體","C":"葉綠體","D":"液胞","answer":"C","explanation":"葉綠體含有葉綠素，是光合作用的場所。","image":""},{"id":"B-10-02","isl":"B","lv":1,"stem":"光合作用的產物是？","A":"二氧化碳和水","B":"葡萄糖和氧氣","C":"氧氣和水","D":"葡萄糖和二氧化碳","answer":"B","explanation":"二氧化碳 + 水 → 葡萄糖 + 氧氣。","image":""},{"id":"B-10-03","isl":"B","lv":2,"stem":"水草實驗中，燈泡移得越近，每分鐘冒出的氣泡會？","A":"變多","B":"變少","C":"不變","D":"停止","answer":"A","explanation":"光越強，光合作用越旺盛，氧氣氣泡越多。","image":""},{"id":"B-10-04","isl":"B","lv":2,"stem":"做「水蘊草光合作用」實驗時，常在水中加入少量小蘇打，主要是為了增加水中的哪一種物質？","A":"氧氣","B":"氮氣","C":"葡萄糖","D":"二氧化碳","answer":"D","explanation":"小蘇打（碳酸氫鈉）溶在水中可以提供二氧化碳，二氧化碳是光合作用的原料，水蘊草就能產生較多氧氣（氣泡）。","image":""},{"id":"B-10-05","isl":"B","lv":3,"stem":"探討「光的強弱」對光合作用的影響，下列何者是操縱變因？","A":"水草的種類","B":"水溫","C":"燈泡與水草的距離","D":"水的量","answer":"C","explanation":"只改變光的強弱（燈的距離），其他條件保持相同。","image":""},{"id":"B-11-01","isl":"B","lv":1,"stem":"呼吸作用主要在細胞的哪個構造進行？","A":"粒線體","B":"葉綠體","C":"細胞壁","D":"細胞核","answer":"A","explanation":"粒線體是細胞的能量工廠。","image":""},{"id":"B-11-02","isl":"B","lv":1,"stem":"呼吸作用的能量轉換是？","A":"光能 → 化學能","B":"熱能 → 化學能","C":"電能 → 化學能","D":"化學能 → 生命活動所需的能量與熱能","answer":"D","explanation":"呼吸作用分解養分，釋放化學能，一部分變成熱。","image":""},{"id":"B-11-03","isl":"B","lv":2,"stem":"麵包發酵時麵團會膨脹，是因為酵母菌產生了？","A":"氧氣","B":"氮氣","C":"二氧化碳","D":"水蒸氣","answer":"C","explanation":"酵母菌呼吸產生二氧化碳，撐大麵團。","image":""},{"id":"B-11-04","isl":"B","lv":2,"stem":"人體內大多數酵素的最適溫度大約是？","A":"0℃","B":"37℃","C":"20℃","D":"80℃","answer":"B","explanation":"接近體溫 37℃ 時作用最好。","image":""},{"id":"B-11-05","isl":"B","lv":3,"stem":"發高燒太久可能危險，主要原因是？","A":"酵素可能變性，影響新陳代謝","B":"血液會沸騰","C":"細胞停止吸水","D":"呼吸作用會變成光合作用","answer":"A","explanation":"溫度過高會讓酵素失去作用。","image":""},{"id":"B-12-01","isl":"B","lv":1,"stem":"生態系中能量的最初來源是？","A":"土壤","B":"水","C":"太陽","D":"分解者","answer":"C","explanation":"生產者利用太陽光能行光合作用。","image":""},{"id":"B-12-02","isl":"B","lv":1,"stem":"下列何者是生產者？","A":"兔子","B":"青草","C":"蘑菇","D":"老鷹","answer":"B","explanation":"綠色植物能行光合作用，是生產者；蘑菇是分解者。","image":""},{"id":"B-12-03","isl":"B","lv":2,"stem":"草 → 蚱蜢 → 青蛙 → 蛇，哪一級得到的能量最少？","A":"蛇","B":"草","C":"蚱蜢","D":"青蛙","answer":"A","explanation":"能量每傳一級就少很多，蛇在最上層。","image":""},{"id":"B-12-04","isl":"B","lv":2,"stem":"若草有 10000 單位能量，每級約傳 10%，青蛙（第三級）約得到？","A":"1000","B":"10","C":"1","D":"100","answer":"D","explanation":"草 → 蚱蜢 1000 → 青蛙 100。","image":""},{"id":"B-12-05","isl":"B","lv":3,"stem":"下列關於生態系的敘述何者正確？","A":"能量和物質都會循環","B":"能量循環、物質單向","C":"物質循環、能量單向流動","D":"兩者都單向","answer":"C","explanation":"碳等物質會循環，能量單向流動最後變成熱。","image":""},{"id":"B-21-01","isl":"B","lv":1,"stem":"物理學上，力對物體做功的條件是？","A":"物體必須靜止","B":"力的方向上有位移","C":"力必須很大","D":"只要有施力","answer":"B","explanation":"要做功，物體必須在力的方向上移動一段距離。","image":""},{"id":"B-21-02","isl":"B","lv":1,"stem":"做功的大小等於？","A":"質量×速度","B":"力×位移","C":"力＋位移","D":"力÷位移","answer":"B","explanation":"功＝力×在力的方向上的位移。","image":""},{"id":"B-21-03","isl":"B","lv":2,"stem":"用 20 N 的力沿水平推箱子前進 3 m，做功多少焦耳？","A":"23 焦耳","B":"60 焦耳","C":"17 焦耳","D":"6.7 焦耳","answer":"B","explanation":"W＝20×3＝60 J。","image":""},{"id":"B-21-04","isl":"B","lv":2,"stem":"抱著 10 kg 的箱子站著不動 1 分鐘，對箱子做功多少？","A":"5880 焦耳","B":"0 焦耳","C":"98 焦耳","D":"980 焦耳","answer":"B","explanation":"箱子沒有位移，所以沒有做功。","image":""},{"id":"B-21-05","isl":"B","lv":3,"stem":"甲在 10 秒內做功 500 J，功率是多少瓦特？","A":"0.02 瓦特","B":"510 瓦特","C":"5000 瓦特","D":"50 瓦特","answer":"D","explanation":"功率＝功÷時間＝500÷10＝50 W。","image":""},{"id":"B-22-01","isl":"B","lv":1,"stem":"物體因為運動而具有的能量稱為？","A":"化學能","B":"位能","C":"熱能","D":"動能","answer":"D","explanation":"運動中的物體具有動能。","image":""},{"id":"B-22-02","isl":"B","lv":1,"stem":"被舉高的物體具有什麼能量？","A":"彈力位能","B":"核能","C":"光能","D":"重力位能","answer":"D","explanation":"高度越高，重力位能越大。","image":""},{"id":"B-22-03","isl":"B","lv":2,"stem":"同一個物體速度變成 2 倍，動能變成幾倍？","A":"4 倍","B":"2 倍","C":"8 倍","D":"1/2 倍","answer":"A","explanation":"動能與速度的平方成正比，速度 2 倍，動能 4 倍。","image":""},{"id":"B-22-04","isl":"B","lv":2,"stem":"質量 2 kg 的物體升高 5 m（g 取 10 m/s²），位能增加多少焦耳？","A":"10 焦耳","B":"20 焦耳","C":"100 焦耳","D":"50 焦耳","answer":"C","explanation":"位能＝mgh＝2×10×5＝100 J。","image":""},{"id":"B-22-05","isl":"B","lv":3,"stem":"質量相同的甲在 10 m 高，乙在 20 m 高，甲、乙的位能比是？","A":"1：1","B":"1：2","C":"1：4","D":"2：1","answer":"B","explanation":"位能與高度成正比，所以是 10：20＝1：2。","image":""},{"id":"B-23-01","isl":"B","lv":1,"stem":"忽略空氣阻力，自由下落物體的力學能會？","A":"越來越大","B":"先增後減","C":"保持不變","D":"越來越小","answer":"C","explanation":"只受重力時，位能減少多少，動能就增加多少，力學能守恆。","image":""},{"id":"B-23-02","isl":"B","lv":1,"stem":"自由下落的物體，位能主要轉換成？","A":"動能","B":"核能","C":"光能","D":"化學能","answer":"A","explanation":"下落時高度變小、速度變快，位能轉為動能。","image":""},{"id":"B-23-03","isl":"B","lv":2,"stem":"單擺擺到最低點時，下列何者最大？","A":"動能","B":"質量","C":"週期","D":"重力位能","answer":"A","explanation":"最低點高度最小，位能最小，速度最快，動能最大。","image":""},{"id":"B-23-04","isl":"B","lv":2,"stem":"雲霄飛車從高處衝下，速度變快，是因為？","A":"能量憑空增加","B":"動能轉換成位能","C":"重力消失","D":"位能轉換成動能","answer":"D","explanation":"高度降低，位能減少，動能增加。","image":""},{"id":"B-23-05","isl":"B","lv":3,"stem":"忽略阻力，球從 5 m 高自由下落，在 2 m 高處時，動能與位能何者較大？","A":"位能較大","B":"動能為零","C":"兩者一樣大","D":"動能較大","answer":"D","explanation":"力學能守恆，下落了 3 m，動能為 mg×3，位能為 mg×2，動能較大。","image":""},{"id":"B-24-01","isl":"B","lv":1,"stem":"質量相同時，比熱愈大的物質，溫度改變 1℃ 所需的熱量？","A":"愈少","B":"不一定","C":"愈多","D":"一樣多","answer":"C","explanation":"比熱是 1 g 物質升高 1℃ 所需的熱量，比熱愈大，需要的熱量愈多。","image":""},{"id":"B-24-02","isl":"B","lv":1,"stem":"1 卡是使 1 g 的水升高多少℃所需的熱量？","A":"0.1℃","B":"10℃","C":"100℃","D":"1℃","answer":"D","explanation":"1 卡的定義就是使 1 g 水升高 1℃ 所需的熱量。","image":""},{"id":"B-24-03","isl":"B","lv":2,"stem":"100 g 的水由 20℃ 升到 50℃，吸收多少卡的熱量？（水的比熱為 1）","A":"100 卡","B":"3000 卡","C":"7000 卡","D":"30 卡","answer":"B","explanation":"Q＝100×1×30＝3000 卡。","image":""},{"id":"B-24-04","isl":"B","lv":2,"stem":"質量相同的物質吸收相同熱量，哪一種溫度升高最多？","A":"密度最大的","B":"體積最大的","C":"比熱最大的","D":"比熱最小的","answer":"D","explanation":"Q＝msΔt，Q 與 m 相同時，比熱 s 越小，溫度變化越大。","image":""},{"id":"B-24-05","isl":"B","lv":3,"stem":"50 g 的金屬吸收 600 cal 的熱量，溫度升高 40℃，比熱是多少？","A":"0.6 cal/(g·℃)","B":"3 cal/(g·℃)","C":"0.3 cal/(g·℃)","D":"15 cal/(g·℃)","answer":"C","explanation":"s＝Q÷(m×Δt)＝600÷(50×40)＝0.3。","image":""},{"id":"B-25-01","isl":"B","lv":1,"stem":"太陽的熱傳到地球，主要靠哪一種方式？","A":"蒸發","B":"對流","C":"傳導","D":"輻射","answer":"D","explanation":"太空中接近真空，熱只能以輻射方式傳播。","image":""},{"id":"B-25-02","isl":"B","lv":1,"stem":"金屬湯匙放進熱湯，湯匙柄也變燙，是哪一種熱傳播？","A":"輻射","B":"傳導","C":"蒸發","D":"對流","answer":"B","explanation":"熱沿著固體由高溫處傳到低溫處，稱為傳導。","image":""},{"id":"B-25-03","isl":"B","lv":2,"stem":"冷氣機裝在高處，室內能變涼，主要是利用？","A":"金屬的傳導","B":"太陽的輻射","C":"冷空氣上升的對流","D":"冷空氣下沉的對流","answer":"D","explanation":"冷空氣密度大會下沉，熱空氣上升，形成對流。","image":""},{"id":"B-25-04","isl":"B","lv":2,"stem":"保溫瓶內層鍍銀並抽成真空，目的是？","A":"增加熱對流","B":"減少三種熱傳播","C":"增加熱輻射","D":"增加熱傳導","answer":"B","explanation":"真空減少傳導與對流，鍍銀反射熱輻射。","image":""},{"id":"B-25-05","isl":"B","lv":3,"stem":"燒開水時從底部加熱，上下層水都會變熱，主要是靠？","A":"蒸發","B":"輻射","C":"凝結","D":"對流","answer":"D","explanation":"受熱的水變輕上升，冷水下沉，形成對流。","image":""},{"id":"B-26-01","isl":"B","lv":1,"stem":"電器的功率常用什麼單位？","A":"伏特","B":"歐姆","C":"瓦特","D":"安培","answer":"C","explanation":"功率的單位是瓦特（W）。","image":""},{"id":"B-26-02","isl":"B","lv":1,"stem":"家用電表上的「度」是什麼量的單位？","A":"電阻","B":"電流","C":"電壓","D":"電能","answer":"D","explanation":"1 度電等於 1 千瓦的電器使用 1 小時所用的電能。","image":""},{"id":"B-26-03","isl":"B","lv":2,"stem":"電壓 110 V、電流 2 A 的電器，功率是多少瓦特？","A":"55 瓦特","B":"220 瓦特","C":"112 瓦特","D":"108 瓦特","answer":"B","explanation":"功率＝電壓×電流＝110×2＝220 W。","image":""},{"id":"B-26-04","isl":"B","lv":2,"stem":"1000 W 的電暖器使用 2 小時，用電多少度？","A":"2000 度","B":"1000 度","C":"2 度","D":"0.5 度","answer":"C","explanation":"1000 W＝1 kW，1×2＝2 度。","image":""},{"id":"B-26-05","isl":"B","lv":3,"stem":"100 W 與 20 W 的燈泡各亮 10 小時，用電量的比是？","A":"10：1","B":"1：5","C":"5：1","D":"1：1","answer":"C","explanation":"電能＝功率×時間，時間相同，所以比等於功率比 100：20＝5：1。","image":""},{"id":"B-27-01","isl":"B","lv":1,"stem":"太陽內部放出能量的主要來源是？","A":"核分裂","B":"化學反應","C":"燃燒","D":"核融合","answer":"D","explanation":"太陽內部氫原子核融合成氦，釋放出大量能量。","image":""},{"id":"B-27-02","isl":"B","lv":1,"stem":"電風扇運轉時，電能主要轉換成？","A":"光能","B":"動能","C":"核能","D":"化學能","answer":"B","explanation":"馬達把電能轉換成扇葉的動能。","image":""},{"id":"B-27-03","isl":"B","lv":2,"stem":"火力發電廠的能量轉換順序是？","A":"電能→熱能→動能→化學能","B":"動能→熱能→電能→化學能","C":"熱能→化學能→電能→動能","D":"化學能→熱能→動能→電能","answer":"D","explanation":"燃料的化學能燃燒成熱，推動渦輪機轉動，再帶動發電機發電。","image":""},{"id":"B-27-04","isl":"B","lv":2,"stem":"能量守恆定律的內容是？","A":"能量可以憑空產生","B":"能量用完就消失","C":"能量只轉換，總量不變","D":"只有熱能會守恆","answer":"C","explanation":"能量不會憑空產生或消失，只會從一種形式轉換成另一種。","image":""},{"id":"B-27-05","isl":"B","lv":3,"stem":"燈泡消耗 100 J 電能，其中 20 J 轉成光能，發光效率是多少？","A":"80%","B":"100%","C":"120%","D":"20%","answer":"D","explanation":"效率＝有用的能量÷輸入的能量＝20÷100＝20%，其餘 80 J 變成熱。","image":""},{"id":"B-28-01","isl":"B","lv":1,"stem":"槓桿中，支點到重物作用點的距離稱為？","A":"功","B":"施力臂","C":"力矩","D":"抗力臂","answer":"D","explanation":"支點到施力點是施力臂，支點到抗力（重物）作用點是抗力臂。","image":""},{"id":"B-28-02","isl":"B","lv":1,"stem":"斜面的主要功用是？","A":"省功","B":"省力","C":"增加功","D":"省時間","answer":"B","explanation":"斜面可以用較小的力把物體推高，但要走較長的距離。","image":""},{"id":"B-28-03","isl":"B","lv":2,"stem":"翹翹板平衡時，需要滿足？","A":"兩邊力矩相等","B":"兩邊重量一定相等","C":"兩邊質量一定相等","D":"兩邊距離一定相等","answer":"A","explanation":"平衡條件是順時針力矩等於逆時針力矩。","image":""},{"id":"B-28-04","isl":"B","lv":2,"stem":"使用簡單機械時，下列何者是不可能做到的？","A":"增加移動距離","B":"省功","C":"改變施力方向","D":"省力","answer":"B","explanation":"功的原理：使用任何機械都不能省功。","image":""},{"id":"B-28-05","isl":"B","lv":3,"stem":"用槓桿撬重物，抗力 500 N，抗力臂 20 cm，施力臂 100 cm，最少需施力多少 N？","A":"500 N","B":"100 N","C":"20 N","D":"2500 N","answer":"B","explanation":"力矩平衡：F×100＝500×20，F＝100 N。","image":""},{"id":"C-01-01","isl":"C","lv":1,"stem":"過濾適合用來分離下列哪一種混合物？","A":"泥沙水","B":"糖水","C":"食鹽水","D":"酒精水溶液","answer":"A","explanation":"泥沙不溶於水，會被濾紙擋住。","image":""},{"id":"C-01-02","isl":"C","lv":1,"stem":"過濾時，穿過濾紙流到燒杯裡的液體稱為？","A":"濾渣","B":"溶質","C":"結晶","D":"濾液","answer":"D","explanation":"流下來的是濾液，留在濾紙上的是濾渣。","image":""},{"id":"C-01-03","isl":"C","lv":2,"stem":"過濾時倒入的液面高過濾紙邊緣，最可能發生什麼事？","A":"過濾變得更乾淨","B":"濾紙會溶解","C":"液體從縫隙流下，濾液變混濁","D":"泥沙會溶解","answer":"C","explanation":"液面要低於濾紙邊緣。","image":""},{"id":"C-01-04","isl":"C","lv":2,"stem":"過濾時，漏斗下端的尖口應該？","A":"懸在燒杯正中央","B":"靠著燒杯內壁","C":"浸到濾液裡面最底部","D":"朝向燒杯外面","answer":"B","explanation":"靠著內壁，濾液沿杯壁流下不會濺出。","image":""},{"id":"C-01-05","isl":"C","lv":3,"stem":"把食鹽和沙的混合物加水攪拌後過濾，濾紙上和濾液中分別有什麼？","A":"濾紙上是沙，濾液中有食鹽","B":"濾紙上是食鹽，濾液中有沙","C":"兩者都留在濾紙上","D":"兩者都在濾液中","answer":"A","explanation":"沙不溶於水被擋住；食鹽溶於水穿過濾紙，再把濾液蒸發就能得到食鹽。","image":""},{"id":"C-02-01","isl":"C","lv":1,"stem":"一定溫度下，100 公克水最多能溶解的溶質質量稱為？","A":"濃度","B":"密度","C":"溶解度","D":"沸點","answer":"C","explanation":"溶解度的定義。","image":""},{"id":"C-02-02","isl":"C","lv":1,"stem":"要從海水中得到食鹽，最適合用哪一種方法？","A":"冷卻結晶","B":"蒸發結晶","C":"過濾","D":"磁鐵吸引","answer":"B","explanation":"食鹽溶解度幾乎不隨溫度改變，要蒸發掉水。","image":""},{"id":"C-02-03","isl":"C","lv":2,"stem":"下列哪一種物質最適合用冷卻熱飽和溶液的方法得到晶體？","A":"硝酸鉀","B":"食鹽","C":"沙","D":"酒精","answer":"A","explanation":"硝酸鉀溶解度隨溫度變化很大，冷卻時析出大量晶體。","image":""},{"id":"C-02-04","isl":"C","lv":2,"stem":"20°C 時硝酸鉀的溶解度約 32 公克，在 20°C、100 公克水中加入 50 公克硝酸鉀充分攪拌，約有多少公克沉在杯底？","A":"0 公克","B":"32 公克","C":"50 公克","D":"18 公克","answer":"D","explanation":"最多溶 32 公克，50 − 32 ＝ 18 公克溶不了。","image":""},{"id":"C-02-05","isl":"C","lv":3,"stem":"80°C 時 100 公克水溶有 169 公克硝酸鉀（飽和），冷卻到 20°C（溶解度約 32 公克），約可析出多少公克晶體？","A":"32 公克","B":"169 公克","C":"137 公克","D":"201 公克","answer":"C","explanation":"169 − 32 ＝ 137 公克。","image":""},{"id":"C-03-01","isl":"C","lv":1,"stem":"濾紙色層分析法可以用來分離？","A":"墨水中的不同色素","B":"泥沙水","C":"鐵粉和沙","D":"海水中的鹽","answer":"A","explanation":"利用色素移動速度不同而分開。","image":""},{"id":"C-03-02","isl":"C","lv":1,"stem":"做濾紙色層分析時，起始線最好用什麼畫？","A":"原子筆","B":"彩色筆","C":"螢光筆","D":"鉛筆","answer":"D","explanation":"鉛筆的石墨不會被展開液帶走。","image":""},{"id":"C-03-03","isl":"C","lv":2,"stem":"墨點如果被浸在展開液的液面以下，會發生什麼事？","A":"分得更清楚","B":"濾紙會燒焦","C":"色素溶進展開液，無法在濾紙上分開","D":"色素變成黑色","answer":"C","explanation":"墨點要高於液面。","image":""},{"id":"C-03-04","isl":"C","lv":2,"stem":"黑色水性筆的墨水在濾紙上分出藍、紅、黃三條色帶，表示這種墨水是？","A":"純物質","B":"混合物","C":"元素","D":"化合物","answer":"B","explanation":"含有多種色素，是混合物。","image":""},{"id":"C-03-05","isl":"C","lv":3,"stem":"用同樣方法分析兩支筆的墨水，色帶的顏色和位置完全相同，最合理的推論是？","A":"兩支筆可能用同一種墨水","B":"兩支筆一定是同一支","C":"兩支筆墨水的顏色一定不同","D":"墨水是元素","answer":"A","explanation":"色帶相同表示成分可能相同，可用來比對筆跡。","image":""},{"id":"C-04-01","isl":"C","lv":1,"stem":"將氣體通入澄清石灰水，石灰水變混濁，這種氣體是？","A":"氧氣","B":"氫氣","C":"二氧化碳","D":"氮氣","answer":"C","explanation":"二氧化碳使石灰水混濁。","image":""},{"id":"C-04-02","isl":"C","lv":1,"stem":"藍色的氯化亞鈷試紙遇到哪一種物質會變成粉紅色？","A":"食鹽","B":"水","C":"二氧化碳","D":"澱粉","answer":"B","explanation":"氯化亞鈷試紙用來檢驗水。","image":""},{"id":"C-04-03","isl":"C","lv":2,"stem":"在一片麵包上滴碘液，出現藍黑色，表示麵包含有？","A":"澱粉","B":"葡萄糖","C":"蛋白質","D":"脂肪","answer":"A","explanation":"澱粉遇碘液呈藍黑色。","image":""},{"id":"C-04-04","isl":"C","lv":2,"stem":"一包白色粉末加入稀鹽酸冒出氣泡，氣泡能使石灰水混濁，粉末最可能是？","A":"食鹽","B":"糖","C":"澱粉","D":"碳酸鈣","answer":"D","explanation":"碳酸鈣和鹽酸反應產生二氧化碳。","image":""},{"id":"C-04-05","isl":"C","lv":3,"stem":"兩杯透明液體分別是水和酒精，最適合用哪一種方法分辨？","A":"看顏色","B":"用磁鐵","C":"用藍色氯化亞鈷試紙","D":"搖一搖聽聲音","answer":"C","explanation":"純酒精不會使氯化亞鈷試紙變色，水會使它變粉紅（也可以聞氣味）。","image":""},{"id":"C-05-01","isl":"C","lv":1,"stem":"下列何者是由不同種原子組成的化合物分子？","A":"H₂O","B":"O₂","C":"N₂","D":"H₂","answer":"A","explanation":"H₂O 由氫和氧兩種原子組成。","image":""},{"id":"C-05-02","isl":"C","lv":1,"stem":"提出「物質由原子組成，化學反應是原子重新排列」的科學家是？","A":"牛頓","B":"伽利略","C":"達爾文","D":"道耳頓","answer":"D","explanation":"道耳頓原子說。","image":""},{"id":"C-05-03","isl":"C","lv":2,"stem":"一個二氧化碳分子（CO₂）由幾個原子組成？","A":"1 個","B":"2 個","C":"3 個","D":"4 個","answer":"C","explanation":"1 個碳原子＋2 個氧原子。","image":""},{"id":"C-05-04","isl":"C","lv":2,"stem":"關於分子與原子，下列何者正確？","A":"原子由分子組成","B":"分子由原子組成","C":"分子比原子小","D":"原子不能組成物質","answer":"B","explanation":"分子是由原子結合而成的。","image":""},{"id":"C-05-05","isl":"C","lv":3,"stem":"水分解成氫氣和氧氣時，下列敘述何者正確？","A":"原子的種類和數目不變，只是重新組合","B":"氫原子變成了氧原子","C":"原子消失了一部分","D":"水分子沒有被破壞","answer":"A","explanation":"化學反應中原子重新排列，種類和數目不變。","image":""},{"id":"C-06-01","isl":"C","lv":1,"stem":"鑽石、石墨、C₆₀ 都是由哪一種元素組成的？","A":"氧","B":"矽","C":"碳","D":"氫","answer":"C","explanation":"三者都只含碳原子。","image":""},{"id":"C-06-02","isl":"C","lv":1,"stem":"下列哪一組互為同素異形體？","A":"水和冰","B":"鑽石和石墨","C":"乙醇和甲醚","D":"食鹽和糖","answer":"B","explanation":"同一種元素、排列不同。水和冰是同一種物質的不同狀態。","image":""},{"id":"C-06-03","isl":"C","lv":2,"stem":"石墨可以做鉛筆芯，是因為？","A":"碳原子排成層狀，層與層之間容易滑動","B":"石墨含有鉛","C":"石墨非常堅硬","D":"石墨是金屬","answer":"A","explanation":"層間容易滑動，所以質軟、能留下痕跡。","image":""},{"id":"C-06-04","isl":"C","lv":2,"stem":"鑽石和石墨性質差很多，主要原因是？","A":"組成元素不同","B":"鑽石含有氧","C":"石墨比較重","D":"碳原子的排列方式不同","answer":"D","explanation":"同一種元素，排列不同，性質不同。","image":""},{"id":"C-06-05","isl":"C","lv":3,"stem":"下列哪一種用途，是利用石墨「能導電」的性質？","A":"做鉛筆芯","B":"做鑽頭","C":"做電池或電解的電極","D":"做戒指","answer":"C","explanation":"石墨能導電，可以當電極；鉛筆芯是利用質軟。","image":""},{"id":"C-07-01","isl":"C","lv":1,"stem":"乙醇和甲醚的分子式都是？","A":"C₂H₆O","B":"CH₄","C":"CO₂","D":"C₆H₁₂O₆","answer":"A","explanation":"兩者都是 2 個碳、6 個氫、1 個氧。","image":""},{"id":"C-07-02","isl":"C","lv":1,"stem":"分子式相同但結構不同的物質，互稱為？","A":"同位素","B":"同素異形體","C":"混合物","D":"同分異構物","answer":"D","explanation":"同分異構物的定義。","image":""},{"id":"C-07-03","isl":"C","lv":2,"stem":"乙醇和甲醚的沸點差很多，主要原因是？","A":"原子種類不同","B":"原子數目不同","C":"原子連接排列的方式不同","D":"一個是元素一個是化合物","answer":"C","explanation":"分子式相同，結構不同，性質就不同。","image":""},{"id":"C-07-04","isl":"C","lv":2,"stem":"常溫常壓下，乙醇和甲醚的狀態分別是？","A":"乙醇氣體、甲醚液體","B":"乙醇液體、甲醚氣體","C":"都是液體","D":"都是氣體","answer":"B","explanation":"乙醇沸點約 78°C、甲醚約 −24°C。","image":""},{"id":"C-07-05","isl":"C","lv":3,"stem":"下列哪一組互為同分異構物？","A":"乙醇和甲醚","B":"鑽石和石墨","C":"氧氣和臭氧","D":"水和冰","answer":"A","explanation":"鑽石／石墨、氧氣／臭氧是同素異形體；水和冰是同一物質的不同狀態。","image":""},{"id":"C-21-01","isl":"C","lv":1,"stem":"蒸餾法是利用混合物中各成分的什麼不同來分離？","A":"重量","B":"導電性","C":"沸點","D":"顏色","answer":"C","explanation":"不同物質沸點不同，加熱後先沸騰的先蒸發，再冷凝收集。","image":""},{"id":"C-21-02","isl":"C","lv":1,"stem":"要從食鹽水中取得純水，最適合的方法是？","A":"磁鐵吸引","B":"蒸餾","C":"過濾","D":"傾析","answer":"B","explanation":"食鹽水中的食鹽是溶解的，過濾分不開，要用蒸餾。","image":""},{"id":"C-21-03","isl":"C","lv":2,"stem":"油和水不互溶，要把它們分開最適合用？","A":"漏斗與濾紙","B":"蒸發皿","C":"分液漏斗","D":"酒精燈","answer":"C","explanation":"兩種不互溶的液體分層後，可用分液漏斗分離。","image":""},{"id":"C-21-04","isl":"C","lv":2,"stem":"鐵粉和硫粉的混合物，要快速分出鐵粉可以用？","A":"色層分析","B":"磁鐵","C":"蒸餾","D":"過濾","answer":"B","explanation":"鐵會被磁鐵吸引，硫不會。","image":""},{"id":"C-21-05","isl":"C","lv":3,"stem":"把泥沙水靜置後，輕輕倒出上層清水，這種方法稱為？","A":"蒸餾","B":"結晶","C":"色層分析","D":"傾析","answer":"D","explanation":"讓固體沉澱後倒出上層液體，稱為傾析。","image":""},{"id":"C-22-01","isl":"C","lv":1,"stem":"一般固體物質的溶解度，隨溫度升高通常會？","A":"先減後增","B":"減小","C":"不變","D":"增大","answer":"D","explanation":"大部分固體在水中的溶解度，溫度越高越大。","image":""},{"id":"C-22-02","isl":"C","lv":1,"stem":"飽和溶液是指在該溫度下？","A":"溶液一定很濃","B":"不能再溶解溶質","C":"溶液一定無色","D":"溶質多於溶劑","answer":"B","explanation":"飽和表示溶質已溶到最多，再加也不會溶解。","image":""},{"id":"C-22-03","isl":"C","lv":2,"stem":"硝酸鉀飽和溶液降溫後出現晶體，是因為降溫使溶解度？","A":"變為零","B":"變小","C":"不變","D":"變大","answer":"B","explanation":"溶解度變小，多出來的溶質就析出成晶體。","image":""},{"id":"C-22-04","isl":"C","lv":2,"stem":"要從氯化鈉水溶液取得食鹽晶體，最常用的方法是？","A":"傾析","B":"過濾","C":"蒸發水分","D":"磁鐵吸引","answer":"C","explanation":"氯化鈉的溶解度受溫度影響小，用蒸發水分的方式結晶。","image":""},{"id":"C-22-05","isl":"C","lv":3,"stem":"某物質 20℃ 的溶解度為 30 g/100 g 水，50 g 水最多可溶解多少 g？","A":"150 g","B":"60 g","C":"30 g","D":"15 g","answer":"D","explanation":"50 g 水是 100 g 的一半，所以最多溶 15 g。","image":""},{"id":"C-23-01","isl":"C","lv":1,"stem":"能使帶有餘燼的線香復燃的氣體是？","A":"二氧化碳","B":"氫氣","C":"氧氣","D":"氮氣","answer":"C","explanation":"氧氣有助燃性，可使餘燼復燃。","image":""},{"id":"C-23-02","isl":"C","lv":1,"stem":"氫氣遇到火焰會發出什麼現象？","A":"黃色火焰","B":"耀眼白光","C":"爆鳴聲","D":"沒有反應","answer":"C","explanation":"氫氣和氧氣混合遇火會快速燃燒，發出爆鳴聲。","image":""},{"id":"C-23-03","isl":"C","lv":2,"stem":"雙氧水加入二氧化錳，產生的氣體是？","A":"氯氣","B":"氧氣","C":"二氧化碳","D":"氫氣","answer":"B","explanation":"二氧化錳是催化劑，使雙氧水分解成水和氧氣。","image":""},{"id":"C-23-04","isl":"C","lv":2,"stem":"鋅粒與稀鹽酸反應，產生的氣體是？","A":"氫氣","B":"氮氣","C":"二氧化碳","D":"氧氣","answer":"A","explanation":"活性較大的金屬和酸反應會產生氫氣。","image":""},{"id":"C-23-05","isl":"C","lv":3,"stem":"排水集氣法適合收集具有什麼性質的氣體？","A":"易溶於水","B":"比空氣重","C":"有顏色","D":"不易溶於水","answer":"D","explanation":"氣體不易溶於水，才能用排水法收集。","image":""},{"id":"C-24-01","isl":"C","lv":1,"stem":"石墨可以做鉛筆筆芯，是因為它？","A":"是金屬","B":"質地軟且能在紙上留痕","C":"非常堅硬","D":"能透明","answer":"B","explanation":"石墨的碳原子成層狀排列，層與層之間容易滑動，質地軟。","image":""},{"id":"C-24-02","isl":"C","lv":1,"stem":"鑽石是由哪一種原子組成的？","A":"矽原子","B":"碳原子","C":"硫原子","D":"氧原子","answer":"B","explanation":"鑽石是碳的同素異形體。","image":""},{"id":"C-24-03","isl":"C","lv":2,"stem":"鑽石和石墨性質差異很大，主要原因是？","A":"碳原子排列方式不同","B":"組成元素不同","C":"質子數不同","D":"中子數不同","answer":"A","explanation":"兩者都由碳組成，但原子排列方式不同，造成性質差異。","image":""},{"id":"C-24-04","isl":"C","lv":2,"stem":"氧氣（O₂）和臭氧（O₃）的關係是？","A":"同素異形體","B":"同一種物質","C":"同分異構物","D":"同位素","answer":"A","explanation":"同一種元素組成的不同單質，互稱同素異形體。","image":""},{"id":"C-24-05","isl":"C","lv":3,"stem":"下列何組互為同素異形體？","A":"氧氣與二氧化碳","B":"水與冰","C":"氫氣與氧氣","D":"紅磷與白磷","answer":"D","explanation":"紅磷和白磷都由磷元素組成，結構不同。","image":""},{"id":"C-25-01","isl":"C","lv":1,"stem":"氧氣的化學式 O₂，表示 1 個氧分子由幾個氧原子組成？","A":"1 個","B":"2 個","C":"4 個","D":"3 個","answer":"B","explanation":"右下角的 2 表示 1 個分子中有 2 個氧原子。","image":""},{"id":"C-25-02","isl":"C","lv":1,"stem":"下列何者的分子只含有同一種原子？","A":"N₂","B":"H₂O","C":"CO₂","D":"CH₄","answer":"A","explanation":"N₂ 只含氮原子，是單質分子。","image":""},{"id":"C-25-03","isl":"C","lv":2,"stem":"1 個 H₂SO₄ 分子中共有幾個原子？","A":"7 個","B":"6 個","C":"3 個","D":"4 個","answer":"A","explanation":"2＋1＋4＝7 個。","image":""},{"id":"C-25-04","isl":"C","lv":2,"stem":"化學式前面的係數「3 H₂O」表示？","A":"3 個氫分子","B":"6 個水分子","C":"1 個水分子","D":"3 個水分子","answer":"D","explanation":"係數表示分子的個數，3 H₂O 就是 3 個水分子。","image":""},{"id":"C-25-05","isl":"C","lv":3,"stem":"2 CO₂ 中共有幾個氧原子？","A":"6 個","B":"4 個","C":"2 個","D":"3 個","answer":"B","explanation":"每個 CO₂ 有 2 個氧，2 個分子共 4 個。","image":""},{"id":"C-26-01","isl":"C","lv":1,"stem":"乾燥空氣中含量第二多的氣體是？","A":"氬氣","B":"氧氣","C":"氮氣","D":"二氧化碳","answer":"B","explanation":"空氣中氮氣約 78%，氧氣約 21%。","image":""},{"id":"C-26-02","isl":"C","lv":1,"stem":"氧氣約占乾燥空氣體積的百分之幾？","A":"21%","B":"78%","C":"1%","D":"50%","answer":"A","explanation":"氧氣約占 21%。","image":""},{"id":"C-26-03","isl":"C","lv":2,"stem":"植物行光合作用時，主要吸收空氣中的？","A":"二氧化碳","B":"氬氣","C":"氫氣","D":"氮氣","answer":"A","explanation":"光合作用吸收二氧化碳和水，產生葡萄糖和氧氣。","image":""},{"id":"C-26-04","isl":"C","lv":2,"stem":"食品包裝常充入氮氣，主要因為氮氣？","A":"會助燃","B":"性質穩定不易反應","C":"有甜味","D":"性質非常活潑","answer":"B","explanation":"氮氣性質穩定，可以減少食物氧化腐壞。","image":""},{"id":"C-26-05","isl":"C","lv":3,"stem":"蠟燭在密閉瓶中燃燒一段時間後熄滅，主要因為？","A":"氮氣被用完","B":"氧氣被消耗到不足","C":"二氧化碳被用完","D":"水蒸氣太多","answer":"B","explanation":"燃燒需要氧氣，瓶中氧氣不足時火焰就熄滅了。","image":""},{"id":"C-27-01","isl":"C","lv":1,"stem":"金屬通常具有的性質是？","A":"都不導電","B":"能導電導熱","C":"沒有光澤","D":"質地易碎","answer":"B","explanation":"金屬有光澤，能導電、導熱，可以延展。","image":""},{"id":"C-27-02","isl":"C","lv":1,"stem":"下列何者是非金屬元素？","A":"銅","B":"鐵","C":"鋁","D":"硫","answer":"D","explanation":"硫是非金屬，其他三個是金屬。","image":""},{"id":"C-27-03","isl":"C","lv":2,"stem":"金屬可以被拉成細絲，這種性質稱為？","A":"展性","B":"彈性","C":"脆性","D":"延性","answer":"D","explanation":"可以被拉長成細絲是延性。","image":""},{"id":"C-27-04","isl":"C","lv":2,"stem":"金屬可以被錘打成薄片，這種性質稱為？","A":"導電性","B":"延性","C":"彈性","D":"展性","answer":"D","explanation":"可以被錘成薄片是展性。","image":""},{"id":"C-27-05","isl":"C","lv":3,"stem":"一般而言，金屬氧化物與非金屬氧化物溶於水，水溶液依序呈？","A":"都是中性","B":"都是酸性","C":"鹼性、酸性","D":"酸性、鹼性","answer":"C","explanation":"金屬氧化物多為鹼性，非金屬氧化物多為酸性。","image":""},{"id":"C-28-01","isl":"C","lv":1,"stem":"食鹽（氯化鈉）屬於哪一類化合物？","A":"分子化合物","B":"合金","C":"金屬","D":"離子化合物","answer":"D","explanation":"氯化鈉由鈉離子和氯離子組成。","image":""},{"id":"C-28-02","isl":"C","lv":1,"stem":"下列何者屬於分子化合物？","A":"氯化鈣","B":"水","C":"氧化鎂","D":"氯化鈉","answer":"B","explanation":"水由水分子組成，是分子化合物。","image":""},{"id":"C-28-03","isl":"C","lv":2,"stem":"離子化合物通常的熔點是？","A":"一定低於 0℃","B":"比分子化合物低","C":"很低","D":"較高","answer":"D","explanation":"離子之間的吸引力強，所以熔點通常較高。","image":""},{"id":"C-28-04","isl":"C","lv":2,"stem":"糖水不導電，是因為蔗糖溶於水時？","A":"變成金屬","B":"產生離子","C":"不產生離子","D":"產生電子","answer":"C","explanation":"蔗糖是分子化合物，溶於水仍是分子，沒有自由移動的離子。","image":""},{"id":"C-28-05","isl":"C","lv":3,"stem":"氯化鈉固體不導電，但熔化後可導電，與下列哪項有關？","A":"質子移動","B":"電子脫離原子","C":"分子分解","D":"離子能自由移動","answer":"D","explanation":"熔化後離子可以自由移動，能傳導電流。","image":""},{"id":"C-30-01","isl":"C","lv":1,"stem":"下列哪一組器材可以組成過濾裝置？","A":"漏斗、濾紙、玻璃棒、燒杯","B":"量筒、滴管","C":"試管、試管夾","D":"蒸發皿、酒精燈","answer":"A","explanation":"過濾需要漏斗、濾紙、燒杯，並用玻璃棒引導液體。","image":""},{"id":"C-30-02","isl":"C","lv":1,"stem":"過濾時，玻璃棒的主要用途是什麼？","A":"夾取濾紙","B":"攪拌加熱","C":"引導液體流下","D":"測量溫度","answer":"C","explanation":"玻璃棒貼著漏斗內壁，讓液體順著流下，避免濺出或沖破濾紙。","image":""},{"id":"C-30-03","isl":"C","lv":2,"stem":"濾紙摺好放進漏斗後，通常先怎麼做使它貼緊漏斗？","A":"用手指壓緊","B":"用酒精擦拭","C":"用少量水潤濕","D":"對著吹氣","answer":"C","explanation":"用少量水潤濕濾紙，濾紙就會貼緊漏斗壁。","image":""},{"id":"C-30-04","isl":"C","lv":2,"stem":"過濾後的濾液仍然混濁，最可能的原因是？","A":"濾紙太乾","B":"濾紙破損","C":"燒杯太大","D":"漏斗太乾淨","answer":"B","explanation":"濾紙破洞，會讓細小顆粒漏過去。","image":""},{"id":"C-30-05","isl":"C","lv":3,"stem":"下列哪一種混合物，無法用過濾法把溶質分出來？","A":"粉筆灰和水","B":"沙和水","C":"食鹽水","D":"泥水","answer":"C","explanation":"食鹽溶解後粒子非常小，會和水一起穿過濾紙。","image":""},{"id":"C-31-01","isl":"C","lv":1,"stem":"咖啡濾杯沖泡咖啡，利用的是哪一種分離方法？","A":"色層分析","B":"蒸餾","C":"結晶","D":"過濾","answer":"D","explanation":"濾紙留住咖啡渣，讓咖啡液流下。","image":""},{"id":"C-31-02","isl":"C","lv":1,"stem":"家用淨水器的濾心，主要作用是？","A":"濾除水中的雜質","B":"製造氧氣","C":"改變水的顏色","D":"增加水的溫度","answer":"A","explanation":"濾心像濾紙一樣，可以留住較大的雜質顆粒。","image":""},{"id":"C-31-03","isl":"C","lv":2,"stem":"口罩能阻擋飛沫，原理和下列哪一項最相似？","A":"燃燒","B":"過濾","C":"結晶","D":"蒸餾","answer":"B","explanation":"口罩纖維之間的小孔只讓空氣通過，擋住較大的顆粒，類似過濾。","image":""},{"id":"C-31-04","isl":"C","lv":2,"stem":"過濾無法除去水中的哪一種物質？","A":"懸浮的微粒","B":"落葉","C":"泥沙","D":"溶解的鹽類","answer":"D","explanation":"溶解的物質粒子太小，過濾無法分離。","image":""},{"id":"C-31-05","isl":"C","lv":3,"stem":"想從食鹽水中得到食鹽，過濾之後還要做什麼？","A":"用磁鐵吸","B":"蒸發結晶","C":"加入沙","D":"再過濾一次","answer":"B","explanation":"食鹽溶在水中，過濾無效，需要把水蒸發才能得到食鹽。","image":""},{"id":"C-32-01","isl":"C","lv":1,"stem":"固體的溶解度，常用什麼單位表示？","A":"g／100 g 水","B":"個／cm³","C":"g／mL","D":"kg／L","answer":"A","explanation":"溶解度是指在一定溫度下，100 g 水最多能溶解的溶質克數。","image":""},{"id":"C-32-02","isl":"C","lv":1,"stem":"氣體的溶解度隨溫度升高會怎麼變化？","A":"不變","B":"先增加後減少","C":"減少","D":"增加","answer":"C","explanation":"溫度愈高，氣體愈容易跑出來，溶解度變小。","image":""},{"id":"C-32-03","isl":"C","lv":2,"stem":"加熱汽水會冒出較多氣泡，主要因為？","A":"溫度升高使氣體溶解度變小","B":"糖變成氣體","C":"汽水變重","D":"水變成氣體","answer":"A","explanation":"氣體的溶解度隨溫度升高而減少，二氧化碳逸出。","image":""},{"id":"C-32-04","isl":"C","lv":2,"stem":"20℃ 時 A 物質的溶解度是 40 g／100 g 水，把 30 g A 放入 100 g 水，溶液屬於？","A":"過飽和溶液","B":"未飽和溶液","C":"不會溶解","D":"飽和溶液","answer":"B","explanation":"30 g 小於 40 g，還可以繼續溶解，所以是未飽和。","image":""},{"id":"C-32-05","isl":"C","lv":3,"stem":"20℃ 時食鹽溶解度約 36 g／100 g 水，50 g 水最多能溶解多少食鹽？","A":"36 g","B":"72 g","C":"18 g","D":"9 g","answer":"C","explanation":"50 g 水是 100 g 的一半，最多溶解 36÷2＝18 g。","image":""},{"id":"C-33-01","isl":"C","lv":1,"stem":"鹽田曬鹽主要是利用什麼讓食鹽結晶？","A":"過濾","B":"冷卻","C":"磁鐵","D":"水蒸發","answer":"D","explanation":"海水的水分蒸發後，溶解的食鹽便結晶析出。","image":""},{"id":"C-33-02","isl":"C","lv":1,"stem":"溶解度隨溫度變化很大的物質，適合用哪一種方法得到晶體？","A":"用磁鐵吸","B":"冷卻熱飽和溶液","C":"直接過濾","D":"蒸發溶液","answer":"B","explanation":"降溫後溶解度明顯下降，多餘的溶質就會結晶。","image":""},{"id":"C-33-03","isl":"C","lv":2,"stem":"溶解度受溫度影響很小的物質，如食鹽，適合怎麼取得晶體？","A":"直接過濾","B":"大幅冷卻","C":"用磁鐵吸","D":"蒸發溶劑","answer":"D","explanation":"降溫幾乎不會讓它結晶，所以要靠蒸發水分。","image":""},{"id":"C-33-04","isl":"C","lv":2,"stem":"想得到較大顆的晶體，冷卻時應該怎麼做？","A":"一直攪拌","B":"快速冰鎮","C":"慢慢冷卻","D":"加入大量沙","answer":"C","explanation":"慢慢冷卻，粒子有時間規則排列，晶體可長得較大。","image":""},{"id":"C-33-05","isl":"C","lv":3,"stem":"蒸發結晶時，蒸發皿快要蒸乾時，最恰當的做法是？","A":"一直攪拌到全乾","B":"加水再煮","C":"繼續用大火加熱","D":"停止加熱，靠餘熱蒸乾","answer":"D","explanation":"全部蒸乾時固體容易噴濺，應提早停火用餘熱蒸乾。","image":""},{"id":"C-34-01","isl":"C","lv":1,"stem":"想把含少量雜質的固體純化，常用什麼方法？","A":"傾析","B":"磁選","C":"直接加熱","D":"再結晶","answer":"D","explanation":"再結晶是先溶解再結晶，可以去除雜質。","image":""},{"id":"C-34-02","isl":"C","lv":1,"stem":"硝酸鉀中混有少量食鹽，可利用什麼性質純化？","A":"密度不同","B":"顏色不同","C":"溶解度隨溫度變化的差異","D":"磁性不同","answer":"C","explanation":"硝酸鉀溶解度隨溫度變化大，食鹽變化小。","image":""},{"id":"C-34-03","isl":"C","lv":2,"stem":"把含少量食鹽的熱硝酸鉀飽和溶液冷卻，主要析出的是？","A":"食鹽晶體","B":"沒有晶體","C":"兩者一樣多","D":"硝酸鉀晶體","answer":"D","explanation":"硝酸鉀降溫後溶解度大減，大量析出；食鹽仍留在溶液中。","image":""},{"id":"C-34-04","isl":"C","lv":2,"stem":"過濾出晶體後，用少量冷水沖洗，目的是？","A":"洗去表面殘留的溶液","B":"讓晶體變色","C":"增加晶體重量","D":"讓晶體溶解","answer":"A","explanation":"洗去附在晶體表面的雜質，用少量冷水可減少晶體溶失。","image":""},{"id":"C-34-05","isl":"C","lv":3,"stem":"洗滌晶體時為什麼不用熱水？","A":"熱水沒有任何影響","B":"熱水使溶解度變大，晶體會溶失","C":"熱水太乾淨","D":"熱水會讓晶體變重","answer":"B","explanation":"固體溶解度多半隨溫度升高而增加，熱水會溶掉較多晶體。","image":""},{"id":"C-35-01","isl":"C","lv":1,"stem":"色層分析法能分離不同色素，是因為各成分在濾紙上什麼不同？","A":"重量","B":"熔點","C":"導電性","D":"移動速度","answer":"D","explanation":"各種色素在濾紙與展開液中的移動速度不同，因此分開。","image":""},{"id":"C-35-02","isl":"C","lv":1,"stem":"進行簽字筆墨水的色層分析，展開液可以使用？","A":"鐵粉","B":"沙","C":"食鹽","D":"水或酒精","answer":"D","explanation":"許多水性墨水可以用水或酒精作為展開液。","image":""},{"id":"C-35-03","isl":"C","lv":2,"stem":"展開液沿著濾紙向上爬升，主要是靠什麼現象？","A":"磁力","B":"重力","C":"浮力","D":"毛細現象","answer":"D","explanation":"濾紙纖維間的細小空隙產生毛細現象，帶著展開液上升。","image":""},{"id":"C-35-04","isl":"C","lv":2,"stem":"在色層分析的濾紙上，較靠近上方的色素點，表示什麼？","A":"不溶於展開液","B":"是最重的色素","C":"移動較快，較容易隨展開液移動","D":"移動較慢","answer":"C","explanation":"移動愈遠的色素，愈容易被展開液帶著走。","image":""},{"id":"C-35-05","isl":"C","lv":3,"stem":"甲墨水分出 3 條色帶，乙墨水只分出 2 條，可推論？","A":"兩者成分完全相同","B":"甲至少含 3 種色素","C":"乙一定是純物質","D":"甲是純物質","answer":"B","explanation":"色帶數目反映至少含有幾種色素。","image":""},{"id":"C-36-01","isl":"C","lv":1,"stem":"綠葉中含有多種色素，可以用什麼方法分離？","A":"電解","B":"過濾","C":"色層分析","D":"磁選","answer":"C","explanation":"色層分析可以把葉綠素、葉黃素等色素分開。","image":""},{"id":"C-36-02","isl":"C","lv":1,"stem":"要檢驗糖果中有哪些人工色素，可以用哪一種方法？","A":"色層分析","B":"過濾","C":"傾析","D":"蒸餾","answer":"A","explanation":"色層分析能把糖果色素分成不同的色帶。","image":""},{"id":"C-36-03","isl":"C","lv":2,"stem":"想比對現場留下的墨跡與嫌犯的筆是否相同，可用？","A":"電解","B":"蒸發結晶","C":"色層分析","D":"過濾","answer":"C","explanation":"比較兩種墨水分出的色帶，就能判斷成分是否相同。","image":""},{"id":"C-36-04","isl":"C","lv":2,"stem":"要比較兩種墨水，實驗時應盡量讓什麼條件相同？","A":"濾紙與展開液","B":"墨水的牌子","C":"筆的價錢","D":"墨點的形狀","answer":"A","explanation":"條件相同，結果才能比較。","image":""},{"id":"C-36-05","isl":"C","lv":3,"stem":"已知色素 A、B 的位置，未知墨水的色帶與 A 同高度，且沒有 B 的位置的色帶，表示？","A":"含 A，不含 B","B":"兩者都不含","C":"兩者都含","D":"含 B，不含 A","answer":"A","explanation":"色帶位置相同，表示是同一種色素。","image":""},{"id":"C-37-01","isl":"C","lv":1,"stem":"鑑定氧氣最常用的方法是什麼？","A":"石蕊試紙","B":"帶有餘燼的線香","C":"澄清石灰水","D":"點火燃燒","answer":"B","explanation":"氧氣能使餘燼的線香重新燃燒。","image":""},{"id":"C-37-02","isl":"C","lv":1,"stem":"鑑定二氧化碳最常用的試劑是什麼？","A":"藍色石蕊試紙","B":"澄清石灰水","C":"碘液","D":"酚酞","answer":"B","explanation":"二氧化碳通入澄清石灰水會使它變混濁。","image":""},{"id":"C-37-03","isl":"C","lv":2,"stem":"氫氣與空氣混合後點燃，會發出什麼現象？","A":"耀眼白光","B":"爆鳴聲","C":"沒有反應","D":"黃色濃煙","answer":"B","explanation":"氫氣遇火會燃燒，混合空氣時發出爆鳴聲，所以要小心。","image":""},{"id":"C-37-04","isl":"C","lv":2,"stem":"二氧化碳使澄清石灰水變混濁，產生的白色物質是？","A":"氫氧化鈣","B":"氧化鈣","C":"碳酸鈣","D":"碳","answer":"C","explanation":"二氧化碳與氫氧化鈣反應，生成難溶於水的碳酸鈣。","image":""},{"id":"C-37-05","isl":"C","lv":3,"stem":"某無色氣體：火焰靠近會熄滅，不使石灰水混濁，餘燼線香也熄滅，最可能是？","A":"氧氣","B":"二氧化碳","C":"氫氣","D":"氮氣","answer":"D","explanation":"氧氣會助燃，二氧化碳會使石灰水混濁，氫氣會燃燒，所以最可能是氮氣。","image":""},{"id":"C-38-01","isl":"C","lv":1,"stem":"無水硫酸銅（白色）遇到水會變成什麼顏色？","A":"黑色","B":"藍色","C":"不變","D":"紅色","answer":"B","explanation":"無水硫酸銅遇水變成藍色，常用來檢驗水。","image":""},{"id":"C-38-02","isl":"C","lv":1,"stem":"鈉的化合物做焰色反應，火焰的顏色是？","A":"紅色","B":"綠色","C":"紫色","D":"黃色","answer":"D","explanation":"鈉的火焰是黃色，所以能辨認含鈉的物質。","image":""},{"id":"C-38-03","isl":"C","lv":2,"stem":"含銅的化合物做焰色反應，火焰通常呈現？","A":"紫色","B":"紅色","C":"藍綠色","D":"黃色","answer":"C","explanation":"銅的焰色反應呈綠色或藍綠色。","image":""},{"id":"C-38-04","isl":"C","lv":2,"stem":"在食鹽水中加入硝酸銀溶液，會出現什麼現象？","A":"白色沉澱","B":"大量氣泡","C":"藍色沉澱","D":"紅褐色沉澱","answer":"A","explanation":"氯離子與銀離子生成白色的氯化銀沉澱。","image":""},{"id":"C-38-05","isl":"C","lv":3,"stem":"某白色粉末焰色反應為黃色，溶於水後加硝酸銀出現白色沉澱，最可能是？","A":"氯化鈉","B":"硝酸鈉","C":"氯化銅","D":"氯化鉀","answer":"A","explanation":"黃色焰色表示含鈉，白色沉澱表示含氯離子，所以是氯化鈉。","image":""},{"id":"C-39-01","isl":"C","lv":1,"stem":"藍色石蕊試紙遇到酸性溶液會變成什麼顏色？","A":"綠色","B":"不變色","C":"黃色","D":"紅色","answer":"D","explanation":"酸性溶液會讓藍色石蕊試紙變紅。","image":""},{"id":"C-39-02","isl":"C","lv":1,"stem":"酚酞遇到鹼性溶液會變成什麼顏色？","A":"藍色","B":"無色","C":"黃色","D":"紅色","answer":"D","explanation":"酚酞在鹼性溶液中呈現紅色（粉紅色）。","image":""},{"id":"C-39-03","isl":"C","lv":2,"stem":"紅色石蕊試紙遇到鹼性溶液會怎樣？","A":"變黃","B":"不變","C":"變藍","D":"變白","answer":"C","explanation":"鹼性溶液會讓紅色石蕊試紙變藍。","image":""},{"id":"C-39-04","isl":"C","lv":2,"stem":"要檢驗檸檬汁是酸性，可以用哪一種試紙？","A":"氯化亞鈷試紙","B":"澱粉試紙","C":"紅色石蕊試紙","D":"藍色石蕊試紙","answer":"D","explanation":"酸性溶液能使藍色石蕊試紙變紅。","image":""},{"id":"C-39-05","isl":"C","lv":3,"stem":"某溶液使紅、藍石蕊試紙都不變色，且加酚酞仍無色，最可能是？","A":"鹼性溶液","B":"強鹼性溶液","C":"酸性溶液","D":"中性溶液","answer":"D","explanation":"酸性使藍試紙變紅，鹼性使紅試紙變藍、酚酞變紅，都沒有，表示呈中性。","image":""},{"id":"C-40-01","isl":"C","lv":1,"stem":"保有物質化學性質的最小粒子，一般指的是什麼？","A":"電子","B":"原子核","C":"質子","D":"分子","answer":"D","explanation":"由分子組成的物質，其最小粒子就是分子。","image":""},{"id":"C-40-02","isl":"C","lv":1,"stem":"氫氣是由什麼粒子組成的？","A":"氫分子（H₂）","B":"氫離子","C":"單獨的氫原子","D":"氫原子核","answer":"A","explanation":"氫氣由氫分子組成，每個氫分子含 2 個氫原子。","image":""},{"id":"C-40-03","isl":"C","lv":2,"stem":"1 個水分子是由哪兩種原子組成的？","A":"氫原子與氧原子","B":"氫原子與碳原子","C":"氧原子與碳原子","D":"氫原子與氮原子","answer":"A","explanation":"水分子由 2 個氫原子和 1 個氧原子組成。","image":""},{"id":"C-40-04","isl":"C","lv":2,"stem":"氦氣（He）是由什麼粒子直接組成的？","A":"氦分子（He₂）","B":"氦原子核","C":"氦原子","D":"氦離子","answer":"C","explanation":"氦是惰性氣體，由單一原子獨立存在。","image":""},{"id":"C-40-05","isl":"C","lv":3,"stem":"化學反應前後，下列哪一項保持不變？","A":"原子的種類和數目","B":"分子的種類","C":"分子的數目","D":"物質的性質","answer":"A","explanation":"化學反應是原子重新排列，原子的種類和數目不變。","image":""},{"id":"C-41-01","isl":"C","lv":1,"stem":"H₂O 中右下角的 2 代表什麼意思？","A":"2 個氫離子","B":"2 個水分子","C":"2 個氫原子","D":"2 個氧原子","answer":"C","explanation":"右下角數字表示該原子的個數。","image":""},{"id":"C-41-02","isl":"C","lv":1,"stem":"1 個氨分子（NH₃）共有幾個原子？","A":"1","B":"4","C":"3","D":"2","answer":"B","explanation":"1 個氮原子加 3 個氫原子，共 4 個原子。","image":""},{"id":"C-41-03","isl":"C","lv":2,"stem":"葡萄糖 C₆H₁₂O₆ 的 1 個分子共有多少個原子？","A":"12","B":"18","C":"24","D":"6","answer":"C","explanation":"6＋12＋6＝24。","image":""},{"id":"C-41-04","isl":"C","lv":2,"stem":"化學式前面的 3O₂ 表示什麼？","A":"3 個氧分子","B":"3 個氧原子","C":"2 個臭氧分子","D":"6 個氧分子","answer":"A","explanation":"3O₂ 表示 3 個氧分子，共含 6 個氧原子。","image":""},{"id":"C-41-05","isl":"C","lv":3,"stem":"硫酸（H₂SO₄）分子中，氧原子占全部原子數的幾分之幾？","A":"3／7","B":"1／7","C":"4／7","D":"2／7","answer":"C","explanation":"共有 2＋1＋4＝7 個原子，其中氧原子有 4 個。","image":""},{"id":"C-42-01","isl":"C","lv":1,"stem":"下列哪一種是由同一種原子組成的分子？","A":"H₂O","B":"NH₃","C":"O₂","D":"CO₂","answer":"C","explanation":"O₂ 由兩個氧原子組成，是元素分子。","image":""},{"id":"C-42-02","isl":"C","lv":1,"stem":"下列哪一種分子由兩種以上的原子組成？","A":"H₂","B":"CH₄","C":"O₂","D":"N₂","answer":"B","explanation":"CH₄ 含碳和氫兩種原子，是化合物分子。","image":""},{"id":"C-42-03","isl":"C","lv":2,"stem":"元素分子與化合物分子最大的差別是？","A":"是否有顏色","B":"分子大小不同","C":"是否為氣體","D":"是否由同一種原子組成","answer":"D","explanation":"元素分子的原子都相同，化合物分子含不同種原子。","image":""},{"id":"C-42-04","isl":"C","lv":2,"stem":"關於 N₂ 與 NO 兩種分子，下列敘述何者正確？","A":"N₂ 是化合物分子","B":"N₂ 與 NO 都是化合物分子","C":"N₂ 與 NO 都是元素分子","D":"N₂ 是元素分子，NO 是化合物分子","answer":"D","explanation":"N₂ 只含氮原子，NO 含氮和氧兩種原子。","image":""},{"id":"C-42-05","isl":"C","lv":3,"stem":"O₂、H₂O、N₂、CO₂、O₃ 這五種分子中，元素分子有幾種？","A":"3 種","B":"2 種","C":"5 種","D":"4 種","answer":"A","explanation":"O₂、N₂、O₃ 都只含一種原子，共 3 種。","image":""},{"id":"C-43-01","isl":"C","lv":1,"stem":"同素異形體指的是什麼？","A":"同一種元素組成、性質不同的物質","B":"不同元素組成、性質相同","C":"質子數不同的原子","D":"中子數不同的原子","answer":"A","explanation":"同一元素形成不同結構的單質，彼此互稱同素異形體。","image":""},{"id":"C-43-02","isl":"C","lv":1,"stem":"臭氧的化學式是什麼？","A":"3O","B":"O₃","C":"O","D":"O₂","answer":"B","explanation":"臭氧分子由 3 個氧原子組成。","image":""},{"id":"C-43-03","isl":"C","lv":2,"stem":"紅磷與白磷互為什麼？","A":"混合物","B":"同分異構物","C":"同素異形體","D":"同位素","answer":"C","explanation":"兩者都是磷元素，但原子排列不同。","image":""},{"id":"C-43-04","isl":"C","lv":2,"stem":"同一種元素的不同單質，性質不同的原因是？","A":"原子排列方式不同","B":"質子數不同","C":"原子量不同","D":"電子數不同","answer":"A","explanation":"組成的原子相同，只是排列方式不同。","image":""},{"id":"C-43-05","isl":"C","lv":3,"stem":"下列哪一項不是碳的同素異形體？","A":"鑽石","B":"二氧化碳","C":"石墨","D":"富勒烯","answer":"B","explanation":"二氧化碳是碳與氧組成的化合物，不是碳的單質。","image":""},{"id":"C-44-01","isl":"C","lv":1,"stem":"C₆₀ 分子的形狀最像什麼？","A":"金字塔","B":"長直線","C":"足球","D":"平面薄片","answer":"C","explanation":"C₆₀ 由 60 個碳原子組成，形狀像足球。","image":""},{"id":"C-44-02","isl":"C","lv":1,"stem":"天然物質中硬度最高的是哪一種？","A":"煤","B":"鑽石","C":"石墨","D":"木炭","answer":"B","explanation":"鑽石的碳原子以強力的結構連接，是最硬的天然物質。","image":""},{"id":"C-44-03","isl":"C","lv":2,"stem":"石墨烯是什麼結構？","A":"足球形分子","B":"長鏈分子","C":"立體的鑽石","D":"單層的碳原子平面","answer":"D","explanation":"石墨烯是只有一層碳原子的二維材料。","image":""},{"id":"C-44-04","isl":"C","lv":2,"stem":"奈米碳管的結構是什麼？","A":"碳原子排成球","B":"金屬原子排成管","C":"水分子排成管","D":"碳原子捲成管狀","answer":"D","explanation":"奈米碳管是碳原子排成的圓管狀結構。","image":""},{"id":"C-44-05","isl":"C","lv":3,"stem":"石墨能導電、鑽石不導電，主要原因是？","A":"石墨有可自由移動的電子","B":"鑽石是化合物","C":"石墨比鑽石硬","D":"鑽石的碳比較少","answer":"A","explanation":"石墨每個碳只用部分電子鍵結，剩下的電子可以自由移動。","image":""},{"id":"C-45-01","isl":"C","lv":1,"stem":"正丁烷與異丁烷的分子式都是什麼？","A":"C₄H₁₀","B":"C₃H₈","C":"C₄H₈","D":"CH₄","answer":"A","explanation":"兩者都含 4 個碳、10 個氫，但原子連接的方式不同。","image":""},{"id":"C-45-02","isl":"C","lv":1,"stem":"同分異構物的物理性質通常有什麼特點？","A":"完全相同","B":"只有質量不同","C":"只有顏色不同","D":"有差異","answer":"D","explanation":"結構不同，所以熔點、沸點等性質多半不同。","image":""},{"id":"C-45-03","isl":"C","lv":2,"stem":"同分異構物之間，下列哪一項相同？","A":"結構","B":"密度","C":"分子式","D":"沸點","answer":"C","explanation":"同分異構物的分子式相同。","image":""},{"id":"C-45-04","isl":"C","lv":2,"stem":"乙醇和甲醚的主要差別在哪裡？","A":"原子的數目","B":"原子的種類","C":"原子的連接方式","D":"分子量","answer":"C","explanation":"兩者分子式都是 C₂H₆O，但原子連接方式不同。","image":""},{"id":"C-45-05","isl":"C","lv":3,"stem":"下列哪一種物質的分子量與乙醇（C₂H₆O）相同？","A":"水（H₂O）","B":"甲醚（C₂H₆O）","C":"乙烷（C₂H₆）","D":"甲醇（CH₄O）","answer":"B","explanation":"甲醚與乙醇是同分異構物，分子式相同，所以分子量也相同。","image":""},{"id":"C-46-01","isl":"C","lv":1,"stem":"下列哪一種物質的沸點最高？","A":"氧氣","B":"水","C":"氫氣","D":"氮氣","answer":"B","explanation":"水在一大氣壓下 100℃ 才沸騰，其他三種都是極低溫才沸騰的氣體。","image":""},{"id":"C-46-02","isl":"C","lv":1,"stem":"某物質在室溫下是氣態，表示它的沸點？","A":"高於室溫","B":"低於室溫","C":"等於 100℃","D":"無法判斷","answer":"B","explanation":"沸點低於室溫，常溫下就是氣態。","image":""},{"id":"C-46-03","isl":"C","lv":2,"stem":"乙醇沸點 78℃，甲醚沸點 －24℃，在室溫 25℃ 時，甲醚是？","A":"液體","B":"無法判斷","C":"氣體","D":"固體","answer":"C","explanation":"室溫高於甲醚的沸點，所以是氣體。","image":""},{"id":"C-46-04","isl":"C","lv":2,"stem":"沸點愈高，通常表示分子間的吸引力？","A":"不變","B":"沒有關係","C":"愈強","D":"愈弱","answer":"C","explanation":"分子間吸引力大，要更高溫度才能讓分子分開成氣體。","image":""},{"id":"C-46-05","isl":"C","lv":3,"stem":"A 的沸點 100℃，B 的沸點 －183℃，在 25℃ 時，A 和 B 的狀態依序是？","A":"固態、氣態","B":"液態、氣態","C":"液態、液態","D":"氣態、液態","answer":"B","explanation":"25℃ 高於 B 的沸點，低於 A 的沸點，B 是氣體，A 是液體。","image":""},{"id":"C-47-01","isl":"C","lv":1,"stem":"下列哪一項既不是元素也不是化合物？","A":"空氣","B":"氧氣","C":"水","D":"鐵","answer":"A","explanation":"空氣由多種物質混合而成，是混合物。","image":""},{"id":"C-47-02","isl":"C","lv":1,"stem":"銅是由銅原子直接組成的，銅屬於？","A":"混合物","B":"化合物","C":"元素","D":"溶液","answer":"C","explanation":"只含一種原子的純物質稱為元素。","image":""},{"id":"C-47-03","isl":"C","lv":2,"stem":"CO 與 CO₂ 都由碳和氧組成，性質卻不同，主要原因是？","A":"原子個數比不同","B":"碳原子不同","C":"氧原子不同","D":"顏色不同","answer":"A","explanation":"原子個數比不同，成為不同的化合物。","image":""},{"id":"C-47-04","isl":"C","lv":2,"stem":"下列哪一組物質全部都是元素？","A":"氮、二氧化碳、銅","B":"水、氧、鐵","C":"氧、氮、鐵","D":"鹽、氫、鋁","answer":"C","explanation":"氧、氮、鐵都只含一種原子，是元素。","image":""},{"id":"C-47-05","isl":"C","lv":3,"stem":"某物質加熱後分解成兩種新的物質，這種物質是？","A":"化合物","B":"都有可能","C":"元素","D":"混合物","answer":"A","explanation":"元素不能再分解成其他物質，能分解成兩種以上新物質的是化合物。","image":""},{"id":"C-48-01","isl":"C","lv":1,"stem":"要準確量取一定體積的液體，最適合用哪一種器材？","A":"燒杯","B":"蒸發皿","C":"試管","D":"量筒","answer":"D","explanation":"量筒有刻度，可用來量取液體體積。","image":""},{"id":"C-48-02","isl":"C","lv":1,"stem":"蒸發結晶時，盛放溶液加熱的器材是？","A":"量筒","B":"漏斗","C":"滴管","D":"蒸發皿","answer":"D","explanation":"蒸發皿口寬而淺，適合蒸發液體。","image":""},{"id":"C-48-03","isl":"C","lv":2,"stem":"用試管加熱液體時，液體量不宜超過試管的？","A":"三分之一","B":"三分之二","C":"全滿","D":"四分之三","answer":"A","explanation":"液體太多，沸騰時容易噴出。","image":""},{"id":"C-48-04","isl":"C","lv":2,"stem":"取用粉末狀藥品，通常使用什麼器材？","A":"滴管","B":"手","C":"鑷子","D":"藥匙","answer":"D","explanation":"粉末用藥匙取，避免手直接接觸藥品。","image":""},{"id":"C-48-05","isl":"C","lv":3,"stem":"酒精燈用完要熄滅時，正確的方法是？","A":"用燈蓋蓋熄","B":"加水澆熄","C":"用嘴吹熄","D":"直接倒掉酒精","answer":"A","explanation":"蓋上燈蓋讓火焰缺氧而熄滅，用嘴吹容易引燃燈內酒精。","image":""},{"id":"C-49-01","isl":"C","lv":1,"stem":"進行化學實驗前，應該先做什麼？","A":"把藥品混在一起","B":"直接開始","C":"穿實驗衣、戴護目鏡","D":"先喝水","answer":"C","explanation":"保護眼睛與身體，是實驗最基本的安全原則。","image":""},{"id":"C-49-02","isl":"C","lv":1,"stem":"要聞藥品或氣體的氣味，正確的方法是？","A":"用舌頭嘗","B":"直接湊近深吸","C":"用力吸入","D":"用手搧動氣味到鼻子","answer":"D","explanation":"用手輕輕搧向鼻子，可避免吸入過多有害氣體。","image":""},{"id":"C-49-03","isl":"C","lv":2,"stem":"實驗用剩的藥品，應該怎麼處理？","A":"帶回家","B":"倒回原瓶","C":"倒進水槽","D":"放入老師指定的回收容器","answer":"D","explanation":"剩餘藥品倒回原瓶會污染，也不能隨便倒掉。","image":""},{"id":"C-49-04","isl":"C","lv":2,"stem":"要在酒精燈中添加酒精，下列做法何者正確？","A":"用嘴吹熄再加","B":"點著火直接倒","C":"邊燃燒邊添加","D":"熄火後用漏斗添加","answer":"D","explanation":"燈火未熄時添加酒精，容易引起火災。","image":""},{"id":"C-49-05","isl":"C","lv":3,"stem":"實驗中不小心打破玻璃器材，下列做法何者最恰當？","A":"丟進一般垃圾桶","B":"告知老師，用掃具清理","C":"不理它","D":"用手撿起碎片","answer":"B","explanation":"玻璃碎片很鋒利，要用掃具清理並請老師處理。","image":""},{"id":"D-01-01","isl":"D","lv":1,"stem":"目鏡 10×、物鏡 40×，顯微鏡的放大倍率是？","A":"400 倍","B":"50 倍","C":"4 倍","D":"30 倍","answer":"A","explanation":"放大倍率＝10×40＝400 倍。","image":""},{"id":"D-01-02","isl":"D","lv":1,"stem":"觀察洋蔥表皮細胞時，常用哪一種染液讓細胞核更清楚？","A":"石灰水","B":"酚酞","C":"本氏液","D":"碘液","answer":"D","explanation":"洋蔥表皮細胞常用碘液染色；口腔皮膜細胞用亞甲藍液。","image":""},{"id":"D-01-03","isl":"D","lv":2,"stem":"由低倍物鏡換成高倍物鏡後，視野中的變化何者正確？","A":"視野變亮、細胞數目變多","B":"視野範圍變大","C":"視野變暗、細胞看起來變大","D":"細胞看起來變小","answer":"C","explanation":"高倍：視野變暗、範圍變小、細胞變大、數目變少。","image":""},{"id":"D-01-04","isl":"D","lv":2,"stem":"在顯微鏡下看到細胞位在視野的右下方，要把它移到中央，玻片應該往哪裡移？","A":"左上方","B":"右下方","C":"左下方","D":"右上方","answer":"B","explanation":"像上下左右顛倒，影像在哪裡，玻片就往哪個方向移。","image":""},{"id":"D-01-05","isl":"D","lv":3,"stem":"使用高倍物鏡時，只能用細調節輪微調，主要原因是？","A":"高倍物鏡離玻片很近，用粗調節輪容易壓破玻片","B":"細調節輪比較省力","C":"粗調節輪只能往上調","D":"高倍時影像不會顛倒","answer":"A","explanation":"高倍物鏡較長，離玻片很近。","image":""},{"id":"D-02-01","isl":"D","lv":1,"stem":"細胞中含有遺傳物質、控制生命活動的構造是？","A":"細胞膜","B":"液胞","C":"細胞核","D":"細胞壁","answer":"C","explanation":"細胞核含遺傳物質。","image":""},{"id":"D-02-02","isl":"D","lv":1,"stem":"下列哪一個構造是植物細胞有、動物細胞沒有的？","A":"細胞膜","B":"細胞壁","C":"細胞核","D":"粒線體","answer":"B","explanation":"細胞壁在細胞膜外，只有植物細胞有。","image":""},{"id":"D-02-03","isl":"D","lv":2,"stem":"能進行呼吸作用、提供細胞能量的構造是？","A":"粒線體","B":"葉綠體","C":"液胞","D":"細胞壁","answer":"A","explanation":"粒線體進行呼吸作用，動植物細胞都有。","image":""},{"id":"D-02-04","isl":"D","lv":2,"stem":"在顯微鏡下觀察洋蔥表皮細胞，通常看不到下列哪一個構造？","A":"細胞壁","B":"細胞核","C":"細胞膜的位置","D":"葉綠體","answer":"D","explanation":"洋蔥表皮細胞沒有葉綠體。","image":""},{"id":"D-02-05","isl":"D","lv":3,"stem":"「細胞是組成生物體的基本單位」，下列敘述何者最能說明這句話？","A":"細胞都一樣大","B":"細胞都有細胞壁","C":"生物體都是由細胞構成的，單細胞生物一個細胞就能獨立生活","D":"所有細胞都會行光合作用","answer":"C","explanation":"所有生物都由細胞組成，細胞能表現生命現象。","image":""},{"id":"D-03-01","isl":"D","lv":1,"stem":"把一滴紅墨水滴入靜止的水中，紅色慢慢散開到整杯水，這種現象稱為？","A":"擴散","B":"蒸發","C":"凝結","D":"過濾","answer":"A","explanation":"分子由濃度高往濃度低移動。","image":""},{"id":"D-03-02","isl":"D","lv":1,"stem":"下列哪一種情況，紅墨水在水中擴散得最快？","A":"5°C 的冷水","B":"25°C 的室溫水","C":"都一樣快","D":"60°C 的熱水","answer":"D","explanation":"溫度越高，分子運動越快，擴散越快。","image":""},{"id":"D-03-03","isl":"D","lv":2,"stem":"把裝有澱粉液的透析袋放入碘液中，一段時間後袋內變成藍黑色、袋外沒有變色，這表示？","A":"澱粉分子跑出袋外","B":"透析袋會吸收顏色","C":"碘分子進入袋內，澱粉分子出不來","D":"碘液和水發生滲透","answer":"C","explanation":"碘分子小，可以穿過透析袋；澱粉分子大，不能通過。","image":""},{"id":"D-03-04","isl":"D","lv":2,"stem":"把蘿蔔條泡在濃鹽水中一段時間，蘿蔔條會變得如何？","A":"變硬挺，質量增加","B":"變軟，質量減少","C":"完全不變","D":"變硬挺，質量減少","answer":"B","explanation":"外面鹽水較濃，細胞內的水滲透出去，細胞失水變軟。","image":""},{"id":"D-03-05","isl":"D","lv":3,"stem":"把紅血球放入清水中，紅血球脹大甚至破裂，原因是？","A":"清水的水分子滲透進入紅血球","B":"水由紅血球內往外滲透","C":"紅血球把鹽排出","D":"紅血球進行光合作用","answer":"A","explanation":"紅血球內較濃，水往濃的一側（細胞內）移動。","image":""},{"id":"D-04-01","isl":"D","lv":1,"stem":"形態相似、功能相同的細胞聚集在一起，形成？","A":"器官","B":"器官系統","C":"組織","D":"個體","answer":"C","explanation":"組織的定義。","image":""},{"id":"D-04-02","isl":"D","lv":1,"stem":"下列何者屬於「器官」這個層次？","A":"紅血球","B":"心臟","C":"肌肉組織","D":"消化系統","answer":"B","explanation":"心臟由多種組織組成，是器官。","image":""},{"id":"D-04-03","isl":"D","lv":2,"stem":"下列哪一個組成層次，植物體沒有？","A":"器官系統","B":"細胞","C":"組織","D":"器官","answer":"A","explanation":"植物：細胞→組織→器官→個體。","image":""},{"id":"D-04-04","isl":"D","lv":2,"stem":"下列哪一組由小到大排列正確？","A":"細胞→器官→組織→個體","B":"組織→細胞→器官→器官系統","C":"器官→組織→細胞→個體","D":"細胞→組織→器官→器官系統","answer":"D","explanation":"動物體由小到大：細胞→組織→器官→器官系統→個體。","image":""},{"id":"D-04-05","isl":"D","lv":3,"stem":"一片葉子屬於植物體的哪一個層次？","A":"細胞","B":"組織","C":"器官","D":"器官系統","answer":"C","explanation":"葉由表皮、葉肉、維管束等組織組成，是器官。","image":""},{"id":"D-05-01","isl":"D","lv":1,"stem":"細胞分裂最主要的結果是？","A":"細胞數目增加","B":"細胞變成組織","C":"細胞核消失","D":"染色體數目加倍","answer":"A","explanation":"一個細胞分裂成兩個。","image":""},{"id":"D-05-02","isl":"D","lv":1,"stem":"人體的皮膚細胞有 46 條染色體，經細胞分裂後，每個子細胞有幾條？","A":"23 條","B":"92 條","C":"0 條","D":"46 條","answer":"D","explanation":"子細胞染色體數目和原來相同。","image":""},{"id":"D-05-03","isl":"D","lv":2,"stem":"細胞分裂前，細胞核裡的遺傳物質會先？","A":"消失","B":"移到細胞膜外","C":"複製","D":"變成葉綠體","answer":"C","explanation":"先複製，才能平均分給兩個子細胞。","image":""},{"id":"D-05-04","isl":"D","lv":2,"stem":"觀察植物的細胞分裂，最適合選用洋蔥的哪一部分？","A":"葉","B":"根尖","C":"鱗葉表皮","D":"花","answer":"B","explanation":"根尖的細胞分裂旺盛。","image":""},{"id":"D-05-05","isl":"D","lv":3,"stem":"把細胞分裂的過程排序：甲.細胞質分開 乙.遺傳物質複製 丙.染色體排在中央 丁.染色體分開移向兩端","A":"乙→丙→丁→甲","B":"甲→乙→丙→丁","C":"丙→乙→甲→丁","D":"乙→甲→丙→丁","answer":"A","explanation":"複製→排中央→分開→細胞質分開。","image":""},{"id":"D-06-01","isl":"D","lv":1,"stem":"下列哪一個器官是食物會經過的消化道？","A":"肝臟","B":"胰臟","C":"小腸","D":"唾腺","answer":"C","explanation":"肝臟、胰臟、唾腺是消化腺。","image":""},{"id":"D-06-02","isl":"D","lv":1,"stem":"人體消化和吸收養分最主要的場所是？","A":"口腔","B":"小腸","C":"胃","D":"大腸","answer":"B","explanation":"小腸有絨毛，消化液最多。","image":""},{"id":"D-06-03","isl":"D","lv":2,"stem":"關於膽汁的敘述，何者正確？","A":"能把脂肪乳化成小油滴","B":"由膽囊製造","C":"含有分解脂肪的酵素","D":"在胃中作用","answer":"A","explanation":"膽汁由肝臟分泌、膽囊儲存，不含酵素。","image":""},{"id":"D-06-04","isl":"D","lv":2,"stem":"小腸內壁有許多皺褶和絨毛，主要的好處是？","A":"讓食物走得比較快","B":"分泌膽汁","C":"儲存糞便","D":"增加吸收養分的表面積","answer":"D","explanation":"表面積大，吸收效率高。","image":""},{"id":"D-06-05","isl":"D","lv":3,"stem":"在試管中加入澱粉液和唾液，放在 37°C 水中 10 分鐘後，加入本氏液加熱出現磚紅色沉澱，表示？","A":"唾液含有蛋白質","B":"澱粉沒有變化","C":"唾液把澱粉分解成醣類","D":"本氏液把澱粉分解了","answer":"C","explanation":"本氏液檢驗出葡萄糖等醣類，表示唾液能分解澱粉。","image":""},{"id":"D-07-01","isl":"D","lv":1,"stem":"心臟中肌肉壁最厚、把血液送往全身的腔室是？","A":"左心室","B":"右心房","C":"右心室","D":"左心房","answer":"A","explanation":"左心室要把血液壓到全身，壁最厚。","image":""},{"id":"D-07-02","isl":"D","lv":1,"stem":"心臟內防止血液倒流的構造是？","A":"微血管","B":"肺泡","C":"絨毛","D":"瓣膜","answer":"D","explanation":"瓣膜只讓血液往一個方向流。","image":""},{"id":"D-07-03","isl":"D","lv":2,"stem":"在手腕上量到的脈搏，主要反映的是？","A":"呼吸的次數","B":"靜脈的跳動","C":"心跳的次數","D":"肺泡的伸縮","answer":"C","explanation":"脈搏次數和心跳次數相同。","image":""},{"id":"D-07-04","isl":"D","lv":2,"stem":"血液和身體細胞交換養分、氧氣與廢物，主要發生在？","A":"動脈","B":"微血管","C":"靜脈","D":"心房","answer":"B","explanation":"微血管的管壁只有一層細胞。","image":""},{"id":"D-07-05","isl":"D","lv":3,"stem":"運動後心跳變快，主要的意義是？","A":"讓血液更快把氧和養分送到肌肉","B":"讓心臟休息","C":"減少血液的量","D":"讓靜脈變成動脈","answer":"A","explanation":"肌肉需要更多氧和養分，心跳加快以增加輸送。","image":""},{"id":"D-08-01","isl":"D","lv":1,"stem":"血液中能攜帶氧氣的是？","A":"血漿","B":"白血球","C":"紅血球","D":"血小板","answer":"C","explanation":"紅血球含血紅素，能與氧結合。","image":""},{"id":"D-08-02","isl":"D","lv":1,"stem":"受傷流血時，能幫助血液凝固的是？","A":"紅血球","B":"血小板","C":"白血球","D":"血漿中的水","answer":"B","explanation":"血小板幫助凝血。","image":""},{"id":"D-08-03","isl":"D","lv":2,"stem":"肺循環的路徑何者正確？","A":"右心室→肺動脈→肺→肺靜脈→左心房","B":"左心室→主動脈→肺→右心房","C":"右心房→肺靜脈→肺→左心室","D":"左心房→肺動脈→肺→右心室","answer":"A","explanation":"肺循環由右心室出發，回到左心房。","image":""},{"id":"D-08-04","isl":"D","lv":2,"stem":"下列哪一條血管裡流的是充氧血？","A":"肺動脈","B":"上大靜脈","C":"下大靜脈","D":"肺靜脈","answer":"D","explanation":"肺靜脈把在肺部取得氧氣的血液送回左心房。","image":""},{"id":"D-08-05","isl":"D","lv":3,"stem":"一顆紅血球從右心室出發，最先會到達？","A":"全身的微血管","B":"左心室","C":"肺部的微血管","D":"主動脈","answer":"C","explanation":"右心室→肺動脈→肺部微血管。","image":""},{"id":"D-09-01","isl":"D","lv":1,"stem":"人體和外界交換氣體的主要場所是？","A":"肺泡","B":"氣管","C":"支氣管","D":"喉","answer":"A","explanation":"肺泡外包著微血管，進行氣體交換。","image":""},{"id":"D-09-02","isl":"D","lv":1,"stem":"吸氣時，橫膈和胸腔的變化是？","A":"橫膈上升，胸腔變小","B":"橫膈上升，胸腔變大","C":"橫膈不動","D":"橫膈下降，胸腔變大","answer":"D","explanation":"橫膈收縮下降，胸腔變大，空氣進入。","image":""},{"id":"D-09-03","isl":"D","lv":2,"stem":"在鐘形罩肺模型中，把底部的橡皮膜往下拉，氣球會？","A":"縮小","B":"不變","C":"脹大","D":"破掉","answer":"C","explanation":"橡皮膜（橫膈）下拉，罩內空間變大、氣壓變小，空氣進入氣球。","image":""},{"id":"D-09-04","isl":"D","lv":2,"stem":"肺泡中的氧氣進入血液，是靠哪一種方式？","A":"過濾","B":"擴散","C":"心臟壓送","D":"肌肉推擠","answer":"B","explanation":"氧由濃度高的肺泡擴散到濃度低的血液。","image":""},{"id":"D-09-05","isl":"D","lv":3,"stem":"對著澄清石灰水吹氣，石灰水變混濁，能說明？","A":"呼出的氣體中二氧化碳比空氣中多","B":"呼出的氣體中沒有氧","C":"呼出的氣體全部是二氧化碳","D":"石灰水會產生氧氣","answer":"A","explanation":"呼出的氣體二氧化碳較多，但大部分仍是氮氣。","image":""},{"id":"D-10-01","isl":"D","lv":1,"stem":"把芹菜插入紅墨水中，被染紅的部位主要是？","A":"表皮","B":"葉綠體","C":"維管束","D":"根毛","answer":"C","explanation":"紅墨水隨水在維管束（木質部）中上升。","image":""},{"id":"D-10-02","isl":"D","lv":1,"stem":"植物體中負責把水和礦物質由根往上運送的是？","A":"韌皮部","B":"木質部","C":"氣孔","D":"保衛細胞","answer":"B","explanation":"木質部運送根吸收的水和礦物質。","image":""},{"id":"D-10-03","isl":"D","lv":2,"stem":"植物葉片製造的養分，經由哪個構造運送到根部？","A":"韌皮部","B":"木質部","C":"氣孔","D":"根毛","answer":"A","explanation":"韌皮部運送葉片製造的養分，可以往下送到根部。","image":""},{"id":"D-10-04","isl":"D","lv":2,"stem":"下列哪一種植物，莖的維管束是散生的？","A":"向日葵","B":"朱槿","C":"綠豆","D":"玉米","answer":"D","explanation":"玉米是單子葉植物，維管束散生。","image":""},{"id":"D-10-05","isl":"D","lv":3,"stem":"用塑膠袋套住植物的葉片，一段時間後袋內出現水珠，這主要是因為？","A":"光合作用產生水","B":"根吸收太多水","C":"蒸散作用由氣孔散失水分","D":"塑膠袋產生水","answer":"C","explanation":"水由氣孔散失，是蒸散作用。","image":""},{"id":"D-11-01","isl":"D","lv":1,"stem":"雄蕊中能產生花粉粒的部位是？","A":"花藥","B":"花絲","C":"柱頭","D":"子房","answer":"A","explanation":"花藥產生花粉粒。","image":""},{"id":"D-11-02","isl":"D","lv":1,"stem":"雌蕊的哪一個部位內有胚珠？","A":"柱頭","B":"花柱","C":"花萼","D":"子房","answer":"D","explanation":"胚珠在子房內。","image":""},{"id":"D-11-03","isl":"D","lv":2,"stem":"關於花的生殖細胞，何者正確？","A":"花粉粒內有卵細胞","B":"子房就是卵細胞","C":"花粉粒內有精細胞，胚珠內有卵細胞","D":"花藥內有胚珠","answer":"C","explanation":"花粉粒內有精細胞；胚珠內有卵細胞。","image":""},{"id":"D-11-04","isl":"D","lv":2,"stem":"花粉從花藥傳到雌蕊柱頭上的過程稱為？","A":"受精","B":"授粉","C":"發芽","D":"蒸散","answer":"B","explanation":"授粉；精卵結合才是受精。","image":""},{"id":"D-11-05","isl":"D","lv":3,"stem":"受精後，花的哪些部位會分別發育成果實和種子？","A":"子房→果實，胚珠→種子","B":"胚珠→果實，子房→種子","C":"花瓣→果實，花藥→種子","D":"柱頭→果實，花絲→種子","answer":"A","explanation":"子房發育成果實，胚珠發育成種子。","image":""},{"id":"D-12-01","isl":"D","lv":1,"stem":"神經系統的基本單位是？","A":"肌肉細胞","B":"紅血球","C":"神經細胞","D":"脊髓","answer":"C","explanation":"神經細胞又稱神經元。","image":""},{"id":"D-12-02","isl":"D","lv":1,"stem":"下列何者屬於中樞神經？","A":"脊神經","B":"脊髓","C":"腦神經","D":"感覺神經","answer":"B","explanation":"中樞神經包括腦和脊髓。","image":""},{"id":"D-12-03","isl":"D","lv":2,"stem":"手碰到很燙的鍋子立刻縮回，這個反應的路徑何者正確？","A":"受器→感覺神經→脊髓→運動神經→動器","B":"動器→運動神經→大腦→感覺神經→受器","C":"受器→運動神經→大腦→感覺神經→動器","D":"大腦→受器→動器","answer":"A","explanation":"縮手反射由脊髓控制。","image":""},{"id":"D-12-04","isl":"D","lv":2,"stem":"騎腳踏車時維持身體平衡，主要靠腦的哪一部分？","A":"大腦","B":"腦幹","C":"脊髓","D":"小腦","answer":"D","explanation":"小腦協調動作、維持平衡。","image":""},{"id":"D-12-05","isl":"D","lv":3,"stem":"用「接住落下的尺」測反應時間，接住的位置離原本越遠，表示？","A":"反應時間越短","B":"尺掉得比較慢","C":"反應時間越長","D":"和反應時間無關","answer":"C","explanation":"尺落下的距離越長，表示越晚接到，反應時間越長。","image":""},{"id":"D-13-01","isl":"D","lv":1,"stem":"內分泌腺分泌的激素，主要經由什麼運送到全身？","A":"血液","B":"神經","C":"消化道","D":"淋巴結","answer":"A","explanation":"激素直接進入血液。","image":""},{"id":"D-13-02","isl":"D","lv":1,"stem":"能使血糖降低的激素是？","A":"生長激素","B":"甲狀腺素","C":"腎上腺素","D":"胰島素","answer":"D","explanation":"胰島素由胰臟的胰島分泌。","image":""},{"id":"D-13-03","isl":"D","lv":2,"stem":"吃完一大碗飯後，體內的變化何者正確？","A":"血糖降低，胰島素分泌增加","B":"血糖升高，胰島素分泌減少","C":"血糖升高，胰島素分泌增加","D":"血糖不變","answer":"C","explanation":"血糖升高時，胰島素分泌增加讓血糖回到正常。","image":""},{"id":"D-13-04","isl":"D","lv":2,"stem":"大熱天打完球，流了很多汗，這時身體的尿量通常會？","A":"增加","B":"減少","C":"不變","D":"變成紅色","answer":"B","explanation":"流汗失水，腎臟減少排尿以保留水分。","image":""},{"id":"D-13-05","isl":"D","lv":3,"stem":"想探討「運動對心跳的影響」，下列哪一個是操縱變因？","A":"運動的時間或強度","B":"心跳次數","C":"受測者的身高","D":"測量的時鐘","answer":"A","explanation":"操縱變因是實驗中刻意改變的因素；心跳次數是應變變因。","image":""},{"id":"D-14-01","isl":"D","lv":1,"stem":"人體抵抗病菌入侵的第一道防線是？","A":"白血球","B":"抗體","C":"皮膚","D":"血小板","answer":"C","explanation":"皮膚能阻擋細菌入侵。","image":""},{"id":"D-14-02","isl":"D","lv":1,"stem":"能吞噬侵入人體病菌的血球是？","A":"紅血球","B":"白血球","C":"血小板","D":"血漿","answer":"B","explanation":"白血球能吞噬病菌。","image":""},{"id":"D-14-03","isl":"D","lv":2,"stem":"淋巴結中的淋巴球主要能？","A":"產生抗體","B":"運送氧氣","C":"幫助凝血","D":"分泌膽汁","answer":"A","explanation":"淋巴球產生抗體，發揮免疫作用。","image":""},{"id":"D-14-04","isl":"D","lv":2,"stem":"關於抗體的敘述，何者正確？","A":"一種抗體能對付所有病菌","B":"抗體由紅血球產生","C":"抗體就是白血球","D":"抗體具有專一性，對付特定的病原體","answer":"D","explanation":"抗體只對付特定的病原體。","image":""},{"id":"D-14-05","isl":"D","lv":3,"stem":"接種流感疫苗可以預防流感，主要原理是？","A":"疫苗直接殺死所有細菌","B":"疫苗增加紅血球","C":"讓身體先產生對抗病原體的抗體","D":"疫苗讓皮膚變厚","answer":"C","explanation":"疫苗讓免疫系統先「認識」病原體，下次能更快反應。","image":""},{"id":"D-21-01","isl":"D","lv":1,"stem":"植物細胞有、動物細胞沒有的構造是？","A":"細胞膜","B":"粒線體","C":"細胞核","D":"細胞壁","answer":"D","explanation":"植物細胞有細胞壁，位在細胞膜外，可支持保護細胞。","image":""},{"id":"D-21-02","isl":"D","lv":1,"stem":"控制物質進出細胞的構造是？","A":"細胞膜","B":"葉綠體","C":"細胞核","D":"粒線體","answer":"A","explanation":"細胞膜具選擇性，控制物質的進出。","image":""},{"id":"D-21-03","isl":"D","lv":2,"stem":"用顯微鏡觀察洋蔥表皮細胞，看不到下列哪一種構造？","A":"葉綠體","B":"細胞壁","C":"細胞核","D":"液泡","answer":"A","explanation":"洋蔥表皮細胞不見光，沒有葉綠體。","image":""},{"id":"D-21-04","isl":"D","lv":2,"stem":"植物細胞中，儲存水分與養分的大型構造是？","A":"細胞核","B":"葉綠體","C":"液泡","D":"粒線體","answer":"C","explanation":"成熟的植物細胞有大型液泡，儲存水分、色素和養分。","image":""},{"id":"D-21-05","isl":"D","lv":3,"stem":"下列哪一種細胞的粒線體數量最可能較多？","A":"心肌細胞","B":"洋蔥表皮細胞","C":"死亡的細胞","D":"成熟紅血球","answer":"A","explanation":"心肌需要持續收縮，耗能多，所以粒線體多。","image":""},{"id":"D-22-01","isl":"D","lv":1,"stem":"唾液中的酵素主要能分解哪一種養分？","A":"維生素","B":"澱粉","C":"蛋白質","D":"脂肪","answer":"B","explanation":"唾液澱粉酶可以把澱粉分解成麥芽糖。","image":""},{"id":"D-22-02","isl":"D","lv":1,"stem":"人體消化並吸收養分最主要的器官是？","A":"胃","B":"大腸","C":"小腸","D":"食道","answer":"C","explanation":"小腸很長，內壁有許多絨毛，是消化吸收的主要場所。","image":""},{"id":"D-22-03","isl":"D","lv":2,"stem":"肝臟製造的膽汁，作用是？","A":"殺死病毒","B":"分解蛋白質","C":"分解澱粉","D":"幫助脂肪消化","answer":"D","explanation":"膽汁能把脂肪乳化成小油滴，幫助脂肪的消化。","image":""},{"id":"D-22-04","isl":"D","lv":2,"stem":"胃液中的鹽酸，功能之一是？","A":"殺死食物中的細菌","B":"吸收水分","C":"分解澱粉","D":"分解脂肪","answer":"A","explanation":"鹽酸提供酸性環境並殺死大部分隨食物進入的細菌。","image":""},{"id":"D-22-05","isl":"D","lv":3,"stem":"饅頭在口中愈嚼愈甜，是因為？","A":"澱粉被分解成麥芽糖","B":"蛋白質被分解","C":"水分蒸發","D":"脂肪被分解","answer":"A","explanation":"唾液澱粉酶把澱粉分解成有甜味的麥芽糖。","image":""},{"id":"D-23-01","isl":"D","lv":1,"stem":"血液中，幫助傷口凝血的是？","A":"血小板","B":"水分","C":"紅血球","D":"白血球","answer":"A","explanation":"血小板能凝聚，幫助止血。","image":""},{"id":"D-23-02","isl":"D","lv":1,"stem":"血管中管壁最薄、負責物質交換的是？","A":"靜脈","B":"微血管","C":"動脈","D":"主動脈","answer":"B","explanation":"微血管管壁只有一層細胞，利於物質交換。","image":""},{"id":"D-23-03","isl":"D","lv":2,"stem":"靜脈中有瓣膜，作用是？","A":"防止血液倒流","B":"加快血流","C":"儲存血液","D":"增加血壓","answer":"A","explanation":"靜脈壓力低，瓣膜可避免血液倒流回去。","image":""},{"id":"D-23-04","isl":"D","lv":2,"stem":"體循環中，血液由心臟的哪個腔室送出？","A":"右心室","B":"左心室","C":"左心房","D":"右心房","answer":"B","explanation":"左心室壁最厚，把血液送往全身。","image":""},{"id":"D-23-05","isl":"D","lv":3,"stem":"肺循環中，由心臟送往肺的血液特徵是？","A":"只有血漿","B":"含氧量高","C":"完全沒有血球","D":"含氧量低","answer":"D","explanation":"肺動脈運送的是全身回來、含氧量低的血液，到肺換氣。","image":""},{"id":"D-24-01","isl":"D","lv":1,"stem":"吸氣時，空氣進入肺部的順序是？","A":"咽、鼻、喉、氣管、肺","B":"鼻、喉、咽、氣管、肺","C":"鼻、氣管、喉、咽、肺","D":"鼻、咽、喉、氣管、肺","answer":"D","explanation":"空氣依序經過鼻、咽、喉、氣管、支氣管，最後到肺。","image":""},{"id":"D-24-02","isl":"D","lv":1,"stem":"肺中進行氣體交換的構造是？","A":"氣管","B":"肺泡","C":"橫膈","D":"支氣管","answer":"B","explanation":"肺泡壁薄，周圍布滿微血管，是氣體交換的場所。","image":""},{"id":"D-24-03","isl":"D","lv":2,"stem":"吸氣時，橫膈會怎麼變化？","A":"先升後降","B":"不變","C":"上升","D":"下降","answer":"D","explanation":"吸氣時肋骨上提、橫膈下降，胸腔變大。","image":""},{"id":"D-24-04","isl":"D","lv":2,"stem":"吸氣時，胸腔體積與肺內壓力的變化是？","A":"兩者都變小","B":"體積變小、壓力變大","C":"兩者都變大","D":"體積變大、壓力變小","answer":"D","explanation":"胸腔變大，肺內壓力小於外界，空氣就被吸入。","image":""},{"id":"D-24-05","isl":"D","lv":3,"stem":"肺泡適合氣體交換，是因為？","A":"壁很薄且布滿微血管","B":"不含任何血管","C":"壁厚且堅硬","D":"表面完全乾燥","answer":"A","explanation":"壁薄、表面濕潤且有微血管，利於氧與二氧化碳擴散。","image":""},{"id":"D-25-01","isl":"D","lv":1,"stem":"人體製造尿液的器官是？","A":"膀胱","B":"輸尿管","C":"肝臟","D":"腎臟","answer":"D","explanation":"腎臟過濾血液，形成尿液。","image":""},{"id":"D-25-02","isl":"D","lv":1,"stem":"尿液在排出前暫時儲存在？","A":"輸尿管","B":"尿道","C":"腎臟","D":"膀胱","answer":"D","explanation":"膀胱可儲存尿液。","image":""},{"id":"D-25-03","isl":"D","lv":2,"stem":"腎臟的主要功能是？","A":"製造膽汁","B":"過濾血液中的廢物","C":"儲存血液","D":"消化食物","answer":"B","explanation":"腎臟過濾血液，排出廢物並調節體內水分和鹽分。","image":""},{"id":"D-25-04","isl":"D","lv":2,"stem":"蛋白質分解後產生的含氮廢物，主要形成？","A":"尿素","B":"二氧化碳","C":"葡萄糖","D":"膽汁","answer":"A","explanation":"含氮廢物主要變成尿素，由腎臟隨尿液排出。","image":""},{"id":"D-25-05","isl":"D","lv":3,"stem":"皮膚排汗除了排出少量廢物，還有哪個重要功能？","A":"消化食物","B":"儲存養分","C":"製造尿素","D":"調節體溫","answer":"D","explanation":"汗水蒸發帶走熱量，可以調節體溫。","image":""},{"id":"D-26-01","isl":"D","lv":1,"stem":"植物吸收水分主要靠哪一個構造？","A":"莖","B":"花瓣","C":"根毛","D":"葉片","answer":"C","explanation":"根毛增加吸收面積，主要吸收水分和礦物質。","image":""},{"id":"D-26-02","isl":"D","lv":1,"stem":"葉片散失水蒸氣的出入口是？","A":"根毛","B":"氣孔","C":"篩管","D":"導管","answer":"B","explanation":"氣孔由兩個保衛細胞圍成，是水蒸氣與氣體的出入口。","image":""},{"id":"D-26-03","isl":"D","lv":2,"stem":"把水和礦物質由根往上運送的管道是？","A":"保衛細胞","B":"篩管","C":"氣孔","D":"導管","answer":"D","explanation":"導管位於木質部，向上運輸水和礦物質。","image":""},{"id":"D-26-04","isl":"D","lv":2,"stem":"把葉片製造的養分運送到全身的管道是？","A":"導管","B":"氣孔","C":"篩管","D":"根毛","answer":"C","explanation":"篩管位於韌皮部，運送光合作用產生的養分。","image":""},{"id":"D-26-05","isl":"D","lv":3,"stem":"下列哪一種環境蒸散作用最旺盛？","A":"低溫、潮濕、無風","B":"陰暗、潮濕","C":"下雨、無風","D":"高溫、乾燥、有風","answer":"D","explanation":"溫度高、空氣乾燥、有風時，水分散失得最快。","image":""},{"id":"D-27-01","isl":"D","lv":1,"stem":"神經系統的中樞是？","A":"神經與肌肉","B":"腦與脊髓","C":"腦與感覺器官","D":"脊髓與肌肉","answer":"B","explanation":"腦和脊髓組成中樞神經系統。","image":""},{"id":"D-27-02","isl":"D","lv":1,"stem":"把感覺訊息傳到中樞的神經稱為？","A":"感覺神經","B":"運動神經","C":"自主神經","D":"血管","answer":"A","explanation":"感覺神經把訊息傳進中樞，運動神經把命令傳出去。","image":""},{"id":"D-27-03","isl":"D","lv":2,"stem":"手碰到熱水立刻縮回，這個反射的控制中樞主要在？","A":"脊髓","B":"小腦","C":"大腦","D":"眼睛","answer":"A","explanation":"縮手反射由脊髓控制，速度快，不必先經過大腦思考。","image":""},{"id":"D-27-04","isl":"D","lv":2,"stem":"維持身體平衡與協調動作，主要由哪一部分負責？","A":"小腦","B":"耳殼","C":"大腦","D":"脊髓","answer":"A","explanation":"小腦負責平衡與協調。","image":""},{"id":"D-27-05","isl":"D","lv":3,"stem":"縮手反射中，訊息傳遞的順序是？","A":"感覺神經→脊髓→運動神經","B":"感覺神經→大腦→運動神經","C":"運動神經→脊髓→感覺神經","D":"脊髓→感覺神經→運動神經","answer":"A","explanation":"訊息由感覺神經送入脊髓，再經運動神經傳到肌肉。","image":""},{"id":"D-28-01","isl":"D","lv":1,"stem":"血糖過高時，胰臟分泌哪一種激素使血糖下降？","A":"腎上腺素","B":"生長激素","C":"胰島素","D":"甲狀腺素","answer":"C","explanation":"胰島素能促使血糖進入細胞，降低血糖。","image":""},{"id":"D-28-02","isl":"D","lv":1,"stem":"生長激素由哪一個腺體分泌？","A":"腦下垂體","B":"甲狀腺","C":"腎上腺","D":"胰臟","answer":"A","explanation":"腦下垂體分泌生長激素，影響身高。","image":""},{"id":"D-28-03","isl":"D","lv":2,"stem":"夏天流汗、冬天顫抖，這些反應主要是為了維持？","A":"視力正常","B":"血壓升高","C":"體溫恆定","D":"體重增加","answer":"C","explanation":"人體會調節產熱與散熱，維持體溫恆定。","image":""},{"id":"D-28-04","isl":"D","lv":2,"stem":"遇到緊急危險時，心跳加快，與哪一種激素有關？","A":"生長激素","B":"腎上腺素","C":"膽汁","D":"胰島素","answer":"B","explanation":"腎上腺素使心跳加快、呼吸加深，讓身體準備應變。","image":""},{"id":"D-28-05","isl":"D","lv":3,"stem":"糖尿病患者血糖偏高，可能是因為？","A":"甲狀腺素過多","B":"胰島素不足或作用不良","C":"生長激素不足","D":"腎上腺素過多","answer":"B","explanation":"胰島素無法有效降低血糖，血糖就會偏高。","image":""},{"id":"E-01-01","isl":"E","lv":1,"stem":"下列何者是基本物理量？","A":"質量","B":"密度","C":"體積","D":"速度","answer":"A","explanation":"時間、長度、質量是基本量；密度、體積、速度都由基本量算出。","image":""},{"id":"E-01-02","isl":"E","lv":1,"stem":"用最小刻度 1 mm 的尺量書長，下列記錄何者合理？","A":"21 cm","B":"21.3 cm","C":"21.352 cm","D":"21.35 cm","answer":"D","explanation":"讀到 mm（21.3 cm）再估計一位，所以是 21.35 cm。","image":""},{"id":"E-01-03","isl":"E","lv":2,"stem":"金屬塊質量 54 g、體積 20 cm³，密度是多少？","A":"0.37 g/cm³","B":"34 g/cm³","C":"2.7 g/cm³","D":"1080 g/cm³","answer":"C","explanation":"密度 = 54 ÷ 20 = 2.7 g/cm³。","image":""},{"id":"E-01-04","isl":"E","lv":2,"stem":"石頭放進量筒，水位由 30 mL 升到 42 mL，石頭的體積是？","A":"30 cm³","B":"12 cm³","C":"42 cm³","D":"72 cm³","answer":"B","explanation":"42 − 30 = 12 mL，1 mL = 1 cm³。","image":""},{"id":"E-01-05","isl":"E","lv":3,"stem":"均勻的木塊切成兩半，下列何者不變？","A":"密度","B":"質量","C":"體積","D":"重量","answer":"A","explanation":"密度是物質的特性，切開後質量、體積、重量都變一半，密度不變。","image":""},{"id":"E-02-01","isl":"E","lv":1,"stem":"描述一張紙的厚度，最適合用哪個單位？","A":"公里","B":"公尺","C":"毫米","D":"光年","answer":"C","explanation":"一張紙約 0.1 mm，用毫米最合適。","image":""},{"id":"E-02-02","isl":"E","lv":1,"stem":"下列何者最小？","A":"細胞","B":"原子","C":"螞蟻","D":"沙粒","answer":"B","explanation":"細胞由大量原子組成，原子最小。","image":""},{"id":"E-02-03","isl":"E","lv":2,"stem":"1 公尺等於多少毫米？","A":"1000","B":"10","C":"100","D":"10000","answer":"A","explanation":"1 m = 100 cm = 1000 mm。","image":""},{"id":"E-02-04","isl":"E","lv":2,"stem":"要測一張紙的厚度，哪個方法比較準確？","A":"直接用尺量一張","B":"用手感估計","C":"用量筒","D":"量 100 張的總厚度再除以 100","answer":"D","explanation":"累積測量再平均，可以減少誤差。","image":""},{"id":"E-02-05","isl":"E","lv":3,"stem":"「光年」是哪一種量的單位？","A":"時間","B":"速度","C":"距離","D":"質量","answer":"C","explanation":"光年是光在一年內走的距離，是長度（距離）單位。","image":""},{"id":"E-03-01","isl":"E","lv":1,"stem":"下列何者不是力的作用效果？","A":"改變物體質量","B":"改變運動狀態","C":"改變形狀","D":"使物體轉動","answer":"A","explanation":"質量不會因為受力而改變。","image":""},{"id":"E-03-02","isl":"E","lv":1,"stem":"下列何者是力的單位？","A":"公斤","B":"公尺","C":"秒","D":"公斤重","answer":"D","explanation":"公斤是質量單位，公斤重才是力的單位。","image":""},{"id":"E-03-03","isl":"E","lv":2,"stem":"推門時，推哪裡最容易把門推開？","A":"靠近門軸","B":"門的中間","C":"離門軸最遠的門把處","D":"都一樣","answer":"C","explanation":"離轉軸越遠，轉動效果越大。","image":""},{"id":"E-03-04","isl":"E","lv":2,"stem":"用同樣大小的力水平推地上的高箱子，推哪裡最容易讓箱子翻倒？","A":"底部","B":"頂部","C":"一樣","D":"都不會翻","answer":"B","explanation":"作用點越高，越容易繞著底邊轉動而翻倒。","image":""},{"id":"E-03-05","isl":"E","lv":3,"stem":"冰上滑出去的冰壺越滑越慢，主要原因是？","A":"冰面摩擦力使它減速","B":"沒人推它","C":"它的質量變小","D":"重力消失","answer":"A","explanation":"受到摩擦力，運動狀態才會改變（減速）。","image":""},{"id":"E-04-01","isl":"E","lv":1,"stem":"推桌子但桌子沒動，桌子受到的摩擦力是？","A":"動摩擦力","B":"沒有摩擦力","C":"靜摩擦力","D":"浮力","answer":"C","explanation":"沒有滑動，受到的是靜摩擦力。","image":""},{"id":"E-04-02","isl":"E","lv":1,"stem":"摩擦力的方向和物體運動（或想要運動）的方向？","A":"相同","B":"相反","C":"垂直","D":"無關","answer":"B","explanation":"摩擦力阻礙相對運動，方向相反。","image":""},{"id":"E-04-03","isl":"E","lv":2,"stem":"用 3 kgw 水平推箱子沒推動，箱子受到的靜摩擦力是？","A":"3 kgw","B":"0","C":"小於 3 kgw","D":"大於 3 kgw","answer":"A","explanation":"箱子靜止，推力與靜摩擦力平衡。","image":""},{"id":"E-04-04","isl":"E","lv":2,"stem":"下列哪種做法可以增加摩擦力？","A":"在輪軸加潤滑油","B":"用滾輪搬重物","C":"把冰刀磨光","D":"鞋底刻紋路","answer":"D","explanation":"接觸面變粗糙，摩擦力增加。","image":""},{"id":"E-04-05","isl":"E","lv":3,"stem":"拉力從零慢慢增加，箱子由靜止到開始滑動，摩擦力怎麼變？","A":"一直不變","B":"一直減少","C":"先隨拉力增加，滑動後變成稍小的動摩擦力","D":"一開始就最大","answer":"C","explanation":"靜摩擦力會跟著拉力變大，滑動後變成較小的動摩擦力。","image":""},{"id":"E-05-01","isl":"E","lv":1,"stem":"力矩的大小等於？","A":"力 × 力臂","B":"力 + 力臂","C":"力 ÷ 力臂","D":"力 × 時間","answer":"A","explanation":"力矩 = 力 × 力臂。","image":""},{"id":"E-05-02","isl":"E","lv":1,"stem":"力臂是指？","A":"支點到施力點的距離","B":"力的大小","C":"槓桿的長度","D":"支點到力的作用線的垂直距離","answer":"D","explanation":"力臂要量垂直距離。","image":""},{"id":"E-05-03","isl":"E","lv":2,"stem":"翹翹板左邊 30 kgw 的人坐在距支點 2 m 處，右邊 40 kgw 的人要坐多遠才平衡？","A":"1.2 m","B":"2 m","C":"1.5 m","D":"2.67 m","answer":"C","explanation":"30 × 2 = 40 × 1.5，兩邊力矩相等。","image":""},{"id":"E-05-04","isl":"E","lv":2,"stem":"物體達到靜力平衡的條件是？","A":"合力為零","B":"合力與合力矩都為零","C":"合力矩為零","D":"只要沒在動","answer":"B","explanation":"不移動也不轉動，兩個條件都要成立。","image":""},{"id":"E-05-05","isl":"E","lv":3,"stem":"用扳手鬆螺絲鬆不開，最好的做法是？","A":"換長扳手或握在把手末端","B":"握在靠近螺絲處","C":"換短扳手","D":"往螺絲方向推","answer":"A","explanation":"增加力臂可以增加力矩。","image":""},{"id":"E-06-01","isl":"E","lv":1,"stem":"下列何者不屬於簡單機械？","A":"滑輪","B":"斜面","C":"電池","D":"齒輪","answer":"C","explanation":"電池是電源，不是簡單機械。","image":""},{"id":"E-06-02","isl":"E","lv":1,"stem":"定滑輪的主要功用是？","A":"省力","B":"改變施力方向","C":"省時","D":"增加功","answer":"B","explanation":"定滑輪的施力等於物重，只改變方向。","image":""},{"id":"E-06-03","isl":"E","lv":2,"stem":"用一個動滑輪（不計滑輪重與摩擦）提起 20 kgw 的物體，需施力多少？","A":"10 kgw","B":"5 kgw","C":"20 kgw","D":"40 kgw","answer":"A","explanation":"兩段繩子分擔物重，施力是一半。","image":""},{"id":"E-06-04","isl":"E","lv":2,"stem":"筷子屬於哪一種槓桿？","A":"省力槓桿","B":"等臂槓桿","C":"不是槓桿","D":"費力槓桿","answer":"D","explanation":"施力點在支點與抗力點之間，是費力槓桿。","image":""},{"id":"E-06-05","isl":"E","lv":3,"stem":"把重物推上卡車，用較長的斜板比用短斜板？","A":"較費力","B":"一樣","C":"較省力，但推的距離較長","D":"推不上去","answer":"C","explanation":"省力就要多走距離，不能省功。","image":""},{"id":"E-07-01","isl":"E","lv":1,"stem":"壓力的定義是？","A":"垂直作用力 ÷ 受力面積","B":"力 × 面積","C":"力 ÷ 時間","D":"質量 ÷ 體積","answer":"A","explanation":"壓力 = 垂直作用力 ÷ 受力面積。","image":""},{"id":"E-07-02","isl":"E","lv":1,"stem":"同一塊磚放在沙上，哪種放法陷得最深？","A":"最大面朝下","B":"一樣深","C":"斜放","D":"最小面朝下","answer":"D","explanation":"受力面積最小，壓力最大。","image":""},{"id":"E-07-03","isl":"E","lv":2,"stem":"20 kgw 的箱子，底面積 50 cm²，對地面的壓力是？","A":"2.5 kgw/cm²","B":"70 kgw/cm²","C":"0.4 kgw/cm²","D":"1000 kgw/cm²","answer":"C","explanation":"20 ÷ 50 = 0.4 kgw/cm²。","image":""},{"id":"E-07-04","isl":"E","lv":2,"stem":"密閉容器中的液體某處受到壓力時，壓力會？","A":"只往下傳","B":"大小不變地傳到液體各處","C":"越傳越小","D":"只往上傳","answer":"B","explanation":"這就是帕斯卡原理。","image":""},{"id":"E-07-05","isl":"E","lv":3,"stem":"液壓機小活塞面積 2 cm²、大活塞 100 cm²，在小活塞施力 3 kgw，大活塞可舉起多重？","A":"150 kgw","B":"6 kgw","C":"50 kgw","D":"300 kgw","answer":"A","explanation":"兩邊壓力相同：3 ÷ 2 × 100 = 150 kgw。","image":""},{"id":"E-08-01","isl":"E","lv":1,"stem":"鐵塊會沉，但鐵做的大船能浮起來，主要是因為？","A":"船比較輕","B":"海水有磁力","C":"船排開大量的水","D":"船上有人","answer":"C","explanation":"排開的水越多，浮力越大。","image":""},{"id":"E-08-02","isl":"E","lv":1,"stem":"阿基米德原理：物體在液體中受的浮力等於？","A":"物體的重量","B":"排開液體的重量","C":"物體的質量","D":"液體的總重","answer":"B","explanation":"浮力 = 排開液體的重量。","image":""},{"id":"E-08-03","isl":"E","lv":2,"stem":"物體在空氣中重 50 gw，完全沒入水中時彈簧秤讀數 30 gw，浮力是？","A":"20 gw","B":"30 gw","C":"50 gw","D":"80 gw","answer":"A","explanation":"浮力 = 50 − 30 = 20 gw。","image":""},{"id":"E-08-04","isl":"E","lv":2,"stem":"物體在空氣中重 50 gw，完全沒入水中時彈簧秤讀數 30 gw，水的密度 1 g/cm³，物體的體積是？","A":"30 cm³","B":"50 cm³","C":"80 cm³","D":"20 cm³","answer":"D","explanation":"排開 20 g 的水，體積是 20 cm³，也就是物體體積。","image":""},{"id":"E-08-05","isl":"E","lv":3,"stem":"同一艘船從河裡開進海裡（海水密度較大），吃水深度會？","A":"變深","B":"不變","C":"變淺","D":"沉沒","answer":"C","explanation":"浮力不變，海水密度大，排開的體積變小，船浮得比較高。","image":""},{"id":"E-09-01","isl":"E","lv":1,"stem":"完整描述物體的運動，需要哪些資訊？","A":"位置、時間與方向","B":"只要速度","C":"只要質量","D":"只要顏色","answer":"A","explanation":"描述運動要有位置、時間與方向。","image":""},{"id":"E-09-02","isl":"E","lv":1,"stem":"小明 10 秒內往東走了 20 公尺，平均速度是？","A":"2 m/s 向西","B":"200 m/s","C":"0.5 m/s","D":"2 m/s 向東","answer":"D","explanation":"20 ÷ 10 = 2 m/s，速度要包含方向。","image":""},{"id":"E-09-03","isl":"E","lv":2,"stem":"x–t 圖是一條水平直線，代表物體？","A":"等速前進","B":"加速","C":"靜止","D":"減速","answer":"C","explanation":"位置不隨時間改變，表示靜止。","image":""},{"id":"E-09-04","isl":"E","lv":2,"stem":"沿 400 m 操場跑一圈回到起點，位移是？","A":"400 m","B":"0","C":"200 m","D":"無法判斷","answer":"B","explanation":"起點等於終點，位移為 0；路徑長是 400 m。","image":""},{"id":"E-09-05","isl":"E","lv":2,"stem":"一輛車 4 秒內速度從 0 增加到 20 m/s，平均加速度是？","A":"5 m/s²","B":"80 m/s²","C":"20 m/s²","D":"0.2 m/s²","answer":"A","explanation":"a = Δv ÷ Δt = (20 − 0) ÷ 4 = 5 m/s²。","image":""},{"id":"E-10-01","isl":"E","lv":3,"stem":"旋轉木馬上的人以固定快慢繞圈，他的運動是？","A":"等速度運動","B":"靜止","C":"速率不變但方向一直改變的加速度運動","D":"等加速直線運動","answer":"C","explanation":"方向一直改變，所以有加速度。","image":""},{"id":"E-10-02","isl":"E","lv":1,"stem":"等速率圓周運動中，物體的速度方向沿著？","A":"指向圓心","B":"圓的切線","C":"半徑向外","D":"固定不變的方向","answer":"B","explanation":"速度方向沿切線，而且一直在改變。","image":""},{"id":"E-10-03","isl":"E","lv":2,"stem":"用繩子綁著球在水平桌面上繞圈，繩子突然斷了，球接下來會？","A":"沿當時的切線方向直線前進","B":"沿半徑方向往外飛","C":"繼續繞圈","D":"立刻停下","answer":"A","explanation":"沒有指向圓心的力，球依慣性沿切線方向直線前進。","image":""},{"id":"E-10-04","isl":"E","lv":2,"stem":"月球繞地球轉，提供指向地心的力是？","A":"月球的離心力","B":"太陽光的壓力","C":"月球的自轉","D":"地球對月球的萬有引力","answer":"D","explanation":"地球對月球的萬有引力指向地心，讓月球不斷轉彎。","image":""},{"id":"E-10-05","isl":"E","lv":3,"stem":"同一條繩子甩同一顆球，轉得越快，手需要的拉力會？","A":"越小","B":"不變","C":"越大","D":"變成 0","answer":"C","explanation":"轉得越快，速度方向改變越快，需要指向圓心的力越大。","image":""},{"id":"E-11-01","isl":"E","lv":1,"stem":"公車突然煞車，乘客往前傾，是因為？","A":"慣性","B":"浮力","C":"摩擦力消失","D":"作用與反作用","answer":"A","explanation":"身體要保持原來的運動狀態，所以往前傾。","image":""},{"id":"E-11-02","isl":"E","lv":1,"stem":"物體質量越大，慣性？","A":"越小","B":"不變","C":"無關","D":"越大","answer":"D","explanation":"質量決定慣性的大小。","image":""},{"id":"E-11-03","isl":"E","lv":2,"stem":"用相同的力推空購物車和裝滿的購物車相同時間，哪一台速度變化較大？","A":"滿車","B":"一樣","C":"空車","D":"無法判斷","answer":"C","explanation":"質量小，速度變化大。","image":""},{"id":"E-11-04","isl":"E","lv":2,"stem":"人走路時用腳往後蹬地，使人前進的力是？","A":"人推地的力","B":"地面推人的力","C":"重力","D":"慣性","answer":"B","explanation":"地面給人的反作用力作用在人身上，使人前進。","image":""},{"id":"E-11-05","isl":"E","lv":3,"stem":"火箭向下噴出氣體而上升，主要原理是？","A":"作用力與反作用力","B":"慣性定律","C":"浮力","D":"摩擦力","answer":"A","explanation":"火箭推氣體向下，氣體推火箭向上。","image":""},{"id":"E-12-01","isl":"E","lv":1,"stem":"大氣壓力是怎麼產生的？","A":"太陽光","B":"地球自轉","C":"空氣的重量","D":"風","answer":"C","explanation":"地表上方空氣的重量造成大氣壓力。","image":""},{"id":"E-12-02","isl":"E","lv":1,"stem":"一大氣壓約等於多少公分水銀柱？","A":"7.6","B":"76","C":"760","D":"100","answer":"B","explanation":"一大氣壓約 76 cmHg，也就是 760 mmHg。","image":""},{"id":"E-12-03","isl":"E","lv":2,"stem":"用吸管喝飲料，飲料上升的主要原因是？","A":"大氣壓力把飲料壓上來","B":"嘴巴把飲料拉上來的力","C":"飲料自己會上升","D":"吸管的磁力","answer":"A","explanation":"吸管內氣壓變小，大氣壓力把飲料壓上來。","image":""},{"id":"E-12-04","isl":"E","lv":2,"stem":"定溫下把密閉針筒的活塞往內推，筒內氣體會？","A":"體積變小、壓力變小","B":"體積不變","C":"壓力不變","D":"體積變小、壓力變大","answer":"D","explanation":"密閉氣體被壓縮，體積變小、壓力變大。","image":""},{"id":"E-12-05","isl":"E","lv":3,"stem":"帶上山的密封零食包到山頂會膨脹，主要原因是？","A":"山上溫度比較高","B":"零食發酵","C":"山上大氣壓力較小，袋內氣體體積變大","D":"袋子吸水","answer":"C","explanation":"外面的壓力變小，袋內氣體就膨脹。","image":""},{"id":"E-13-01","isl":"E","lv":1,"stem":"組成宇宙的基本單位是？","A":"星系","B":"行星","C":"恆星","D":"衛星","answer":"A","explanation":"宇宙由非常多的星系組成。","image":""},{"id":"E-13-02","isl":"E","lv":1,"stem":"太陽屬於哪一個星系？","A":"仙女座星系","B":"大麥哲倫星系","C":"太陽系","D":"銀河系","answer":"D","explanation":"太陽在銀河系中；太陽系不是星系。","image":""},{"id":"E-13-03","isl":"E","lv":2,"stem":"銀河系主要由什麼組成？","A":"只有行星","B":"只有氣體","C":"大量恆星","D":"只有黑洞","answer":"C","explanation":"銀河系主要由大量恆星組成。","image":""},{"id":"E-13-04","isl":"E","lv":2,"stem":"由小到大排列，下列何者正確？","A":"太陽系 < 地球 < 銀河系 < 宇宙","B":"地球 < 太陽系 < 銀河系 < 宇宙","C":"銀河系 < 太陽系 < 宇宙 < 地球","D":"地球 < 銀河系 < 太陽系 < 宇宙","answer":"B","explanation":"太陽系包含地球，銀河系包含太陽系，宇宙包含銀河系。","image":""},{"id":"E-13-05","isl":"E","lv":3,"stem":"晴朗夜空中看到的「銀河」光帶，其實是？","A":"從銀河系內部看到的大量恆星","B":"高空的雲","C":"月光反射","D":"大氣折射","answer":"A","explanation":"我們在銀河系裡面，沿著銀河盤面看到大量恆星。","image":""},{"id":"E-14-01","isl":"E","lv":1,"stem":"下列關於萬有引力的敘述，何者正確？","A":"只有星球之間才有","B":"只有地球才有","C":"任何兩個有質量的物體之間都有","D":"只有在真空中才有","answer":"C","explanation":"任何兩個有質量的物體之間都有萬有引力。","image":""},{"id":"E-14-02","isl":"E","lv":2,"stem":"兩物體的距離不變，其中一個質量變成 3 倍，引力變成幾倍？","A":"1/3 倍","B":"3 倍","C":"6 倍","D":"9 倍","answer":"B","explanation":"引力和質量成正比，質量 3 倍，引力也是 3 倍。","image":""},{"id":"E-14-03","isl":"E","lv":2,"stem":"兩物體質量不變，距離變成原來的 2 倍，引力變成幾倍？","A":"1/4 倍","B":"2 倍","C":"1/2 倍","D":"4 倍","answer":"A","explanation":"引力和距離平方成反比：1 ÷ 2² = 1/4。","image":""},{"id":"E-14-04","isl":"E","lv":2,"stem":"讓月球能夠一直繞著地球轉的力是？","A":"月球的慣性","B":"太陽風","C":"月球自轉產生的力","D":"地球對月球的萬有引力","answer":"D","explanation":"地球的萬有引力提供月球做圓周運動所需的向心力。","image":""},{"id":"E-14-05","isl":"E","lv":3,"stem":"兩物體質量都變 2 倍，距離也變 2 倍，引力變成幾倍？","A":"2 倍","B":"4 倍","C":"1 倍（不變）","D":"1/2 倍","answer":"C","explanation":"質量相乘 2 × 2 = 4 倍，距離 2 倍使引力變 1/4，4 × 1/4 = 1，不變。","image":""},{"id":"E-21-01","isl":"E","lv":1,"stem":"平均速率的計算式是？","A":"時間÷路程","B":"路程＋時間","C":"路程÷時間","D":"路程×時間","answer":"C","explanation":"平均速率＝總路程÷總時間。","image":""},{"id":"E-21-02","isl":"E","lv":1,"stem":"汽車速率 72 km/h，等於多少 m/s？","A":"7.2 m/s","B":"72 m/s","C":"20 m/s","D":"259 m/s","answer":"C","explanation":"72 km/h＝72×1000÷3600＝20 m/s。","image":""},{"id":"E-21-03","isl":"E","lv":2,"stem":"小明 10 分鐘走 600 m，平均速率是多少 m/s？","A":"0.1 m/s","B":"1 m/s","C":"60 m/s","D":"6 m/s","answer":"B","explanation":"10 分鐘＝600 秒，600÷600＝1 m/s。","image":""},{"id":"E-21-04","isl":"E","lv":2,"stem":"以 5 m/s 等速騎車，20 秒可以行進多少 m？","A":"100 m","B":"4 m","C":"25 m","D":"15 m","answer":"A","explanation":"路程＝速率×時間＝5×20＝100 m。","image":""},{"id":"E-21-05","isl":"E","lv":3,"stem":"甲車以 20 m/s 追前方 100 m 處、以 10 m/s 等速前進的乙車，幾秒後追上？","A":"5 秒","B":"30 秒","C":"20 秒","D":"10 秒","answer":"D","explanation":"相對速度為 10 m/s，100÷10＝10 秒。","image":""},{"id":"E-22-01","isl":"E","lv":1,"stem":"牛頓第二運動定律的式子是？","A":"F＝m/a","B":"F＝a/m","C":"F＝mv","D":"F＝ma","answer":"D","explanation":"合力＝質量×加速度。","image":""},{"id":"E-22-02","isl":"E","lv":1,"stem":"力的單位「牛頓」等於？","A":"1 kg/m","B":"1 g·cm","C":"1 kg·m/s","D":"1 kg·m/s²","answer":"D","explanation":"1 N 是使 1 kg 物體產生 1 m/s² 加速度的力。","image":""},{"id":"E-22-03","isl":"E","lv":2,"stem":"2 kg 的物體受到 10 N 的合力，加速度是多少 m/s²？","A":"12","B":"5","C":"20","D":"0.2","answer":"B","explanation":"a＝F÷m＝10÷2＝5 m/s²。","image":""},{"id":"E-22-04","isl":"E","lv":2,"stem":"合力不變，物體質量變成 2 倍，加速度變成？","A":"2 倍","B":"1/2 倍","C":"不變","D":"4 倍","answer":"B","explanation":"a＝F/m，質量加倍，加速度變成一半。","image":""},{"id":"E-22-05","isl":"E","lv":3,"stem":"質量 5 kg 的物體受到向右 30 N、向左 10 N 的力，加速度是？","A":"向右 4 m/s²","B":"向左 4 m/s²","C":"向右 8 m/s²","D":"向右 2 m/s²","answer":"A","explanation":"合力＝30－10＝20 N 向右，a＝20÷5＝4 m/s²。","image":""},{"id":"E-23-01","isl":"E","lv":1,"stem":"作用力與反作用力的大小關係是？","A":"相等","B":"反作用力較大","C":"作用力較大","D":"不一定","answer":"A","explanation":"牛頓第三運動定律：兩者大小相等。","image":""},{"id":"E-23-02","isl":"E","lv":1,"stem":"作用力與反作用力的方向？","A":"相同","B":"相反","C":"不一定","D":"互相垂直","answer":"B","explanation":"兩力方向相反，作用在不同的物體上。","image":""},{"id":"E-23-03","isl":"E","lv":2,"stem":"火箭向下噴出氣體而升空，是利用？","A":"慣性","B":"作用力與反作用力","C":"摩擦力","D":"浮力","answer":"B","explanation":"火箭向下推氣體，氣體反過來向上推火箭。","image":""},{"id":"E-23-04","isl":"E","lv":2,"stem":"用力拍桌子手會痛，是因為？","A":"手沒有力","B":"桌子沒有受力","C":"桌子也對手施力","D":"手的質量太小","answer":"C","explanation":"手拍桌子的同時，桌子也以相同大小的力反推手。","image":""},{"id":"E-23-05","isl":"E","lv":3,"stem":"下列哪一組是一對作用力與反作用力？","A":"摩擦力與重力","B":"蘋果拉地球與地球拉蘋果","C":"拉力與重力","D":"蘋果重力與桌面支持力","answer":"B","explanation":"作用力與反作用力是兩個物體間相互的力，重力與支持力作用在同一物體，不是。","image":""},{"id":"E-24-01","isl":"E","lv":1,"stem":"摩擦力的方向與物體運動（或運動趨勢）的方向？","A":"隨機","B":"相反","C":"垂直","D":"相同","answer":"B","explanation":"摩擦力阻礙物體的相對運動，方向相反。","image":""},{"id":"E-24-02","isl":"E","lv":1,"stem":"下列哪一種做法能增加摩擦力？","A":"塗上潤滑油","B":"增加接觸面的粗糙程度","C":"讓表面更光滑","D":"減小接觸面的壓力","answer":"B","explanation":"接觸面越粗糙，摩擦力越大。","image":""},{"id":"E-24-03","isl":"E","lv":2,"stem":"同一個木塊在桌面上滑動，摩擦力與接觸面積的關係是？","A":"面積越大越大","B":"面積越小就沒摩擦","C":"與面積大小無關","D":"面積越大越小","answer":"C","explanation":"在國中範圍，滑動摩擦力與接觸面積大小無關。","image":""},{"id":"E-24-04","isl":"E","lv":2,"stem":"用 5 N 的力推箱子但箱子沒動，此時靜摩擦力？","A":"小於 5 N","B":"等於 5 N","C":"大於 5 N","D":"為 0","answer":"B","explanation":"箱子靜止，合力為 0，靜摩擦力與推力大小相等、方向相反。","image":""},{"id":"E-24-05","isl":"E","lv":3,"stem":"重 20 N 的木塊在水平桌面上，用 5 N 的水平力使它等速滑動，動摩擦力是多少？","A":"15 N","B":"5 N","C":"25 N","D":"20 N","answer":"B","explanation":"等速表示合力為 0，所以摩擦力等於拉力 5 N。","image":""},{"id":"E-25-01","isl":"E","lv":1,"stem":"質量的常用單位是？","A":"焦耳","B":"公斤","C":"牛頓","D":"瓦特","answer":"B","explanation":"質量用公斤（kg）、公克（g）表示。","image":""},{"id":"E-25-02","isl":"E","lv":1,"stem":"重量（重力）的單位是？","A":"公尺","B":"秒","C":"牛頓","D":"公斤","answer":"C","explanation":"重量是力，單位是牛頓。","image":""},{"id":"E-25-03","isl":"E","lv":2,"stem":"質量 10 kg 的物體，在地球上（g≈10 m/s²）的重量約是？","A":"100 N","B":"1 N","C":"1000 N","D":"10 N","answer":"A","explanation":"重量＝質量×g＝10×10＝100 N。","image":""},{"id":"E-25-04","isl":"E","lv":2,"stem":"同一個物體從地球帶到月球，質量與重量的變化是？","A":"質量變小、重量不變","B":"質量不變、重量變小","C":"兩者都變大","D":"兩者都不變","answer":"B","explanation":"質量是物體的量，不會改變；月球重力小，所以重量變小。","image":""},{"id":"E-25-05","isl":"E","lv":3,"stem":"月球重力約為地球的 1/6，在地球上重 600 N 的人，到月球重多少？","A":"6 N","B":"600 N","C":"3600 N","D":"100 N","answer":"D","explanation":"600÷6＝100 N。","image":""},{"id":"E-26-01","isl":"E","lv":1,"stem":"壓力的計算式是？","A":"力＋受力面積","B":"力×受力面積","C":"受力面積÷力","D":"力÷受力面積","answer":"D","explanation":"壓力＝垂直作用的力÷受力面積。","image":""},{"id":"E-26-02","isl":"E","lv":1,"stem":"下列哪一個是壓力的單位？","A":"焦耳","B":"瓦特","C":"安培","D":"帕斯卡","answer":"D","explanation":"壓力的單位是帕斯卡（Pa），也就是 N/m²。","image":""},{"id":"E-26-03","isl":"E","lv":2,"stem":"菜刀的刀刃磨得很薄，目的是？","A":"增加重量","B":"減小受力面積以增大壓力","C":"減少壓力","D":"增加受力面積","answer":"B","explanation":"面積越小，同樣的力產生的壓力越大，容易切開食物。","image":""},{"id":"E-26-04","isl":"E","lv":2,"stem":"100 N 的力垂直作用在 0.5 m² 的面積上，壓力是多少 Pa？","A":"200 Pa","B":"100 Pa","C":"0.005 Pa","D":"50 Pa","answer":"A","explanation":"壓力＝100÷0.5＝200 Pa。","image":""},{"id":"E-26-05","isl":"E","lv":3,"stem":"液體內部的壓力大小與下列何者有關？","A":"容器大小","B":"容器形狀","C":"深度與液體密度","D":"液體顏色","answer":"C","explanation":"液體壓力隨深度和密度增加。","image":""},{"id":"E-27-01","isl":"E","lv":1,"stem":"浮力的方向是？","A":"向下","B":"向上","C":"水平","D":"不一定","answer":"B","explanation":"液體對物體的浮力方向向上。","image":""},{"id":"E-27-02","isl":"E","lv":1,"stem":"阿基米德原理指出，浮力大小等於物體排開液體的什麼？","A":"顏色","B":"重量","C":"溫度","D":"密度","answer":"B","explanation":"浮力＝物體排開的液體所受的重力。","image":""},{"id":"E-27-03","isl":"E","lv":2,"stem":"物體在水中受到 5 N 的浮力，它排開的水重多少？","A":"2.5 N","B":"10 N","C":"5 N","D":"0 N","answer":"C","explanation":"浮力等於排開液體的重量。","image":""},{"id":"E-27-04","isl":"E","lv":2,"stem":"物體漂浮在水面上時，浮力與重力的關係是？","A":"浮力為 0","B":"浮力大於重力","C":"浮力小於重力","D":"浮力等於重力","answer":"D","explanation":"漂浮時靜止，合力為 0，浮力等於重力。","image":""},{"id":"E-27-05","isl":"E","lv":3,"stem":"輪船從淡水河駛入海洋，船身會？","A":"沉沒","B":"沒有變化","C":"稍微下沉","D":"稍微上浮","answer":"D","explanation":"海水密度較大，排開較少的水就能產生相同浮力，所以上浮一些。","image":""},{"id":"E-28-01","isl":"E","lv":1,"stem":"加速度是單位時間內什麼量的變化？","A":"質量","B":"路程","C":"位移","D":"速度","answer":"D","explanation":"加速度＝速度變化量÷時間。","image":""},{"id":"E-28-02","isl":"E","lv":1,"stem":"等速度運動的物體，加速度是多少？","A":"10","B":"無限大","C":"1","D":"0","answer":"D","explanation":"速度不變，所以加速度為 0。","image":""},{"id":"E-28-03","isl":"E","lv":2,"stem":"汽車由靜止出發，4 秒後速度為 20 m/s，加速度是多少？","A":"80 m/s²","B":"16 m/s²","C":"0.2 m/s²","D":"5 m/s²","answer":"D","explanation":"a＝20÷4＝5 m/s²。","image":""},{"id":"E-28-04","isl":"E","lv":2,"stem":"忽略空氣阻力，自由落體在地球表面的加速度約為？","A":"98 m/s²","B":"0","C":"9.8 m/s²","D":"1 m/s²","answer":"C","explanation":"重力加速度 g 約 9.8 m/s²，常取 10。","image":""},{"id":"E-28-05","isl":"E","lv":3,"stem":"自由落體（g 取 10）從靜止下落 3 秒末的速度是多少？","A":"30 m/s","B":"15 m/s","C":"10 m/s","D":"45 m/s","answer":"A","explanation":"v＝gt＝10×3＝30 m/s。","image":""},{"id":"F-01-01","isl":"F","lv":1,"stem":"包圍在地球外面的空氣層稱為？","A":"大氣圈","B":"水圈","C":"岩石圈","D":"地函","answer":"A","explanation":"包圍地球的空氣就是大氣圈。","image":""},{"id":"F-01-02","isl":"F","lv":1,"stem":"下列何者屬於水圈？","A":"空氣中的氮氣","B":"花岡岩","C":"臭氧層","D":"南極冰川","answer":"D","explanation":"冰川是固態的水，屬於水圈。","image":""},{"id":"F-01-03","isl":"F","lv":2,"stem":"水氣上升後冷卻，變成雲中的小水滴，這個過程稱為？","A":"蒸發","B":"入滲","C":"凝結","D":"逕流","answer":"C","explanation":"水氣遇冷凝結成小水滴或小冰晶，聚集成雲。","image":""},{"id":"F-01-04","isl":"F","lv":2,"stem":"推動水循環、讓海水不斷蒸發的能量主要來自？","A":"地球內部的熱","B":"太陽","C":"月球的引力","D":"風車","answer":"B","explanation":"太陽的熱使水蒸發。","image":""},{"id":"F-01-05","isl":"F","lv":3,"stem":"下雨後，一部分雨水滲進土壤和岩石的縫隙成為地下水，這個過程稱為？","A":"入滲","B":"蒸發","C":"凝結","D":"降水","answer":"A","explanation":"雨水往地下滲透叫入滲，成為地下水，之後仍會慢慢流回河川或海洋。","image":""},{"id":"F-02-01","isl":"F","lv":1,"stem":"地球上的水，大部分是？","A":"河水","B":"地下水","C":"海水","D":"冰川","answer":"C","explanation":"海水約占 97%。","image":""},{"id":"F-02-02","isl":"F","lv":1,"stem":"海水中含量最多的鹽類是？","A":"碳酸鈣","B":"氯化鈉","C":"硫酸銅","D":"氫氧化鈉","answer":"B","explanation":"海水中的鹽類以氯化鈉最多。","image":""},{"id":"F-02-03","isl":"F","lv":2,"stem":"淡水中占比最高的是？","A":"冰川","B":"河川","C":"湖泊","D":"雲中的水","answer":"A","explanation":"淡水約三分之二以上是冰川。","image":""},{"id":"F-02-04","isl":"F","lv":2,"stem":"海水鹽度約 35‰，表示 2000 公克海水中約含多少公克鹽類？","A":"35 公克","B":"350 公克","C":"17.5 公克","D":"70 公克","answer":"D","explanation":"每 1000 公克含約 35 公克，2000 公克就約 70 公克。","image":""},{"id":"F-02-05","isl":"F","lv":3,"stem":"把溫度計慢慢放入海中，讀數「先幾乎不變、接著快速下降、最後又幾乎不變」，中間快速下降的那一段是？","A":"混合層","B":"深水層","C":"斜溫層","D":"大氣層","answer":"C","explanation":"斜溫層的溫度隨深度迅速下降。","image":""},{"id":"F-03-01","isl":"F","lv":1,"stem":"把礦物在白色素瓷板上刻劃，留下的粉末顏色稱為？","A":"條痕色","B":"光澤","C":"晶形","D":"硬度","answer":"A","explanation":"粉末的顏色就是條痕色。","image":""},{"id":"F-03-02","isl":"F","lv":1,"stem":"莫氏硬度中，硬度最大的是？","A":"滑石","B":"石英","C":"方解石","D":"金剛石","answer":"D","explanation":"金剛石（鑽石）硬度 10 最硬。","image":""},{"id":"F-03-03","isl":"F","lv":2,"stem":"某礦物用銅幣可以刻出痕跡，用指甲卻刻不動它，它的硬度可能是？","A":"1","B":"6","C":"3","D":"8","answer":"C","explanation":"銅幣刻得動，表示它比銅幣（約 3.5）軟；指甲刻不動，表示它比指甲（約 2.5）硬，所以約 3。","image":""},{"id":"F-03-04","isl":"F","lv":2,"stem":"辨認礦物時，下列哪一項最<b>不</b>可靠？","A":"條痕色","B":"外表顏色","C":"硬度","D":"遇鹽酸是否冒泡","answer":"B","explanation":"同一種礦物可能有好幾種顏色。","image":""},{"id":"F-03-05","isl":"F","lv":3,"stem":"一塊白色礦物不能刻傷玻璃，滴稀鹽酸會冒泡，它最可能是？","A":"方解石","B":"石英","C":"金剛石","D":"黃鐵礦","answer":"A","explanation":"方解石硬度 3，遇稀鹽酸產生二氧化碳氣泡。","image":""},{"id":"F-04-01","isl":"F","lv":1,"stem":"由岩漿冷卻凝固形成的岩石是？","A":"沉積岩","B":"變質岩","C":"火成岩","D":"石灰岩","answer":"C","explanation":"岩漿冷卻凝固形成火成岩。","image":""},{"id":"F-04-02","isl":"F","lv":1,"stem":"下列哪一種岩石屬於變質岩？","A":"砂岩","B":"大理岩","C":"玄武岩","D":"礫岩","answer":"B","explanation":"大理岩由石灰岩變質而成。","image":""},{"id":"F-04-03","isl":"F","lv":2,"stem":"花岡岩的晶體比玄武岩大，主要原因是？","A":"花岡岩在地下慢慢冷卻","B":"花岡岩的岩漿比較熱","C":"花岡岩含有化石","D":"花岡岩被壓得比較緊","answer":"A","explanation":"冷卻越慢，晶體越大。","image":""},{"id":"F-04-04","isl":"F","lv":2,"stem":"在岩石中看到一層一層的層理和貝殼化石，這塊岩石最可能是？","A":"花岡岩","B":"玄武岩","C":"板岩","D":"砂岩","answer":"D","explanation":"沉積岩有層理，常含化石。","image":""},{"id":"F-04-05","isl":"F","lv":3,"stem":"板岩是由哪一種岩石經過高溫高壓變質而成？","A":"花岡岩","B":"玄武岩","C":"頁岩","D":"大理岩","answer":"C","explanation":"頁岩受高溫高壓變質成板岩。","image":""},{"id":"F-05-01","isl":"F","lv":1,"stem":"岩漿冷卻凝固後，形成哪一類岩石？","A":"火成岩","B":"沉積岩","C":"變質岩","D":"礦物","answer":"A","explanation":"岩漿冷卻凝固形成火成岩。","image":""},{"id":"F-05-02","isl":"F","lv":1,"stem":"沉積物變成沉積岩，需要經過哪個過程？","A":"熔融","B":"變質","C":"噴發","D":"壓密與膠結","answer":"D","explanation":"沉積物被壓密、膠結成沉積岩。","image":""},{"id":"F-05-03","isl":"F","lv":2,"stem":"花岡岩露出地表後經過長時間風化侵蝕，碎屑堆積成岩，最後會變成？","A":"變質岩","B":"岩漿","C":"沉積岩","D":"火成岩","answer":"C","explanation":"火成岩也能經風化侵蝕再沉積成沉積岩。","image":""},{"id":"F-05-04","isl":"F","lv":2,"stem":"下列何者是驅動岩石「變質」與「熔融」的主要能量來源？","A":"太陽","B":"地球內部的熱","C":"月球引力","D":"風","answer":"B","explanation":"變質、熔融發生在地下深處，靠地球內部的熱。","image":""},{"id":"F-05-05","isl":"F","lv":3,"stem":"一塊石灰岩被埋到地下深處，溫度再升高到熔化，冷卻後最終會成為？","A":"火成岩","B":"大理岩","C":"砂岩","D":"石灰岩","answer":"A","explanation":"先變質，若溫度高到熔融成岩漿，冷卻後就成為火成岩。","image":""},{"id":"F-06-01","isl":"F","lv":1,"stem":"乾燥空氣中含量最多的氣體是？","A":"氧氣","B":"二氧化碳","C":"氮氣","D":"氬氣","answer":"C","explanation":"氮氣約占 78%。","image":""},{"id":"F-06-02","isl":"F","lv":1,"stem":"下列何者屬於大氣中的變動氣體？","A":"氮氣","B":"水氣","C":"氬氣","D":"氧氣","answer":"B","explanation":"水氣含量隨時間地點改變。","image":""},{"id":"F-06-03","isl":"F","lv":2,"stem":"若把 100 顆空氣粒子按比例分，氧氣約占幾顆？","A":"21 顆","B":"78 顆","C":"1 顆","D":"50 顆","answer":"A","explanation":"氧氣約 21%。","image":""},{"id":"F-06-04","isl":"F","lv":2,"stem":"大氣中雲、雨、霧等天氣現象，主要和哪一種氣體有關？","A":"氮氣","B":"氬氣","C":"氦氣","D":"水氣","answer":"D","explanation":"水氣凝結成雲、雨、霧。","image":""},{"id":"F-06-05","isl":"F","lv":3,"stem":"近百年大氣中的二氧化碳濃度逐年上升，主要原因是？","A":"海水變鹹","B":"氮氣變成二氧化碳","C":"人類大量燃燒化石燃料","D":"火山完全停止噴發","answer":"C","explanation":"燃燒煤、石油、天然氣放出大量二氧化碳。","image":""},{"id":"F-07-01","isl":"F","lv":1,"stem":"雲、雨等天氣現象主要發生在大氣的哪一層？","A":"對流層","B":"平流層","C":"中氣層","D":"增溫層","answer":"A","explanation":"對流層水氣多、對流旺盛。","image":""},{"id":"F-07-02","isl":"F","lv":1,"stem":"能吸收紫外線、保護地表生物的臭氧層位於？","A":"對流層","B":"中氣層","C":"增溫層","D":"平流層","answer":"D","explanation":"臭氧層在平流層中。","image":""},{"id":"F-07-03","isl":"F","lv":2,"stem":"大氣分層主要依據什麼來劃分？","A":"空氣的顏色","B":"雲的多少","C":"溫度隨高度的變化","D":"風的方向","answer":"C","explanation":"每層溫度隨高度的變化不同。","image":""},{"id":"F-07-04","isl":"F","lv":2,"stem":"山腳氣溫 26°C，若高度每升高 1 公里約降 6.5°C，3 公里高的山頂氣溫約為？","A":"0°C","B":"6.5°C","C":"19.5°C","D":"32.5°C","answer":"B","explanation":"26 − 6.5×3 ＝ 6.5°C。","image":""},{"id":"F-07-05","isl":"F","lv":3,"stem":"平流層的溫度隨高度升高，主要原因是？","A":"臭氧吸收紫外線而增溫","B":"離太陽比較近","C":"飛機排放廢氣","D":"有很多雲","answer":"A","explanation":"臭氧層吸收太陽紫外線，使平流層上部變暖。","image":""},{"id":"F-08-01","isl":"F","lv":1,"stem":"太陽系中離太陽最近的行星是？","A":"金星","B":"地球","C":"水星","D":"火星","answer":"C","explanation":"由內而外：水、金、地、火……","image":""},{"id":"F-08-02","isl":"F","lv":1,"stem":"下列何者屬於類木行星？","A":"火星","B":"土星","C":"金星","D":"水星","answer":"B","explanation":"木、土、天王、海王是類木行星。","image":""},{"id":"F-08-03","isl":"F","lv":2,"stem":"下列哪一顆行星的公轉週期最長？","A":"海王星","B":"火星","C":"木星","D":"土星","answer":"A","explanation":"海王星離太陽最遠，公轉週期最長。","image":""},{"id":"F-08-04","isl":"F","lv":2,"stem":"關於太陽系八大行星，下列敘述何者正確？","A":"都是由岩石組成","B":"都有液態水","C":"都自己發光","D":"都以相同方向繞太陽公轉","answer":"D","explanation":"行星公轉方向相同，本身不發光。","image":""},{"id":"F-08-05","isl":"F","lv":3,"stem":"火星公轉週期約 1.9 年，木星約 12 年。由此推論，在火星與木星之間公轉的小行星，週期最可能是？","A":"0.5 年","B":"1 年","C":"4 年","D":"20 年","answer":"C","explanation":"軌道介於兩者之間，週期也介於 1.9 年和 12 年之間。","image":""},{"id":"F-09-01","isl":"F","lv":1,"stem":"目前已知唯一有液態水和生命的行星是？","A":"地球","B":"火星","C":"金星","D":"水星","answer":"A","explanation":"地球有液態水與適合生命的大氣。","image":""},{"id":"F-09-02","isl":"F","lv":1,"stem":"表面溫度最高、約 460°C 的行星是？","A":"水星","B":"火星","C":"地球","D":"金星","answer":"D","explanation":"金星的濃厚大氣造成強烈溫室效應。","image":""},{"id":"F-09-03","isl":"F","lv":2,"stem":"水星白天約 430°C、夜晚約 −180°C，晝夜溫差極大的主要原因是？","A":"有很多海洋","B":"自轉太快","C":"幾乎沒有大氣保溫","D":"離太陽太遠","answer":"C","explanation":"沒有大氣保溫，熱量很快散失。","image":""},{"id":"F-09-04","isl":"F","lv":2,"stem":"火星表面呈紅色，主要是因為？","A":"溫度非常高","B":"表面有大量氧化鐵","C":"被岩漿覆蓋","D":"反射太陽的紅光","answer":"B","explanation":"氧化鐵（像鐵鏽）讓火星呈紅色。","image":""},{"id":"F-09-05","isl":"F","lv":3,"stem":"金星離太陽比水星遠，表面溫度卻更高，最主要的原因是？","A":"金星的大氣以二氧化碳為主且濃厚，溫室效應強","B":"金星自轉比較快","C":"金星比較大","D":"金星有很多火山正在噴發","answer":"A","explanation":"濃厚的二氧化碳大氣把熱留住。","image":""},{"id":"F-10-01","isl":"F","lv":1,"stem":"月球發出的光來自？","A":"月球自己燃燒","B":"地球的燈光","C":"反射太陽光","D":"星星的光","answer":"C","explanation":"月球本身不發光，反射太陽光。","image":""},{"id":"F-10-02","isl":"F","lv":1,"stem":"農曆初一左右的月相是？","A":"滿月","B":"新月","C":"上弦月","D":"下弦月","answer":"B","explanation":"初一新月，月球在日地之間，看不見。","image":""},{"id":"F-10-03","isl":"F","lv":2,"stem":"從上一次滿月到下一次滿月，大約經過多久？","A":"29.5 天","B":"7 天","C":"15 天","D":"365 天","answer":"A","explanation":"月相週期約 29.5 天。","image":""},{"id":"F-10-04","isl":"F","lv":2,"stem":"在臺灣，黃昏時從東方升起的月亮最可能是？","A":"新月","B":"上弦月","C":"下弦月","D":"滿月","answer":"D","explanation":"滿月和太陽相對，黃昏時太陽西下、滿月東升。","image":""},{"id":"F-10-05","isl":"F","lv":3,"stem":"某天黃昏看到亮面朝西的半月，過了大約 7 天，最可能看到的月相是？","A":"新月","B":"下弦月","C":"滿月","D":"上弦月","answer":"C","explanation":"亮面朝西的半月是上弦月，約 7 天後變成滿月。","image":""},{"id":"F-11-01","isl":"F","lv":1,"stem":"發生日食時，太陽、月球、地球的位置關係是？","A":"月球在中間","B":"地球在中間","C":"太陽在中間","D":"三者不在一直線","answer":"A","explanation":"月球在日、地之間，擋住太陽。","image":""},{"id":"F-11-02","isl":"F","lv":1,"stem":"月食發生時的月相是？","A":"新月","B":"上弦月","C":"下弦月","D":"滿月","answer":"D","explanation":"月食時地球在中間，月球在太陽對面，是滿月。","image":""},{"id":"F-11-03","isl":"F","lv":2,"stem":"在月球本影區內的人，看到的是？","A":"日偏食","B":"月全食","C":"日全食","D":"月偏食","answer":"C","explanation":"本影區完全看不到太陽，是日全食。","image":""},{"id":"F-11-04","isl":"F","lv":2,"stem":"月全食時月亮常呈暗紅色，原因是？","A":"月亮自己發出紅光","B":"地球大氣把紅光折射到月面","C":"太陽變紅了","D":"月亮被火山灰蓋住","answer":"B","explanation":"地球大氣折射的紅光照到月面。","image":""},{"id":"F-11-05","isl":"F","lv":3,"stem":"為什麼不是每個月的新月都會發生日食？","A":"月球軌道和地球軌道有約 5° 夾角","B":"月球有時不繞地球轉","C":"太陽有時不發光","D":"新月時月球太遠","answer":"A","explanation":"軌道傾斜，大多數新月時三者不在同一直線。","image":""},{"id":"F-21-01","isl":"F","lv":1,"stem":"含有化石的岩石大多是哪一類岩石？","A":"沉積岩","B":"變質岩","C":"都不可能","D":"火成岩","answer":"A","explanation":"沉積岩由沉積物堆積而成，生物遺骸可以被保存成化石。","image":""},{"id":"F-21-02","isl":"F","lv":1,"stem":"石灰岩受到高溫高壓後會變成？","A":"砂岩","B":"玄武岩","C":"花崗岩","D":"大理岩","answer":"D","explanation":"石灰岩變質後形成大理岩。","image":""},{"id":"F-21-03","isl":"F","lv":2,"stem":"沉積岩形成過程的順序是？","A":"成岩→沉積→風化→搬運","B":"風化→搬運→沉積→成岩","C":"搬運→風化→成岩→沉積","D":"沉積→風化→搬運→成岩","answer":"B","explanation":"岩石先風化破碎，被搬運到低處沉積，再壓實膠結成岩。","image":""},{"id":"F-21-04","isl":"F","lv":2,"stem":"頁岩受到變質作用後，常形成？","A":"花崗岩","B":"板岩","C":"大理岩","D":"石英岩","answer":"B","explanation":"頁岩變質成板岩。","image":""},{"id":"F-21-05","isl":"F","lv":3,"stem":"下列哪一種岩石最可能看到層理？","A":"花崗岩","B":"砂岩","C":"安山岩","D":"玄武岩","answer":"B","explanation":"沉積岩一層一層堆積，常有層理；火成岩沒有層理。","image":""},{"id":"F-22-01","isl":"F","lv":1,"stem":"水由液態變成氣態進入大氣，稱為？","A":"降水","B":"蒸發","C":"逕流","D":"凝結","answer":"B","explanation":"液態水變成水蒸氣是蒸發。","image":""},{"id":"F-22-02","isl":"F","lv":1,"stem":"水蒸氣遇冷變成小水滴，稱為？","A":"昇華","B":"蒸發","C":"凝結","D":"沸騰","answer":"C","explanation":"氣態變成液態是凝結，雲就是這樣形成的。","image":""},{"id":"F-22-03","isl":"F","lv":2,"stem":"地球水循環的主要能量來源是？","A":"月球","B":"太陽","C":"地熱","D":"風","answer":"B","explanation":"太陽提供能量使水蒸發，帶動整個水循環。","image":""},{"id":"F-22-04","isl":"F","lv":2,"stem":"降到地面的水沿地表流入河川、海洋，稱為？","A":"凝結","B":"逕流","C":"昇華","D":"蒸散","answer":"B","explanation":"在地表流動的水稱為逕流。","image":""},{"id":"F-22-05","isl":"F","lv":3,"stem":"降水滲入地底儲存起來的水稱為？","A":"地下水","B":"雲","C":"冰河","D":"海水","answer":"A","explanation":"滲入土壤岩層裡的水是地下水。","image":""},{"id":"F-23-01","isl":"F","lv":1,"stem":"臭氧層主要位在大氣的哪一層？","A":"對流層","B":"平流層","C":"中氣層","D":"增溫層","answer":"B","explanation":"臭氧層大多位在平流層。","image":""},{"id":"F-23-02","isl":"F","lv":1,"stem":"對流層中，氣溫隨高度升高會怎麼變化？","A":"升高","B":"先升後降","C":"不變","D":"降低","answer":"D","explanation":"對流層氣溫隨高度升高而下降。","image":""},{"id":"F-23-03","isl":"F","lv":2,"stem":"臭氧層的功用是？","A":"吸收大部分紫外線","B":"反射所有可見光","C":"增加氧氣","D":"製造雨水","answer":"A","explanation":"臭氧層能吸收來自太陽的大部分紫外線，保護生物。","image":""},{"id":"F-23-04","isl":"F","lv":2,"stem":"飛機常在平流層底部飛行，原因是？","A":"氧氣最多","B":"氣流穩定、天氣變化少","C":"重力最小","D":"氣溫最低","answer":"B","explanation":"平流層沒有劇烈的上下對流，飛行較平穩。","image":""},{"id":"F-23-05","isl":"F","lv":3,"stem":"哪一種物質會破壞臭氧層，已被限制使用？","A":"氧氣","B":"氮氣","C":"氟氯碳化物","D":"氬氣","answer":"C","explanation":"冰箱、冷氣使用的氟氯碳化物會分解臭氧。","image":""},{"id":"F-24-01","isl":"F","lv":1,"stem":"月球繞地球公轉一圈，約需多久？","A":"約 1 週","B":"約 1 個月","C":"約 1 年","D":"約 1 天","answer":"B","explanation":"月球公轉週期約一個月，月相也約一個月循環一次。","image":""},{"id":"F-24-02","isl":"F","lv":1,"stem":"農曆初一的月相是？","A":"上弦月","B":"下弦月","C":"新月","D":"滿月","answer":"C","explanation":"農曆初一是新月，幾乎看不到月亮。","image":""},{"id":"F-24-03","isl":"F","lv":2,"stem":"農曆十五前後的月相是？","A":"下弦月","B":"上弦月","C":"滿月","D":"新月","answer":"C","explanation":"農曆十五前後，地球位於太陽與月球之間，看到滿月。","image":""},{"id":"F-24-04","isl":"F","lv":2,"stem":"月相變化的主要原因是？","A":"雲層遮蔽","B":"地球的影子遮住月球","C":"月球自己改變亮度","D":"太陽、地球、月球的相對位置改變","answer":"D","explanation":"月球本身不發光，我們看到被太陽照亮的部分隨位置變化。","image":""},{"id":"F-24-05","isl":"F","lv":3,"stem":"月食發生時，三個天體的排列是？","A":"太陽、月球、地球","B":"太陽、地球、月球","C":"地球、太陽、月球","D":"月球、太陽、地球","answer":"B","explanation":"月食是地球擋住太陽光，月球進入地球影子中。","image":""},{"id":"F-25-01","isl":"F","lv":1,"stem":"太陽系中最大的行星是？","A":"土星","B":"海王星","C":"木星","D":"地球","answer":"C","explanation":"木星是太陽系最大的行星。","image":""},{"id":"F-25-02","isl":"F","lv":1,"stem":"以明顯的環聞名的行星是？","A":"火星","B":"水星","C":"金星","D":"土星","answer":"D","explanation":"土星有明亮顯著的環。","image":""},{"id":"F-25-03","isl":"F","lv":2,"stem":"表面呈紅色，被稱為「紅色行星」的是？","A":"火星","B":"水星","C":"金星","D":"木星","answer":"A","explanation":"火星表面富含氧化鐵，呈紅色。","image":""},{"id":"F-25-04","isl":"F","lv":2,"stem":"溫室效應最強、表面溫度最高的行星是？","A":"木星","B":"火星","C":"水星","D":"金星","answer":"D","explanation":"金星大氣主要是二氧化碳，溫室效應強，表面溫度比水星還高。","image":""},{"id":"F-25-05","isl":"F","lv":3,"stem":"下列哪一組都屬於類地行星？","A":"天王星、海王星","B":"木星、土星","C":"木星、火星","D":"水星、金星、地球、火星","answer":"D","explanation":"類地行星是體積較小、表面為岩石的行星：水星、金星、地球、火星。","image":""},{"id":"F-26-01","isl":"F","lv":1,"stem":"比較礦物硬度，常用什麼方法？","A":"比顏色","B":"互相敲打","C":"聞味道","D":"互相刻劃","answer":"D","explanation":"硬度大的礦物可以刻劃硬度小的礦物。","image":""},{"id":"F-26-02","isl":"F","lv":1,"stem":"石英的主要成分是？","A":"碳酸鈣","B":"氧化鐵","C":"氯化鈉","D":"二氧化矽","answer":"D","explanation":"石英的成分是二氧化矽。","image":""},{"id":"F-26-03","isl":"F","lv":2,"stem":"方解石遇稀鹽酸會冒出氣泡，是因為含有？","A":"鐵","B":"碳酸鈣","C":"二氧化矽","D":"硫","answer":"B","explanation":"碳酸鈣和酸反應產生二氧化碳。","image":""},{"id":"F-26-04","isl":"F","lv":2,"stem":"礦物沿特定方向裂成平滑面，這種性質稱為？","A":"條痕","B":"解理","C":"硬度","D":"光澤","answer":"B","explanation":"沿一定方向裂開成平滑的面，是解理。","image":""},{"id":"F-26-05","isl":"F","lv":3,"stem":"兩種礦物互相刻劃，會在哪一種上留下刻痕？","A":"兩者都留下","B":"兩者都不留下","C":"硬度較小的","D":"硬度較大的","answer":"C","explanation":"硬度大的可以刻劃硬度小的，所以刻痕留在硬度較小的礦物上。","image":""},{"id":"F-27-01","isl":"F","lv":1,"stem":"海水喝起來是鹹的，主要是因為含有大量的？","A":"硫酸","B":"氯化鉀","C":"碳酸鈣","D":"氯化鈉","answer":"D","explanation":"海水中最多的是氯化鈉，也就是食鹽。","image":""},{"id":"F-27-02","isl":"F","lv":1,"stem":"海水的平均鹽度大約是？","A":"350‰","B":"0.35‰","C":"35‰","D":"3.5‰","answer":"C","explanation":"全球海水平均鹽度約 35‰，也就是每公斤海水約含 35 g 鹽類。","image":""},{"id":"F-27-03","isl":"F","lv":2,"stem":"海水的溫度隨深度增加，通常會？","A":"一直不變","B":"先降後升","C":"逐漸降低","D":"逐漸升高","answer":"C","explanation":"陽光無法到達深處，所以越深越冷。","image":""},{"id":"F-27-04","isl":"F","lv":2,"stem":"下列哪一個地方的海水鹽度通常較低？","A":"沙漠海岸","B":"副熱帶海","C":"紅海","D":"河口","answer":"D","explanation":"河口有大量淡水注入，鹽度較低。","image":""},{"id":"F-27-05","isl":"F","lv":3,"stem":"海洋表層受風與波浪攪動、溫度較均勻的一層稱為？","A":"大氣層","B":"斜溫層","C":"深海層","D":"混合層","answer":"D","explanation":"表層被風浪混合，溫度比較均勻，稱為混合層。","image":""},{"id":"F-28-01","isl":"F","lv":1,"stem":"「光年」是什麼量的單位？","A":"時間","B":"速度","C":"亮度","D":"距離","answer":"D","explanation":"光年是光在一年中走的距離。","image":""},{"id":"F-28-02","isl":"F","lv":1,"stem":"太陽是一顆什麼天體？","A":"恆星","B":"衛星","C":"彗星","D":"行星","answer":"A","explanation":"太陽自己發光發熱，是恆星。","image":""},{"id":"F-28-03","isl":"F","lv":2,"stem":"光在真空中，每秒大約前進多遠？","A":"30 萬公里","B":"340 公尺","C":"3 萬公里","D":"3000 公里","answer":"A","explanation":"光速約每秒 30 萬公里。","image":""},{"id":"F-28-04","isl":"F","lv":2,"stem":"夜空中看到的大多數閃爍光點是？","A":"恆星","B":"彗星","C":"衛星","D":"流星","answer":"A","explanation":"夜空中大部分是遙遠的恆星。","image":""},{"id":"F-28-05","isl":"F","lv":3,"stem":"某恆星距離我們 4 光年，表示它的光到達地球需要？","A":"4 年","B":"4 天","C":"4 分鐘","D":"4 秒","answer":"A","explanation":"1 光年是光走 1 年的距離，所以需要 4 年。","image":""},{"id":"G-01-01","isl":"G","lv":1,"stem":"下列哪一種生物主要以出芽生殖產生後代？","A":"酵母菌","B":"草履蟲","C":"黴菌","D":"蕨類","answer":"A","explanation":"酵母菌、水螅會出芽生殖。","image":""},{"id":"G-01-02","isl":"G","lv":1,"stem":"無性生殖產生的子代，有什麼特點？","A":"性狀和親代差異很大","B":"一定需要兩個親代","C":"一定要經過受精","D":"遺傳物質和親代相同","answer":"D","explanation":"無性生殖的子代和親代遺傳物質相同。","image":""},{"id":"G-01-03","isl":"G","lv":2,"stem":"農民把馬鈴薯切成帶有芽眼的小塊種下去，這是利用？","A":"種子繁殖","B":"孢子繁殖","C":"營養器官繁殖","D":"有性生殖","answer":"C","explanation":"馬鈴薯的塊莖是營養器官。","image":""},{"id":"G-01-04","isl":"G","lv":2,"stem":"利用組織培養大量繁殖蘭花，最主要的好處是？","A":"產生許多新品種","B":"快速得到大量性狀相同的優良植株","C":"讓蘭花開更多種顏色","D":"讓蘭花不需要水分","answer":"B","explanation":"組織培養屬於無性生殖，能保留優良性狀。","image":""},{"id":"G-01-05","isl":"G","lv":3,"stem":"果農把甜柿的枝條嫁接到澀柿的樹幹上，長出的果實會是？","A":"甜柿","B":"澀柿","C":"一半甜一半澀","D":"不會結果","answer":"A","explanation":"果實性狀由接穗（甜柿）決定。","image":""},{"id":"G-02-01","isl":"G","lv":1,"stem":"人的體細胞有 46 條染色體，精子有幾條？","A":"92 條","B":"46 條","C":"23 條","D":"12 條","answer":"C","explanation":"配子染色體數目減半：23 條。","image":""},{"id":"G-02-02","isl":"G","lv":1,"stem":"減數分裂主要發生在人體的哪裡？","A":"皮膚","B":"生殖器官（睪丸、卵巢）","C":"肝臟","D":"骨骼","answer":"B","explanation":"減數分裂在生殖器官產生配子。","image":""},{"id":"G-02-03","isl":"G","lv":2,"stem":"關於減數分裂和體細胞分裂（有絲分裂）的比較，何者正確？","A":"減數分裂產生的子細胞染色體數目減半","B":"兩者都產生 2 個子細胞","C":"體細胞分裂產生配子","D":"減數分裂時染色體不複製","answer":"A","explanation":"減數分裂：4 個子細胞、染色體減半。","image":""},{"id":"G-02-04","isl":"G","lv":2,"stem":"某生物體細胞有 8 條染色體，它的受精卵有幾條？","A":"4 條","B":"16 條","C":"2 條","D":"8 條","answer":"D","explanation":"配子 4 條＋4 條＝8 條，和親代相同。","image":""},{"id":"G-02-05","isl":"G","lv":3,"stem":"為什麼配子的染色體數目一定要減半？","A":"讓配子游得比較快","B":"讓配子比較小","C":"讓受精後的染色體數目和親代相同，代代維持穩定","D":"因為配子不需要遺傳物質","answer":"C","explanation":"若不減半，每一代染色體數目會加倍。","image":""},{"id":"G-03-01","isl":"G","lv":1,"stem":"下列哪一種動物是體外受精？","A":"青蛙","B":"雞","C":"狗","D":"烏龜","answer":"A","explanation":"青蛙在水中排出精子和卵。","image":""},{"id":"G-03-02","isl":"G","lv":1,"stem":"有性生殖的子代性狀和親代差異較大，主要是因為？","A":"子代只來自母親","B":"子代沒有染色體","C":"子代長在水裡","D":"子代得到雙親的遺傳物質","answer":"D","explanation":"遺傳物質來自父母雙方。","image":""},{"id":"G-03-03","isl":"G","lv":2,"stem":"魚類一次產下大量的卵，最主要的原因是？","A":"魚很大","B":"魚卵很便宜","C":"體外受精，受精和存活的機會較低","D":"魚不會照顧後代所以不需要","answer":"C","explanation":"體外受精易受環境影響，產卵多才能留下後代。","image":""},{"id":"G-03-04","isl":"G","lv":2,"stem":"雞蛋中提供胚胎發育主要養分的是？","A":"卵殼","B":"卵黃","C":"氣室","D":"殼膜","answer":"B","explanation":"卵黃儲存大量養分。","image":""},{"id":"G-03-05","isl":"G","lv":3,"stem":"關於卵生和胎生的敘述，何者正確？","A":"胎生的胚胎在子宮內發育，由母體供應養分","B":"胎生動物都在水中生活","C":"卵生動物都是體外受精","D":"胎生動物不需要受精","answer":"A","explanation":"胎生由母體透過胎盤供應養分。","image":""},{"id":"G-04-01","isl":"G","lv":1,"stem":"受精後，胚珠會發育成什麼？","A":"果實","B":"花瓣","C":"種子","D":"根","answer":"C","explanation":"胚珠 → 種子；子房 → 果實。","image":""},{"id":"G-04-02","isl":"G","lv":1,"stem":"花粉從雄蕊傳到雌蕊柱頭的過程稱為？","A":"受精","B":"授粉","C":"發芽","D":"蒸散","answer":"B","explanation":"這個過程叫做授粉。","image":""},{"id":"G-04-03","isl":"G","lv":2,"stem":"花粉落到柱頭後，精細胞如何到達胚珠？","A":"花粉粒長出花粉管穿過花柱","B":"被風吹進去","C":"由昆蟲搬進去","D":"從葉子送過去","answer":"A","explanation":"花粉管穿過花柱到達胚珠。","image":""},{"id":"G-04-04","isl":"G","lv":2,"stem":"玉米的花粉多而輕、花瓣不明顯，最可能靠什麼傳粉？","A":"昆蟲","B":"鳥","C":"水","D":"風","answer":"D","explanation":"這是風媒花的特徵。","image":""},{"id":"G-04-05","isl":"G","lv":3,"stem":"一個西瓜裡有很多粒種子，表示這個西瓜的子房內原本有？","A":"很多個花藥","B":"很多個柱頭","C":"很多個胚珠","D":"很多片花瓣","answer":"C","explanation":"每粒種子都由一個受精的胚珠發育而來。","image":""},{"id":"G-05-01","isl":"G","lv":1,"stem":"人體中能產生精子的器官是？","A":"睪丸","B":"攝護腺","C":"輸精管","D":"膀胱","answer":"A","explanation":"睪丸產生精子並分泌雄性激素。","image":""},{"id":"G-05-02","isl":"G","lv":1,"stem":"女性的受精作用通常發生在？","A":"卵巢","B":"子宮","C":"陰道","D":"輸卵管","answer":"D","explanation":"卵和精子在輸卵管相遇受精。","image":""},{"id":"G-05-03","isl":"G","lv":2,"stem":"胎兒在子宮內，主要經由什麼構造從母體獲得養分和氧氣？","A":"肺","B":"消化道","C":"胎盤和臍帶","D":"輸卵管","answer":"C","explanation":"胎盤是母體和胎兒交換物質的地方。","image":""},{"id":"G-05-04","isl":"G","lv":2,"stem":"青春期男生長出鬍子、聲音變低沉，主要和哪一種激素有關？","A":"胰島素","B":"雄性激素","C":"腎上腺素","D":"雌性激素","answer":"B","explanation":"睪丸分泌的雄性激素造成第二性徵。","image":""},{"id":"G-05-05","isl":"G","lv":3,"stem":"關於月經的敘述，何者正確？","A":"卵沒有受精時，增厚的子宮內膜剝落排出","B":"月經是卵受精後的現象","C":"月經是卵巢剝落","D":"月經與激素無關","answer":"A","explanation":"子宮內膜剝落隨血液排出，受激素調節。","image":""},{"id":"G-06-01","isl":"G","lv":1,"stem":"孟德爾用哪一種植物做遺傳實驗？","A":"玉米","B":"稻米","C":"豌豆","D":"向日葵","answer":"C","explanation":"孟德爾使用豌豆。","image":""},{"id":"G-06-02","isl":"G","lv":1,"stem":"高莖純品系和矮莖純品系豌豆雜交，第一子代會是？","A":"全部矮莖","B":"全部高莖","C":"高矮各一半","D":"中等高度","answer":"B","explanation":"高莖是顯性，F1 全部高莖。","image":""},{"id":"G-06-03","isl":"G","lv":2,"stem":"孟德爾進行人工授粉時，先去掉花的雄蕊，目的是？","A":"避免自花授粉","B":"讓花更好看","C":"讓花長得更高","D":"讓種子更大","answer":"A","explanation":"去雄才能確定花粉來自另一株。","image":""},{"id":"G-06-04","isl":"G","lv":2,"stem":"第一子代的高莖豌豆自花授粉，第二子代 400 株中，矮莖大約有幾株？","A":"0 株","B":"200 株","C":"300 株","D":"100 株","answer":"D","explanation":"高：矮≈3：1，矮莖約 1/4。","image":""},{"id":"G-06-05","isl":"G","lv":3,"stem":"孟德爾的研究能成功，下列何者不是原因？","A":"選用性狀對比明顯的豌豆","B":"用大量數據做統計","C":"他用顯微鏡看到了基因","D":"先培育出純品系","answer":"C","explanation":"當時還看不到基因，他靠實驗與統計推論。","image":""},{"id":"G-07-01","isl":"G","lv":1,"stem":"基因主要位在細胞的哪一個構造中？","A":"細胞核的染色體上","B":"細胞膜","C":"液胞","D":"細胞壁","answer":"A","explanation":"基因是染色體上 DNA 的片段。","image":""},{"id":"G-07-02","isl":"G","lv":1,"stem":"下列哪一種基因型會表現隱性性狀？","A":"AA","B":"Aa","C":"都會","D":"aa","answer":"D","explanation":"兩個隱性基因才表現隱性。","image":""},{"id":"G-07-03","isl":"G","lv":2,"stem":"Aa 和 aa 交配，子代表現隱性性狀的機率是？","A":"0","B":"1/4","C":"1/2","D":"1","answer":"C","explanation":"Aa×aa → Aa：aa＝1：1。","image":""},{"id":"G-07-04","isl":"G","lv":2,"stem":"關於基因型與表現型，何者正確？","A":"表現型相同，基因型一定相同","B":"AA 與 Aa 表現型相同","C":"aa 表現顯性性狀","D":"基因型不會遺傳","answer":"B","explanation":"AA 與 Aa 都表現顯性。","image":""},{"id":"G-07-05","isl":"G","lv":3,"stem":"兩個雙眼皮（顯性）的父母生下單眼皮的孩子，父母的基因型最可能是？","A":"Aa 和 Aa","B":"AA 和 AA","C":"aa 和 aa","D":"AA 和 aa","answer":"A","explanation":"孩子 aa，父母各給一個 a，又都是雙眼皮，所以都是 Aa。","image":""},{"id":"G-08-01","isl":"G","lv":1,"stem":"人類女性體細胞的性染色體是？","A":"XY","B":"YY","C":"XX","D":"X","answer":"C","explanation":"女性 XX，男性 XY。","image":""},{"id":"G-08-02","isl":"G","lv":1,"stem":"決定生男或生女的是？","A":"卵帶 X 或 Y","B":"精子帶 X 或 Y","C":"母親的血型","D":"受精的時間","answer":"B","explanation":"卵都帶 X，精子帶 X 或 Y。","image":""},{"id":"G-08-03","isl":"G","lv":2,"stem":"AB 型血型的基因型是？","A":"IAIB","B":"IAIA","C":"IAi","D":"ii","answer":"A","explanation":"AB 型＝IAIB。","image":""},{"id":"G-08-04","isl":"G","lv":2,"stem":"父親 A 型（IAi）、母親 B 型（IBi），孩子可能是哪些血型？","A":"只有 A、B 型","B":"只有 AB 型","C":"只有 O 型","D":"A、B、AB、O 型都有可能","answer":"D","explanation":"IAi×IBi → IAIB、IAi、IBi、ii。","image":""},{"id":"G-08-05","isl":"G","lv":3,"stem":"一對夫妻已經生了三個男孩，第四胎是女孩的機率是？","A":"0","B":"1/4","C":"1/2","D":"3/4","answer":"C","explanation":"每一胎獨立，機率仍約 1/2。","image":""},{"id":"G-09-01","isl":"G","lv":1,"stem":"遺傳物質發生改變稱為？","A":"突變","B":"受精","C":"授粉","D":"演化","answer":"A","explanation":"遺傳物質改變就是突變。","image":""},{"id":"G-09-02","isl":"G","lv":1,"stem":"下列何者可能引起突變？","A":"喝白開水","B":"睡覺","C":"吃水果","D":"過量的紫外線","answer":"D","explanation":"輻射、某些化學物質可能引起突變。","image":""},{"id":"G-09-03","isl":"G","lv":2,"stem":"下列哪一種突變可能遺傳給下一代？","A":"皮膚細胞的突變","B":"肺細胞的突變","C":"精子或卵的突變","D":"肌肉細胞的突變","answer":"C","explanation":"生殖細胞的突變才可能遺傳。","image":""},{"id":"G-09-04","isl":"G","lv":2,"stem":"農業上用輻射照射種子，目的是？","A":"殺死種子","B":"誘發突變，篩選出新品種","C":"讓種子更快發芽","D":"讓種子變乾","answer":"B","explanation":"人類利用誘發突變培育新品種。","image":""},{"id":"G-09-05","isl":"G","lv":3,"stem":"關於突變的敘述，何者正確？","A":"突變可能改變性狀，影響可能有害、無害或有利","B":"所有突變都會遺傳","C":"突變一定讓生物變強","D":"突變只發生在植物","answer":"A","explanation":"突變影響各有不同。","image":""},{"id":"G-10-01","isl":"G","lv":1,"stem":"把人類的胰島素基因放入細菌中，使細菌生產胰島素，這是？","A":"組織培養","B":"嫁接","C":"基因轉殖","D":"雜交","answer":"C","explanation":"轉移基因到另一種生物＝基因轉殖。","image":""},{"id":"G-10-02","isl":"G","lv":1,"stem":"下列何者屬於傳統的生物技術？","A":"基因轉殖","B":"釀酒","C":"複製羊","D":"螢光魚","answer":"B","explanation":"釀酒利用酵母菌，是傳統生技。","image":""},{"id":"G-10-03","isl":"G","lv":2,"stem":"萃取 DNA 時加入冰酒精，會看到什麼？","A":"白色絲狀的 DNA 析出","B":"溶液變紅","C":"產生氣泡","D":"溶液結冰","answer":"A","explanation":"DNA 不溶於冰酒精，析出成白色絲狀。","image":""},{"id":"G-10-04","isl":"G","lv":2,"stem":"基因轉殖作物可能帶來的疑慮，下列何者合理？","A":"讓作物完全不能吃","B":"會讓吃的人變成植物","C":"會讓土壤消失","D":"可能影響生態或引起食品安全的討論","answer":"D","explanation":"需要評估生態與食品安全。","image":""},{"id":"G-10-05","isl":"G","lv":3,"stem":"下列關於生物技術的敘述，何者最恰當？","A":"生技只能用在醫藥","B":"生技一定不安全","C":"生技可應用在多個領域，但也可能帶來新問題","D":"組織培養會產生新品種","answer":"C","explanation":"課綱強調兩面性。","image":""},{"id":"G-11-01","isl":"G","lv":1,"stem":"從化石可以知道下列哪一件事？","A":"地球上曾經存在現在已消失的生物","B":"所有生物都沒有改變","C":"恐龍現在還活著","D":"化石都是假的","answer":"A","explanation":"例如三葉蟲、恐龍已經滅絕。","image":""},{"id":"G-11-02","isl":"G","lv":1,"stem":"在沒有翻轉的地層中，哪一層的化石通常最古老？","A":"最上層","B":"中間層","C":"無法判斷","D":"最下層","answer":"D","explanation":"下層較老、上層較新。","image":""},{"id":"G-11-03","isl":"G","lv":2,"stem":"化石最容易在什麼情況下形成？","A":"生物死後暴露在地表","B":"生物被火燒","C":"生物死後很快被泥沙掩埋","D":"生物被吃掉","answer":"C","explanation":"快速掩埋才能保存下來。","image":""},{"id":"G-11-04","isl":"G","lv":2,"stem":"比較不同年代地層的化石，通常會發現？","A":"所有地層化石都一樣","B":"古老地層的生物構造較簡單","C":"新的地層都沒有化石","D":"古老地層只有哺乳類","answer":"B","explanation":"生物隨時間演化，構造漸趨複雜多樣。","image":""},{"id":"G-11-05","isl":"G","lv":3,"stem":"依天擇說，下列哪一個解釋最合理？","A":"脖子較長的長頸鹿較能吃到食物，較容易存活並留下後代","B":"長頸鹿為了吃高處的葉子，脖子越伸越長","C":"長頸鹿的脖子一出生就固定不變，所以不會演化","D":"環境不會影響生物","answer":"A","explanation":"天擇：適應的個體存活並繁衍。","image":""},{"id":"G-12-01","isl":"G","lv":1,"stem":"生物分類階層由大到小，下列何者正確？","A":"種屬科目綱門界","B":"界綱門目科種屬","C":"界門綱目科屬種","D":"門界綱目屬科種","answer":"C","explanation":"界、門、綱、目、科、屬、種。","image":""},{"id":"G-12-02","isl":"G","lv":1,"stem":"人的學名是 Homo sapiens，其中 Homo 是？","A":"種小名","B":"屬名","C":"科名","D":"界名","answer":"B","explanation":"學名＝屬名＋種小名。","image":""},{"id":"G-12-03","isl":"G","lv":2,"stem":"下列哪兩種生物的親緣關係最近？","A":"同屬不同種","B":"同界不同門","C":"同門不同綱","D":"同科不同屬","answer":"A","explanation":"共同階層愈多愈相近。","image":""},{"id":"G-12-04","isl":"G","lv":2,"stem":"馬和驢交配生下騾，但騾通常不能生育，所以馬和驢？","A":"是同一種","B":"是同一屬也同一種","C":"不能判斷","D":"是不同種","answer":"D","explanation":"後代沒有生殖能力，不同種。","image":""},{"id":"G-12-05","isl":"G","lv":3,"stem":"使用二分法檢索表時，每一步驟的做法是？","A":"一次分成很多組","B":"只看顏色","C":"依一個特徵分成兩組，逐步比對","D":"隨便選一組","answer":"C","explanation":"每次依一組相對的特徵二選一。","image":""},{"id":"G-13-01","isl":"G","lv":1,"stem":"下列哪一種生物屬於真菌界？","A":"香菇","B":"海帶","C":"草履蟲","D":"蕨類","answer":"A","explanation":"香菇、黴菌、酵母菌屬真菌界。","image":""},{"id":"G-13-02","isl":"G","lv":1,"stem":"細菌的細胞和其他生物最大的不同是？","A":"沒有細胞膜","B":"沒有遺傳物質","C":"沒有細胞質","D":"沒有細胞核膜","answer":"D","explanation":"原核生物沒有細胞核膜。","image":""},{"id":"G-13-03","isl":"G","lv":2,"stem":"病毒不被歸入五界的主要原因是？","A":"病毒太小","B":"病毒會讓人生病","C":"病毒沒有細胞構造","D":"病毒不會繁殖","answer":"C","explanation":"病毒沒有細胞構造，需寄生在活細胞內繁殖。","image":""},{"id":"G-13-04","isl":"G","lv":2,"stem":"眼蟲有葉綠體，又能游動，它屬於？","A":"植物界","B":"原生生物界","C":"動物界","D":"原核生物界","answer":"B","explanation":"眼蟲是單細胞、有細胞核的原生生物。","image":""},{"id":"G-13-05","isl":"G","lv":3,"stem":"在生態系中，細菌和真菌常扮演什麼角色？","A":"分解者","B":"生產者","C":"消費者","D":"沒有角色","answer":"A","explanation":"分解遺體，讓物質回到環境中。","image":""},{"id":"G-14-01","isl":"G","lv":1,"stem":"酵母菌發酵時會產生什麼？","A":"氧氣和水","B":"澱粉","C":"酒精和二氧化碳","D":"蛋白質","answer":"C","explanation":"酵母菌分解糖產生酒精和二氧化碳。","image":""},{"id":"G-14-02","isl":"G","lv":1,"stem":"下列哪一種食品主要是利用乳酸菌製作的？","A":"麵包","B":"優格","C":"豆腐乳","D":"啤酒","answer":"B","explanation":"乳酸菌製作優格、泡菜。","image":""},{"id":"G-14-03","isl":"G","lv":2,"stem":"把酵母菌發酵產生的氣體通入澄清石灰水，會看到？","A":"石灰水變混濁","B":"石灰水變紅","C":"石灰水沸騰","D":"沒有變化","answer":"A","explanation":"二氧化碳使石灰水變混濁。","image":""},{"id":"G-14-04","isl":"G","lv":2,"stem":"關於人體內微生物的敘述，何者正確？","A":"全部都有害","B":"人體內沒有微生物","C":"微生物只在皮膚上","D":"腸道中有些細菌對人體有益","answer":"D","explanation":"有益菌能幫助消化、合成維生素。","image":""},{"id":"G-14-05","isl":"G","lv":3,"stem":"感冒（病毒感染）時吃抗生素通常沒有幫助，原因是？","A":"抗生素太苦","B":"病毒很大","C":"抗生素只對付細菌，不能殺死病毒","D":"感冒不會好","answer":"C","explanation":"抗生素對病毒無效，濫用還可能讓細菌產生抗藥性。","image":""},{"id":"G-21-01","isl":"G","lv":1,"stem":"遺傳物質 DNA 主要位在細胞的哪一個構造中？","A":"細胞膜","B":"細胞壁","C":"液泡","D":"細胞核","answer":"D","explanation":"DNA 主要位在細胞核的染色體上。","image":""},{"id":"G-21-02","isl":"G","lv":1,"stem":"DNA 的立體結構像什麼？","A":"單股直線","B":"實心圓球","C":"平面方格","D":"雙股螺旋","answer":"D","explanation":"華生與克里克發現 DNA 是雙股螺旋結構。","image":""},{"id":"G-21-03","isl":"G","lv":2,"stem":"染色體主要由哪兩種物質組成？","A":"DNA 與蛋白質","B":"水與無機鹽","C":"澱粉與纖維","D":"脂質與糖類","answer":"A","explanation":"染色體由 DNA 纏繞在蛋白質上形成。","image":""},{"id":"G-21-04","isl":"G","lv":2,"stem":"基因是什麼？","A":"一整個細胞","B":"含遺傳訊息的 DNA 片段","C":"一個器官","D":"一種激素","answer":"B","explanation":"基因是 DNA 上帶有遺傳訊息的片段，控制生物的性狀。","image":""},{"id":"G-21-05","isl":"G","lv":3,"stem":"同卵雙胞胎的基因幾乎完全相同，是因為？","A":"父母的基因相同","B":"由同一個受精卵分裂而來","C":"由兩個受精卵發育","D":"受精了兩次","answer":"B","explanation":"一個受精卵早期分成兩群細胞各自發育，所以遺傳物質相同。","image":""},{"id":"G-22-01","isl":"G","lv":1,"stem":"生殖細胞（精子與卵）是經由哪一種分裂產生的？","A":"分裂生殖","B":"體細胞分裂","C":"減數分裂","D":"出芽生殖","answer":"C","explanation":"減數分裂使染色體數目減半，形成生殖細胞。","image":""},{"id":"G-22-02","isl":"G","lv":1,"stem":"體細胞分裂後，子細胞與母細胞的染色體數目？","A":"加倍","B":"減半","C":"相同","D":"不一定","answer":"C","explanation":"體細胞分裂先複製染色體再平均分配，所以數目相同。","image":""},{"id":"G-22-03","isl":"G","lv":2,"stem":"人的卵細胞含有幾條染色體？","A":"46 條","B":"22 條","C":"92 條","D":"23 條","answer":"D","explanation":"人的體細胞有 46 條染色體，生殖細胞減半為 23 條。","image":""},{"id":"G-22-04","isl":"G","lv":2,"stem":"精子與卵受精後，受精卵有幾條染色體？","A":"23 條","B":"69 條","C":"46 條","D":"92 條","answer":"C","explanation":"23＋23＝46 條，恢復成體細胞的染色體數。","image":""},{"id":"G-22-05","isl":"G","lv":3,"stem":"減數分裂使生殖細胞染色體數減半，目的是？","A":"製造更多能量","B":"使受精後染色體數維持穩定","C":"使細胞變大","D":"增加細胞數量","answer":"B","explanation":"若沒有減半，每次受精染色體數都會加倍。","image":""},{"id":"G-23-01","isl":"G","lv":1,"stem":"孟德爾的豌豆實驗中，F1 只表現出來的性狀稱為？","A":"突變性狀","B":"顯性性狀","C":"隱性性狀","D":"變異性狀","answer":"B","explanation":"在雜交後代中表現出來的性狀是顯性性狀。","image":""},{"id":"G-23-02","isl":"G","lv":1,"stem":"豌豆圓形（R）對皺縮（r）為顯性，基因型 Rr 的表現型是？","A":"圓形","B":"皺縮","C":"半圓半皺","D":"無法判斷","answer":"A","explanation":"有顯性基因 R，就表現為圓形。","image":""},{"id":"G-23-03","isl":"G","lv":2,"stem":"Rr × Rr，子代表現型比例約為？","A":"1：1","B":"顯性：隱性＝3：1","C":"全部顯性","D":"1：3","answer":"B","explanation":"Rr×Rr 子代有 RR、Rr、Rr、rr，顯性與隱性約 3：1。","image":""},{"id":"G-23-04","isl":"G","lv":2,"stem":"純種高莖（TT）與純種矮莖（tt）雜交，F1 的基因型是？","A":"Tt","B":"TT","C":"Tt 與 tt","D":"tt","answer":"A","explanation":"親代各提供一個基因，F1 全是 Tt。","image":""},{"id":"G-23-05","isl":"G","lv":3,"stem":"Rr × rr，子代表現隱性性狀的機率約為？","A":"1","B":"3/4","C":"1/2","D":"1/4","answer":"C","explanation":"子代為 Rr 與 rr 各一半，隱性占 1/2。","image":""},{"id":"G-24-01","isl":"G","lv":1,"stem":"人類的 ABO 血型系統有幾種血型？","A":"4 種","B":"3 種","C":"8 種","D":"2 種","answer":"A","explanation":"有 A、B、AB、O 四種血型。","image":""},{"id":"G-24-02","isl":"G","lv":1,"stem":"O 型血的基因型是？","A":"IAIB","B":"ii","C":"IAi","D":"IBi","answer":"B","explanation":"O 型是隱性純合 ii。","image":""},{"id":"G-24-03","isl":"G","lv":2,"stem":"基因型 IAIB 的血型是？","A":"O 型","B":"B 型","C":"A 型","D":"AB 型","answer":"D","explanation":"IA 與 IB 都表現，是 AB 型。","image":""},{"id":"G-24-04","isl":"G","lv":2,"stem":"父親 AB 型、母親 O 型，孩子的血型可能是？","A":"只有 AB 型","B":"AB 型或 O 型","C":"只有 O 型","D":"A 型或 B 型","answer":"D","explanation":"AB 型提供 IA 或 IB，O 型提供 i，孩子是 IAi（A 型）或 IBi（B 型）。","image":""},{"id":"G-24-05","isl":"G","lv":3,"stem":"孩子是 O 型，父母不可能是下列哪一組？","A":"AB 型、AB 型","B":"A 型、B 型","C":"A 型、O 型","D":"B 型、B 型","answer":"A","explanation":"O 型孩子的基因型是 ii，父母各要提供 i，AB 型沒有 i。","image":""},{"id":"G-25-01","isl":"G","lv":1,"stem":"人類男性的性染色體組成是？","A":"XX","B":"XY","C":"YY","D":"XXY","answer":"B","explanation":"男性是 XY，女性是 XX。","image":""},{"id":"G-25-02","isl":"G","lv":1,"stem":"孩子的性別是由什麼決定的？","A":"母親的卵","B":"出生的時間","C":"醫生的判斷","D":"父親精子帶 X 還是 Y","answer":"D","explanation":"卵都帶 X，精子可能帶 X 或 Y，所以由精子決定。","image":""},{"id":"G-25-03","isl":"G","lv":2,"stem":"生男生女的機率各約為？","A":"1/3","B":"1/2","C":"1/4","D":"3/4","answer":"B","explanation":"精子帶 X 或 Y 的機會相等。","image":""},{"id":"G-25-04","isl":"G","lv":2,"stem":"紅綠色盲基因是 X 染色體上的隱性基因，男性比女性容易色盲，原因是？","A":"男性有兩條 Y","B":"男性有兩條 X","C":"女性沒有 X","D":"男性只有一條 X 染色體","answer":"D","explanation":"男性只有一條 X，只要有色盲基因就會表現。","image":""},{"id":"G-25-05","isl":"G","lv":3,"stem":"母親帶有色盲基因但本身正常，父親正常，兒子色盲的機率約為？","A":"1","B":"1/4","C":"0","D":"1/2","answer":"D","explanation":"兒子的 X 來自母親，有一半機會拿到帶色盲基因的 X。","image":""},{"id":"G-26-01","isl":"G","lv":1,"stem":"提出天擇說的科學家是？","A":"孟德爾","B":"牛頓","C":"達爾文","D":"巴斯德","answer":"C","explanation":"達爾文提出天擇說，解釋生物如何演化。","image":""},{"id":"G-26-02","isl":"G","lv":1,"stem":"化石是演化的證據，因為它能顯示？","A":"未來的生物","B":"太陽的距離","C":"現在的氣溫","D":"過去生物的樣貌","answer":"D","explanation":"化石記錄了過去生物的形態，可與現代生物比較。","image":""},{"id":"G-26-03","isl":"G","lv":2,"stem":"細菌對抗生素產生抗藥性，最合理的解釋是？","A":"所有細菌同時突變","B":"抗生素變弱了","C":"細菌決定要變強","D":"有抗藥性的細菌存活較多","answer":"D","explanation":"抗生素殺死不抗藥的細菌，留下的抗藥細菌繁殖出更多後代。","image":""},{"id":"G-26-04","isl":"G","lv":2,"stem":"達爾文發現各島的雀鳥喙形不同，與什麼最有關係？","A":"巢的形狀","B":"飛行速度","C":"羽毛顏色","D":"食物種類","answer":"D","explanation":"喙的形狀適合各島食物的類型。","image":""},{"id":"G-26-05","isl":"G","lv":3,"stem":"天擇的結果是？","A":"較適應環境的個體留下較多後代","B":"所有個體都一樣","C":"生物主動改變","D":"弱者全部死亡","answer":"A","explanation":"適應環境的個體存活和繁殖機會較高，特徵就逐漸變多。","image":""},{"id":"G-27-01","isl":"G","lv":1,"stem":"草履蟲主要以哪一種方式繁殖？","A":"孢子生殖","B":"分裂生殖","C":"出芽生殖","D":"有性生殖","answer":"B","explanation":"草履蟲一分為二，是分裂生殖。","image":""},{"id":"G-27-02","isl":"G","lv":1,"stem":"馬鈴薯塊莖長出新植株，屬於？","A":"孢子生殖","B":"營養繁殖","C":"有性生殖","D":"分裂生殖","answer":"B","explanation":"利用植物的營養器官長成新個體，是營養繁殖。","image":""},{"id":"G-27-03","isl":"G","lv":2,"stem":"無性生殖的後代與親代的遺傳性狀？","A":"隨機","B":"幾乎相同","C":"完全不同","D":"各占一半","answer":"B","explanation":"無性生殖沒有基因重組，後代性狀幾乎與親代相同。","image":""},{"id":"G-27-04","isl":"G","lv":2,"stem":"有性生殖的好處是？","A":"速度比較快","B":"後代與親代完全相同","C":"不需要配偶","D":"後代有較多變異","answer":"D","explanation":"兩性生殖細胞結合，使後代有較多變異，利於適應環境。","image":""},{"id":"G-27-05","isl":"G","lv":3,"stem":"下列哪一種屬於無性生殖？","A":"卵受精","B":"扦插","C":"種子發芽","D":"蜜蜂授粉","answer":"B","explanation":"扦插是切下枝條使其長成新植株，是無性生殖。","image":""},{"id":"G-28-01","isl":"G","lv":1,"stem":"生物的學名使用哪一種命名法？","A":"二名法","B":"數字法","C":"一名法","D":"三名法","answer":"A","explanation":"學名由屬名和種名組成，稱為二名法。","image":""},{"id":"G-28-02","isl":"G","lv":1,"stem":"下列哪一種動物屬於哺乳類？","A":"鱷魚","B":"鯨","C":"青蛙","D":"鯊魚","answer":"B","explanation":"鯨胎生並哺乳，是哺乳類，不是魚。","image":""},{"id":"G-28-03","isl":"G","lv":2,"stem":"學名 Homo sapiens 中的 Homo 是？","A":"屬名","B":"界名","C":"種名","D":"科名","answer":"A","explanation":"學名前面是屬名，後面是種名。","image":""},{"id":"G-28-04","isl":"G","lv":2,"stem":"蝙蝠會飛卻屬於哺乳類，是因為它？","A":"用鰓呼吸","B":"有羽毛","C":"有鱗片","D":"胎生並哺乳","answer":"D","explanation":"蝙蝠胎生並以乳汁哺育幼體。","image":""},{"id":"G-28-05","isl":"G","lv":3,"stem":"下列哪一組生物親緣關係最近？","A":"同屬的兩種生物","B":"同科不同屬的生物","C":"同界不同門的生物","D":"同綱不同目的生物","answer":"A","explanation":"分類階層越小，親緣關係越近，同屬比同科更近。","image":""},{"id":"H-01-01","isl":"H","lv":1,"stem":"下列哪一種情況，生物最容易形成化石？","A":"死後很快被泥沙掩埋","B":"死後留在森林地面","C":"被其他動物吃掉","D":"漂浮在海面上","answer":"A","explanation":"快速掩埋可以隔絕空氣，避免腐爛和被吃掉。","image":""},{"id":"H-01-02","isl":"H","lv":1,"stem":"化石最常保存在哪一類岩石中？","A":"火成岩","B":"變質岩","C":"岩漿","D":"沉積岩","answer":"D","explanation":"沉積物一層層掩埋生物，最容易保存化石。","image":""},{"id":"H-01-03","isl":"H","lv":2,"stem":"下列哪種生物最容易留下化石？","A":"水母","B":"蚯蚓","C":"有硬殼的貝類","D":"細菌","answer":"C","explanation":"有外殼、骨骼等堅硬部分，不容易腐爛。","image":""},{"id":"H-01-04","isl":"H","lv":2,"stem":"在高山上的岩層找到原本深埋地下的化石，主要是因為？","A":"化石會往上爬","B":"地殼抬升，加上侵蝕使岩層露出","C":"火山把化石噴上來","D":"有人把化石搬上山","answer":"B","explanation":"化石原本埋在地下，經過抬升與侵蝕才露出地表。","image":""},{"id":"H-01-05","isl":"H","lv":3,"stem":"恐龍骨頭化石摸起來像石頭，主要原因是？","A":"礦物質填入或取代了原本的骨頭","B":"恐龍的骨頭本來就是石頭","C":"化石被冷凍了","D":"化石外面塗了一層漆","answer":"A","explanation":"石化作用讓礦物慢慢填入、取代生物體。","image":""},{"id":"H-02-01","isl":"H","lv":1,"stem":"下列何者屬於遺跡化石？","A":"恐龍的牙齒","B":"貝殼","C":"恐龍足跡","D":"魚的骨骼","answer":"C","explanation":"足跡是生物活動留下的痕跡。","image":""},{"id":"H-02-02","isl":"H","lv":1,"stem":"下列何者屬於實體化石？","A":"蟲爬過的痕跡","B":"三葉蟲的外殼","C":"巢穴","D":"糞便化石","answer":"B","explanation":"外殼是生物身體的一部分。","image":""},{"id":"H-02-03","isl":"H","lv":2,"stem":"琥珀中的昆蟲是怎麼被保存下來的？","A":"被古代樹脂包住，樹脂硬化","B":"被冰凍起來","C":"被火山灰燒過","D":"一直泡在海水裡","answer":"A","explanation":"樹脂包住昆蟲後硬化成琥珀，隔絕了空氣。","image":""},{"id":"H-02-04","isl":"H","lv":2,"stem":"從一串恐龍足跡化石，最<b>不可能</b>知道的是？","A":"恐龍大概的體型","B":"恐龍走路的方向","C":"每一步的距離","D":"恐龍皮膚的顏色","answer":"D","explanation":"足跡保存不了顏色。","image":""},{"id":"H-02-05","isl":"H","lv":3,"stem":"在某岩層發現大量蟲孔化石，最合理的推論是？","A":"這層岩石是火成岩","B":"當時完全沒有生物","C":"當時有生物在泥中鑽洞生活","D":"這些洞是最近才挖的","answer":"C","explanation":"蟲孔是生物活動的痕跡，表示當時有生物生活在沉積物中。","image":""},{"id":"H-03-01","isl":"H","lv":1,"stem":"造礁珊瑚化石表示當時的環境是？","A":"溫暖清澈的淺海","B":"寒冷的深海","C":"乾燥的沙漠","D":"冰河","answer":"A","explanation":"造礁珊瑚只生活在溫暖、清澈的淺海。","image":""},{"id":"H-03-02","isl":"H","lv":1,"stem":"可以用來推測古代生活環境的化石稱為？","A":"標準化石","B":"遺跡化石","C":"人造化石","D":"指相化石","answer":"D","explanation":"指相化石指示當時的生活環境。","image":""},{"id":"H-03-03","isl":"H","lv":2,"stem":"某地岩層由下到上依序是：珊瑚化石層 → 貝殼化石層 → 樹葉化石層，最合理的推論是？","A":"那裡一直都是陸地","B":"那裡從陸地變成深海","C":"那裡從淺海逐漸變成陸地","D":"化石是被人放進去的","answer":"C","explanation":"下層較老：一開始是溫暖淺海，最上層時已變成陸地。","image":""},{"id":"H-03-04","isl":"H","lv":2,"stem":"在高山的岩層中發現貝殼化石，最可能的原因是？","A":"古代海水曾淹到現在這麼高","B":"地殼抬升，把海底的岩層抬到高處","C":"鳥把貝殼叼上山","D":"火山把貝殼噴上來","answer":"B","explanation":"地殼抬升把原本在海底的岩層帶到高山。","image":""},{"id":"H-03-05","isl":"H","lv":3,"stem":"下列哪一種生物的化石，最適合用來判斷古環境？","A":"只能生活在特定環境的生物","B":"什麼環境都能生活的生物","C":"剛死掉不久的生物","D":"人造的模型","answer":"A","explanation":"生活環境越特定，越能指示當時的環境。","image":""},{"id":"H-04-01","isl":"H","lv":1,"stem":"恐龍最興盛的時代是？","A":"古生代","B":"新生代","C":"中生代","D":"現在","answer":"C","explanation":"恐龍是中生代的代表生物。","image":""},{"id":"H-04-02","isl":"H","lv":1,"stem":"含有三葉蟲化石的岩層，最可能屬於哪個時代？","A":"中生代","B":"古生代","C":"新生代","D":"現在","answer":"B","explanation":"三葉蟲是古生代的標準化石。","image":""},{"id":"H-04-03","isl":"H","lv":2,"stem":"適合當作標準化石的生物，應該具備什麼特徵？","A":"生存時間短、分布範圍廣、特徵明顯","B":"生存時間長、分布範圍小","C":"只生活在一個小島上","D":"數量非常稀少、很難辨認","answer":"A","explanation":"生存時間短，年代才精確；分布廣、數量多，各地才找得到；特徵明顯，才容易鑑定。","image":""},{"id":"H-04-04","isl":"H","lv":2,"stem":"把地球 46 億年的歷史縮成一天，人類大約出現在？","A":"早上 6 點","B":"中午 12 點","C":"晚上 6 點","D":"午夜前幾秒","answer":"D","explanation":"人類出現至今只有幾十萬年，相當於一天的最後幾秒。","image":""},{"id":"H-04-05","isl":"H","lv":3,"stem":"某岩層中同時找到恐龍骨骼和菊石化石，這層岩層最可能形成於？","A":"古生代","B":"新生代","C":"中生代","D":"最近一萬年","answer":"C","explanation":"恐龍和菊石都是中生代的代表生物。","image":""},{"id":"H-05-01","isl":"H","lv":1,"stem":"沒有受到擾動的地層，哪一層最老？","A":"最下層","B":"最上層","C":"中間層","D":"都一樣老","answer":"A","explanation":"疊置原理：下層先沉積，比較老。","image":""},{"id":"H-05-02","isl":"H","lv":1,"stem":"沉積物變成沉積岩，需要經過？","A":"熔化","B":"高溫結晶","C":"結冰","D":"壓實與膠結","answer":"D","explanation":"沉積物被壓實、膠結，形成沉積岩。","image":""},{"id":"H-05-03","isl":"H","lv":2,"stem":"由礫石膠結而成的沉積岩是？","A":"頁岩","B":"砂岩","C":"礫岩","D":"玄武岩","answer":"C","explanation":"顆粒最大的礫石膠結成礫岩。","image":""},{"id":"H-05-04","isl":"H","lv":2,"stem":"河流流進湖裡，最先在湖邊沉積下來的是？","A":"泥","B":"礫石","C":"沙","D":"三種同時","answer":"B","explanation":"流速一變慢，顆粒最大的礫石最先沉下。","image":""},{"id":"H-05-05","isl":"H","lv":3,"stem":"如果一套地層被翻轉成上下顛倒，要怎麼判斷原本的上下？","A":"用化石或沉積構造判斷原本的上下","B":"看哪一層顏色比較深","C":"一律認定下層比較老","D":"看哪一層比較厚","answer":"A","explanation":"疊置原理只適用於沒翻轉的地層，要用化石等證據確認。","image":""},{"id":"H-06-01","isl":"H","lv":1,"stem":"地層受擠壓向上拱起的構造稱為？","A":"向斜","B":"正斷層","C":"背斜","D":"逆斷層","answer":"C","explanation":"向上拱起的是背斜。","image":""},{"id":"H-06-02","isl":"H","lv":1,"stem":"褶皺主要是地層受到什麼力造成的？","A":"拉張力","B":"擠壓力","C":"向下的重力","D":"磁力","answer":"B","explanation":"兩側擠壓使地層彎曲。","image":""},{"id":"H-06-03","isl":"H","lv":2,"stem":"背斜的中心部分，地層的年代比兩側？","A":"較老","B":"較新","C":"一樣","D":"無法比較","answer":"A","explanation":"背斜向上拱，中心露出的是較老的地層。","image":""},{"id":"H-06-04","isl":"H","lv":2,"stem":"下列哪個地區最容易看到褶皺？","A":"板塊中央穩定的平原","B":"大洋中央的深海平原","C":"月球表面","D":"板塊聚合、受到擠壓的地區","answer":"D","explanation":"受擠壓力大的地方，容易形成褶皺。","image":""},{"id":"H-06-05","isl":"H","lv":3,"stem":"背斜經過長時間侵蝕後，地表一定還是高山嗎？","A":"一定是高山","B":"一定變成湖","C":"不一定，侵蝕後地形可能變低","D":"一定變成海","answer":"C","explanation":"地層構造和地表地形不一定一致。","image":""},{"id":"H-07-01","isl":"H","lv":1,"stem":"岩層斷裂，且兩側沿斷裂面發生相對移動，稱為？","A":"斷層","B":"褶皺","C":"節理","D":"層面","answer":"A","explanation":"有相對移動才是斷層。","image":""},{"id":"H-07-02","isl":"H","lv":1,"stem":"正斷層是受到什麼力形成的？","A":"擠壓力","B":"磁力","C":"浮力","D":"拉張力","answer":"D","explanation":"拉張力使上盤往下滑。","image":""},{"id":"H-07-03","isl":"H","lv":2,"stem":"逆斷層中，上盤相對於下盤如何移動？","A":"往下","B":"不動","C":"往上","D":"左右錯開","answer":"C","explanation":"擠壓力使上盤沿斷層面往上移。","image":""},{"id":"H-07-04","isl":"H","lv":2,"stem":"1999 年九二一大地震是哪一條斷層錯動造成的？","A":"聖安地列斯斷層","B":"車籠埔斷層","C":"花東縱谷斷層","D":"梅山斷層","answer":"B","explanation":"九二一地震由車籠埔斷層錯動造成，屬於逆斷層。","image":""},{"id":"H-07-05","isl":"H","lv":3,"stem":"在野外看到岩層裂開，但兩側完全沒有錯動，最可能是？","A":"節理","B":"正斷層","C":"逆斷層","D":"背斜","answer":"A","explanation":"裂開但沒有移動的裂縫叫節理。","image":""},{"id":"H-08-01","isl":"H","lv":1,"stem":"岩漿切穿岩層後冷卻，形成的岩石屬於？","A":"沉積岩","B":"化石","C":"火成岩","D":"土壤","answer":"C","explanation":"岩漿冷卻形成火成岩。","image":""},{"id":"H-08-02","isl":"H","lv":1,"stem":"依截切原理，切穿岩層的岩脈和被切穿的岩層相比？","A":"岩脈較老","B":"岩脈較年輕","C":"一樣老","D":"無法判斷","answer":"B","explanation":"被切穿的岩層要先存在，所以岩脈較年輕。","image":""},{"id":"H-08-03","isl":"H","lv":2,"stem":"侵蝕面代表這個地方曾經？","A":"被抬升並受到侵蝕","B":"連續沉積沒有中斷","C":"被岩漿整個熔化","D":"發生化學反應","answer":"A","explanation":"侵蝕面代表地層曾露出地表被侵蝕，沉積中斷了一段時間。","image":""},{"id":"H-08-04","isl":"H","lv":2,"stem":"一條斷層切斷了甲、乙兩層，但沒有切斷上面的丙層，事件的先後順序是？","A":"丙沉積 → 斷層 → 甲、乙沉積","B":"斷層 → 甲、乙沉積 → 丙沉積","C":"甲、乙、丙沉積 → 斷層","D":"甲、乙沉積 → 斷層 → 丙沉積","answer":"D","explanation":"斷層比甲、乙年輕，但比沒被切斷的丙老。","image":""},{"id":"H-08-05","isl":"H","lv":3,"stem":"侵蝕面下方地層傾斜、上方地層水平，下方地層經歷的順序是？","A":"侵蝕 → 沉積 → 傾斜","B":"傾斜 → 沉積 → 侵蝕","C":"沉積 → 傾斜 → 侵蝕","D":"只有沉積","answer":"C","explanation":"先沉積，再受力傾斜、抬升侵蝕，之後才在上面沉積水平地層。","image":""},{"id":"H-09-01","isl":"H","lv":1,"stem":"判讀沒翻轉地層的先後順序，最先使用的是？","A":"疊置原理","B":"浮力原理","C":"槓桿原理","D":"能量守恆","answer":"A","explanation":"疊置原理：下老上新。","image":""},{"id":"H-09-02","isl":"H","lv":2,"stem":"剖面中岩脈切穿甲、乙、丙三層，但沒有切到最上方的丁層，則？","A":"岩脈最老","B":"岩脈最年輕","C":"岩脈和甲一樣老","D":"岩脈比丁老、比甲乙丙年輕","answer":"D","explanation":"岩脈比切穿的地層年輕，比沒切到的丁老。","image":""},{"id":"H-09-03","isl":"H","lv":2,"stem":"某剖面下方地層褶皺、上方地層水平，兩者之間有侵蝕面，最合理的順序是？","A":"上方沉積 → 下方沉積 → 褶皺","B":"褶皺 → 下方沉積 → 侵蝕","C":"下方沉積 → 褶皺 → 侵蝕 → 上方沉積","D":"侵蝕 → 褶皺 → 下方沉積","answer":"C","explanation":"地層要先沉積才能褶皺，侵蝕之後才再沉積上方地層。","image":""},{"id":"H-09-04","isl":"H","lv":3,"stem":"斷層切過甲、乙兩層；後來岩脈又切穿了斷層和最上方的丙層。最年輕的是？","A":"甲","B":"岩脈","C":"斷層","D":"乙","answer":"B","explanation":"岩脈切穿了斷層和丙層，所以最年輕。","image":""},{"id":"H-09-05","isl":"H","lv":3,"stem":"下列何者<b>不能</b>用來判斷地層的先後順序？","A":"地層的顏色","B":"疊置原理","C":"截切原理","D":"標準化石","answer":"A","explanation":"地層顏色和年代無關。","image":""},{"id":"H-10-01","isl":"H","lv":1,"stem":"利用相同的標準化石，把不同地區的地層對應起來，稱為？","A":"疊置原理","B":"截切原理","C":"地層對比","D":"岩石循環","answer":"C","explanation":"地層對比可以比較各地地層的年代。","image":""},{"id":"H-10-02","isl":"H","lv":2,"stem":"甲地某層含菊石化石，乙地某層也含菊石化石，可以推論？","A":"兩地以前一定連在一起","B":"兩層大約在相近的年代形成","C":"兩層一定一樣厚","D":"菊石會長途游泳","answer":"B","explanation":"相同的標準化石代表相近的年代。","image":""},{"id":"H-10-03","isl":"H","lv":2,"stem":"臺灣目前沒有發現恐龍化石，最主要的原因是？","A":"臺灣的岩層大多形成於恐龍滅絕之後","B":"臺灣的恐龍都被吃光了","C":"臺灣沒有沉積岩","D":"化石都被颱風吹走了","answer":"A","explanation":"臺灣的岩層大多屬於新生代。","image":""},{"id":"H-10-04","isl":"H","lv":2,"stem":"臺南左鎮一帶出土的犀牛、劍齒虎化石，屬於哪個代？","A":"古生代","B":"中生代","C":"前寒武紀","D":"新生代","answer":"D","explanation":"哺乳動物在新生代興盛。","image":""},{"id":"H-10-05","isl":"H","lv":3,"stem":"要把各地零碎的地層紀錄拼成完整的地球歷史，最需要的是？","A":"只研究一個地方","B":"只看岩石顏色","C":"地層對比","D":"只量地層厚度","answer":"C","explanation":"對比各地地層，才能把零碎的紀錄連起來。","image":""},{"id":"H-21-01","isl":"H","lv":1,"stem":"地質年代由老到新的順序是？","A":"新生代、中生代、古生代","B":"中生代、古生代、新生代","C":"古生代、中生代、新生代","D":"古生代、新生代、中生代","answer":"C","explanation":"古生代最老，其次中生代，新生代最新。","image":""},{"id":"H-21-02","isl":"H","lv":1,"stem":"人類出現在哪一個代？","A":"前寒武紀","B":"古生代","C":"中生代","D":"新生代","answer":"D","explanation":"人類出現在新生代。","image":""},{"id":"H-21-03","isl":"H","lv":2,"stem":"三葉蟲是哪一個代的標準化石？","A":"新生代","B":"古生代","C":"現代","D":"中生代","answer":"B","explanation":"三葉蟲繁盛於古生代。","image":""},{"id":"H-21-04","isl":"H","lv":2,"stem":"地質年代的劃分主要依據什麼？","A":"天氣預報","B":"人類的歷史","C":"生物種類的重大變化","D":"各國的疆界","answer":"C","explanation":"地質年代是依地層中生物化石的變化來劃分的。","image":""},{"id":"H-21-05","isl":"H","lv":3,"stem":"地球整個歷史中，時間最長的是？","A":"新生代","B":"前寒武紀","C":"古生代","D":"中生代","answer":"B","explanation":"前寒武紀約占地球歷史的 88%。","image":""},{"id":"H-22-01","isl":"H","lv":1,"stem":"地球上最早出現的生物是？","A":"開花植物","B":"哺乳類","C":"恐龍","D":"單細胞生物","answer":"D","explanation":"最早的生命是簡單的單細胞生物。","image":""},{"id":"H-22-02","isl":"H","lv":1,"stem":"最早登上陸地的脊椎動物是？","A":"哺乳類","B":"魚類","C":"鳥類","D":"兩生類","answer":"D","explanation":"兩生類是第一類登上陸地的脊椎動物。","image":""},{"id":"H-22-03","isl":"H","lv":2,"stem":"生命大爆發（寒武紀）出現在哪一個時期？","A":"現代","B":"新生代","C":"中生代末期","D":"古生代初期","answer":"D","explanation":"寒武紀是古生代初期，許多動物類群突然出現。","image":""},{"id":"H-22-04","isl":"H","lv":2,"stem":"中生代末期恐龍大滅絕，可能原因是？","A":"海洋消失","B":"小行星撞擊造成氣候劇變","C":"人類獵殺","D":"太陽熄滅","answer":"B","explanation":"許多證據顯示約 6600 萬年前有小行星撞擊地球。","image":""},{"id":"H-22-05","isl":"H","lv":3,"stem":"哺乳類大量繁盛，是在哪一個代？","A":"新生代","B":"前寒武紀","C":"中生代初期","D":"古生代","answer":"A","explanation":"恐龍滅絕後，哺乳類在新生代快速演化繁盛。","image":""},{"id":"H-23-01","isl":"H","lv":1,"stem":"科學家測定岩石絕對年齡，常用什麼方法？","A":"放射性元素定年","B":"秤重量","C":"看顏色","D":"量長度","answer":"A","explanation":"利用放射性元素衰變的速率可以推算年齡。","image":""},{"id":"H-23-02","isl":"H","lv":1,"stem":"半衰期是指放射性元素衰變到剩下原來的多少，所需的時間？","A":"四分之一","B":"一半","C":"兩倍","D":"全部","answer":"B","explanation":"半衰期是原子數量減少一半所需的時間。","image":""},{"id":"H-23-03","isl":"H","lv":2,"stem":"某元素半衰期 10 年，經過 20 年後剩下原來的？","A":"1/8","B":"0","C":"1/2","D":"1/4","answer":"D","explanation":"20 年是 2 個半衰期，剩 1/2×1/2＝1/4。","image":""},{"id":"H-23-04","isl":"H","lv":2,"stem":"碳-14 定年法適合測定什麼的年代？","A":"火山岩","B":"曾經是生物的遺物","C":"金屬","D":"隕石","answer":"B","explanation":"碳-14 存在於生物體內，可測定生物遺物的年代。","image":""},{"id":"H-23-05","isl":"H","lv":3,"stem":"某化石的碳-14 剩下 1/8，半衰期為 5700 年，年齡約為？","A":"22800 年","B":"17100 年","C":"11400 年","D":"5700 年","answer":"B","explanation":"1/8 是 3 個半衰期，5700×3＝17100 年。","image":""},{"id":"H-24-01","isl":"H","lv":1,"stem":"提出大陸漂移說的科學家是？","A":"伽利略","B":"達爾文","C":"魏格納","D":"牛頓","answer":"C","explanation":"魏格納於 1912 年提出大陸漂移說。","image":""},{"id":"H-24-02","isl":"H","lv":1,"stem":"魏格納認為過去各大陸連在一起，這塊大陸稱為？","A":"盤古大陸","B":"泰坦大陸","C":"新大陸","D":"南極大陸","answer":"A","explanation":"古代連在一起的超大陸稱為盤古大陸。","image":""},{"id":"H-24-03","isl":"H","lv":2,"stem":"支持大陸漂移說的證據之一是？","A":"太陽黑子","B":"不同大陸有相同的生物化石","C":"月相變化","D":"潮汐","answer":"B","explanation":"相隔大洋的大陸出現相同的化石，表示它們曾經相連。","image":""},{"id":"H-24-04","isl":"H","lv":2,"stem":"南美洲東岸與非洲西岸的海岸線形狀？","A":"都是圓形","B":"大致可以拼合","C":"都是直線","D":"完全不同","answer":"B","explanation":"兩岸形狀相合，是魏格納提出的證據。","image":""},{"id":"H-24-05","isl":"H","lv":3,"stem":"海底擴張說認為新的海洋地殼在哪裡形成？","A":"河口","B":"大陸中心","C":"中洋脊","D":"海溝","answer":"C","explanation":"岩漿在中洋脊湧出，冷卻形成新的海洋地殼。","image":""},{"id":"H-25-01","isl":"H","lv":1,"stem":"岩脈切穿岩層時，何者較新？","A":"兩者同時","B":"無法比較","C":"被切穿的岩層","D":"岩脈","answer":"D","explanation":"後來切入的岩脈比被切穿的岩層晚形成。","image":""},{"id":"H-25-02","isl":"H","lv":1,"stem":"地層中的褶皺和斷層是怎麼形成的？","A":"生物挖掘","B":"地殼受力","C":"風吹","D":"月球引力","answer":"B","explanation":"地殼受到擠壓或拉張，就會彎曲或斷裂。","image":""},{"id":"H-25-03","isl":"H","lv":2,"stem":"斷層面上方的岩層相對下滑，稱為？","A":"平移斷層","B":"正斷層","C":"褶皺","D":"逆斷層","answer":"B","explanation":"上盤下降的是正斷層，多因拉張力造成。","image":""},{"id":"H-25-04","isl":"H","lv":2,"stem":"受到擠壓力，使上盤相對上升的斷層稱為？","A":"正斷層","B":"逆斷層","C":"向斜","D":"平移斷層","answer":"B","explanation":"上盤上升的是逆斷層，由擠壓造成。","image":""},{"id":"H-25-05","isl":"H","lv":3,"stem":"岩層中向下凹的彎曲構造稱為？","A":"背斜","B":"節理","C":"向斜","D":"斷層","answer":"C","explanation":"向下彎曲的褶皺是向斜，向上拱的是背斜。","image":""},{"id":"H-26-01","isl":"H","lv":1,"stem":"發現煤層，表示當時的環境可能是？","A":"極地冰原","B":"乾燥沙漠","C":"深海","D":"茂密的植物環境","answer":"D","explanation":"煤是大量植物遺體堆積變質形成的。","image":""},{"id":"H-26-02","isl":"H","lv":1,"stem":"在高山上發現海洋生物化石，說明？","A":"化石是假的","B":"該地過去曾是海洋","C":"山很低","D":"魚會爬山","answer":"B","explanation":"地殼運動使海底隆起成山。","image":""},{"id":"H-26-03","isl":"H","lv":2,"stem":"岩層中有冰河刮痕與冰磧物，表示？","A":"當時曾有冰河作用","B":"曾是沙漠","C":"曾是熱帶雨林","D":"曾是火山","answer":"A","explanation":"冰河移動會留下刮痕與冰磧物。","image":""},{"id":"H-26-04","isl":"H","lv":2,"stem":"石膏、岩鹽沉積層通常表示當時環境？","A":"高山","B":"乾燥、蒸發旺盛","C":"極地","D":"潮濕多雨","answer":"B","explanation":"海水或湖水大量蒸發才會留下鹽類沉積。","image":""},{"id":"H-26-05","isl":"H","lv":3,"stem":"在極地發現熱帶生物的化石，最合理的解釋是？","A":"化石自己移動","B":"大陸位置或氣候改變過","C":"太陽變大","D":"生物不怕冷","answer":"B","explanation":"大陸漂移或氣候變遷，使當地環境與現在不同。","image":""},{"id":"H-27-01","isl":"H","lv":1,"stem":"地球的年齡約為？","A":"46 億年","B":"4600 萬年","C":"4.6 億年","D":"4.6 萬年","answer":"A","explanation":"地球約形成於 46 億年前。","image":""},{"id":"H-27-02","isl":"H","lv":1,"stem":"恐龍大約在多久以前滅絕？","A":"660 年前","B":"66 萬年前","C":"6600 萬年前","D":"6600 年前","answer":"C","explanation":"中生代末期，約 6600 萬年前。","image":""},{"id":"H-27-03","isl":"H","lv":2,"stem":"把地球歷史比喻成 24 小時，人類大約出現在？","A":"凌晨剛開始","B":"早上六點","C":"中午","D":"最後不到一分鐘","answer":"D","explanation":"人類出現的時間只占地球歷史極短的一刻。","image":""},{"id":"H-27-04","isl":"H","lv":2,"stem":"下列哪一個事件發生最早？","A":"人類出現","B":"恐龍出現","C":"開花植物出現","D":"單細胞生物出現","answer":"D","explanation":"單細胞生命最早，約 35 億年前。","image":""},{"id":"H-27-05","isl":"H","lv":3,"stem":"地質年代的「新生代」約開始於？","A":"6600 萬年前","B":"1 萬年前","C":"2.5 億年前","D":"46 億年前","answer":"A","explanation":"新生代從恐龍大滅絕之後開始，到現在。","image":""},{"id":"H-28-01","isl":"H","lv":1,"stem":"臺灣位在哪兩個板塊的交界附近？","A":"印度板塊與非洲板塊","B":"太平洋板塊與南極板塊","C":"北美板塊與南美板塊","D":"歐亞板塊與菲律賓海板塊","answer":"D","explanation":"臺灣在歐亞板塊與菲律賓海板塊的碰撞帶上。","image":""},{"id":"H-28-02","isl":"H","lv":1,"stem":"臺灣的造山運動主要由什麼造成？","A":"海水","B":"板塊碰撞擠壓","C":"河流","D":"風力","answer":"B","explanation":"板塊相互擠壓，使地層隆起成山。","image":""},{"id":"H-28-03","isl":"H","lv":2,"stem":"臺灣最高峰玉山屬於哪一座山脈？","A":"中央山脈","B":"海岸山脈","C":"雪山山脈","D":"玉山山脈","answer":"D","explanation":"玉山位於玉山山脈，海拔 3952 公尺。","image":""},{"id":"H-28-04","isl":"H","lv":2,"stem":"臺灣東部的海岸山脈，原本屬於哪個板塊？","A":"印澳板塊","B":"歐亞板塊","C":"太平洋板塊","D":"菲律賓海板塊","answer":"D","explanation":"海岸山脈是菲律賓海板塊上的島弧，因碰撞而併入臺灣。","image":""},{"id":"H-28-05","isl":"H","lv":3,"stem":"花東縱谷是兩個板塊的縫合帶，這裡容易發生？","A":"暴風雪","B":"地震","C":"日食","D":"沙塵暴","answer":"B","explanation":"板塊交界地帶應力累積，容易發生地震。","image":""},{"id":"I-01-01","isl":"I","lv":1,"stem":"下列何者屬於內營力？","A":"造山運動","B":"河流侵蝕","C":"海浪拍打","D":"風吹沙","answer":"A","explanation":"造山運動的能量來自地球內部。","image":""},{"id":"I-01-02","isl":"I","lv":1,"stem":"岩石在原地崩解、分解的作用稱為？","A":"侵蝕","B":"搬運","C":"沉積","D":"風化","answer":"D","explanation":"風化是在原地發生；被帶走才是侵蝕。","image":""},{"id":"I-01-03","isl":"I","lv":2,"stem":"河流到了河口流速變慢，最可能發生？","A":"侵蝕加劇","B":"造山運動","C":"泥沙沉積","D":"火山爆發","answer":"C","explanation":"流速變慢，搬運能力下降，泥沙沉積形成三角洲。","image":""},{"id":"I-01-04","isl":"I","lv":2,"stem":"外營力長期作用的結果，地表會？","A":"越來越崎嶇","B":"趨向平坦","C":"不斷隆起","D":"完全不變","answer":"B","explanation":"外營力削高填低，使地表趨向平坦。","image":""},{"id":"I-01-05","isl":"I","lv":3,"stem":"臺灣的山雖然一直被侵蝕，卻沒有變平，主要原因是？","A":"板塊擠壓使山持續隆起","B":"侵蝕作用很弱","C":"沒有下雨","D":"山都是硬石頭","answer":"A","explanation":"內營力（板塊擠壓）讓臺灣的山持續隆起。","image":""},{"id":"I-02-01","isl":"I","lv":1,"stem":"地球構造由外而內依序為？","A":"地核、地函、地殼","B":"地函、地殼、地核","C":"地殼、地函、地核","D":"地殼、地核、地函","answer":"C","explanation":"由外而內是地殼、地函、地核。","image":""},{"id":"I-02-02","isl":"I","lv":1,"stem":"板塊互相分離的交界，常形成？","A":"海溝","B":"中洋脊","C":"高山","D":"島弧","answer":"B","explanation":"張裂型交界岩漿上湧，形成中洋脊。","image":""},{"id":"I-02-03","isl":"I","lv":2,"stem":"喜馬拉雅山是怎麼形成的？","A":"兩個大陸板塊碰撞擠壓","B":"板塊張裂","C":"火山噴發堆積","D":"河流沉積","answer":"A","explanation":"印度板塊和歐亞板塊碰撞，形成高山。","image":""},{"id":"I-02-04","isl":"I","lv":2,"stem":"關於岩石圈，下列何者正確？","A":"只包含地殼","B":"是液態的","C":"位在地核中","D":"包含地殼與上部地函的堅硬部分","answer":"D","explanation":"岩石圈 = 地殼 + 上部地函的堅硬部分。","image":""},{"id":"I-02-05","isl":"I","lv":3,"stem":"臺灣中央山脈至今仍在隆起，主要原因是？","A":"火山噴發","B":"河流沉積","C":"歐亞板塊與菲律賓海板塊持續聚合擠壓","D":"海平面下降","answer":"C","explanation":"兩板塊持續擠壓，使臺灣的山持續隆起。","image":""},{"id":"I-03-01","isl":"I","lv":1,"stem":"表示地震釋放能量大小的是？","A":"規模","B":"震度","C":"震源","D":"震央","answer":"A","explanation":"規模代表釋放的能量。","image":""},{"id":"I-03-02","isl":"I","lv":1,"stem":"全世界地震最多、最集中的地帶是？","A":"赤道","B":"北極圈","C":"撒哈拉沙漠","D":"環太平洋地震帶","answer":"D","explanation":"環太平洋地震帶又稱火環。","image":""},{"id":"I-03-03","isl":"I","lv":2,"stem":"同一次地震，臺北震度 3 級、花蓮震度 5 級，最可能的原因是？","A":"兩地規模不同","B":"臺北比較高","C":"花蓮離震央較近","D":"花蓮的房子比較舊","answer":"C","explanation":"震度通常離震央越近越大；規模只有一個。","image":""},{"id":"I-03-04","isl":"I","lv":2,"stem":"震源正上方的地表位置稱為？","A":"震源","B":"震央","C":"斷層","D":"火山口","answer":"B","explanation":"震央在震源正上方的地表。","image":""},{"id":"I-03-05","isl":"I","lv":3,"stem":"把全球地震和火山的位置畫在地圖上，會發現？","A":"兩者分布相當吻合，多在板塊交界","B":"兩者分布毫無關係","C":"都在大陸中央","D":"只出現在南半球","answer":"A","explanation":"Ia-IV-4：地震與火山分布在特定地帶，且兩者相當吻合。","image":""},{"id":"I-04-01","isl":"I","lv":1,"stem":"臺灣白天最短的一天是？","A":"春分","B":"夏至","C":"冬至","D":"秋分","answer":"C","explanation":"冬至白天最短、黑夜最長。","image":""},{"id":"I-04-02","isl":"I","lv":1,"stem":"造成晝夜交替的原因是？","A":"地球公轉","B":"地球自轉","C":"月球公轉","D":"太陽自轉","answer":"B","explanation":"地球自轉造成晝夜交替。","image":""},{"id":"I-04-03","isl":"I","lv":2,"stem":"夏至這天，臺北的太陽大約從哪個方位升起？","A":"東北","B":"正東","C":"東南","D":"正北","answer":"A","explanation":"夏天太陽從東北方升起、西北方落下。","image":""},{"id":"I-04-04","isl":"I","lv":2,"stem":"下列哪個地方，一年四季晝夜長短變化最小？","A":"臺灣","B":"日本","C":"北極附近","D":"赤道附近","answer":"D","explanation":"赤道附近終年晝夜大約等長。","image":""},{"id":"I-04-05","isl":"I","lv":3,"stem":"冬天放學走出校門時天已經暗了，夏天同一時間天還很亮，主要原因是？","A":"冬天雲比較多","B":"冬天太陽比較小","C":"冬天白天比較短","D":"冬天地球離太陽比較遠","answer":"C","explanation":"Id-IV-1：冬季黑夜較長、白天較短。","image":""},{"id":"I-05-01","isl":"I","lv":1,"stem":"陽光照射角度越接近垂直，地表單位面積吸收的能量？","A":"越多","B":"越少","C":"不變","D":"先多後少","answer":"A","explanation":"越直射，能量越集中。","image":""},{"id":"I-05-02","isl":"I","lv":1,"stem":"一天中太陽仰角最大的時刻約在？","A":"清晨","B":"傍晚","C":"午夜","D":"正午","answer":"D","explanation":"正午太陽仰角最大。","image":""},{"id":"I-05-03","isl":"I","lv":2,"stem":"同樣的手電筒斜斜照在格子紙上，比起直直照，照到的格子數會？","A":"較少","B":"一樣","C":"較多","D":"變成 0","answer":"C","explanation":"斜射時光分散，照到的面積變大。","image":""},{"id":"I-05-04","isl":"I","lv":2,"stem":"臺北冬至正午的影子比夏至正午的影子？","A":"較短","B":"較長","C":"一樣長","D":"沒有影子","answer":"B","explanation":"冬至太陽仰角小，影子較長。","image":""},{"id":"I-05-05","isl":"I","lv":3,"stem":"太陽能板裝成可以轉動、追著太陽，主要目的是？","A":"讓陽光盡量直射以吸收較多能量","B":"讓板子不積灰塵","C":"讓陽光盡量斜射","D":"降低板子溫度","answer":"A","explanation":"直射時單位面積接收的能量最多。","image":""},{"id":"I-06-01","isl":"I","lv":1,"stem":"地球自轉軸相對於公轉軌道面傾斜約？","A":"0°","B":"45°","C":"23.5°","D":"90°","answer":"C","explanation":"地軸傾斜約 23.5°。","image":""},{"id":"I-06-02","isl":"I","lv":1,"stem":"春分、秋分時，太陽直射？","A":"北回歸線","B":"赤道","C":"南回歸線","D":"北極","answer":"B","explanation":"春秋分太陽直射赤道。","image":""},{"id":"I-06-03","isl":"I","lv":2,"stem":"如果地軸沒有傾斜，地球會？","A":"沒有明顯四季","B":"四季更明顯","C":"沒有晝夜","D":"沒有颱風","answer":"A","explanation":"沒有傾斜，太陽直射點固定在赤道，四季不明顯。","image":""},{"id":"I-06-04","isl":"I","lv":2,"stem":"下列哪個地方在夏至正午時，太陽會出現在頭頂正上方？","A":"臺北","B":"赤道","C":"北極","D":"北回歸線上","answer":"D","explanation":"夏至太陽直射北回歸線，通過嘉義。","image":""},{"id":"I-06-05","isl":"I","lv":3,"stem":"北半球冬季時地球反而比較靠近太陽，這說明？","A":"距離是四季的主因","B":"冬天太陽比較大","C":"距離不是四季的主因","D":"地球公轉停止","answer":"C","explanation":"四季主因是地軸傾斜造成的太陽仰角與晝長變化。","image":""},{"id":"I-07-01","isl":"I","lv":1,"stem":"風形成的主要原因是？","A":"兩地有氣壓差","B":"兩地溫度相同","C":"月球引力","D":"地震","answer":"A","explanation":"氣壓差使空氣流動形成風。","image":""},{"id":"I-07-02","isl":"I","lv":1,"stem":"北半球高氣壓中心的空氣如何運動？","A":"逆時針旋入、上升","B":"靜止不動","C":"直線向上","D":"順時針旋出、下沉","answer":"D","explanation":"北半球高壓順時針旋出、中心下沉。","image":""},{"id":"I-07-03","isl":"I","lv":2,"stem":"天氣圖上甲地等壓線很密、乙地很稀疏，哪裡風較大？","A":"乙地","B":"一樣大","C":"甲地","D":"無法判斷","answer":"C","explanation":"等壓線越密，風越大。","image":""},{"id":"I-07-04","isl":"I","lv":2,"stem":"低氣壓籠罩的地區，天氣通常？","A":"晴朗乾燥","B":"多雲、容易下雨","C":"一定下雪","D":"一定颳颱風","answer":"B","explanation":"低壓中心空氣上升，容易成雲致雨。","image":""},{"id":"I-07-05","isl":"I","lv":3,"stem":"北半球的風在流動時向右偏，主要是因為？","A":"地球自轉","B":"月球引力","C":"地形阻擋","D":"海水溫度","answer":"A","explanation":"Ib-IV-3：地球自轉造成高低氣壓空氣的旋轉。","image":""},{"id":"I-08-01","isl":"I","lv":1,"stem":"性質不同的兩個氣團的交界面稱為？","A":"等壓線","B":"颱風眼","C":"鋒面","D":"季風","answer":"C","explanation":"Ib-IV-4：鋒面是性質不同的氣團之交界面。","image":""},{"id":"I-08-02","isl":"I","lv":1,"stem":"天氣圖上藍色三角形符號代表？","A":"暖鋒","B":"冷鋒","C":"滯留鋒","D":"高氣壓","answer":"B","explanation":"冷鋒是藍色三角形。","image":""},{"id":"I-08-03","isl":"I","lv":2,"stem":"冷鋒通過時，最可能出現的天氣是？","A":"短暫大雨或雷雨，過後降溫","B":"連續一個月的細雨","C":"晴朗無雲","D":"氣溫上升","answer":"A","explanation":"暖空氣被快速抬升，形成積雨雲。","image":""},{"id":"I-08-04","isl":"I","lv":2,"stem":"在溫暖海洋上形成的氣團，性質通常是？","A":"乾冷","B":"乾熱","C":"冷濕","D":"暖濕","answer":"D","explanation":"海洋使氣團潮濕、低緯度使其溫暖。","image":""},{"id":"I-08-05","isl":"I","lv":3,"stem":"冷暖氣團勢力相當、鋒面在臺灣附近徘徊好幾天，可能造成？","A":"乾旱","B":"颱風","C":"連續性降雨","D":"寒流","answer":"C","explanation":"滯留鋒帶來連續降雨，例如梅雨。","image":""},{"id":"I-09-01","isl":"I","lv":1,"stem":"臺灣夏季主要受哪一種季風影響？","A":"西南季風","B":"東北季風","C":"西北季風","D":"東南季風","answer":"A","explanation":"夏季吹西南季風。","image":""},{"id":"I-09-02","isl":"I","lv":1,"stem":"空氣遇到山脈被迫抬升時，容易？","A":"變得更乾燥","B":"溫度升高","C":"形成地震","D":"成雲降雨","answer":"D","explanation":"空氣上升冷卻，水氣凝結成雲雨。","image":""},{"id":"I-09-03","isl":"I","lv":2,"stem":"冬天東北季風吹來時，下列哪個地方最可能陰雨綿綿？","A":"高雄","B":"臺南","C":"基隆","D":"屏東","answer":"C","explanation":"基隆位在東北季風的迎風面。","image":""},{"id":"I-09-04","isl":"I","lv":2,"stem":"冬天中南部常常晴朗乾燥，主要原因是？","A":"離海較遠","B":"位在東北季風的背風面","C":"夏天下太多雨","D":"比較靠近赤道","answer":"B","explanation":"中央山脈擋住東北季風，中南部是背風面。","image":""},{"id":"I-09-05","isl":"I","lv":3,"stem":"下列關於臺灣季風的敘述何者正確？","A":"季風造成各地氣溫、風向、降水的季節差異","B":"季風風向一年四季不變","C":"季風只影響北部","D":"季風和山脈無關","answer":"A","explanation":"Ib-IV-6：季風造成各地氣溫、風向和降水的季節性差異。","image":""},{"id":"I-10-01","isl":"I","lv":1,"stem":"颱風在哪裡形成？","A":"北極","B":"沙漠","C":"熱帶海洋上","D":"高山上","answer":"C","explanation":"颱風在溫暖的熱帶海洋上形成。","image":""},{"id":"I-10-02","isl":"I","lv":1,"stem":"颱風屬於下列哪一種天氣系統？","A":"高氣壓","B":"低氣壓","C":"冷氣團","D":"鋒面","answer":"B","explanation":"颱風是強烈的低氣壓。","image":""},{"id":"I-10-03","isl":"I","lv":2,"stem":"颱風登陸後通常會減弱，主要原因是？","A":"失去海洋水氣來源並受地形破壞","B":"陸地上空氣比較冷","C":"颱風眼消失","D":"晚上溫度下降","answer":"A","explanation":"失去水氣、被地形破壞而減弱。","image":""},{"id":"I-10-04","isl":"I","lv":2,"stem":"颱風中心位在臺灣正東方的海上時，臺北大約吹什麼方向的風？（提示：北半球颱風逆時針旋轉）","A":"南風","B":"東風","C":"西風","D":"北風","answer":"D","explanation":"颱風中心在東方，臺北位在颱風西側，逆時針旋轉在西側由北往南吹，是北風。","image":""},{"id":"I-10-05","isl":"I","lv":3,"stem":"2009 年莫拉克颱風讓南部累積雨量達數千毫米，主要原因是？","A":"颱風從北部登陸","B":"颱風風速很小","C":"颱風移動緩慢，加上引進旺盛的西南氣流","D":"東北季風很強","answer":"C","explanation":"移動慢、加上西南氣流帶來大量水氣，南部迎風山區豪雨。","image":""},{"id":"I-11-01","isl":"I","lv":1,"stem":"臺灣的梅雨季主要出現在？","A":"5～6 月","B":"1～2 月","C":"8～9 月","D":"11～12 月","answer":"A","explanation":"梅雨季約在 5～6 月。","image":""},{"id":"I-11-02","isl":"I","lv":1,"stem":"寒潮來襲時，主要的天氣變化是？","A":"連續大雨","B":"颱風增強","C":"氣溫上升","D":"氣溫驟降","answer":"D","explanation":"大陸冷氣團南下使氣溫驟降。","image":""},{"id":"I-11-03","isl":"I","lv":2,"stem":"若某年梅雨季雨量很少，又沒有颱風帶來雨水，最可能發生？","A":"寒潮","B":"地震","C":"乾旱","D":"海嘯","answer":"C","explanation":"降雨偏少，水庫蓄水不足，可能乾旱。","image":""},{"id":"I-11-04","isl":"I","lv":2,"stem":"寒流來時，養殖漁業最需要注意什麼？","A":"海水變鹹","B":"魚因低溫凍死","C":"颱風巨浪","D":"水太熱","answer":"B","explanation":"低溫會造成養殖魚類凍死。","image":""},{"id":"I-11-05","isl":"I","lv":3,"stem":"臺灣年雨量比世界平均多，卻仍常缺水，原因<b>不包括</b>？","A":"臺灣每天都下雨","B":"降雨集中在梅雨和颱風季","C":"河川短而陡，雨水很快入海","D":"人口稠密，用水量大","answer":"A","explanation":"臺灣並非每天下雨，降雨在時間和空間上分布不均。","image":""},{"id":"I-12-01","isl":"I","lv":1,"stem":"流經臺灣東部、終年北上的海流是？","A":"親潮","B":"中國沿岸流","C":"黑潮","D":"赤道逆流","answer":"C","explanation":"黑潮是終年北上的暖流。","image":""},{"id":"I-12-02","isl":"I","lv":1,"stem":"波浪主要是由什麼形成的？","A":"月球引力","B":"風吹海面","C":"地震","D":"海水鹽度","answer":"B","explanation":"一般的波浪主要由風吹海面形成。","image":""},{"id":"I-12-03","isl":"I","lv":2,"stem":"海上有一顆浮球，一道道波浪經過時，浮球會？","A":"大致在原地上下起伏","B":"被帶到很遠的地方","C":"沉到海底","D":"逆著波浪前進","answer":"A","explanation":"波浪傳遞能量，水和浮球大致在原地運動。","image":""},{"id":"I-12-04","isl":"I","lv":2,"stem":"冬季臺灣海峽的海水較冷，主要是因為？","A":"黑潮增強","B":"颱風帶來冷水","C":"夏季季風","D":"中國沿岸流南下","answer":"D","explanation":"冬季東北季風強，中國沿岸流（冷水）沿大陸沿岸南下進入臺灣海峽，使海水變冷。","image":""},{"id":"I-12-05","isl":"I","lv":3,"stem":"受暖流影響的沿岸地區，氣候通常會？","A":"較乾冷","B":"變成沙漠","C":"較溫暖潮濕","D":"不受影響","answer":"C","explanation":"暖流會把熱量帶到沿岸，使氣候較溫暖潮濕。","image":""},{"id":"I-13-01","isl":"I","lv":1,"stem":"造成潮汐的主要原因是？","A":"月球引力","B":"風","C":"地震","D":"海流","answer":"A","explanation":"潮汐主要由月球引力造成。","image":""},{"id":"I-13-02","isl":"I","lv":1,"stem":"一天中大約會有幾次滿潮？","A":"一次","B":"四次","C":"六次","D":"兩次","answer":"D","explanation":"一天約兩次滿潮、兩次乾潮。","image":""},{"id":"I-13-03","isl":"I","lv":2,"stem":"某漁港今天上午 6:00 滿潮，明天上午這次滿潮約在？","A":"6:00","B":"5:10","C":"6:50","D":"12:00","answer":"C","explanation":"滿潮每天約延後 50 分鐘。","image":""},{"id":"I-13-04","isl":"I","lv":2,"stem":"下列哪一天的潮差最大？","A":"上弦月","B":"滿月","C":"下弦月","D":"每天都一樣","answer":"B","explanation":"新月、滿月時日月地成一直線，形成大潮。","image":""},{"id":"I-13-05","isl":"I","lv":3,"stem":"想在潮間帶觀察生物，最適合選擇？","A":"大潮日的乾潮時段","B":"小潮日的滿潮時段","C":"颱風天","D":"任何時間都一樣","answer":"A","explanation":"大潮日乾潮時水位最低，露出的潮間帶範圍最大。","image":""},{"id":"I-21-01","isl":"I","lv":1,"stem":"兩個板塊彼此分離的邊界稱為？","A":"靜止型邊界","B":"張裂型邊界","C":"聚合型邊界","D":"錯動型邊界","answer":"B","explanation":"板塊分離，形成新的地殼，是張裂型邊界。","image":""},{"id":"I-21-02","isl":"I","lv":1,"stem":"兩個板塊互相碰撞擠壓的邊界稱為？","A":"張裂型邊界","B":"聚合型邊界","C":"漂移型邊界","D":"錯動型邊界","answer":"B","explanation":"板塊相互靠近、碰撞，是聚合型邊界。","image":""},{"id":"I-21-03","isl":"I","lv":2,"stem":"海底的中洋脊屬於哪一種板塊邊界？","A":"沒有邊界","B":"聚合型","C":"錯動型","D":"張裂型","answer":"D","explanation":"中洋脊是板塊分離、新地殼生成的地方。","image":""},{"id":"I-21-04","isl":"I","lv":2,"stem":"聖安德列斯斷層兩側的板塊水平錯動，屬於？","A":"聚合型","B":"碰撞型","C":"張裂型","D":"錯動型","answer":"D","explanation":"板塊水平相對滑動的邊界稱為錯動型邊界。","image":""},{"id":"I-21-05","isl":"I","lv":3,"stem":"海洋板塊與大陸板塊相撞時，密度較大的海洋板塊會？","A":"變成大陸","B":"隱沒到大陸板塊下方","C":"停止移動","D":"浮在大陸板塊上方","answer":"B","explanation":"海洋板塊密度大，會沉入大陸板塊下，形成海溝。","image":""},{"id":"I-22-01","isl":"I","lv":1,"stem":"地震發生時，最先到達的波是？","A":"表面波","B":"S 波","C":"光波","D":"P 波","answer":"D","explanation":"P 波速度最快，最先到達。","image":""},{"id":"I-22-02","isl":"I","lv":1,"stem":"地下發生地震的位置稱為？","A":"斷層","B":"震度","C":"震央","D":"震源","answer":"D","explanation":"震源是地下岩層斷裂釋放能量的地方。","image":""},{"id":"I-22-03","isl":"I","lv":2,"stem":"地震發生後，位在震源正上方的地面位置稱為？","A":"規模","B":"震度","C":"震央","D":"震源","answer":"C","explanation":"震央是震源在地表的垂直投影點。","image":""},{"id":"I-22-04","isl":"I","lv":2,"stem":"P 波與 S 波相比，何者較快？","A":"S 波較快","B":"P 波較快","C":"要看地點","D":"速度一樣","answer":"B","explanation":"P 波是縱波，速度比 S 波快，所以先到達。","image":""},{"id":"I-22-05","isl":"I","lv":3,"stem":"S 波無法通過下列哪一種物質？","A":"液體","B":"地函","C":"地殼","D":"固體","answer":"A","explanation":"S 波不能通過液體，因此推知地球外核是液態。","image":""},{"id":"I-23-01","isl":"I","lv":1,"stem":"火山噴出的岩漿冷卻後形成？","A":"火成岩","B":"變質岩","C":"化石","D":"沉積岩","answer":"A","explanation":"岩漿冷卻凝固形成火成岩。","image":""},{"id":"I-23-02","isl":"I","lv":1,"stem":"環太平洋地區火山與地震特別多，這一帶稱為？","A":"喜馬拉雅帶","B":"環太平洋火環","C":"赤道帶","D":"大西洋脊","answer":"B","explanation":"環太平洋有許多板塊邊界，稱為火環。","image":""},{"id":"I-23-03","isl":"I","lv":2,"stem":"臺灣的大屯火山群位在哪個地區？","A":"東部","B":"北部","C":"西部","D":"南部","answer":"B","explanation":"大屯火山群在臺灣北部。","image":""},{"id":"I-23-04","isl":"I","lv":2,"stem":"火山噴發時可能釋放哪些氣體？","A":"氦氣","B":"純氧","C":"純氮","D":"水蒸氣、二氧化碳、二氧化硫","answer":"D","explanation":"火山氣體以水蒸氣為主，也有二氧化碳、二氧化硫等。","image":""},{"id":"I-23-05","isl":"I","lv":3,"stem":"大量火山灰進入平流層，可能造成？","A":"完全沒有影響","B":"氣溫上升","C":"臭氧增加","D":"地表氣溫暫時下降","answer":"D","explanation":"火山灰會遮擋陽光，使地表氣溫暫時降低。","image":""},{"id":"I-24-01","isl":"I","lv":1,"stem":"岩石因溫度變化或水結冰而破裂，屬於？","A":"變質作用","B":"沉積作用","C":"物理風化","D":"化學風化","answer":"C","explanation":"只改變大小、不改變成分的是物理風化。","image":""},{"id":"I-24-02","isl":"I","lv":1,"stem":"二氧化碳溶於雨水，使石灰岩被溶蝕，屬於？","A":"沉積作用","B":"搬運作用","C":"物理風化","D":"化學風化","answer":"D","explanation":"岩石的成分改變或被溶解，是化學風化。","image":""},{"id":"I-24-03","isl":"I","lv":2,"stem":"植物的根長進岩縫，使岩石裂開，屬於？","A":"沉積作用","B":"變質作用","C":"化學風化","D":"物理風化","answer":"D","explanation":"根的生長把岩石撐開，是物理風化。","image":""},{"id":"I-24-04","isl":"I","lv":2,"stem":"風化後的碎屑被水或風帶往他處，稱為？","A":"蒸發","B":"凝結","C":"沉積作用","D":"搬運作用","answer":"D","explanation":"碎屑被移動稱為搬運作用。","image":""},{"id":"I-24-05","isl":"I","lv":3,"stem":"下列哪一種氣候下，化學風化最旺盛？","A":"低溫乾燥","B":"高溫多雨","C":"低溫多雨","D":"高溫乾燥","answer":"B","explanation":"溫度高、水分多，化學反應最快。","image":""},{"id":"I-25-01","isl":"I","lv":1,"stem":"河流上游常見的谷地形狀是？","A":"沖積平原","B":"潟湖","C":"三角洲","D":"V 形谷","answer":"D","explanation":"上游坡度大，下切侵蝕強，形成 V 形谷。","image":""},{"id":"I-25-02","isl":"I","lv":1,"stem":"河流入海處，泥沙堆積形成的地形是？","A":"曲流","B":"三角洲","C":"瀑布","D":"河階","answer":"B","explanation":"河口流速變慢，泥沙堆積成三角洲。","image":""},{"id":"I-25-03","isl":"I","lv":2,"stem":"河流流出山谷口，坡度變緩，泥沙堆積成扇形，稱為？","A":"峽谷","B":"沖積扇","C":"三角洲","D":"海蝕洞","answer":"B","explanation":"在山谷出口堆積的扇形地形是沖積扇。","image":""},{"id":"I-25-04","isl":"I","lv":2,"stem":"河流曲流的外側（凹岸）主要發生？","A":"結冰","B":"侵蝕作用","C":"乾涸","D":"堆積作用","answer":"B","explanation":"外側水流較快，以侵蝕為主。","image":""},{"id":"I-25-05","isl":"I","lv":3,"stem":"臺灣西部平原主要由什麼堆積而成？","A":"河流搬運的泥沙","B":"冰河","C":"火山噴發","D":"風力","answer":"A","explanation":"河流把山區的泥沙帶到西部堆積，形成沖積平原。","image":""},{"id":"I-26-01","isl":"I","lv":1,"stem":"海浪長期侵蝕海岸，可能形成？","A":"沙洲","B":"三角洲","C":"沙灘","D":"海蝕崖","answer":"D","explanation":"海浪不斷拍擊岩岸，形成陡峭的海蝕崖。","image":""},{"id":"I-26-02","isl":"I","lv":1,"stem":"沙灘主要是海浪的什麼作用形成的？","A":"風化作用","B":"堆積作用","C":"侵蝕作用","D":"火山作用","answer":"B","explanation":"海浪把泥沙帶到岸邊堆積成沙灘。","image":""},{"id":"I-26-03","isl":"I","lv":2,"stem":"岩岸通常出現在哪裡？","A":"海浪侵蝕力強的地方","B":"河口平原","C":"沙漠","D":"平坦低地","answer":"A","explanation":"海浪侵蝕強、岩石堅硬處易形成岩岸。","image":""},{"id":"I-26-04","isl":"I","lv":2,"stem":"珊瑚礁海岸通常出現在？","A":"極地","B":"寒冷的深海","C":"高山","D":"溫暖的淺海","answer":"D","explanation":"造礁珊瑚需要溫暖、陽光充足的淺海環境。","image":""},{"id":"I-26-05","isl":"I","lv":3,"stem":"北海岸野柳的女王頭，主要是什麼作用形成？","A":"火山噴發","B":"冰河侵蝕","C":"風化與海浪侵蝕","D":"河流堆積","answer":"C","explanation":"岩石受風化與海浪侵蝕，形成奇特的蕈狀岩。","image":""},{"id":"I-27-01","isl":"I","lv":1,"stem":"風向是指風「從哪個方向吹來」還是「吹往哪個方向」？","A":"向上的方向","B":"從哪個方向吹來","C":"吹往哪個方向","D":"向下的方向","answer":"B","explanation":"風向是指風吹來的方向，北風是從北方吹來。","image":""},{"id":"I-27-02","isl":"I","lv":1,"stem":"高氣壓地區的天氣通常是？","A":"有鋒面","B":"有颱風","C":"多雲有雨","D":"晴朗","answer":"D","explanation":"高氣壓中心空氣下沉，天氣通常晴朗。","image":""},{"id":"I-27-03","isl":"I","lv":2,"stem":"在地面上，風是由哪裡吹向哪裡？","A":"低氣壓吹向高氣壓","B":"北方吹向南方","C":"隨機方向","D":"高氣壓吹向低氣壓","answer":"D","explanation":"空氣由氣壓高的地方流向氣壓低的地方。","image":""},{"id":"I-27-04","isl":"I","lv":2,"stem":"氣壓常用的單位是？","A":"度","B":"公分","C":"百帕","D":"焦耳","answer":"C","explanation":"氣象上常用百帕（hPa）。","image":""},{"id":"I-27-05","isl":"I","lv":3,"stem":"海邊白天常吹海風（由海吹向陸地），是因為？","A":"陸地氣壓較高","B":"海洋升溫快","C":"海洋沒有氣壓","D":"陸地升溫快，氣壓較低","answer":"D","explanation":"白天陸地比海洋熱，空氣上升形成低壓，海上空氣吹向陸地。","image":""},{"id":"I-28-01","isl":"I","lv":1,"stem":"天氣圖上的「L」代表？","A":"颱風眼","B":"高氣壓","C":"鋒面","D":"低氣壓","answer":"D","explanation":"L 是 Low，表示低氣壓。","image":""},{"id":"I-28-02","isl":"I","lv":1,"stem":"天氣圖上，等壓線越密集，表示風？","A":"沒有關係","B":"方向相反","C":"越強","D":"越弱","answer":"C","explanation":"等壓線密表示氣壓差大，風速大。","image":""},{"id":"I-28-03","isl":"I","lv":2,"stem":"冷氣團推向暖氣團所形成的鋒面稱為？","A":"滯留鋒","B":"囚錮鋒","C":"冷鋒","D":"暖鋒","answer":"C","explanation":"冷氣團主動前進的是冷鋒。","image":""},{"id":"I-28-04","isl":"I","lv":2,"stem":"赤道附近氣溫高、雨量多，主要因為？","A":"海拔很高","B":"陽光接近直射","C":"沒有大氣","D":"離太陽較遠","answer":"B","explanation":"赤道地區太陽直射，單位面積獲得熱量多。","image":""},{"id":"I-28-05","isl":"I","lv":3,"stem":"冷鋒過境時，天氣通常會怎麼變化？","A":"降雨、降溫","B":"起霧、升溫","C":"升溫、無雨","D":"沒有變化","answer":"A","explanation":"冷鋒前進時，暖空氣被抬升，常出現降雨與降溫。","image":""},{"id":"J-01-01","isl":"J","lv":1,"stem":"把二氧化碳通入澄清石灰水，最可能觀察到？","A":"溶液變混濁","B":"溶液變藍色","C":"溶液沸騰","D":"沒有任何變化","answer":"A","explanation":"二氧化碳和石灰水反應生成不溶於水的碳酸鈣，所以變混濁。","image":""},{"id":"J-01-02","isl":"J","lv":1,"stem":"下列哪一個現象最能表示發生了化學反應？","A":"冰塊融化","B":"糖溶在水裡","C":"水沸騰冒泡","D":"鐵釘生鏽變紅褐色","answer":"D","explanation":"生鏽產生了新物質（鐵鏽）。","image":""},{"id":"J-01-03","isl":"J","lv":2,"stem":"小蘇打加入醋中，冒出的氣體主要是？","A":"氧氣","B":"氫氣","C":"二氧化碳","D":"氮氣","answer":"C","explanation":"碳酸氫鈉和醋酸反應產生二氧化碳。","image":""},{"id":"J-01-04","isl":"J","lv":2,"stem":"小蘇打加醋反應時，用溫度計測量會發現？","A":"溫度上升","B":"溫度下降","C":"溫度不變","D":"溶液沸騰","answer":"B","explanation":"這個反應會吸熱，所以溫度下降。","image":""},{"id":"J-01-05","isl":"J","lv":3,"stem":"下列何者屬於物理變化？","A":"乾冰昇華","B":"木炭燃燒","C":"食物腐敗","D":"鐵生鏽","answer":"A","explanation":"乾冰昇華只是狀態改變，沒有生成新物質。","image":""},{"id":"J-02-01","isl":"J","lv":1,"stem":"化學反應前後，下列何者一定不變？","A":"分子的種類","B":"分子的數目","C":"原子的種類和數目","D":"物質的顏色","answer":"C","explanation":"化學反應是原子重新排列，原子的種類和數目不變。","image":""},{"id":"J-02-02","isl":"J","lv":1,"stem":"大理石和鹽酸在開口燒杯中反應，總質量變少的原因是？","A":"原子消失了","B":"產生的二氧化碳跑到空氣中","C":"質量守恆不成立","D":"鹽酸全部蒸發了","answer":"B","explanation":"改在密閉容器中做，總質量就不變。","image":""},{"id":"J-02-03","isl":"J","lv":2,"stem":"鋼絲絨在空氣中燃燒後，質量會？","A":"變大","B":"變小","C":"不變","D":"完全消失","answer":"A","explanation":"鐵和空氣中的氧結合，生成的氧化物比原來的鐵重。","image":""},{"id":"J-02-04","isl":"J","lv":2,"stem":"2H₂＋O₂ → 2H₂O 中，反應前後的分子數目分別是？","A":"都是 3 個","B":"都是 2 個","C":"反應前 2 個、反應後 3 個","D":"反應前 3 個、反應後 2 個","answer":"D","explanation":"分子數目可以改變，但氫、氧原子的數目不變。","image":""},{"id":"J-02-05","isl":"J","lv":3,"stem":"10 公克的甲和 5 公克的乙恰好完全反應，生成 12 公克的丙和另一種物質丁，丁有幾公克？","A":"5 公克","B":"15 公克","C":"3 公克","D":"17 公克","answer":"C","explanation":"總質量不變：10＋5＝12＋丁，丁＝3 公克。","image":""},{"id":"J-03-01","isl":"J","lv":1,"stem":"平衡化學反應式時，可以調整的是？","A":"化學式前面的係數","B":"化學式右下角的數字","C":"元素符號","D":"箭頭的方向","answer":"A","explanation":"只能改係數，不能改化學式。","image":""},{"id":"J-03-02","isl":"J","lv":1,"stem":"1 莫耳的水分子有幾個？","A":"6 個","B":"18 個","C":"18×10²³ 個","D":"6×10²³ 個","answer":"D","explanation":"1 莫耳是 6×10²³ 個粒子。","image":""},{"id":"J-03-03","isl":"J","lv":2,"stem":"CH₄＋□O₂ → CO₂＋2H₂O，□ 應填？","A":"1","B":"3","C":"2","D":"4","answer":"C","explanation":"右邊氧原子共 2＋2＝4 個，所以 O₂ 的係數是 2。","image":""},{"id":"J-03-04","isl":"J","lv":2,"stem":"二氧化碳 CO₂ 的分子量是多少？（C＝12、O＝16）","A":"28","B":"44","C":"32","D":"56","answer":"B","explanation":"12＋16×2＝44。","image":""},{"id":"J-03-05","isl":"J","lv":3,"stem":"2H₂＋O₂ → 2H₂O 中，4 莫耳氫氣完全反應，需要幾莫耳氧氣？","A":"2 莫耳","B":"1 莫耳","C":"4 莫耳","D":"8 莫耳","answer":"A","explanation":"係數比 H₂：O₂＝2：1，所以 4 莫耳氫氣需要 2 莫耳氧氣。","image":""},{"id":"J-04-01","isl":"J","lv":1,"stem":"物質和氧結合的反應稱為？","A":"還原反應","B":"中和反應","C":"氧化反應","D":"沉澱反應","answer":"C","explanation":"和氧結合就是氧化。","image":""},{"id":"J-04-02","isl":"J","lv":1,"stem":"鎂帶燃燒時會？","A":"完全不反應","B":"發出強烈白光","C":"變成藍色液體","D":"只冒黑煙","answer":"B","explanation":"鎂活性大，燃燒劇烈並發出強光，生成白色的氧化鎂。","image":""},{"id":"J-04-03","isl":"J","lv":2,"stem":"把鎂、鋅、鐵、銅依對氧的活性由大到小排列，正確的是？","A":"鎂＞鋅＞鐵＞銅","B":"銅＞鐵＞鋅＞鎂","C":"鐵＞銅＞鎂＞鋅","D":"鋅＞鎂＞銅＞鐵","answer":"A","explanation":"鎂最活潑，銅最不活潑。","image":""},{"id":"J-04-04","isl":"J","lv":2,"stem":"鎂帶燃燒後的產物溶於水，滴入酚酞，溶液會？","A":"變藍色","B":"保持無色","C":"變黃色","D":"變紅色","answer":"D","explanation":"氧化鎂溶於水呈鹼性，酚酞遇鹼變紅。","image":""},{"id":"J-04-05","isl":"J","lv":3,"stem":"硫燃燒後的產物溶於水，用藍色石蕊試紙檢驗會？","A":"不變","B":"變綠","C":"變紅","D":"變黑","answer":"C","explanation":"硫是非金屬，它的氧化物溶於水呈酸性。","image":""},{"id":"J-05-01","isl":"J","lv":1,"stem":"物質失去氧的反應稱為？","A":"還原","B":"氧化","C":"中和","D":"燃燒","answer":"A","explanation":"失去氧是還原。","image":""},{"id":"J-05-02","isl":"J","lv":1,"stem":"碳粉和氧化銅一起加熱，黑色粉末會逐漸變成？","A":"白色","B":"綠色","C":"透明","D":"紅色","answer":"D","explanation":"氧化銅被還原成紅色的銅。","image":""},{"id":"J-05-03","isl":"J","lv":2,"stem":"碳＋氧化銅 → 銅＋二氧化碳，此反應中的還原劑是？","A":"氧化銅","B":"銅","C":"碳","D":"二氧化碳","answer":"C","explanation":"碳搶走氧、自己被氧化，是還原劑。","image":""},{"id":"J-05-04","isl":"J","lv":2,"stem":"氧化還原反應中，氧化和還原？","A":"只會發生其中一個","B":"一定同時發生","C":"先氧化很久才還原","D":"互不相關","answer":"B","explanation":"有物質得到氧，就有物質失去氧。","image":""},{"id":"J-05-05","isl":"J","lv":3,"stem":"下列哪一種元素能搶走氧化鎂中的氧？","A":"以下三者都不能，因為它們的活性都比鎂小","B":"銅","C":"鐵","D":"碳","answer":"A","explanation":"鎂的活性很大，銅、鐵、碳的活性都比鎂小。","image":""},{"id":"J-06-01","isl":"J","lv":1,"stem":"鐵生鏽屬於哪一種反應？","A":"還原","B":"中和","C":"緩慢的氧化","D":"沉澱","answer":"C","explanation":"鐵和氧慢慢結合，是緩慢的氧化。","image":""},{"id":"J-06-02","isl":"J","lv":1,"stem":"下列哪一種做法<b>不能</b>防止鐵生鏽？","A":"塗油漆","B":"常常泡在鹽水中","C":"表面上油","D":"鍍鋅","answer":"B","explanation":"鹽水反而會加快生鏽。","image":""},{"id":"J-06-03","isl":"J","lv":2,"stem":"鐵釘分別放進四支試管：乾燥空氣、煮沸並封油的水、一般的水、鹽水，最快生鏽的是？","A":"鹽水","B":"乾燥空氣","C":"煮沸並封油的水","D":"一般的水","answer":"A","explanation":"有水、有氧氣，再加上鹽，生鏽最快。","image":""},{"id":"J-06-04","isl":"J","lv":2,"stem":"煉鐵時，搶走氧化鐵中的氧的物質主要是？","A":"氧氣","B":"水","C":"氮氣","D":"一氧化碳","answer":"D","explanation":"焦炭燃燒產生一氧化碳，一氧化碳還原氧化鐵。","image":""},{"id":"J-06-05","isl":"J","lv":3,"stem":"食品包裝中放入含鐵粉的脫氧劑，主要目的是？","A":"讓食物變甜","B":"讓食物變熱","C":"吸收氧氣，延緩食物氧化變質","D":"增加食物的鐵質","answer":"C","explanation":"鐵粉和氧反應，把袋中的氧氣吸收掉。","image":""},{"id":"J-07-01","isl":"J","lv":1,"stem":"下列哪一種物質的水溶液能導電？","A":"食鹽","B":"蔗糖","C":"酒精","D":"純水","answer":"A","explanation":"食鹽是電解質，溶在水中解離出離子。","image":""},{"id":"J-07-02","isl":"J","lv":1,"stem":"電解質的水溶液能導電，是因為溶液中有？","A":"很多水分子","B":"氧氣","C":"電子在水裡跑","D":"可以移動的離子","answer":"D","explanation":"離子在溶液中移動，傳導電流。","image":""},{"id":"J-07-03","isl":"J","lv":2,"stem":"氯化鈉在水中解離，產生的離子是？","A":"Na⁻ 和 Cl⁺","B":"Na 和 Cl₂","C":"Na⁺ 和 Cl⁻","D":"NaCl⁺","answer":"C","explanation":"NaCl → Na⁺＋Cl⁻。","image":""},{"id":"J-07-04","isl":"J","lv":2,"stem":"把電極放入食鹽水中通電，氯離子會往哪裡移動？","A":"負極","B":"正極","C":"不會移動","D":"跑出水面","answer":"B","explanation":"帶負電的陰離子被正極吸引。","image":""},{"id":"J-07-05","isl":"J","lv":3,"stem":"下列關於電解質水溶液的敘述，何者正確？","A":"陽離子和陰離子的總電量相等，溶液呈電中性","B":"溶液帶正電","C":"溶液帶負電","D":"溶液中只有陽離子","answer":"A","explanation":"正負電量相等，溶液整體不帶電。","image":""},{"id":"J-08-01","isl":"J","lv":1,"stem":"下列何者能使紅色石蕊試紙變藍？","A":"醋","B":"鹽酸","C":"氫氧化鈉溶液","D":"檸檬汁","answer":"C","explanation":"鹼性溶液使紅色石蕊試紙變藍。","image":""},{"id":"J-08-02","isl":"J","lv":1,"stem":"稀鹽酸加入鎂帶，產生的氣體是？","A":"氧氣","B":"氫氣","C":"二氧化碳","D":"氯氣","answer":"B","explanation":"酸和活性較大的金屬反應產生氫氣。","image":""},{"id":"J-08-03","isl":"J","lv":2,"stem":"酸雨侵蝕大理石雕像，是因為酸和大理石反應產生？","A":"二氧化碳","B":"氧氣","C":"氫氣","D":"水蒸氣","answer":"A","explanation":"碳酸鈣和酸反應生成二氧化碳。","image":""},{"id":"J-08-04","isl":"J","lv":2,"stem":"稀釋濃硫酸的正確方法是？","A":"把水倒進濃硫酸","B":"直接加熱","C":"加入大量食鹽","D":"把濃硫酸慢慢倒入水中並攪拌","answer":"D","explanation":"濃硫酸溶於水會大量放熱，要把酸加入水中。","image":""},{"id":"J-08-05","isl":"J","lv":3,"stem":"收集鎂帶和稀鹽酸反應產生的氣體，把點燃的火柴靠近試管口，會看到什麼現象？","A":"火柴熄滅，沒有聲音","B":"火柴燒得更旺","C":"發出爆鳴聲","D":"產生大量白煙","answer":"C","explanation":"鎂帶和稀鹽酸反應產生氫氣，氫氣遇火燃燒會發出爆鳴聲。","image":""},{"id":"J-09-01","isl":"J","lv":1,"stem":"常溫下，下列哪一個 pH 值的溶液酸性最強？","A":"1","B":"5","C":"7","D":"12","answer":"A","explanation":"pH 越小越酸。","image":""},{"id":"J-09-02","isl":"J","lv":1,"stem":"常溫下，中性溶液的 pH 值是？","A":"0","B":"10","C":"14","D":"7","answer":"D","explanation":"pH＝7 是中性。","image":""},{"id":"J-09-03","isl":"J","lv":2,"stem":"在鹼性溶液中，氫離子和氫氧根離子的關係是？","A":"氫離子比較多","B":"兩者一樣多","C":"氫氧根離子比較多","D":"沒有氫離子","answer":"C","explanation":"鹼性時 [OH⁻]＞[H⁺]。","image":""},{"id":"J-09-04","isl":"J","lv":2,"stem":"pH＝3 的溶液，氫離子濃度是 pH＝5 溶液的幾倍？","A":"2 倍","B":"100 倍","C":"10 倍","D":"1000 倍","answer":"B","explanation":"pH 每差 1 相差 10 倍，差 2 就是 100 倍。","image":""},{"id":"J-09-05","isl":"J","lv":3,"stem":"某溶液滴入酚酞呈無色，滴入廣用指示劑呈綠色，這溶液最可能是？","A":"中性","B":"強酸","C":"強鹼","D":"弱鹼","answer":"A","explanation":"酚酞無色表示不是鹼性，廣用指示劑綠色表示中性。","image":""},{"id":"J-10-01","isl":"J","lv":1,"stem":"鹽酸和氫氧化鈉溶液中和，生成？","A":"氫氣和氧氣","B":"二氧化碳和水","C":"氯化鈉和水","D":"氯氣和鈉","answer":"C","explanation":"HCl＋NaOH → NaCl＋H₂O。","image":""},{"id":"J-10-02","isl":"J","lv":1,"stem":"酸鹼中和反應時，溶液的溫度通常會？","A":"下降","B":"上升","C":"不變","D":"降到 0 ℃","answer":"B","explanation":"中和反應會放熱。","image":""},{"id":"J-10-03","isl":"J","lv":2,"stem":"在加了酚酞的氫氧化鈉溶液中慢慢滴入鹽酸，顏色變化是？","A":"紅色 → 無色","B":"無色 → 紅色","C":"藍色 → 紅色","D":"一直是紅色","answer":"A","explanation":"鹼性時酚酞是紅色，中和後變無色。","image":""},{"id":"J-10-04","isl":"J","lv":2,"stem":"胃酸過多時服用胃藥，胃藥中的有效成分最可能是？","A":"強酸","B":"糖","C":"酒精","D":"弱鹼","answer":"D","explanation":"用弱鹼中和過多的胃酸。","image":""},{"id":"J-10-05","isl":"J","lv":3,"stem":"硝酸銀溶液加入食鹽水，產生的白色沉澱是？","A":"硝酸鈉","B":"氧化銀","C":"氯化銀","D":"碳酸鈣","answer":"C","explanation":"Ag⁺ 和 Cl⁻ 結合成不溶於水的氯化銀。","image":""},{"id":"J-11-01","isl":"J","lv":1,"stem":"食物放在冰箱可以延緩腐敗，主要利用哪一個因素？","A":"溫度","B":"濃度","C":"催化劑","D":"接觸面積","answer":"A","explanation":"低溫讓反應變慢。","image":""},{"id":"J-11-02","isl":"J","lv":1,"stem":"雙氧水中加入二氧化錳，迅速產生氧氣，二氧化錳的角色是？","A":"反應物","B":"生成物","C":"指示劑","D":"催化劑","answer":"D","explanation":"二氧化錳是催化劑，反應前後質量不變。","image":""},{"id":"J-11-03","isl":"J","lv":2,"stem":"同樣 5 公克的大理石和同濃度的鹽酸反應，下列何者最快？","A":"一大塊","B":"切成四小塊","C":"磨成粉末","D":"都一樣快","answer":"C","explanation":"粉末的接觸面積最大。","image":""},{"id":"J-11-04","isl":"J","lv":2,"stem":"比較「濃度」對反應速率的影響時，下列哪一項應該改變？","A":"鹽酸的溫度","B":"鹽酸的濃度","C":"大理石的大小","D":"是否加催化劑","answer":"B","explanation":"只改變要研究的變因，其他都保持相同。","image":""},{"id":"J-11-05","isl":"J","lv":3,"stem":"下列敘述何者正確？","A":"溫度越高，粒子碰撞越頻繁，反應越快","B":"催化劑反應後會消失","C":"濃度越小，反應越快","D":"接觸面積和反應速率無關","answer":"A","explanation":"粒子碰撞越多、越劇烈，反應越快。","image":""},{"id":"J-12-01","isl":"J","lv":1,"stem":"可逆反應達到平衡時，下列敘述何者正確？","A":"反應完全停止","B":"反應物全部用完","C":"正反應速率等於逆反應速率","D":"只剩逆反應","answer":"C","explanation":"平衡是動態的，正、逆反應速率相等。","image":""},{"id":"J-12-02","isl":"J","lv":1,"stem":"在黃色的鉻酸鉀溶液中加入鹽酸，溶液會變成？","A":"藍色","B":"橙色","C":"無色","D":"紫色","answer":"B","explanation":"加酸使平衡往二鉻酸根（橙色）的方向移動。","image":""},{"id":"J-12-03","isl":"J","lv":2,"stem":"在橙色的二鉻酸鉀溶液中加入氫氧化鈉溶液，溶液會變成？","A":"黃色","B":"更深的橙色","C":"紅色","D":"綠色","answer":"A","explanation":"加鹼使 H⁺ 減少，平衡往鉻酸根（黃色）的方向移動。","image":""},{"id":"J-12-04","isl":"J","lv":2,"stem":"化學平衡時，反應物和生成物的量？","A":"一定相等","B":"一直增加","C":"一直減少","D":"不再隨時間改變","answer":"D","explanation":"平衡時各物質的量不再改變，但不一定相等。","image":""},{"id":"J-12-05","isl":"J","lv":3,"stem":"下列何者<b>不會</b>使化學平衡移動？","A":"改變反應物的濃度","B":"改變溫度","C":"把裝溶液的瓶子換個顏色","D":"加入會參與反應的酸或鹼","answer":"C","explanation":"瓶子的顏色和反應無關。","image":""},{"id":"J-13-01","isl":"J","lv":1,"stem":"下列何者屬於有機化合物？","A":"乙醇","B":"二氧化碳","C":"碳酸鈣","D":"食鹽","answer":"A","explanation":"乙醇是醇類有機物。","image":""},{"id":"J-13-02","isl":"J","lv":1,"stem":"天然氣的主要成分是？","A":"乙醇","B":"乙酸","C":"氧氣","D":"甲烷","answer":"D","explanation":"天然氣主要是甲烷。","image":""},{"id":"J-13-03","isl":"J","lv":2,"stem":"有機化合物在空氣中完全燃燒，通常會產生？","A":"氫氣和氧氣","B":"氮氣","C":"二氧化碳和水","D":"鹽和水","answer":"C","explanation":"有機物含碳和氫，完全燃燒生成二氧化碳和水。","image":""},{"id":"J-13-04","isl":"J","lv":2,"stem":"下列哪一種醇類有毒、不可飲用？","A":"乙醇","B":"甲醇","C":"兩種都可以喝","D":"兩種都有毒","answer":"B","explanation":"甲醇有毒。","image":""},{"id":"J-13-05","isl":"J","lv":3,"stem":"依「烷、醇、酸、酯」分類，下列何者屬於酯類？","A":"乙酸乙酯","B":"丙烷","C":"乙醇","D":"乙酸","answer":"A","explanation":"乙酸乙酯由乙酸和乙醇酯化而成。","image":""},{"id":"J-14-01","isl":"J","lv":1,"stem":"乙醇和乙酸發生酯化反應，生成？","A":"肥皂和甘油","B":"甲烷和氧氣","C":"乙酸乙酯和水","D":"二氧化碳和水","answer":"C","explanation":"醇＋酸 → 酯＋水。","image":""},{"id":"J-14-02","isl":"J","lv":1,"stem":"製作肥皂時，油脂要和下列哪一種物質一起加熱？","A":"鹽酸","B":"氫氧化鈉","C":"糖","D":"酒精","answer":"B","explanation":"油脂和強鹼發生皂化反應。","image":""},{"id":"J-14-03","isl":"J","lv":2,"stem":"皂化反應除了肥皂之外，還會生成？","A":"甘油","B":"乙醇","C":"二氧化碳","D":"氫氣","answer":"A","explanation":"油脂＋強鹼 → 肥皂＋甘油。","image":""},{"id":"J-14-04","isl":"J","lv":2,"stem":"酯化反應中加入濃硫酸，主要作用是？","A":"反應物","B":"指示劑","C":"讓溶液變色","D":"催化劑","answer":"D","explanation":"濃硫酸在這裡是催化劑。","image":""},{"id":"J-14-05","isl":"J","lv":3,"stem":"肥皂能清除油汙，是因為肥皂分子？","A":"整個分子都親油","B":"整個分子都親水","C":"一端親油、一端親水","D":"會把油燒掉","answer":"C","explanation":"親油端抓住油汙，親水端讓油汙分散在水中。","image":""},{"id":"J-15-01","isl":"J","lv":1,"stem":"塑膠屬於哪一類物質？","A":"聚合物","B":"天然金屬","C":"無機鹽","D":"元素","answer":"A","explanation":"塑膠是由許多單體連接成的聚合物。","image":""},{"id":"J-15-02","isl":"J","lv":1,"stem":"寶特瓶的材質回收標誌是？","A":"3 號 PVC","B":"5 號 PP","C":"6 號 PS","D":"1 號 PET","answer":"D","explanation":"寶特瓶是 PET，1 號。","image":""},{"id":"J-15-03","isl":"J","lv":2,"stem":"下列何者屬於熱固性塑膠，受熱也不會軟化？","A":"寶特瓶","B":"塑膠袋","C":"美耐皿碗","D":"PP 微波餐盒","answer":"C","explanation":"美耐皿是熱固性塑膠。","image":""},{"id":"J-15-04","isl":"J","lv":2,"stem":"保麗龍的回收標誌是？","A":"2 號 HDPE","B":"6 號 PS","C":"4 號 LDPE","D":"7 號其他","answer":"B","explanation":"保麗龍是聚苯乙烯（PS），6 號。","image":""},{"id":"J-15-05","isl":"J","lv":3,"stem":"為什麼塑膠垃圾會造成長期的環境問題？","A":"大多數塑膠很難自然分解","B":"塑膠很容易溶在水中","C":"塑膠會變成金屬","D":"塑膠會自己燃燒","answer":"A","explanation":"塑膠不易分解，會長期累積，甚至碎成微塑膠。","image":""},{"id":"J-21-01","isl":"J","lv":1,"stem":"增加反應物的濃度，通常會使反應速率？","A":"變慢","B":"不變","C":"變快","D":"變為零","answer":"C","explanation":"濃度越高，粒子碰撞機會越多，反應越快。","image":""},{"id":"J-21-02","isl":"J","lv":1,"stem":"催化劑的作用是？","A":"被反應完全消耗","B":"改變反應速率，本身不耗盡","C":"使反應物消失","D":"增加生成物的總量","answer":"B","explanation":"催化劑能改變反應速率，反應前後本身不變。","image":""},{"id":"J-21-03","isl":"J","lv":2,"stem":"把大塊石灰石磨成粉，與鹽酸反應變快，主要是因為？","A":"加入了催化劑","B":"濃度增大","C":"溫度升高","D":"接觸面積增大","answer":"D","explanation":"顆粒越小，接觸面積越大，反應越快。","image":""},{"id":"J-21-04","isl":"J","lv":2,"stem":"溫度升高，通常使反應速率？","A":"加快","B":"不變","C":"減慢","D":"先慢後停","answer":"A","explanation":"溫度高，粒子運動快，碰撞更頻繁，反應速率加快。","image":""},{"id":"J-21-05","isl":"J","lv":3,"stem":"下列哪一種方法最可能使過氧化氫分解變快？","A":"加水稀釋","B":"加入二氧化錳","C":"密封避光","D":"放進冰箱","answer":"B","explanation":"二氧化錳是過氧化氫分解的催化劑。","image":""},{"id":"J-22-01","isl":"J","lv":1,"stem":"反應過程中放出熱量，稱為？","A":"分解反應","B":"可逆反應","C":"吸熱反應","D":"放熱反應","answer":"D","explanation":"放出熱量的反應是放熱反應。","image":""},{"id":"J-22-02","isl":"J","lv":1,"stem":"燃燒屬於哪一種反應？","A":"吸收光的反應","B":"不涉及能量","C":"放熱反應","D":"吸熱反應","answer":"C","explanation":"燃燒會放出光和熱。","image":""},{"id":"J-22-03","isl":"J","lv":2,"stem":"拍打後會變冰涼的冰敷袋，反應屬於？","A":"放熱反應","B":"吸熱反應","C":"燃燒反應","D":"不吸熱也不放熱","answer":"B","explanation":"反應從周圍吸收熱量，使溫度下降。","image":""},{"id":"J-22-04","isl":"J","lv":2,"stem":"暖暖包使用時（鐵粉氧化）會？","A":"吸收光","B":"吸收熱量","C":"吸收電","D":"放出熱量","answer":"D","explanation":"鐵粉氧化是放熱反應。","image":""},{"id":"J-22-05","isl":"J","lv":3,"stem":"植物的光合作用，在能量上屬於？","A":"放熱的燃燒反應","B":"不需能量的反應","C":"釋放熱能的反應","D":"吸收光能的反應","answer":"D","explanation":"光合作用把光能儲存成葡萄糖的化學能，需要吸收能量。","image":""},{"id":"J-23-01","isl":"J","lv":1,"stem":"溶於水後能導電的物質稱為？","A":"溶劑","B":"非電解質","C":"催化劑","D":"電解質","answer":"D","explanation":"電解質在水中能電離出離子。","image":""},{"id":"J-23-02","isl":"J","lv":1,"stem":"下列哪一種溶液不導電？","A":"食鹽水","B":"稀鹽酸","C":"氫氧化鈉水溶液","D":"糖水","answer":"D","explanation":"糖是分子化合物，溶於水不產生離子，不導電。","image":""},{"id":"J-23-03","isl":"J","lv":2,"stem":"電解質溶於水能導電，是因為產生了？","A":"可自由移動的離子","B":"中子","C":"質子","D":"電子","answer":"A","explanation":"水溶液中有自由移動的離子才能導電。","image":""},{"id":"J-23-04","isl":"J","lv":2,"stem":"氯化氫（HCl）溶於水電離成？","A":"HCl 分子","B":"H⁺ 與 Cl⁻","C":"H₂ 與 Cl₂","D":"H 與 Cl⁻","answer":"B","explanation":"HCl 在水中電離成氫離子與氯離子。","image":""},{"id":"J-23-05","isl":"J","lv":3,"stem":"電解水時，與電池負極相連的電極會產生？","A":"二氧化碳","B":"氫氣","C":"氯氣","D":"氧氣","answer":"B","explanation":"負極（陰極）產生氫氣，正極產生氧氣，體積比約 2：1。","image":""},{"id":"J-24-01","isl":"J","lv":1,"stem":"酸性水溶液會使藍色石蕊試紙變成？","A":"無色","B":"黃色","C":"藍色","D":"紅色","answer":"D","explanation":"酸使藍色石蕊試紙變紅。","image":""},{"id":"J-24-02","isl":"J","lv":1,"stem":"下列哪一種是常見的酸？","A":"氫氧化鈉","B":"鹽酸","C":"酒精","D":"食鹽","answer":"B","explanation":"鹽酸（HCl）是強酸。","image":""},{"id":"J-24-03","isl":"J","lv":2,"stem":"鎂帶放入稀鹽酸中，會產生？","A":"氫氣","B":"氧氣","C":"氯氣","D":"氮氣","answer":"A","explanation":"活性大的金屬與酸反應會產生氫氣。","image":""},{"id":"J-24-04","isl":"J","lv":2,"stem":"大理石（碳酸鈣）與鹽酸反應，產生的氣體是？","A":"氫氣","B":"二氧化碳","C":"氧氣","D":"氨","answer":"B","explanation":"碳酸鈣與酸反應放出二氧化碳。","image":""},{"id":"J-24-05","isl":"J","lv":3,"stem":"酸性溶液中，共同含有的離子是？","A":"氯離子","B":"氫離子","C":"鈉離子","D":"氫氧根離子","answer":"B","explanation":"酸在水中電離出氫離子（H⁺），是酸性的來源。","image":""},{"id":"J-25-01","isl":"J","lv":1,"stem":"下列哪一種是常見的鹼？","A":"硫酸","B":"醋酸","C":"鹽酸","D":"氫氧化鈉","answer":"D","explanation":"氫氧化鈉（NaOH）是強鹼。","image":""},{"id":"J-25-02","isl":"J","lv":1,"stem":"鹼性溶液中，共同含有的離子是？","A":"氫離子","B":"硫酸根離子","C":"氫氧根離子","D":"氯離子","answer":"C","explanation":"鹼在水中電離出氫氧根離子（OH⁻）。","image":""},{"id":"J-25-03","isl":"J","lv":2,"stem":"pH 值為 9 的溶液呈？","A":"鹼性","B":"酸性","C":"無法判斷","D":"中性","answer":"A","explanation":"pH 大於 7 為鹼性。","image":""},{"id":"J-25-04","isl":"J","lv":2,"stem":"酚酞指示劑遇到鹼性溶液會變成？","A":"無色","B":"黃色","C":"紅色（粉紅色）","D":"藍色","answer":"C","explanation":"酚酞在鹼性溶液中呈紅色，酸性和中性呈無色。","image":""},{"id":"J-25-05","isl":"J","lv":3,"stem":"胃酸過多時服用胃藥，主要是為了？","A":"中和胃酸","B":"殺菌","C":"增加胃酸","D":"消化脂肪","answer":"A","explanation":"胃藥含弱鹼，可以中和過多的胃酸。","image":""},{"id":"J-26-01","isl":"J","lv":1,"stem":"酸和鹼混合發生中和，會生成鹽和什麼？","A":"氧氣","B":"二氧化碳","C":"水","D":"氫氣","answer":"C","explanation":"酸＋鹼→鹽＋水。","image":""},{"id":"J-26-02","isl":"J","lv":1,"stem":"氫氧化鈉與鹽酸中和後，生成的鹽是？","A":"硫酸鈉","B":"氯化鈉","C":"碳酸鈉","D":"氯化氫","answer":"B","explanation":"NaOH＋HCl→NaCl＋H₂O。","image":""},{"id":"J-26-03","isl":"J","lv":2,"stem":"酸雨主要和排放大量什麼氣體有關？","A":"氦氣","B":"氧氣","C":"硫氧化物與氮氧化物","D":"氫氣","answer":"C","explanation":"工廠與汽機車排放的硫氧化物、氮氧化物溶於雨水形成酸雨。","image":""},{"id":"J-26-04","isl":"J","lv":2,"stem":"一般正常的雨水因溶有二氧化碳，pH 值約為？","A":"5.6","B":"9","C":"1","D":"7","answer":"A","explanation":"正常雨水略帶酸性，pH 約 5.6；低於 5.6 才稱為酸雨。","image":""},{"id":"J-26-05","isl":"J","lv":3,"stem":"在酸性土壤中加熟石灰，利用的是？","A":"光合作用","B":"中和反應","C":"氧化反應","D":"蒸發作用","answer":"B","explanation":"熟石灰是鹼，可中和土壤中的酸。","image":""},{"id":"J-27-01","isl":"J","lv":1,"stem":"高爐煉鐵時，利用碳使氧化鐵發生什麼變化？","A":"溶解","B":"變成碳","C":"得到氧","D":"失去氧","answer":"D","explanation":"氧化鐵失去氧變成鐵，稱為還原。","image":""},{"id":"J-27-02","isl":"J","lv":1,"stem":"鐵生鏽需要同時接觸哪些物質？","A":"氧氣和水","B":"二氧化碳和乾燥空氣","C":"氫氣和油","D":"氮氣和乾燥空氣","answer":"A","explanation":"鐵在潮濕空氣中，與氧氣和水作用才會生鏽。","image":""},{"id":"J-27-03","isl":"J","lv":2,"stem":"在鐵製品表面鍍鋅或油漆，目的是？","A":"使鐵更重","B":"增加導電性","C":"增加重量","D":"隔絕氧氣和水","answer":"D","explanation":"覆蓋保護層，避免鐵接觸氧氣和水而生鏽。","image":""},{"id":"J-27-04","isl":"J","lv":2,"stem":"乾電池放電時，電池內部發生的是？","A":"氧化還原反應","B":"凝結","C":"昇華","D":"蒸發","answer":"A","explanation":"電池利用氧化還原反應，把化學能轉換成電能。","image":""},{"id":"J-27-05","isl":"J","lv":3,"stem":"氧化銅與碳加熱後生成銅和二氧化碳，其中被還原的是？","A":"二氧化碳","B":"碳","C":"銅","D":"氧化銅","answer":"D","explanation":"氧化銅失去氧變成銅，是被還原。","image":""},{"id":"J-28-01","isl":"J","lv":1,"stem":"最簡單的烷類有機化合物是？","A":"乙酸","B":"乙醇","C":"甲烷","D":"葡萄糖","answer":"C","explanation":"甲烷（CH₄）是最簡單的有機化合物。","image":""},{"id":"J-28-02","isl":"J","lv":1,"stem":"甲烷的化學式是？","A":"C₂H₆","B":"CH₄","C":"CO₂","D":"H₂O","answer":"B","explanation":"1 個碳原子與 4 個氫原子。","image":""},{"id":"J-28-03","isl":"J","lv":2,"stem":"有機化合物完全燃燒，主要產生？","A":"一氧化碳和碳","B":"二氧化碳和水","C":"氫氣和氧氣","D":"氮氣和氫氣","answer":"B","explanation":"含碳、氫的有機物完全燃燒生成 CO₂ 與 H₂O。","image":""},{"id":"J-28-04","isl":"J","lv":2,"stem":"酒精的化學名稱是？","A":"乙醇","B":"甲醇","C":"丙酮","D":"乙酸","answer":"A","explanation":"日常使用的酒精是乙醇。","image":""},{"id":"J-28-05","isl":"J","lv":3,"stem":"有機化合物都含有哪一種元素？","A":"氮","B":"碳","C":"氧","D":"鈉","answer":"B","explanation":"有機化合物以碳為骨架，都含有碳元素。","image":""},{"id":"K-01-01","isl":"K","lv":1,"stem":"相鄰兩個波峰之間的距離稱為？","A":"波長","B":"振幅","C":"週期","D":"頻率","answer":"A","explanation":"波長是相鄰兩個波峰（或波谷）的距離。","image":""},{"id":"K-01-02","isl":"K","lv":1,"stem":"下列何者是縱波？","A":"繩波","B":"水面波","C":"光波","D":"聲波","answer":"D","explanation":"聲波的振動方向和前進方向平行，是縱波。","image":""},{"id":"K-01-03","isl":"K","lv":2,"stem":"某波頻率 5 Hz、波長 2 m，波速是？","A":"2.5 m/s","B":"7 m/s","C":"10 m/s","D":"0.4 m/s","answer":"C","explanation":"v = f × λ = 5 × 2 = 10 m/s。","image":""},{"id":"K-01-04","isl":"K","lv":2,"stem":"某波每秒振動 4 次，週期是？","A":"4 秒","B":"0.25 秒","C":"2 秒","D":"0.4 秒","answer":"B","explanation":"週期 T = 1 ÷ f = 1 ÷ 4 = 0.25 秒。","image":""},{"id":"K-01-05","isl":"K","lv":3,"stem":"水波傳過來時，水面上的樹葉會如何運動？","A":"在原地上下振動","B":"跟著波一起漂向岸邊","C":"往波源方向移動","D":"完全不動","answer":"A","explanation":"波只傳能量和波形，介質（連同上面的樹葉）在原地振動。","image":""},{"id":"K-02-01","isl":"K","lv":1,"stem":"聲音不能在下列哪一種環境中傳播？","A":"水中","B":"空氣中","C":"真空中","D":"鋼鐵中","answer":"C","explanation":"聲音需要介質，真空中無法傳播。","image":""},{"id":"K-02-02","isl":"K","lv":1,"stem":"一般情況下，聲音在哪一種介質中傳得最快？","A":"空氣","B":"鋼鐵","C":"水","D":"真空","answer":"B","explanation":"聲速：固體 > 液體 > 氣體。","image":""},{"id":"K-02-03","isl":"K","lv":2,"stem":"船上聲納發出聲波，0.4 秒後收到海底回聲，水中聲速 1500 m/s，海深多少？","A":"300 m","B":"600 m","C":"150 m","D":"3750 m","answer":"A","explanation":"深度 = 1500 × 0.4 ÷ 2 = 300 m。","image":""},{"id":"K-02-04","isl":"K","lv":2,"stem":"空氣的溫度越高，聲速會？","A":"越慢","B":"不變","C":"先快後慢","D":"越快","answer":"D","explanation":"溫度越高，空氣中聲速越快。","image":""},{"id":"K-02-05","isl":"K","lv":3,"stem":"下列何者沒有利用聲波反射？","A":"蝙蝠飛行定位","B":"醫學超音波","C":"用溫度計量體溫","D":"海底聲納","answer":"C","explanation":"溫度計利用熱脹冷縮，和聲波反射無關。","image":""},{"id":"K-03-01","isl":"K","lv":1,"stem":"聲音的音調高低由什麼決定？","A":"頻率","B":"振幅","C":"波形","D":"波速","answer":"A","explanation":"頻率越高，音調越高。","image":""},{"id":"K-03-02","isl":"K","lv":1,"stem":"人耳可聽到的頻率範圍約為？","A":"2～2000 Hz","B":"200～200000 Hz","C":"20000 Hz 以上","D":"20～20000 Hz","answer":"D","explanation":"人耳約可聽到 20～20000 Hz。","image":""},{"id":"K-03-03","isl":"K","lv":2,"stem":"示波器上兩個波形，甲的波峰比乙高、間隔一樣，代表甲？","A":"音調較高","B":"音色不同","C":"響度較大","D":"波速較快","answer":"C","explanation":"振幅較大 → 響度較大；間隔一樣代表頻率相同。","image":""},{"id":"K-03-04","isl":"K","lv":2,"stem":"吉他弦按得越短，彈出的聲音會？","A":"音調越低","B":"音調越高","C":"越大聲","D":"音色改變","answer":"B","explanation":"弦越短振動頻率越高，音調越高。","image":""},{"id":"K-03-05","isl":"K","lv":3,"stem":"下列何者利用了超聲波？","A":"醫院的超音波檢查","B":"擴音器","C":"風鈴","D":"收音機","answer":"A","explanation":"超音波檢查利用頻率超過 20000 Hz 的聲波反射成像。","image":""},{"id":"K-04-01","isl":"K","lv":1,"stem":"影子的形成可以用光的哪一種性質說明？","A":"反射","B":"折射","C":"直進","D":"色散","answer":"C","explanation":"光沿直線前進，被物體擋住就形成影子。","image":""},{"id":"K-04-02","isl":"K","lv":1,"stem":"光在真空中的速度約為？","A":"340 m/s","B":"3 × 10⁸ m/s","C":"3 × 10⁵ m/s","D":"1500 m/s","answer":"B","explanation":"光速約 3 × 10⁸ m/s。","image":""},{"id":"K-04-03","isl":"K","lv":2,"stem":"針孔成像中，把蠟燭移近針孔，紙屏上的像會？","A":"變大","B":"變小","C":"不變","D":"消失","answer":"A","explanation":"物體越近針孔，像越大。","image":""},{"id":"K-04-04","isl":"K","lv":2,"stem":"針孔成像所成的像是？","A":"正立實像","B":"正立虛像","C":"倒立虛像","D":"倒立實像","answer":"D","explanation":"光真的會到達紙屏上，是倒立的實像。","image":""},{"id":"K-04-05","isl":"K","lv":3,"stem":"打雷時先看到閃電、後聽到雷聲，主要原因是？","A":"閃電比較早發生","B":"聲音會被雲擋住","C":"光速比聲速快很多","D":"光會轉彎","answer":"C","explanation":"光速約 3 × 10⁸ m/s，遠快於聲速 340 m/s。","image":""},{"id":"K-05-01","isl":"K","lv":1,"stem":"光的反射定律中，入射角與反射角的關係是？","A":"入射角等於反射角","B":"入射角大於反射角","C":"入射角小於反射角","D":"兩者相加為 180°","answer":"A","explanation":"入射角 = 反射角。","image":""},{"id":"K-05-02","isl":"K","lv":1,"stem":"平面鏡所成的像是？","A":"倒立實像","B":"放大實像","C":"縮小虛像","D":"正立等大虛像","answer":"D","explanation":"平面鏡成正立、等大、左右相反的虛像。","image":""},{"id":"K-05-03","isl":"K","lv":2,"stem":"光線和鏡面夾 30°，反射角是多少？","A":"30°","B":"90°","C":"60°","D":"120°","answer":"C","explanation":"入射角 = 90° − 30° = 60°，反射角也是 60°。","image":""},{"id":"K-05-04","isl":"K","lv":2,"stem":"汽車後視鏡用凸面鏡，主要是因為？","A":"成像較大","B":"視野較廣","C":"可以聚光","D":"成像倒立","answer":"B","explanation":"凸面鏡讓視野變廣。","image":""},{"id":"K-05-05","isl":"K","lv":3,"stem":"我們能從各個方向看見課本上的字，是因為紙面發生了？","A":"漫射","B":"規則反射","C":"折射","D":"色散","answer":"A","explanation":"粗糙紙面把光往各方向反射，稱為漫射。","image":""},{"id":"K-06-01","isl":"K","lv":1,"stem":"光從空氣斜射進入水中時，折射光會？","A":"偏離法線","B":"沿原方向前進","C":"偏向法線","D":"全部反射","answer":"C","explanation":"光速變慢，偏向法線。","image":""},{"id":"K-06-02","isl":"K","lv":1,"stem":"下列何者是光的折射現象？","A":"影子","B":"插在水中的筷子看起來折斷","C":"鏡中的像","D":"針孔成像","answer":"B","explanation":"筷子看起來折斷是折射造成的。","image":""},{"id":"K-06-03","isl":"K","lv":2,"stem":"光從水中斜射進入空氣時，折射角和入射角相比？","A":"折射角較大","B":"折射角較小","C":"兩者相等","D":"折射角為 0","answer":"A","explanation":"從水進入空氣偏離法線，折射角較大。","image":""},{"id":"K-06-04","isl":"K","lv":2,"stem":"游泳池的水看起來比實際淺，原因是？","A":"光的反射","B":"光的直進","C":"光的色散","D":"光的折射","answer":"D","explanation":"池底的光從水進入空氣偏折，讓池底看起來較淺。","image":""},{"id":"K-06-05","isl":"K","lv":3,"stem":"光由空氣垂直射入玻璃時，下列何者正確？","A":"方向改變、速度不變","B":"方向和速度都不變","C":"方向不變、速度變慢","D":"方向改變、速度變快","answer":"C","explanation":"垂直入射不偏折，但進入玻璃光速仍會變慢。","image":""},{"id":"K-07-01","isl":"K","lv":1,"stem":"平行光通過凸透鏡後會？","A":"會聚在焦點","B":"發散","C":"沿原方向前進","D":"全部反射","answer":"A","explanation":"凸透鏡使平行光會聚於焦點。","image":""},{"id":"K-07-02","isl":"K","lv":2,"stem":"凸透鏡焦距 10 cm，物體放在 30 cm 處，成什麼像？","A":"倒立放大實像","B":"正立放大虛像","C":"不成像","D":"倒立縮小實像","answer":"D","explanation":"物距 30 cm > 2f = 20 cm，成倒立縮小實像。","image":""},{"id":"K-07-03","isl":"K","lv":2,"stem":"凸透鏡焦距 10 cm，物體放在 15 cm 處，成什麼像？","A":"倒立縮小實像","B":"正立放大虛像","C":"倒立放大實像","D":"正立縮小虛像","answer":"C","explanation":"物距在 f 和 2f 之間，成倒立放大實像。","image":""},{"id":"K-07-04","isl":"K","lv":2,"stem":"放大鏡使用時，物體要放在哪裡？","A":"2 倍焦距外","B":"焦距以內","C":"焦距和 2 倍焦距之間","D":"焦點上","answer":"B","explanation":"物距 < f 才成正立放大的虛像。","image":""},{"id":"K-07-05","isl":"K","lv":3,"stem":"下列哪一種像可以呈現在紙屏上？","A":"投影機的像","B":"平面鏡的像","C":"放大鏡的像","D":"凹透鏡的像","answer":"A","explanation":"投影機成倒立放大的實像，可以呈現在紙屏上。","image":""},{"id":"K-08-01","isl":"K","lv":1,"stem":"眼睛的水晶體相當於？","A":"凹透鏡","B":"平面鏡","C":"凸透鏡","D":"凹面鏡","answer":"C","explanation":"水晶體相當於凸透鏡。","image":""},{"id":"K-08-02","isl":"K","lv":1,"stem":"近視眼應配戴哪一種眼鏡矯正？","A":"凸透鏡","B":"凹透鏡","C":"平面鏡","D":"三稜鏡","answer":"B","explanation":"近視成像在視網膜前，要配凹透鏡。","image":""},{"id":"K-08-03","isl":"K","lv":2,"stem":"遠視眼的成像位置在？","A":"視網膜後方","B":"視網膜前方","C":"視網膜上","D":"水晶體上","answer":"A","explanation":"遠視成像在視網膜後方，配凸透鏡矯正。","image":""},{"id":"K-08-04","isl":"K","lv":2,"stem":"相機中相當於眼睛視網膜的是？","A":"鏡頭","B":"光圈","C":"快門","D":"感光元件","answer":"D","explanation":"感光元件接收成像，相當於視網膜。","image":""},{"id":"K-08-05","isl":"K","lv":3,"stem":"在眼睛的視網膜上形成的像是？","A":"正立放大虛像","B":"正立縮小實像","C":"倒立縮小實像","D":"倒立放大虛像","answer":"C","explanation":"物體在 2 倍焦距外，成倒立縮小實像。","image":""},{"id":"K-09-01","isl":"K","lv":1,"stem":"白光經過三稜鏡分成各種色光的現象叫做？","A":"色散","B":"反射","C":"漫射","D":"直進","answer":"A","explanation":"白光分成各種色光稱為色散。","image":""},{"id":"K-09-02","isl":"K","lv":1,"stem":"紅色的蘋果看起來是紅色，是因為它？","A":"吸收紅光","B":"發出紅光","C":"折射紅光","D":"反射紅光","answer":"D","explanation":"不透明物體的顏色由反射的色光決定。","image":""},{"id":"K-09-03","isl":"K","lv":2,"stem":"白光通過三稜鏡時，哪一種色光偏折最多？","A":"紅光","B":"黃光","C":"紫光","D":"綠光","answer":"C","explanation":"紫光偏折最多，紅光偏折最少。","image":""},{"id":"K-09-04","isl":"K","lv":2,"stem":"在只有紅光照射的暗房中，白紙看起來是？","A":"白色","B":"紅色","C":"黑色","D":"綠色","answer":"B","explanation":"白紙反射照到它的紅光，看起來是紅色。","image":""},{"id":"K-09-05","isl":"K","lv":3,"stem":"夏天在大太陽下，穿哪一種顏色的衣服比較涼？","A":"白色","B":"黑色","C":"深藍色","D":"深綠色","answer":"A","explanation":"白色反射所有色光，吸收的光能最少。","image":""},{"id":"K-21-01","isl":"K","lv":1,"stem":"介質振動方向與波前進方向互相垂直的波是？","A":"斜波","B":"縱波","C":"橫波","D":"靜止波","answer":"C","explanation":"振動方向與前進方向垂直是橫波。","image":""},{"id":"K-21-02","isl":"K","lv":1,"stem":"聲波屬於哪一種波？","A":"橫波","B":"縱波","C":"光波","D":"電磁波","answer":"B","explanation":"聲波使空氣疏密變化，是縱波。","image":""},{"id":"K-21-03","isl":"K","lv":2,"stem":"抖動繩子一端產生的波屬於？","A":"橫波","B":"縱波","C":"電磁波","D":"聲波","answer":"A","explanation":"繩子上下抖動，波向前進，是橫波。","image":""},{"id":"K-21-04","isl":"K","lv":2,"stem":"把彈簧一壓一放，傳遞疏密部分的波是？","A":"橫波","B":"電磁波","C":"縱波","D":"光波","answer":"C","explanation":"彈簧圈沿前進方向疏密變化，是縱波。","image":""},{"id":"K-21-05","isl":"K","lv":3,"stem":"波傳播時，介質本身會？","A":"變成波","B":"在原位置附近振動","C":"隨波移動到遠方","D":"消失","answer":"B","explanation":"波傳遞的是能量，介質只在原位附近振動。","image":""},{"id":"K-22-01","isl":"K","lv":1,"stem":"波速、頻率、波長的關係式是？","A":"v＝λ÷f","B":"v＝f÷λ","C":"v＝fλ","D":"v＝f＋λ","answer":"C","explanation":"波速等於頻率乘以波長。","image":""},{"id":"K-22-02","isl":"K","lv":1,"stem":"頻率的單位是？","A":"瓦特","B":"秒","C":"公尺","D":"赫茲","answer":"D","explanation":"頻率單位是赫茲（Hz）。","image":""},{"id":"K-22-03","isl":"K","lv":2,"stem":"某波頻率 5 Hz、波長 2 m，波速是多少 m/s？","A":"10","B":"0.4","C":"7","D":"2.5","answer":"A","explanation":"v＝5×2＝10 m/s。","image":""},{"id":"K-22-04","isl":"K","lv":2,"stem":"波速固定時，頻率增加，波長會？","A":"變短","B":"不變","C":"變為零","D":"變長","answer":"A","explanation":"v＝fλ，v 不變，f 增加，λ 就變小。","image":""},{"id":"K-22-05","isl":"K","lv":3,"stem":"某波的波速 340 m/s、波長 0.68 m，頻率是多少 Hz？","A":"231 Hz","B":"500 Hz","C":"250 Hz","D":"5000 Hz","answer":"B","explanation":"f＝v÷λ＝340÷0.68＝500 Hz。","image":""},{"id":"K-23-01","isl":"K","lv":1,"stem":"聲音的大小（響度）主要和什麼有關？","A":"波速","B":"頻率","C":"波長","D":"振幅","answer":"D","explanation":"振幅越大，聲音越大聲。","image":""},{"id":"K-23-02","isl":"K","lv":1,"stem":"鋼琴和小提琴演奏同一個音，仍能分辨出來，是因為什麼不同？","A":"音調","B":"響度","C":"音速","D":"音色","answer":"D","explanation":"不同樂器的波形不同，音色就不同。","image":""},{"id":"K-23-03","isl":"K","lv":2,"stem":"聲音的振幅變大，會使？","A":"響度變大","B":"音色改變","C":"音調變高","D":"速度變快","answer":"A","explanation":"振幅決定響度。","image":""},{"id":"K-23-04","isl":"K","lv":2,"stem":"人耳可聽到的聲音頻率範圍約為？","A":"0～20 Hz","B":"20000 Hz 以上","C":"1～10 Hz","D":"20～20000 Hz","answer":"D","explanation":"人耳一般可聽見 20 Hz 到 20000 Hz 的聲音。","image":""},{"id":"K-23-05","isl":"K","lv":3,"stem":"蝙蝠發出人耳聽不見的高頻聲波來定位，這種聲波稱為？","A":"無線電波","B":"超聲波","C":"可聞聲","D":"次聲波","answer":"B","explanation":"頻率高於 20000 Hz 的聲波是超聲波。","image":""},{"id":"K-24-01","isl":"K","lv":1,"stem":"聲音在哪一種介質中傳播最快？","A":"真空","B":"氣體","C":"固體","D":"液體","answer":"C","explanation":"通常固體最快，其次液體，氣體最慢。","image":""},{"id":"K-24-02","isl":"K","lv":1,"stem":"聲音遇到障礙物反射回來被聽到，稱為？","A":"色散","B":"回音","C":"共鳴","D":"折射","answer":"B","explanation":"反射回來的聲音就是回音。","image":""},{"id":"K-24-03","isl":"K","lv":2,"stem":"常溫下空氣中的聲速約為？","A":"3000 m/s","B":"3×10⁸ m/s","C":"30 m/s","D":"340 m/s","answer":"D","explanation":"空氣中聲速約 340 m/s。","image":""},{"id":"K-24-04","isl":"K","lv":2,"stem":"對著山壁大喊，2 秒後聽到回音，山壁約距多遠？（聲速 340 m/s）","A":"340 m","B":"680 m","C":"170 m","D":"1360 m","answer":"A","explanation":"聲音來回共 340×2＝680 m，單程是 340 m。","image":""},{"id":"K-24-05","isl":"K","lv":3,"stem":"打雷時看到閃電後 3 秒才聽到雷聲，雷擊處約距多遠？（聲速 340 m/s）","A":"113 m","B":"340 m","C":"1020 m","D":"3000 m","answer":"C","explanation":"光速極快可忽略，距離＝340×3＝1020 m。","image":""},{"id":"K-25-01","isl":"K","lv":1,"stem":"照鏡子時，在平面鏡中看到的像屬於？","A":"倒立實像","B":"縮小實像","C":"倒立虛像","D":"正立虛像","answer":"D","explanation":"平面鏡成正立、等大的虛像。","image":""},{"id":"K-25-02","isl":"K","lv":1,"stem":"平面鏡成像時，像與物的大小？","A":"相等","B":"不一定","C":"較小","D":"較大","answer":"A","explanation":"像與物大小相等。","image":""},{"id":"K-25-03","isl":"K","lv":2,"stem":"站在平面鏡前 2 m，像距離你多遠？","A":"0 m","B":"4 m","C":"1 m","D":"2 m","answer":"B","explanation":"像在鏡後 2 m，與你相距 2＋2＝4 m。","image":""},{"id":"K-25-04","isl":"K","lv":2,"stem":"平面鏡成像時，像與物的左右關係是？","A":"完全相同","B":"左右相反","C":"上下相反","D":"旋轉 90 度","answer":"B","explanation":"鏡中的像左右相反。","image":""},{"id":"K-25-05","isl":"K","lv":3,"stem":"人向平面鏡走近 1 m，人與像的距離縮短多少？","A":"2 m","B":"增加 2 m","C":"不變","D":"1 m","answer":"A","explanation":"人靠近 1 m，像也靠近 1 m，共縮短 2 m。","image":""},{"id":"K-26-01","isl":"K","lv":1,"stem":"凸透鏡對光線有什麼作用？","A":"發散","B":"會聚","C":"反射","D":"吸收","answer":"B","explanation":"凸透鏡使平行光會聚於焦點。","image":""},{"id":"K-26-02","isl":"K","lv":1,"stem":"凹透鏡對光線有什麼作用？","A":"吸收","B":"會聚","C":"發散","D":"反射","answer":"C","explanation":"凹透鏡使平行光發散。","image":""},{"id":"K-26-03","isl":"K","lv":2,"stem":"物體放在凸透鏡的焦距以內，所成的像是？","A":"倒立放大實像","B":"正立放大虛像","C":"倒立縮小實像","D":"正立縮小實像","answer":"B","explanation":"物在焦距內，像是正立放大虛像，這就是放大鏡。","image":""},{"id":"K-26-04","isl":"K","lv":2,"stem":"放大鏡使用的是哪一種鏡？","A":"凹透鏡","B":"凸透鏡","C":"凹面鏡","D":"平面鏡","answer":"B","explanation":"放大鏡是凸透鏡。","image":""},{"id":"K-26-05","isl":"K","lv":3,"stem":"物體在凸透鏡二倍焦距以外，所成的像是？","A":"倒立縮小實像","B":"正立縮小虛像","C":"正立放大虛像","D":"倒立放大實像","answer":"A","explanation":"物在 2 倍焦距外，像是倒立縮小的實像，像照相機。","image":""},{"id":"K-27-01","isl":"K","lv":1,"stem":"眼睛中形成影像、有感光細胞的構造是？","A":"瞳孔","B":"視網膜","C":"角膜","D":"水晶體","answer":"B","explanation":"視網膜上有感光細胞，接收影像。","image":""},{"id":"K-27-02","isl":"K","lv":1,"stem":"眼睛中控制進入光量多少的構造是？","A":"虹膜","B":"視神經","C":"視網膜","D":"水晶體","answer":"A","explanation":"虹膜調節瞳孔大小，控制進光量。","image":""},{"id":"K-27-03","isl":"K","lv":2,"stem":"近視的人看遠處模糊，應配戴？","A":"凸透鏡","B":"凹面鏡","C":"平面鏡","D":"凹透鏡","answer":"D","explanation":"近視者需要凹透鏡，讓光線稍微發散。","image":""},{"id":"K-27-04","isl":"K","lv":2,"stem":"遠視的人應配戴？","A":"凹透鏡","B":"三稜鏡","C":"平面鏡","D":"凸透鏡","answer":"D","explanation":"遠視者需要凸透鏡，幫助光線會聚。","image":""},{"id":"K-27-05","isl":"K","lv":3,"stem":"近視時，遠處物體的像成在視網膜的？","A":"後方","B":"前方","C":"一致","D":"正上方","answer":"B","explanation":"近視的像落在視網膜前方，所以看遠處不清楚。","image":""},{"id":"K-28-01","isl":"K","lv":1,"stem":"色光的三原色是？","A":"紅、綠、藍","B":"黃、綠、紅","C":"紅、黃、藍","D":"橙、黃、綠","answer":"A","explanation":"色光三原色是紅、綠、藍。","image":""},{"id":"K-28-02","isl":"K","lv":1,"stem":"紅光與綠光混合會得到？","A":"紫光","B":"黃光","C":"藍光","D":"白光","answer":"B","explanation":"紅光加綠光是黃光。","image":""},{"id":"K-28-03","isl":"K","lv":2,"stem":"三原色光等量混合，會得到？","A":"灰色","B":"白光","C":"黃光","D":"黑色","answer":"B","explanation":"三原色光等量混合是白光。","image":""},{"id":"K-28-04","isl":"K","lv":2,"stem":"紅色蘋果在白光下看起來是紅色，是因為它主要？","A":"自己發出紅光","B":"吸收紅光","C":"反射所有色光","D":"反射紅光","answer":"D","explanation":"物體反射什麼色光，我們就看到那種顏色。","image":""},{"id":"K-28-05","isl":"K","lv":3,"stem":"在藍光下，紅色的物體看起來是？","A":"紅色","B":"藍色","C":"白色","D":"黑色","answer":"D","explanation":"紅色物體只反射紅光，吸收藍光，藍光下沒有光可反射，看起來是黑色。","image":""},{"id":"K-29-01","isl":"K","lv":1,"stem":"光在均勻介質中沿什麼路徑前進？","A":"折線","B":"直線","C":"曲線","D":"螺旋","answer":"B","explanation":"光在同一均勻介質中沿直線前進。","image":""},{"id":"K-29-02","isl":"K","lv":1,"stem":"光在哪裡傳播速度最快？","A":"鑽石中","B":"玻璃中","C":"水中","D":"真空","answer":"D","explanation":"光在真空中速度最快，約每秒 30 萬公里。","image":""},{"id":"K-29-03","isl":"K","lv":2,"stem":"在暗箱前方開一個小孔，屏幕上形成的像是？","A":"正立虛像","B":"正立實像","C":"倒立虛像","D":"倒立實像","answer":"D","explanation":"光直線前進，通過小孔後成倒立的實像。","image":""},{"id":"K-29-04","isl":"K","lv":2,"stem":"日食和月食的形成與光的哪一個性質有關？","A":"色散","B":"直線前進","C":"折射","D":"反射","answer":"B","explanation":"光直線前進，被天體遮住就形成影子。","image":""},{"id":"K-29-05","isl":"K","lv":3,"stem":"光纖通訊傳送訊號，利用光的哪一種現象？","A":"繞射","B":"影子","C":"全反射","D":"色散","answer":"C","explanation":"光在光纖內不斷全反射，把訊號傳到遠處。","image":""},{"id":"L-01-01","isl":"L","lv":1,"stem":"同一個池塘裡所有的大肚魚，屬於哪一個層次？","A":"族群","B":"個體","C":"群集","D":"生態系","answer":"A","explanation":"同地區同種生物的所有個體＝族群。","image":""},{"id":"L-01-02","isl":"L","lv":1,"stem":"下列何者屬於非生物因子？","A":"細菌","B":"水草","C":"螺","D":"陽光","answer":"D","explanation":"陽光、水、溫度、土壤是非生物因子。","image":""},{"id":"L-01-03","isl":"L","lv":2,"stem":"一座森林中所有的動物、植物和微生物合稱為？","A":"族群","B":"生物圈","C":"群集","D":"個體","answer":"C","explanation":"所有族群的總和是群集。","image":""},{"id":"L-01-04","isl":"L","lv":2,"stem":"關於生態系的敘述，何者正確？","A":"只包含生物","B":"包含群集與非生物環境","C":"一定很大","D":"只有陸地上才有","answer":"B","explanation":"生態系＝生物＋非生物環境，大小不一。","image":""},{"id":"L-01-05","isl":"L","lv":3,"stem":"生物因子的組成層次由低到高的排列，何者正確？","A":"個體 → 族群 → 群集","B":"族群 → 個體 → 群集","C":"群集 → 族群 → 個體","D":"個體 → 群集 → 族群","answer":"A","explanation":"個體、族群、群集。","image":""},{"id":"L-02-01","isl":"L","lv":1,"stem":"下列何者會使族群變小？","A":"出生","B":"遷入","C":"死亡","D":"食物增加","answer":"C","explanation":"死亡和遷出使族群變小。","image":""},{"id":"L-02-02","isl":"L","lv":1,"stem":"估算池塘中鯽魚的數量，最適合用？","A":"樣區法","B":"捉放法","C":"直接計數","D":"顯微鏡計數","answer":"B","explanation":"會移動的動物用捉放法。","image":""},{"id":"L-02-03","isl":"L","lv":2,"stem":"第一次捕捉 30 隻魚做記號放回，第二次捕捉 40 隻，其中 6 隻有記號，估計族群約有幾隻？","A":"200 隻","B":"120 隻","C":"240 隻","D":"76 隻","answer":"A","explanation":"30×40÷6＝200。","image":""},{"id":"L-02-04","isl":"L","lv":2,"stem":"估算校園草地上咸豐草的數量，最適合的方法是？","A":"捉放法","B":"問同學","C":"用網子撈","D":"樣區法","answer":"D","explanation":"植物不移動，用樣區法計數後推算。","image":""},{"id":"L-02-05","isl":"L","lv":3,"stem":"使用捉放法時，下列哪一個做法會使估算結果不準確？","A":"標記後讓魚充分游散再捕捉","B":"第二次捕捉數量夠多","C":"標記方式會讓魚容易被捕食","D":"兩次捕捉在同一池塘","answer":"C","explanation":"有記號的個體若較容易死亡，比例會失真。","image":""},{"id":"L-03-01","isl":"L","lv":1,"stem":"下列何者屬於非生物因子？","A":"土壤","B":"蚯蚓","C":"細菌","D":"雜草","answer":"A","explanation":"土壤、陽光、水、溫度是非生物因子。","image":""},{"id":"L-03-02","isl":"L","lv":1,"stem":"要測量校園中不同地點的光照強度，應使用？","A":"濕度計","B":"酸鹼試紙","C":"溫度計","D":"照度計","answer":"D","explanation":"照度計測量光照強度。","image":""},{"id":"L-03-03","isl":"L","lv":2,"stem":"樹蔭下和操場邊長的植物不同，最主要的非生物因子是？","A":"土壤顏色","B":"風向","C":"光照","D":"海拔","answer":"C","explanation":"光照影響光合作用，進而影響植物分布。","image":""},{"id":"L-03-04","isl":"L","lv":2,"stem":"鼠婦實驗中，盒子一半乾燥、一半潮濕，其他條件都一樣，「濕度」是？","A":"控制變因","B":"操縱變因","C":"應變變因","D":"無關的因素","answer":"B","explanation":"刻意改變的條件是操縱變因。","image":""},{"id":"L-03-05","isl":"L","lv":3,"stem":"調查發現某河段溶氧量很低，魚類很少。這個結果說明了？","A":"非生物因子會影響生物的分布與生存","B":"魚不需要氧氣","C":"溶氧量和魚無關","D":"生物因子決定溶氧量","answer":"A","explanation":"水中溶氧是影響水生動物的重要非生物因子。","image":""},{"id":"L-04-01","isl":"L","lv":1,"stem":"蛔蟲生活在人的腸道中吸取養分，兩者的關係是？","A":"互利共生","B":"競爭","C":"寄生","D":"捕食","answer":"C","explanation":"一方得利、一方受害＝寄生。","image":""},{"id":"L-04-02","isl":"L","lv":1,"stem":"小丑魚躲在海葵中避敵，也幫海葵清除殘渣，兩者的關係是？","A":"片利共生","B":"互利共生","C":"寄生","D":"競爭","answer":"B","explanation":"雙方都得利＝互利共生。","image":""},{"id":"L-04-03","isl":"L","lv":2,"stem":"鮣魚吸附在鯊魚身上撿食殘渣，對鯊魚幾乎沒有影響，這是？","A":"片利共生","B":"寄生","C":"互利共生","D":"捕食","answer":"A","explanation":"一方得利、一方無影響＝片利共生。","image":""},{"id":"L-04-04","isl":"L","lv":2,"stem":"同一塊田裡，稻子和稗草爭奪陽光和養分，這是？","A":"捕食","B":"共生","C":"寄生","D":"競爭","answer":"D","explanation":"爭奪相同資源＝競爭。","image":""},{"id":"L-04-05","isl":"L","lv":3,"stem":"某島上狐狸大量增加後，野兔數量最可能怎麼變化，接著狐狸又會？","A":"野兔增加；狐狸再增加","B":"野兔不變；狐狸不變","C":"野兔減少；狐狸隨後也減少","D":"野兔滅絕；狐狸增加","answer":"C","explanation":"捕食者與獵物的數量互相影響、上下起伏。","image":""},{"id":"L-05-01","isl":"L","lv":1,"stem":"食物鏈「稻 → 蝗蟲 → 青蛙 → 蛇」中，次級消費者是？","A":"青蛙","B":"稻","C":"蝗蟲","D":"蛇","answer":"A","explanation":"青蛙吃初級消費者蝗蟲，是次級消費者。","image":""},{"id":"L-05-02","isl":"L","lv":1,"stem":"食物鏈中的箭頭代表？","A":"生物的大小","B":"生物的壽命","C":"生物的移動方向","D":"能量與物質傳遞的方向","answer":"D","explanation":"箭頭由被吃的指向吃的。","image":""},{"id":"L-05-03","isl":"L","lv":2,"stem":"在食物網中，若青蛙大量減少，短期內蝗蟲的數量最可能？","A":"減少","B":"不變","C":"增加","D":"滅絕","answer":"C","explanation":"捕食者減少，蝗蟲被吃得少，數量增加。","image":""},{"id":"L-05-04","isl":"L","lv":2,"stem":"下列哪一條食物鏈的寫法正確？","A":"老鷹 → 蛇 → 青蛙","B":"草 → 兔 → 狐狸","C":"兔 → 草 → 狐狸","D":"狐狸 → 兔 → 草","answer":"B","explanation":"起點是生產者，箭頭指向吃牠的生物。","image":""},{"id":"L-05-05","isl":"L","lv":3,"stem":"為什麼食物網複雜的生態系通常比較穩定？","A":"某種生物減少時，捕食者可以改吃其他食物","B":"生物都不會死亡","C":"沒有分解者","D":"只有一種生產者","answer":"A","explanation":"食物來源多，受單一物種變動的影響較小。","image":""},{"id":"L-06-02","isl":"L","lv":1,"stem":"能量塔的形狀是？","A":"上寬下窄","B":"下寬上窄","C":"各層一樣寬","D":"中間最寬","answer":"B","explanation":"愈往上能量愈少。","image":""},{"id":"L-06-03","isl":"L","lv":2,"stem":"若生產者有 10000 單位能量，依約十分之一的傳遞，次級消費者大約得到多少？","A":"100","B":"1000","C":"10","D":"10000","answer":"A","explanation":"10000 → 1000 → 100。","image":""},{"id":"L-06-04","isl":"L","lv":2,"stem":"每一層生物得到的能量，大部分到哪裡去了？","A":"全部傳給下一層","B":"變回陽光","C":"存在土壤中","D":"用在呼吸作用與生命活動，以熱散失","answer":"D","explanation":"大部分以熱的形式散失。","image":""},{"id":"L-06-05","isl":"L","lv":3,"stem":"為什麼一條食物鏈通常只有四、五層？","A":"動物不喜歡長的食物鏈","B":"生產者太多","C":"能量逐層大量減少，最上層得不到足夠能量","D":"分解者不夠","answer":"C","explanation":"能量愈往上愈少。","image":""},{"id":"L-07-01","isl":"L","lv":1,"stem":"將大氣中的二氧化碳轉變成生物體內有機物的作用是？","A":"光合作用","B":"呼吸作用","C":"燃燒","D":"分解作用","answer":"A","explanation":"光合作用把二氧化碳和水合成葡萄糖。","image":""},{"id":"L-07-02","isl":"L","lv":1,"stem":"下列哪一個作用會把二氧化碳釋放到大氣中？","A":"光合作用","B":"吸收水分","C":"授粉","D":"呼吸作用","answer":"D","explanation":"呼吸作用分解葡萄糖，產生二氧化碳。","image":""},{"id":"L-07-03","isl":"L","lv":2,"stem":"碳在生物之間主要經由什麼傳遞？","A":"風","B":"雨水","C":"食物鏈","D":"陽光","answer":"C","explanation":"消費者攝食，碳沿食物鏈傳遞。","image":""},{"id":"L-07-04","isl":"L","lv":2,"stem":"近百年大氣二氧化碳濃度上升，主要原因是？","A":"植物增加","B":"大量燃燒化石燃料與森林減少","C":"海洋變冷","D":"分解者消失","answer":"B","explanation":"燃燒化石燃料、砍伐森林使二氧化碳增加。","image":""},{"id":"L-07-05","isl":"L","lv":3,"stem":"關於生態系中物質與能量的敘述，何者正確？","A":"物質可循環，能量單向流動","B":"兩者都能循環","C":"能量可循環，物質不能","D":"兩者都不能循環","answer":"A","explanation":"碳等物質可循環；能量最後以熱散失。","image":""},{"id":"L-08-01","isl":"L","lv":1,"stem":"下列何者是分解者？","A":"青草","B":"兔子","C":"香菇","D":"老鷹","answer":"C","explanation":"真菌、細菌是分解者。","image":""},{"id":"L-08-02","isl":"L","lv":1,"stem":"能自己製造養分的生物稱為？","A":"消費者","B":"生產者","C":"分解者","D":"寄生者","answer":"B","explanation":"生產者行光合作用。","image":""},{"id":"L-08-03","isl":"L","lv":2,"stem":"若生態系中的分解者全部消失，最可能的結果是？","A":"生物遺體和落葉大量堆積，物質無法循環","B":"生產者變多","C":"空氣中氧氣增加","D":"沒有任何影響","answer":"A","explanation":"分解者讓物質回到環境。","image":""},{"id":"L-08-04","isl":"L","lv":2,"stem":"把兩片相同的麵包，一片烤乾後密封、一片沾濕後放在溫暖處，幾天後長出黴菌的最可能是？","A":"烤乾密封的","B":"兩片都不會","C":"兩片一樣多","D":"沾濕放在溫暖處的","answer":"D","explanation":"真菌在潮濕溫暖的環境容易生長。","image":""},{"id":"L-08-05","isl":"L","lv":3,"stem":"關於生態系中三種角色的敘述，何者正確？","A":"只有生產者需要能量","B":"消費者能行光合作用","C":"三者共同促成能量流轉與物質循環","D":"分解者只存在海洋","answer":"C","explanation":"生產者製造養分，消費者攝食，分解者分解遺體，三者共同促成能量流轉和物質循環。","image":""},{"id":"L-09-01","isl":"L","lv":1,"stem":"陸域生態系中，生物種類通常最多的是？","A":"森林","B":"沙漠","C":"草原","D":"凍原","answer":"A","explanation":"森林雨量充足，生物種類多。","image":""},{"id":"L-09-02","isl":"L","lv":1,"stem":"仙人掌的葉退化成刺，主要能？","A":"吸收更多陽光","B":"吸引昆蟲","C":"幫助移動","D":"減少水分散失","answer":"D","explanation":"減少蒸散，適應乾燥。","image":""},{"id":"L-09-03","isl":"L","lv":2,"stem":"決定陸域生態系類型的主要非生物因子是？","A":"風向與潮汐","B":"土壤顏色","C":"雨量與溫度","D":"動物數量","answer":"C","explanation":"雨量和溫度影響植被類型。","image":""},{"id":"L-09-04","isl":"L","lv":2,"stem":"沙漠中許多動物在夜間活動，主要原因是？","A":"夜晚食物比較多","B":"夜晚比較涼爽，可減少水分散失","C":"白天看不見","D":"夜晚比較吵","answer":"B","explanation":"避開白天的高溫。","image":""},{"id":"L-09-05","isl":"L","lv":3,"stem":"從臺灣低海拔往高海拔走，森林類型的變化順序是？","A":"闊葉林 → 針闊葉混合林 → 針葉林","B":"針葉林 → 闊葉林 → 混合林","C":"草原 → 沙漠 → 森林","D":"混合林 → 闊葉林 → 針葉林","answer":"A","explanation":"海拔升高，溫度降低，森林類型改變。","image":""},{"id":"L-10-01","isl":"L","lv":1,"stem":"河流與海洋交會、鹽度變化大的地方稱為？","A":"湖泊","B":"深海","C":"河口","D":"沙漠","answer":"C","explanation":"河口是淡水與海水交會處。","image":""},{"id":"L-10-02","isl":"L","lv":1,"stem":"水筆仔種子在母樹上就發芽，稱為？","A":"孢子","B":"胎生苗","C":"球莖","D":"扦插","answer":"B","explanation":"胎生苗掉落後能很快固著在泥灘。","image":""},{"id":"L-10-03","isl":"L","lv":2,"stem":"紅樹林植物的呼吸根，主要適應哪一種環境條件？","A":"土壤缺氧","B":"陽光太強","C":"溫度太低","D":"風太大","answer":"A","explanation":"泥灘缺氧，呼吸根伸出地面幫助呼吸。","image":""},{"id":"L-10-04","isl":"L","lv":2,"stem":"深海中沒有綠色植物和藻類，主要原因是？","A":"水太鹹","B":"溫度太高","C":"魚太多","D":"缺乏光線","answer":"D","explanation":"沒有光就不能行光合作用。","image":""},{"id":"L-10-05","isl":"L","lv":3,"stem":"河口生態系生物種類多，主要原因是？","A":"鹽度固定","B":"沒有天敵","C":"河流帶來豐富養分","D":"水很深","answer":"C","explanation":"河流帶來大量養分，孕育豐富生物。","image":""},{"id":"L-11-01","isl":"L","lv":1,"stem":"一塊廢耕的農田，最先出現的植物通常是？","A":"一年生草本植物","B":"喬木","C":"針葉樹","D":"仙人掌","answer":"A","explanation":"生長快速的草本植物先進駐。","image":""},{"id":"L-11-02","isl":"L","lv":1,"stem":"生態系中的結構隨時間改變的現象稱為？","A":"演化","B":"突變","C":"遷徙","D":"演替","answer":"D","explanation":"這種現象稱為演替。","image":""},{"id":"L-11-03","isl":"L","lv":2,"stem":"在火山熔岩上，最先能生長的生物是？","A":"喬木","B":"灌木","C":"地衣和苔蘚","D":"稻子","answer":"C","explanation":"地衣、苔蘚能在裸岩上生長並幫助形成土壤。","image":""},{"id":"L-11-04","isl":"L","lv":2,"stem":"灌木長高後，喜歡陽光的小草變少，主要原因是？","A":"土壤變乾","B":"灌木遮住陽光","C":"溫度上升","D":"雨量減少","answer":"B","explanation":"生物改變環境，影響其他生物。","image":""},{"id":"L-11-05","isl":"L","lv":3,"stem":"下列關於演替的敘述，何者正確？","A":"生物與環境的交互作用使生態系結構隨時間改變","B":"演替只發生在海洋","C":"演替的方向完全隨機","D":"演替後生物都消失","answer":"A","explanation":"生物與環境交互作用，使生態系的結構隨時間改變，這就是演替。","image":""},{"id":"L-12-01","isl":"L","lv":1,"stem":"下列哪一種是在臺灣造成危害的入侵種？","A":"臺灣黑熊","B":"櫻花鉤吻鮭","C":"福壽螺","D":"臺灣藍鵲","answer":"C","explanation":"福壽螺啃食水稻幼苗。","image":""},{"id":"L-12-02","isl":"L","lv":1,"stem":"珊瑚白化最主要和下列哪一個環境變化有關？","A":"海水變淡","B":"海水溫度升高","C":"月亮變大","D":"魚變多","answer":"B","explanation":"全球暖化使海水溫度上升。","image":""},{"id":"L-12-03","isl":"L","lv":2,"stem":"外來種容易成為入侵種，主要原因是？","A":"在新環境中缺乏天敵、繁殖快速","B":"體型一定很大","C":"只吃垃圾","D":"不需要水","answer":"A","explanation":"缺乏天敵、適應力強、繁殖快。","image":""},{"id":"L-12-04","isl":"L","lv":2,"stem":"修築道路把森林切成好幾塊，對動物最主要的影響是？","A":"動物變多","B":"食物變多","C":"沒有影響","D":"棲地切割，族群被隔離","answer":"D","explanation":"棲地破碎化使族群孤立、易受威脅。","image":""},{"id":"L-12-05","isl":"L","lv":3,"stem":"下列哪一種人類活動對生物多樣性的影響最直接？","A":"在家裡關燈","B":"多種一棵樹","C":"大面積砍伐熱帶雨林","D":"做資源回收","answer":"C","explanation":"棲地破壞是生物多樣性下降的主因之一。","image":""},{"id":"L-13-01","isl":"L","lv":1,"stem":"食物鏈「浮游生物 → 小魚 → 大魚 → 魚鷹」中，體內 DDT 濃度最高的是？","A":"魚鷹","B":"浮游生物","C":"小魚","D":"大魚","answer":"A","explanation":"愈上層濃度愈高。","image":""},{"id":"L-13-02","isl":"L","lv":1,"stem":"下列何者是會在生物體內累積的汙染物？","A":"氧氣","B":"水","C":"葡萄糖","D":"汞","answer":"D","explanation":"重金屬汞不易排出，會累積。","image":""},{"id":"L-13-03","isl":"L","lv":2,"stem":"湖泊優養化時，魚類大量死亡，主要原因是？","A":"水溫太低","B":"水太清澈","C":"藻類大量繁殖後分解，水中溶氧不足","D":"鹽度升高","answer":"C","explanation":"溶氧減少使魚窒息。","image":""},{"id":"L-13-04","isl":"L","lv":2,"stem":"過去 DDT 對猛禽造成的影響是？","A":"羽毛變色","B":"蛋殼變薄，孵化率下降","C":"飛得更快","D":"沒有影響","answer":"B","explanation":"DDT 影響猛禽的繁殖。","image":""},{"id":"L-13-05","isl":"L","lv":3,"stem":"為什麼人類也需要擔心生物累積？","A":"人類常位在食物鏈上層，可能吃進累積的汙染物","B":"人類不吃任何生物","C":"人類能分解所有汙染物","D":"汙染物只在海裡","answer":"A","explanation":"人類位在食物鏈上層。","image":""},{"id":"L-14-01","isl":"L","lv":1,"stem":"下列何者是保護生物多樣性最根本的方法？","A":"建造更多動物園","B":"捕捉稀有動物","C":"保護棲地","D":"多養寵物","answer":"C","explanation":"保護棲地讓生物能在自然環境中生存繁殖。","image":""},{"id":"L-14-02","isl":"L","lv":1,"stem":"生物多樣性不包括下列哪一項？","A":"物種多樣性","B":"建築多樣性","C":"遺傳多樣性","D":"生態系多樣性","answer":"B","explanation":"三個層次：物種、遺傳、生態系。","image":""},{"id":"L-14-03","isl":"L","lv":2,"stem":"在河川攔砂壩旁設置魚梯，主要目的是？","A":"讓洄游的魚類能通過","B":"方便釣魚","C":"增加水量","D":"防止淹水","answer":"A","explanation":"魚梯讓魚越過人工障礙。","image":""},{"id":"L-14-04","isl":"L","lv":2,"stem":"下列哪一個行為有助於保育？","A":"把吃不完的寵物龜放生到河裡","B":"購買保育類動物製品","C":"在保護區採集植物","D":"移除入侵種並保護棲地","answer":"D","explanation":"移除入侵種並保護棲地，才能保護原生生物；隨意放生外來寵物可能造成入侵種問題。","image":""},{"id":"L-14-05","isl":"L","lv":3,"stem":"櫻花鉤吻鮭族群曾大量減少，保育的做法不包括？","A":"改善溪流棲地、拆除部分攔砂壩","B":"人工繁殖後放流","C":"開放大量垂釣","D":"劃設保護區","answer":"C","explanation":"開放垂釣不利保育。","image":""},{"id":"L-21-01","isl":"L","lv":1,"stem":"生態系由生物與什麼共同組成？","A":"空氣","B":"水","C":"土壤","D":"非生物環境","answer":"D","explanation":"生態系包括所有生物與其非生物環境。","image":""},{"id":"L-21-02","isl":"L","lv":1,"stem":"生態系中的生產者通常是？","A":"肉食動物","B":"人類","C":"綠色植物","D":"草食動物","answer":"C","explanation":"綠色植物行光合作用，製造養分。","image":""},{"id":"L-21-03","isl":"L","lv":2,"stem":"兔子吃草，在生態系中屬於？","A":"生產者","B":"初級消費者","C":"分解者","D":"次級消費者","answer":"B","explanation":"吃生產者的是初級消費者。","image":""},{"id":"L-21-04","isl":"L","lv":2,"stem":"食物鏈「草→蝗蟲→青蛙→蛇」中，蛇屬於？","A":"生產者","B":"初級消費者","C":"次級消費者","D":"三級消費者","answer":"D","explanation":"蝗蟲是初級、青蛙是次級、蛇是三級消費者。","image":""},{"id":"L-21-05","isl":"L","lv":3,"stem":"生態系若缺少分解者，最可能發生？","A":"氧氣增加","B":"遺體堆積、養分無法循環","C":"能量增加","D":"生產者變多","answer":"B","explanation":"分解者把遺體分解，讓養分回到環境。缺少它們，養分就會被卡住。","image":""},{"id":"L-22-01","isl":"L","lv":1,"stem":"能量在食物鏈中的流動方向是？","A":"不流動","B":"單向","C":"循環","D":"雙向","answer":"B","explanation":"能量由生產者往消費者單向流動，最後以熱散失。","image":""},{"id":"L-22-02","isl":"L","lv":1,"stem":"在食物鏈中，越高階的消費者，數量通常？","A":"不變","B":"越多","C":"隨機","D":"越少","answer":"D","explanation":"能量層層減少，高階消費者的數量較少。","image":""},{"id":"L-22-03","isl":"L","lv":2,"stem":"能量金字塔中，每上升一個營養階層，約只傳遞多少能量？","A":"約 10%","B":"約 50%","C":"100%","D":"約 90%","answer":"A","explanation":"每一階層只有約 10% 的能量傳到下一層，其餘用於生活或以熱散失。","image":""},{"id":"L-22-04","isl":"L","lv":2,"stem":"草固定了 1000 單位的能量，草食動物約可得到多少？","A":"約 900 單位","B":"約 10 單位","C":"約 500 單位","D":"約 100 單位","answer":"D","explanation":"1000×10%＝100 單位。","image":""},{"id":"L-22-05","isl":"L","lv":3,"stem":"在食物網中，哪一種生物最容易受到能量不足的影響？","A":"生產者","B":"初級消費者","C":"頂級消費者","D":"分解者","answer":"C","explanation":"頂級消費者能得到的能量最少。","image":""},{"id":"L-23-01","isl":"L","lv":1,"stem":"生物進行呼吸作用時，會釋放？","A":"氮氣","B":"二氧化碳","C":"氧氣","D":"氫氣","answer":"B","explanation":"呼吸作用分解養分，產生二氧化碳和水。","image":""},{"id":"L-23-02","isl":"L","lv":1,"stem":"燃燒化石燃料，會使大氣中哪種氣體增加？","A":"氧氣","B":"二氧化碳","C":"氬氣","D":"氮氣","answer":"B","explanation":"化石燃料含碳，燃燒後產生二氧化碳。","image":""},{"id":"L-23-03","isl":"L","lv":2,"stem":"碳在生物之間，主要以哪種形式傳遞？","A":"惰性氣體","B":"有機物","C":"水蒸氣","D":"純氧","answer":"B","explanation":"生物吃下含碳的有機物，把碳傳給下一階層。","image":""},{"id":"L-23-04","isl":"L","lv":2,"stem":"下列哪一項能減少大氣中的二氧化碳？","A":"焚燒廢棄物","B":"植樹造林","C":"砍伐森林","D":"增加燃煤","answer":"B","explanation":"植物行光合作用吸收二氧化碳。","image":""},{"id":"L-23-05","isl":"L","lv":3,"stem":"分解者在碳循環中的作用是？","A":"製造葡萄糖","B":"把有機物分解成二氧化碳回到大氣","C":"吸收氧氣","D":"固定氮","answer":"B","explanation":"分解者分解遺體，呼吸作用釋出二氧化碳。","image":""},{"id":"L-24-01","isl":"L","lv":1,"stem":"空氣中含量最多的是氮氣，大多數生物能直接利用嗎？","A":"只有人能","B":"只有動物能","C":"不能直接利用","D":"能直接利用","answer":"C","explanation":"大多數生物無法直接利用氮氣，要靠固氮作用轉成可用的形式。","image":""},{"id":"L-24-02","isl":"L","lv":1,"stem":"豆科植物根部的根瘤菌能？","A":"分解岩石","B":"吸收二氧化碳","C":"固定空氣中的氮","D":"製造氧氣","answer":"C","explanation":"根瘤菌可把氮氣轉成植物能用的含氮化合物。","image":""},{"id":"L-24-03","isl":"L","lv":2,"stem":"植物吸收氮，主要是以哪種形式？","A":"二氧化氮氣體","B":"氮的氧化物氣體","C":"硝酸鹽與銨鹽","D":"純氮氣","answer":"C","explanation":"植物從土壤吸收硝酸鹽與銨鹽。","image":""},{"id":"L-24-04","isl":"L","lv":2,"stem":"農民種稻後輪種豆科植物，目的是？","A":"殺蟲","B":"增加土壤含氮量","C":"增加鹽分","D":"減少水分","answer":"B","explanation":"豆科植物的根瘤菌能固氮，提高土壤肥力。","image":""},{"id":"L-24-05","isl":"L","lv":3,"stem":"打雷閃電時，空氣中的氮氣可能轉變成？","A":"氫氣","B":"二氧化碳","C":"純氧","D":"氮氧化物，隨雨進入土壤","answer":"D","explanation":"閃電的高溫使氮與氧反應，形成氮氧化物，溶於雨水進入土壤。","image":""},{"id":"L-25-01","isl":"L","lv":1,"stem":"小丑魚與海葵互相受益，這種關係稱為？","A":"捕食","B":"互利共生","C":"競爭","D":"寄生","answer":"B","explanation":"兩種生物互相受益，是互利共生。","image":""},{"id":"L-25-02","isl":"L","lv":1,"stem":"獅子獵食斑馬，兩者的關係是？","A":"捕食","B":"共生","C":"互利","D":"寄生","answer":"A","explanation":"一方捕捉並吃掉另一方，是捕食關係。","image":""},{"id":"L-25-03","isl":"L","lv":2,"stem":"跳蚤吸食狗的血液，兩者的關係是？","A":"互利共生","B":"競爭","C":"片利共生","D":"寄生","answer":"D","explanation":"寄生者受益，宿主受害。","image":""},{"id":"L-25-04","isl":"L","lv":2,"stem":"同一片草地上，兔子和羊搶食牧草，關係是？","A":"寄生","B":"共生","C":"捕食","D":"競爭","answer":"D","explanation":"兩種生物爭奪相同資源，是競爭。","image":""},{"id":"L-25-05","isl":"L","lv":3,"stem":"根瘤菌供給豆科植物氮肥，植物提供根瘤菌養分，這是？","A":"競爭","B":"寄生","C":"互利共生","D":"捕食","answer":"C","explanation":"雙方都得到好處，是互利共生。","image":""},{"id":"L-26-01","isl":"L","lv":1,"stem":"紅樹林主要生長在哪裡？","A":"沙漠","B":"冰原","C":"高山","D":"河口的泥灘","answer":"D","explanation":"紅樹林生長在河口海水與淡水交會的泥灘地。","image":""},{"id":"L-26-02","isl":"L","lv":1,"stem":"「臺灣特有種」是指？","A":"全世界都有的物種","B":"已滅絕的物種","C":"只分布在臺灣的物種","D":"外來物種","answer":"C","explanation":"特有種只分布在某個特定地區，不在其他地方自然生長。","image":""},{"id":"L-26-03","isl":"L","lv":2,"stem":"臺灣高山上，隨海拔升高，植物分布大致如何變化？","A":"全部相同","B":"愈高愈茂密","C":"都是熱帶雨林","D":"由闊葉林到針葉林再到高山草原","answer":"D","explanation":"隨海拔升高氣溫降低，植物依序改變。","image":""},{"id":"L-26-04","isl":"L","lv":2,"stem":"下列哪一項不是濕地的功能？","A":"調節洪水","B":"淨化水質","C":"提供生物棲地","D":"增加沙漠面積","answer":"D","explanation":"濕地能淨化水質、蓄洪，也是許多生物的棲地。","image":""},{"id":"L-26-05","isl":"L","lv":3,"stem":"櫻花鉤吻鮭是臺灣的？","A":"海水魚","B":"外來種","C":"熱帶魚","D":"冰河時期留下的特有種","answer":"D","explanation":"櫻花鉤吻鮭是冰河孑遺的臺灣特有種。","image":""},{"id":"L-27-01","isl":"L","lv":1,"stem":"生物多樣性包括哪三個層次？","A":"陸、海、空","B":"大、中、小","C":"遺傳、物種、生態系","D":"動物、植物、真菌","answer":"C","explanation":"生物多樣性有遺傳、物種、生態系三個層次。","image":""},{"id":"L-27-02","isl":"L","lv":1,"stem":"物種多樣性是指？","A":"一個生物的大小","B":"一種生物的個體數","C":"一個生物的基因","D":"一個地區生物種類的多寡","answer":"D","explanation":"物種多樣性看有多少種不同的生物。","image":""},{"id":"L-27-03","isl":"L","lv":2,"stem":"熱帶雨林的生物多樣性通常？","A":"無法比較","B":"與沙漠相同","C":"很低","D":"很高","answer":"D","explanation":"熱帶雨林溫暖多雨，生物種類非常豐富。","image":""},{"id":"L-27-04","isl":"L","lv":2,"stem":"物種滅絕最主要的原因之一是？","A":"季節交替","B":"棲地破壞","C":"月相變化","D":"地球自轉","answer":"B","explanation":"棲地被破壞，生物失去生存空間。","image":""},{"id":"L-27-05","isl":"L","lv":3,"stem":"生物多樣性高的生態系，通常比較？","A":"脆弱","B":"容易崩潰","C":"穩定","D":"單調","answer":"C","explanation":"種類多，食物網複雜，部分生物消失時，生態系較不易崩潰。","image":""},{"id":"L-28-01","isl":"L","lv":1,"stem":"水體優養化主要是因為水中什麼增多？","A":"溫度降低","B":"氮、磷等養分","C":"氧氣","D":"鹽分","answer":"B","explanation":"含氮、磷的肥料和汙水流入水體，造成藻類大量生長。","image":""},{"id":"L-28-02","isl":"L","lv":1,"stem":"下列哪一種屬於人類造成的環境破壞？","A":"潮汐","B":"濫墾濫伐","C":"季節轉變","D":"日出","answer":"B","explanation":"濫墾濫伐破壞森林和棲地。","image":""},{"id":"L-28-03","isl":"L","lv":2,"stem":"藻類大量繁殖後（優養化），水中溶氧量通常會？","A":"先降後升","B":"下降","C":"上升","D":"不變","answer":"B","explanation":"藻類死亡被分解，消耗大量氧氣，水中溶氧下降。","image":""},{"id":"L-28-04","isl":"L","lv":2,"stem":"塑膠袋進入海洋，對海洋生物的主要影響是？","A":"被誤食而受傷害","B":"增加氧氣","C":"增加食物來源","D":"沒有影響","answer":"A","explanation":"海洋生物容易把塑膠誤當食物吞下。","image":""},{"id":"L-28-05","isl":"L","lv":3,"stem":"要減少環境汙染，最根本的做法是？","A":"增加使用","B":"源頭減量","C":"露天焚燒","D":"隨意丟棄","answer":"B","explanation":"從源頭減少使用與製造廢棄物，效果最好。","image":""},{"id":"M-01-01","isl":"M","lv":1,"stem":"用豌豆實驗發現遺傳法則的科學家是？","A":"孟德爾","B":"牛頓","C":"伽利略","D":"達爾文","answer":"A","explanation":"孟德爾被稱為遺傳學之父。","image":""},{"id":"M-01-02","isl":"M","lv":1,"stem":"研究放射性，並兩次獲得諾貝爾獎的科學家是？","A":"吳健雄","B":"屠呦呦","C":"孟德爾","D":"居禮夫人","answer":"D","explanation":"居禮夫人獲得物理和化學兩座諾貝爾獎。","image":""},{"id":"M-01-03","isl":"M","lv":2,"stem":"屠呦呦發現青蒿素，主要用來治療哪一種疾病？","A":"感冒","B":"糖尿病","C":"瘧疾","D":"近視","answer":"C","explanation":"她從傳統醫藥文獻得到啟發。","image":""},{"id":"M-01-04","isl":"M","lv":2,"stem":"關於科學知識，下列敘述何者正確？","A":"提出後永遠不變","B":"有新證據時可能被修正","C":"只靠一個人完成","D":"不需要實驗驗證","answer":"B","explanation":"科學是不斷修正、累積的。","image":""},{"id":"M-01-05","isl":"M","lv":3,"stem":"吳健雄的重要貢獻最能說明科學的哪一個特性？","A":"精密的實驗可以檢驗並推翻原本的看法","B":"科學只靠想像","C":"實驗不重要","D":"科學家都來自同一國家","answer":"A","explanation":"她用實驗證實宇稱不守恆。","image":""},{"id":"M-02-01","isl":"M","lv":1,"stem":"下列哪一種食品是利用微生物發酵製成的？","A":"白開水","B":"食鹽","C":"醬油","D":"砂糖","answer":"C","explanation":"醬油由麴菌、酵母菌和乳酸菌共同發酵製成。","image":""},{"id":"M-02-02","isl":"M","lv":1,"stem":"臺灣蘭花產業大量繁殖蘭花苗，主要利用哪一種技術？","A":"雜交","B":"組織培養","C":"輻射","D":"嫁接","answer":"B","explanation":"組織培養可快速大量繁殖。","image":""},{"id":"M-02-03","isl":"M","lv":2,"stem":"讓大腸桿菌製造人類胰島素，是利用哪一種技術？","A":"基因轉殖","B":"組織培養","C":"發酵","D":"扦插","answer":"A","explanation":"把人類胰島素基因放進細菌。","image":""},{"id":"M-02-04","isl":"M","lv":2,"stem":"組織培養得到的幼苗，與母株的性狀關係是？","A":"完全不同","B":"一半相同","C":"隨機","D":"相同","answer":"D","explanation":"無性生殖，遺傳物質相同。","image":""},{"id":"M-02-05","isl":"M","lv":3,"stem":"發展基因改造作物時，下列哪一個考量最恰當？","A":"只看產量","B":"完全不需要規範","C":"評估對健康、其他生物和環境的影響","D":"愈快上市愈好","answer":"C","explanation":"生物技術要避免對環境造成過度影響。","image":""},{"id":"M-03-01","isl":"M","lv":1,"stem":"下列何者屬於合成纖維？","A":"尼龍","B":"棉花","C":"羊毛","D":"蠶絲","answer":"A","explanation":"尼龍是人造的合成纖維。","image":""},{"id":"M-03-02","isl":"M","lv":1,"stem":"下列何者屬於合金？","A":"純銅","B":"金","C":"鋁","D":"不鏽鋼","answer":"D","explanation":"不鏽鋼由鐵、鉻、鎳等混合。","image":""},{"id":"M-03-03","isl":"M","lv":2,"stem":"塑膠被大量使用，但也造成環境問題，主要原因是？","A":"太容易分解","B":"太重","C":"很難被分解","D":"會發光","answer":"C","explanation":"塑膠在自然界可存在很久。","image":""},{"id":"M-03-04","isl":"M","lv":2,"stem":"陶瓷碗的特性是？","A":"柔軟可折","B":"耐高溫但易碎","C":"會生鏽","D":"可以導電","answer":"B","explanation":"陶瓷耐熱、耐腐蝕但易碎。","image":""},{"id":"M-03-05","isl":"M","lv":3,"stem":"電腦和手機晶片的製造，最主要依賴哪一種材料？","A":"半導體材料（如矽）","B":"羊毛","C":"陶土","D":"棉花","answer":"A","explanation":"半導體是電子產品的基礎。","image":""},{"id":"M-04-01","isl":"M","lv":1,"stem":"汙水處理廠的活性汙泥中，主要是什麼在分解有機物？","A":"魚","B":"沙子","C":"微生物","D":"鐵粉","answer":"C","explanation":"微生物分解有機物。","image":""},{"id":"M-04-02","isl":"M","lv":1,"stem":"下列何者是利用生物處理汙染的例子？","A":"把垃圾倒進河裡","B":"人工濕地淨化水質","C":"燃燒塑膠","D":"掩埋電池","answer":"B","explanation":"植物和微生物淨化水質。","image":""},{"id":"M-04-03","isl":"M","lv":2,"stem":"利用植物吸收土壤中的重金屬，再收割處理，稱為？","A":"植生復育","B":"組織培養","C":"光合作用","D":"蒸散作用","answer":"A","explanation":"植物能吸收土壤中的重金屬，收割後集中處理，可降低土壤汙染。","image":""},{"id":"M-04-04","isl":"M","lv":2,"stem":"海上漏油時，可利用哪一種生物幫忙清除？","A":"海鷗","B":"鯨魚","C":"珊瑚","D":"能分解石油的微生物","answer":"D","explanation":"某些微生物能分解石油。","image":""},{"id":"M-04-05","isl":"M","lv":3,"stem":"想讓汙水處理廠的微生物分解得更快，下列哪一個做法最合理？","A":"加入大量殺菌劑","B":"把水冰凍","C":"提供適合的溫度和充足的氧氣","D":"完全隔絕空氣","answer":"C","explanation":"微生物生長需要適合的條件。","image":""},{"id":"M-05-01","isl":"M","lv":1,"stem":"長距離輸電時通常使用高電壓，主要目的是？","A":"減少電能在電線上的損失","B":"讓電跑得更快","C":"讓電線更細","D":"讓電變便宜","answer":"A","explanation":"高壓輸電可減少熱損失。","image":""},{"id":"M-05-02","isl":"M","lv":1,"stem":"變電所改變電壓主要靠哪一種設備？","A":"發電機","B":"電池","C":"電阻","D":"變壓器","answer":"D","explanation":"變壓器可升壓或降壓。","image":""},{"id":"M-05-03","isl":"M","lv":2,"stem":"臺灣家庭插座的電壓通常是？","A":"1.5 V","B":"9 V","C":"110 V（冷氣等用 220 V）","D":"10000 V","answer":"C","explanation":"一般家用 110 V，大型電器 220 V。","image":""},{"id":"M-05-04","isl":"M","lv":2,"stem":"電力輸送的順序何者正確？","A":"發電廠→家庭→升壓","B":"發電廠→升壓→高壓輸電→降壓→家庭","C":"家庭→發電廠→降壓","D":"降壓→發電廠→升壓→家庭","answer":"B","explanation":"先升壓輸送，再降壓使用。","image":""},{"id":"M-05-05","isl":"M","lv":3,"stem":"夏天下午常是用電尖峰，為什麼要特別注意節約用電？","A":"用電量太大可能超過供電能力，造成限電","B":"夏天電會變少","C":"電線會融化","D":"尖峰時電費免費","answer":"A","explanation":"供電不足可能限電、停電。","image":""},{"id":"M-06-01","isl":"M","lv":1,"stem":"發現有人觸電，第一步應該？","A":"直接用手拉開","B":"潑水","C":"切斷電源","D":"大聲叫他放手","answer":"C","explanation":"先斷電，避免自己也觸電。","image":""},{"id":"M-06-02","isl":"M","lv":1,"stem":"下列哪一個行為容易造成電線走火？","A":"用完拔插頭","B":"延長線同時插電暖器、吹風機和電鍋","C":"使用有過載保護的延長線","D":"定期檢查電線","answer":"B","explanation":"總電流過大會使電線過熱。","image":""},{"id":"M-06-03","isl":"M","lv":2,"stem":"家中電路的無熔絲開關的功能是？","A":"電流過大時自動切斷電路","B":"增加電壓","C":"讓電費變少","D":"儲存電能","answer":"A","explanation":"保護電路避免過熱。","image":""},{"id":"M-06-04","isl":"M","lv":2,"stem":"為什麼不要用濕手碰觸插頭？","A":"水會讓插頭變乾","B":"插頭會生鏽","C":"沒有影響","D":"人體潮濕時電阻變小，容易觸電","answer":"D","explanation":"電阻小，通過的電流大。","image":""},{"id":"M-06-05","isl":"M","lv":3,"stem":"洗衣機等大型電器的外殼接地，主要目的是？","A":"讓洗衣機轉得更快","B":"節省電費","C":"漏電時讓電流導入大地，保護使用者","D":"讓聲音變小","answer":"C","explanation":"接地是重要的安全措施。","image":""},{"id":"M-07-01","isl":"M","lv":1,"stem":"1 度電等於多少？","A":"1 千瓦小時","B":"1 瓦特","C":"1 伏特","D":"1 安培","answer":"A","explanation":"1 度＝1 kWh。","image":""},{"id":"M-07-02","isl":"M","lv":1,"stem":"電器標示「110 V 500 W」中的 500 W 是指？","A":"電壓","B":"電流","C":"電阻","D":"電功率","answer":"D","explanation":"W 是電功率的單位。","image":""},{"id":"M-07-03","isl":"M","lv":2,"stem":"1000 W 的電鍋使用 30 分鐘，耗電多少度？","A":"30 度","B":"1000 度","C":"0.5 度","D":"500 度","answer":"C","explanation":"1 kW × 0.5 h＝0.5 度。","image":""},{"id":"M-07-04","isl":"M","lv":2,"stem":"2000 W 的冷氣使用 3 小時，每度 3 元，電費約多少？","A":"6 元","B":"18 元","C":"6000 元","D":"9 元","answer":"B","explanation":"2 × 3＝6 度，6 × 3＝18 元。","image":""},{"id":"M-07-05","isl":"M","lv":3,"stem":"100 W 的燈泡和 10 W 的 LED 燈各用 10 小時，相差多少度？","A":"0.9 度","B":"1 度","C":"90 度","D":"9 度","answer":"A","explanation":"1 度 − 0.1 度＝0.9 度。","image":""},{"id":"M-08-01","isl":"M","lv":1,"stem":"侵襲臺灣的颱風主要發生在哪幾個月？","A":"十二至二月","B":"三至五月","C":"七至九月","D":"十至十一月","answer":"C","explanation":"夏秋之際最常見。","image":""},{"id":"M-08-02","isl":"M","lv":1,"stem":"颱風帶來的災害不包括？","A":"狂風","B":"地震","C":"豪雨","D":"暴潮","answer":"B","explanation":"地震與颱風無關。","image":""},{"id":"M-08-03","isl":"M","lv":2,"stem":"颱風造成沿海低窪地區海水倒灌，主要和哪一個現象有關？","A":"暴潮加上漲潮","B":"地震","C":"乾旱","D":"寒流","answer":"A","explanation":"暴潮使海水位異常升高。","image":""},{"id":"M-08-04","isl":"M","lv":2,"stem":"下列何者是正確的防颱準備？","A":"去海邊看浪","B":"到山區露營","C":"把車停在河邊","D":"固定戶外物品、準備飲用水和手電筒","answer":"D","explanation":"做好準備，遠離危險地區。","image":""},{"id":"M-08-05","isl":"M","lv":3,"stem":"颱風眼經過時風雨突然變小，此時最正確的做法是？","A":"趕快出門修理屋頂","B":"颱風已經結束","C":"繼續留在室內，另一側的強風豪雨很快會來","D":"去海邊看看","answer":"C","explanation":"颱風眼過後風雨會再來。","image":""},{"id":"M-09-01","isl":"M","lv":1,"stem":"臺灣地震頻繁的主要原因是？","A":"位於板塊交界","B":"雨量很多","C":"颱風很多","D":"人口很多","answer":"A","explanation":"歐亞板塊與菲律賓海板塊交界。","image":""},{"id":"M-09-02","isl":"M","lv":1,"stem":"在教室遇到強烈地震，應該？","A":"馬上衝出教室","B":"站在窗邊","C":"搭電梯下樓","D":"趴下、掩護、穩住","answer":"D","explanation":"保護頭頸部最重要。","image":""},{"id":"M-09-03","isl":"M","lv":2,"stem":"地震時為什麼不能搭電梯？","A":"電梯太慢","B":"電梯太擠","C":"可能停電而受困","D":"電梯會變熱","answer":"C","explanation":"停電或故障會被困住。","image":""},{"id":"M-09-04","isl":"M","lv":2,"stem":"在戶外遇到地震，應該？","A":"躲到招牌下","B":"遠離建築物、電線桿和招牌","C":"靠近玻璃帷幕大樓","D":"站在電線桿旁","answer":"B","explanation":"避免被掉落物砸傷。","image":""},{"id":"M-09-05","isl":"M","lv":3,"stem":"下列哪一項是平時最有效的防震準備？","A":"固定家具、準備避難包、熟悉避難路線","B":"等地震預報再準備","C":"把重物放在高處","D":"不需要準備","answer":"A","explanation":"地震無法準確預測，平時準備最重要。","image":""},{"id":"M-10-01","isl":"M","lv":1,"stem":"下列哪一種情況最容易發生山崩？","A":"連續晴天","B":"寒流來襲","C":"颱風豪雨過後","D":"日出時","answer":"C","explanation":"雨水滲入使岩層容易滑動。","image":""},{"id":"M-10-02","isl":"M","lv":1,"stem":"岩層傾斜方向和坡面方向相同的山坡稱為？","A":"逆向坡","B":"順向坡","C":"平原","D":"盆地","answer":"B","explanation":"這種山坡較容易滑動。","image":""},{"id":"M-10-03","isl":"M","lv":2,"stem":"下列哪一個地點最不適合蓋房子？","A":"大雨後的順向坡下方","B":"平坦的高地","C":"遠離河道的空地","D":"逆向坡上方的平台","answer":"A","explanation":"順向坡容易山崩。","image":""},{"id":"M-10-04","isl":"M","lv":2,"stem":"維護山坡的植被可以減少山崩，原因是？","A":"植物會吸收地震","B":"植物讓雨變小","C":"植物使岩層變硬","D":"植物的根能抓住土壤","answer":"D","explanation":"植物的根能抓住土壤，減少雨水沖刷和土石滑動，降低山崩機會，這是水土保持在防災上的應用。","image":""},{"id":"M-10-05","isl":"M","lv":3,"stem":"土石流警戒發布時，住在山區溪谷旁的居民最應該？","A":"到溪邊觀察水量","B":"待在一樓","C":"提早撤離到安全處","D":"開車進山區","answer":"C","explanation":"土石流速度快，要提早撤離。","image":""},{"id":"M-11-01","isl":"M","lv":1,"stem":"空氣品質指標（AQI）中，哪一個顏色代表空氣良好？","A":"綠色","B":"紅色","C":"紫色","D":"褐紅色","answer":"A","explanation":"綠色良好。","image":""},{"id":"M-11-02","isl":"M","lv":1,"stem":"下列何者不是空氣汙染的主要來源？","A":"汽機車廢氣","B":"工廠燃燒燃料","C":"露天燃燒","D":"種樹","answer":"D","explanation":"植物不會造成空氣汙染。","image":""},{"id":"M-11-03","isl":"M","lv":2,"stem":"PM2.5 對健康影響大，主要原因是？","A":"顏色很黑","B":"有臭味","C":"粒徑很小，能深入肺部","D":"很重","answer":"C","explanation":"細懸浮微粒能進入肺泡。","image":""},{"id":"M-11-04","isl":"M","lv":2,"stem":"形成酸雨的主要汙染物是？","A":"氧氣和氮氣","B":"硫氧化物和氮氧化物","C":"水蒸氣","D":"氦氣","answer":"B","explanation":"溶於雨水形成酸。","image":""},{"id":"M-11-05","isl":"M","lv":3,"stem":"空氣品質不良（AQI 紅色）時，下列做法何者最恰當？","A":"減少戶外劇烈運動，必要時戴口罩","B":"到操場跑步","C":"在家燒香","D":"打開所有窗戶","answer":"A","explanation":"減少暴露。","image":""},{"id":"M-12-01","isl":"M","lv":1,"stem":"家庭廢水未經處理排入河川，最可能造成？","A":"河水變清","B":"魚變多","C":"溶氧減少，魚類死亡","D":"水溫下降","answer":"C","explanation":"有機物分解消耗溶氧。","image":""},{"id":"M-12-02","isl":"M","lv":1,"stem":"下列哪一個做法可以減少家庭廢水汙染？","A":"把廢油倒進水槽","B":"先把碗盤油汙擦掉再洗","C":"多用清潔劑","D":"廚餘沖進馬桶","answer":"B","explanation":"減少油脂進入廢水。","image":""},{"id":"M-12-03","isl":"M","lv":2,"stem":"含磷清潔劑大量排入湖泊，可能造成？","A":"優養化","B":"酸雨","C":"地震","D":"颱風","answer":"A","explanation":"藻類大量繁殖。","image":""},{"id":"M-12-04","isl":"M","lv":2,"stem":"汙水處理廠處理後的放流水，適合用來？","A":"直接飲用","B":"泡奶粉","C":"煮飯","D":"澆花、沖廁所","answer":"D","explanation":"非飲用的用途可再利用。","image":""},{"id":"M-12-05","isl":"M","lv":3,"stem":"為什麼家庭廢水要接到汙水下水道，而不是雨水溝？","A":"雨水溝比較窄","B":"汙水下水道比較便宜","C":"汙水下水道會送到汙水處理廠處理","D":"雨水溝會倒流","answer":"C","explanation":"雨水溝直接通往河川。","image":""},{"id":"M-13-01","isl":"M","lv":1,"stem":"日本水俁病是哪一種重金屬汙染造成的？","A":"汞","B":"鐵","C":"鈣","D":"鈉","answer":"A","explanation":"含汞廢水汙染海洋。","image":""},{"id":"M-13-02","isl":"M","lv":1,"stem":"下列何者屬於重金屬汙染物？","A":"氧","B":"氮","C":"碳","D":"鎘","answer":"D","explanation":"鎘是重金屬。","image":""},{"id":"M-13-03","isl":"M","lv":2,"stem":"海洋食物鏈「浮游生物→小魚→大魚→人」中，汞濃度最高的是？","A":"浮游生物","B":"小魚","C":"人","D":"海水","answer":"C","explanation":"生物放大：愈高層愈高。","image":""},{"id":"M-13-04","isl":"M","lv":2,"stem":"重金屬容易沿食物鏈累積，主要原因是？","A":"很容易分解","B":"在生物體內難分解、難排出","C":"會變成氧氣","D":"只存在水中","answer":"B","explanation":"所以會愈積愈多。","image":""},{"id":"M-13-05","isl":"M","lv":3,"stem":"下列哪一個做法最能減少重金屬進入環境？","A":"工廠廢水處理後排放、回收廢電池","B":"把電池埋在土裡","C":"把廢水排入河川稀釋","D":"焚燒電子產品","answer":"A","explanation":"從源頭減少排放。","image":""},{"id":"M-14-01","isl":"M","lv":1,"stem":"表示聲音大小的單位是？","A":"瓦特","B":"伏特","C":"分貝（dB）","D":"度","answer":"C","explanation":"分貝表示音量。","image":""},{"id":"M-14-02","isl":"M","lv":1,"stem":"下列何者屬於光害？","A":"白天陽光","B":"城市夜晚燈光太亮看不到星星","C":"月光","D":"螢火蟲發光","answer":"B","explanation":"過多不當的人工照明。","image":""},{"id":"M-14-03","isl":"M","lv":2,"stem":"在高速公路旁設置隔音牆，屬於哪一種防治噪音的方法？","A":"阻隔傳播","B":"減少音源","C":"保護接收者","D":"增加音量","answer":"A","explanation":"擋住聲音傳播。","image":""},{"id":"M-14-04","isl":"M","lv":2,"stem":"海邊的強烈燈光可能讓剛孵化的小海龜？","A":"游得更快","B":"長得更大","C":"沒有影響","D":"迷失方向，爬不回大海","answer":"D","explanation":"光害干擾生物作息。","image":""},{"id":"M-14-05","isl":"M","lv":3,"stem":"要減少路燈造成的光害，最好的做法是？","A":"把燈改成向上照","B":"增加燈的數量","C":"使用有遮罩、向下照的燈具","D":"整晚開最亮","answer":"C","explanation":"讓光照在需要的地方。","image":""},{"id":"M-21-01","isl":"M","lv":1,"stem":"科學探究的第一步通常是？","A":"觀察並提出問題","B":"直接下結論","C":"公布結果","D":"寫報告","answer":"A","explanation":"探究從觀察現象、發現問題開始。","image":""},{"id":"M-21-02","isl":"M","lv":1,"stem":"實驗中，刻意改變的條件稱為？","A":"操縱變因","B":"應變變因","C":"控制變因","D":"結論","answer":"A","explanation":"操縱變因是實驗者有意改變的因素。","image":""},{"id":"M-21-03","isl":"M","lv":2,"stem":"實驗中，要保持不變的條件稱為？","A":"應變變因","B":"假設","C":"控制變因","D":"操縱變因","answer":"C","explanation":"其他條件保持相同，才能比較操縱變因的影響。","image":""},{"id":"M-21-04","isl":"M","lv":2,"stem":"研究「溫度對糖溶解速率的影響」，應變變因是？","A":"水的量","B":"溶解速率","C":"溫度","D":"糖的種類","answer":"B","explanation":"應變變因是隨操縱變因而改變、被測量的結果。","image":""},{"id":"M-21-05","isl":"M","lv":3,"stem":"科學實驗要重複多次，目的是？","A":"增加變因","B":"浪費時間","C":"改變假設","D":"提高結果的可靠性","answer":"D","explanation":"重複實驗可以減少偶然誤差。","image":""},{"id":"M-22-01","isl":"M","lv":1,"stem":"發現萬有引力與三大運動定律的科學家是？","A":"牛頓","B":"愛因斯坦","C":"道耳頓","D":"達爾文","answer":"A","explanation":"牛頓提出運動定律與萬有引力定律。","image":""},{"id":"M-22-02","isl":"M","lv":1,"stem":"提出元素週期表的科學家是？","A":"哥白尼","B":"門得列夫","C":"牛頓","D":"伽利略","answer":"B","explanation":"門得列夫於 1869 年提出週期表。","image":""},{"id":"M-22-03","isl":"M","lv":2,"stem":"用望遠鏡觀察木星的衛星，支持日心說的科學家是？","A":"法拉第","B":"達爾文","C":"孟德爾","D":"伽利略","answer":"D","explanation":"伽利略的觀測支持了哥白尼的日心說。","image":""},{"id":"M-22-04","isl":"M","lv":2,"stem":"1895 年發現 X 射線的科學家是？","A":"法拉第","B":"倫琴","C":"愛因斯坦","D":"牛頓","answer":"B","explanation":"倫琴發現 X 射線，獲得第一屆諾貝爾物理學獎。","image":""},{"id":"M-22-05","isl":"M","lv":3,"stem":"發明巴氏殺菌法、證明微生物會引起發酵與疾病的科學家是？","A":"牛頓","B":"巴斯德","C":"哥白尼","D":"愛因斯坦","answer":"B","explanation":"巴斯德對微生物學貢獻很大。","image":""},{"id":"M-23-01","isl":"M","lv":1,"stem":"保險絲的作用是？","A":"儲存電能","B":"電流過大時熔斷，保護電路","C":"增加電流","D":"提高電壓","answer":"B","explanation":"電流過大時保險絲熔斷，切斷電路，避免過熱起火。","image":""},{"id":"M-23-02","isl":"M","lv":1,"stem":"許多電器同時插在同一個插座，最可能發生？","A":"電流過大、過熱","B":"沒有影響","C":"電壓變成零","D":"電器變省電","answer":"A","explanation":"總電流過大會使電線發熱，容易起火。","image":""},{"id":"M-23-03","isl":"M","lv":2,"stem":"電器加裝接地線，主要目的是？","A":"提高電壓","B":"增加亮度","C":"防止漏電造成觸電","D":"增加用電量","answer":"C","explanation":"漏電時電流會經接地線導入大地，保護使用者。","image":""},{"id":"M-23-04","isl":"M","lv":2,"stem":"發生短路時，電路中的電流會？","A":"變成交流","B":"突然變得很大","C":"不變","D":"變成零","answer":"B","explanation":"短路時電阻很小，電流突然變得非常大。","image":""},{"id":"M-23-05","isl":"M","lv":3,"stem":"手濕的時候不要碰電器，是因為？","A":"水是絕緣體","B":"電器會生鏽","C":"手會變髒","D":"水能導電，增加觸電危險","answer":"D","explanation":"含有雜質的水會導電，使人更容易觸電。","image":""},{"id":"M-24-01","isl":"M","lv":1,"stem":"疫苗的作用是？","A":"殺死所有細菌","B":"增加食慾","C":"讓身體產生抗體，預防疾病","D":"治療已發病的人","answer":"C","explanation":"疫苗讓免疫系統先認識病原體，產生抗體與記憶。","image":""},{"id":"M-24-02","isl":"M","lv":1,"stem":"下列哪一種疾病是由病毒引起的？","A":"破傷風","B":"霍亂","C":"結核病","D":"流行性感冒","answer":"D","explanation":"流感是病毒引起，結核病、霍亂、破傷風是細菌引起。","image":""},{"id":"M-24-03","isl":"M","lv":2,"stem":"抗生素可以用來對付？","A":"細菌","B":"血球","C":"癌細胞","D":"病毒","answer":"A","explanation":"抗生素能殺死或抑制細菌，對病毒無效。","image":""},{"id":"M-24-04","isl":"M","lv":2,"stem":"勤洗手、戴口罩能預防傳染病，是因為？","A":"殺死體內病毒","B":"增加食慾","C":"增加抗體","D":"減少病原體傳播","answer":"D","explanation":"阻斷病原體的傳播途徑。","image":""},{"id":"M-24-05","isl":"M","lv":3,"stem":"接種疫苗後，身體會產生？","A":"激素","B":"抗生素","C":"抗體與記憶細胞","D":"病毒","answer":"C","explanation":"免疫系統產生抗體和記憶細胞，下次遇到同種病原體能快速反應。","image":""},{"id":"M-25-01","isl":"M","lv":1,"stem":"食品包裝上的「保存期限」是指？","A":"在適當保存下可安全食用的期限","B":"品牌","C":"最低價格","D":"製造日期","answer":"A","explanation":"保存期限是在標示條件下保存，可以安全食用的期限。","image":""},{"id":"M-25-02","isl":"M","lv":1,"stem":"食品添加物中的防腐劑，功能是？","A":"延緩食品腐敗","B":"增加甜味","C":"增加顏色","D":"增加重量","answer":"A","explanation":"防腐劑可抑制微生物，延長保存時間。","image":""},{"id":"M-25-03","isl":"M","lv":2,"stem":"營養標示中，熱量常用的單位是？","A":"伏特","B":"牛頓","C":"公尺","D":"大卡","answer":"D","explanation":"食品熱量用大卡（kcal）表示。","image":""},{"id":"M-25-04","isl":"M","lv":2,"stem":"每日飲食建議中，哪一類食物要特別節制？","A":"全穀類","B":"高油高糖食品","C":"蔬菜","D":"白開水","answer":"B","explanation":"高油高糖食品吃多了容易肥胖，影響健康。","image":""},{"id":"M-25-05","isl":"M","lv":3,"stem":"預防食物中毒，下列哪一種做法正確？","A":"生肉與蔬菜共用砧板","B":"生熟食分開處理","C":"剩菜不加熱","D":"熟食放室溫一整天","answer":"B","explanation":"生熟食分開可避免細菌交叉汙染。","image":""},{"id":"M-26-01","isl":"M","lv":1,"stem":"地震發生時，在室內最好先？","A":"衝向窗戶","B":"點火看路","C":"搭電梯逃生","D":"躲在桌下保護頭部","answer":"D","explanation":"先就地避難，保護頭頸，等搖晃停止再離開。","image":""},{"id":"M-26-02","isl":"M","lv":1,"stem":"颱風來臨前，應該？","A":"游泳","B":"登山","C":"去海邊看浪","D":"固定門窗、準備物資","answer":"D","explanation":"颱風前要加固門窗，準備飲水、食物與手電筒。","image":""},{"id":"M-26-03","isl":"M","lv":2,"stem":"土石流警戒時，應該？","A":"靠近溪邊","B":"遠離溪流與陡坡","C":"留在山坡下","D":"去河邊觀察","answer":"B","explanation":"土石流多發生在溪流與山坡，應盡快遠離。","image":""},{"id":"M-26-04","isl":"M","lv":2,"stem":"發生火災時，逃生的正確做法是？","A":"搭電梯","B":"用濕毛巾掩口鼻、壓低姿勢","C":"躲進衣櫃","D":"站直快跑","answer":"B","explanation":"煙往上飄，壓低姿勢，用濕毛巾可減少吸入濃煙。","image":""},{"id":"M-26-05","isl":"M","lv":3,"stem":"地震後回家，若聞到瓦斯味，應該先？","A":"按電鈴","B":"打開電燈","C":"點蠟燭","D":"開窗並關閉瓦斯，避免火源","answer":"D","explanation":"瓦斯外洩時不能產生火花，要開窗通風、關閉瓦斯開關。","image":""},{"id":"M-27-01","isl":"M","lv":1,"stem":"測量液體體積，常用的工具是？","A":"溫度計","B":"量筒","C":"碼表","D":"直尺","answer":"B","explanation":"量筒用來測量液體體積。","image":""},{"id":"M-27-02","isl":"M","lv":1,"stem":"測量物體的質量，使用的工具是？","A":"量筒","B":"直尺","C":"天平","D":"碼表","answer":"C","explanation":"天平用來測量質量。","image":""},{"id":"M-27-03","isl":"M","lv":2,"stem":"游標卡尺的優點是？","A":"能較精確地測量小物體的長度","B":"測量溫度","C":"測量時間","D":"測量質量","answer":"A","explanation":"游標卡尺可精確測量長度、內外徑與深度。","image":""},{"id":"M-27-04","isl":"M","lv":2,"stem":"GPS 定位系統是利用什麼訊號來定位？","A":"紅外線燈","B":"人造衛星發出的電波","C":"地震波","D":"聲波","answer":"B","explanation":"GPS 接收多顆人造衛星的電波來計算位置。","image":""},{"id":"M-27-05","isl":"M","lv":3,"stem":"測量結果的「有效數字」，最後一位通常是？","A":"零","B":"準確值","C":"估計值","D":"沒有意義","answer":"C","explanation":"有效數字最後一位是估計值，前面都是準確讀到的數字。","image":""},{"id":"N-01-01","isl":"N","lv":1,"stem":"下列何者屬於生物資源？","A":"木材","B":"石油","C":"鐵礦","D":"天然氣","answer":"A","explanation":"木材來自植物，可以靠生長再補充。","image":""},{"id":"N-01-02","isl":"N","lv":1,"stem":"為什麼要限制漁網的網目不能太小？","A":"讓漁網比較便宜","B":"讓船開得比較快","C":"讓大魚逃走","D":"讓幼魚能逃走、長大繁殖","answer":"D","explanation":"幼魚長大繁殖後，族群才能延續。","image":""},{"id":"N-01-03","isl":"N","lv":2,"stem":"某海域長期過度捕撈沙丁魚，最可能發生什麼事？","A":"海鳥數量增加","B":"沙丁魚反而變多","C":"以沙丁魚為食的海鳥也減少","D":"其他生物都不受影響","answer":"C","explanation":"食物減少，捕食者也受影響。","image":""},{"id":"N-01-04","isl":"N","lv":2,"stem":"下列哪一種做法最符合生物資源的永續利用？","A":"全年無休捕撈","B":"設立休漁期與禁漁區","C":"用電魚的方式捕魚","D":"捕到的幼魚全部帶回","answer":"B","explanation":"給族群時間繁殖，才能永續。","image":""},{"id":"N-01-05","isl":"N","lv":3,"stem":"某種魚每年能繁殖補充約 20 萬尾。若希望族群長期維持穩定，每年的捕撈量應該？","A":"不超過 20 萬尾","B":"大於 20 萬尾","C":"愈多愈好","D":"與繁殖量無關","answer":"A","explanation":"取用不超過補充量，族群才不會愈來愈小。","image":""},{"id":"N-02-01","isl":"N","lv":1,"stem":"能源效率分級標示中，哪一級最省電？","A":"5 級","B":"3 級","C":"1 級","D":"都一樣","answer":"C","explanation":"1 級最省電。","image":""},{"id":"N-02-02","isl":"N","lv":1,"stem":"下列何者是節約能源的好方法？","A":"冷氣開到 18 °C","B":"用 LED 燈取代傳統燈泡","C":"出門不關燈","D":"冰箱門常常打開","answer":"B","explanation":"LED 燈耗電較少。","image":""},{"id":"N-02-03","isl":"N","lv":2,"stem":"電視關機後插頭沒拔，下列敘述何者正確？","A":"仍有少量待機耗電","B":"完全不耗電","C":"耗電比開機還多","D":"會自動斷電","answer":"A","explanation":"待機仍耗電，長期累積也可觀。","image":""},{"id":"N-02-04","isl":"N","lv":2,"stem":"夏天使用冷氣，下列哪個做法最省電又舒適？","A":"設 20 °C 並關門窗","B":"設 16 °C 快速降溫後關掉","C":"開著門窗吹冷氣","D":"設 27 °C 搭配電風扇","answer":"D","explanation":"提高設定溫度並搭配電風扇可省電。","image":""},{"id":"N-02-05","isl":"N","lv":3,"stem":"為什麼節約用電能減少二氧化碳排放？","A":"電本身含有二氧化碳","B":"電線會排放二氧化碳","C":"臺灣大部分的電來自燃燒化石燃料發電","D":"節電會讓植物變多","answer":"C","explanation":"少用電，發電廠就少燒燃料。","image":""},{"id":"N-03-01","isl":"N","lv":1,"stem":"自備購物袋去買東西，屬於 5R 中的哪一項？","A":"重複使用","B":"回收","C":"再生","D":"拒絕","answer":"A","explanation":"購物袋一用再用＝重複使用。","image":""},{"id":"N-03-02","isl":"N","lv":1,"stem":"把寶特瓶洗淨壓扁後放進回收箱，屬於？","A":"拒絕","B":"減量","C":"重複使用","D":"回收","answer":"D","explanation":"分類送去回收處理。","image":""},{"id":"N-03-03","isl":"N","lv":2,"stem":"下列何者屬於「拒絕」？","A":"把舊衣送給弟弟","B":"廚餘做堆肥","C":"店家要送塑膠袋時說不用了","D":"回收鋁罐","answer":"C","explanation":"不收下不必要的東西＝拒絕。","image":""},{"id":"N-03-04","isl":"N","lv":2,"stem":"回收的寶特瓶製成衣服的纖維，最符合哪一個 R？","A":"拒絕","B":"再生","C":"減量","D":"重複使用","answer":"B","explanation":"廢棄物變成新的產品原料＝再生。","image":""},{"id":"N-03-05","isl":"N","lv":3,"stem":"為什麼說「拒絕」與「減量」通常比「回收」更好？","A":"從源頭就不產生垃圾，省下製造與處理的資源","B":"回收不需要能源","C":"回收是違法的","D":"拒絕可以賺錢","answer":"A","explanation":"回收仍需運輸與再製，源頭減量更省資源。","image":""},{"id":"N-04-01","isl":"N","lv":1,"stem":"吃剩的菜葉果皮應該分到哪一類？","A":"資源回收","B":"有害廢棄物","C":"廚餘","D":"大型廢棄物","answer":"C","explanation":"果皮菜葉屬於廚餘。","image":""},{"id":"N-04-02","isl":"N","lv":1,"stem":"廢乾電池應如何處理？","A":"丟進一般垃圾","B":"交到回收點","C":"埋在土裡","D":"丟進廚餘桶","answer":"B","explanation":"廢電池含重金屬，要回收。","image":""},{"id":"N-04-03","isl":"N","lv":2,"stem":"關於塑膠微粒，下列何者正確？","A":"可能被生物吃下並沿食物鏈傳遞","B":"很快就被細菌分解","C":"只存在陸地上","D":"對生物完全無害","answer":"A","explanation":"塑膠微粒可被浮游生物、魚類吃下。","image":""},{"id":"N-04-04","isl":"N","lv":2,"stem":"垃圾送進焚化廠的優點不包括？","A":"減少垃圾體積","B":"可回收熱能發電","C":"減少掩埋場用地","D":"完全不產生任何汙染","answer":"D","explanation":"焚化仍會產生廢氣和灰渣。","image":""},{"id":"N-04-05","isl":"N","lv":3,"stem":"某地區的垃圾量持續大於處理和分解能力，最可能的結果是？","A":"環境自然變乾淨","B":"生物多樣性增加","C":"環境品質下降","D":"沒有任何影響","answer":"C","explanation":"超過環境承載能力，環境就會惡化。","image":""},{"id":"N-05-01","isl":"N","lv":1,"stem":"「生態足跡」是指什麼？","A":"維持生活所需資源換算成的土地與水域面積","B":"一個人走過的路程","C":"動物留下的腳印","D":"森林的面積","answer":"A","explanation":"把資源需求換算成面積。","image":""},{"id":"N-05-02","isl":"N","lv":1,"stem":"下列何者可以縮小生態足跡？","A":"天天開車上學","B":"多吃進口食物","C":"用完就丟的餐具","D":"搭大眾運輸、吃在地食物","answer":"D","explanation":"減少運輸與能源使用可縮小足跡。","image":""},{"id":"N-05-03","isl":"N","lv":2,"stem":"關於永續發展，下列何者正確？","A":"完全不使用自然資源","B":"只考慮經濟成長","C":"滿足現在的需要，也不損害下一代滿足需要的能力","D":"資源用完再找新的就好","answer":"C","explanation":"這是永續發展的意義。","image":""},{"id":"N-05-04","isl":"N","lv":2,"stem":"若全人類的生態足跡超過地球的再生能力，會發生什麼事？","A":"地球會變大","B":"資源逐漸耗竭，生態平衡受破壞","C":"資源自動增加","D":"沒有影響","answer":"B","explanation":"超支地球，資源愈用愈少。","image":""},{"id":"N-05-05","isl":"N","lv":3,"stem":"同樣一份午餐，哪一種的生態足跡通常較小？","A":"在地當季的蔬菜和米飯","B":"空運來的進口牛排","C":"多層包裝的冷凍食品","D":"一次性餐具裝的外送","answer":"A","explanation":"在地當季、少包裝、少肉，資源與運輸需求較少。","image":""},{"id":"N-06-01","isl":"N","lv":1,"stem":"下列何者是溫室氣體？","A":"氮氣","B":"氧氣","C":"甲烷","D":"氬氣","answer":"C","explanation":"甲烷是溫室氣體。","image":""},{"id":"N-06-02","isl":"N","lv":1,"stem":"工業革命後，大氣中哪種溫室氣體因人類燃燒燃料而明顯增加？","A":"氮氣","B":"二氧化碳","C":"氧氣","D":"氦氣","answer":"B","explanation":"燃燒化石燃料產生大量二氧化碳。","image":""},{"id":"N-06-03","isl":"N","lv":2,"stem":"關於溫室效應，下列敘述何者正確？","A":"沒有溫室效應，地球會比現在冷很多","B":"完全是人類造成的","C":"溫室氣體會反射所有陽光","D":"溫室效應愈強愈好","answer":"A","explanation":"自然的溫室效應讓地表平均約 15 °C。","image":""},{"id":"N-06-04","isl":"N","lv":2,"stem":"溫室氣體主要吸收哪一種輻射，使地表保溫？","A":"可見光","B":"X 射線","C":"聲波","D":"地面放出的紅外線","answer":"D","explanation":"地面放出紅外線，溫室氣體吸收後再放出。","image":""},{"id":"N-06-05","isl":"N","lv":3,"stem":"「全球暖化」最適合用下列哪一種資料來說明？","A":"今天某城市的高溫","B":"某一年的颱風數","C":"數十年來全球平均氣溫的變化","D":"一天之中的溫差","answer":"C","explanation":"暖化是長期、全球平均的趨勢。","image":""},{"id":"N-07-01","isl":"N","lv":1,"stem":"珊瑚白化主要和下列哪一個因素有關？","A":"海水溫度升高","B":"海水變冷","C":"月亮引力","D":"海浪變小","answer":"A","explanation":"海溫升高使共生藻離開。","image":""},{"id":"N-07-02","isl":"N","lv":1,"stem":"全球暖化使北極熊面臨的主要問題是？","A":"太多食物","B":"天敵變多","C":"空氣太乾","D":"海冰減少，難以捕捉海豹","answer":"D","explanation":"北極熊在海冰上捕捉海豹。","image":""},{"id":"N-07-03","isl":"N","lv":2,"stem":"在暖化的情況下，臺灣高山上的某種植物最可能如何變化？","A":"往平地移動","B":"分布完全不變","C":"分布往更高的海拔移動","D":"長得更矮","answer":"C","explanation":"往較涼爽的高海拔移動。","image":""},{"id":"N-07-04","isl":"N","lv":2,"stem":"為什麼高山頂上的生物特別容易受暖化威脅？","A":"山頂太吵","B":"已經沒有更高、更涼的地方可以遷移","C":"山頂食物太多","D":"山頂沒有陽光","answer":"B","explanation":"退無可退，族群可能消失。","image":""},{"id":"N-07-05","isl":"N","lv":3,"stem":"某植物因暖化提早開花，但幫它授粉的昆蟲仍照原本時間出現，最可能的結果？","A":"授粉成功率下降","B":"授粉成功率上升","C":"昆蟲改吃別的植物所以更好","D":"沒有影響","answer":"A","explanation":"時間錯開，授粉受影響。","image":""},{"id":"N-08-01","isl":"N","lv":1,"stem":"下列何者是造成海平面上升的原因？","A":"海水變冷","B":"下雨變少","C":"陸地冰川融化流入海中","D":"火山爆發","answer":"C","explanation":"陸冰融化與海水熱膨脹使海平面上升。","image":""},{"id":"N-08-02","isl":"N","lv":1,"stem":"氣候變遷可能造成的現象不包括？","A":"熱浪更頻繁","B":"地球自轉停止","C":"豪雨更集中","D":"乾旱更嚴重","answer":"B","explanation":"地球自轉與氣候變遷無關。","image":""},{"id":"N-08-03","isl":"N","lv":2,"stem":"杯中漂浮的冰塊完全融化後，杯中水面會？","A":"幾乎不變","B":"明顯上升","C":"明顯下降","D":"先降後升","answer":"A","explanation":"漂浮的冰排開的水量，約等於它融化成的水。","image":""},{"id":"N-08-04","isl":"N","lv":2,"stem":"海平面上升對臺灣西南沿海的低窪地區可能造成？","A":"土地變高","B":"更不容易淹水","C":"雨量增加","D":"淹水、海水入侵地下水","answer":"D","explanation":"低窪海岸最先受影響。","image":""},{"id":"N-08-05","isl":"N","lv":3,"stem":"某地全年總雨量和以前差不多，但雨集中在少數幾天下完，最可能出現？","A":"水資源更穩定","B":"不會有任何問題","C":"淹水和乾旱的風險都增加","D":"地下水大量增加","answer":"C","explanation":"雨太集中，來不及蓄存，且久旱期更長。","image":""},{"id":"N-09-01","isl":"N","lv":1,"stem":"下列何者屬於氣候變遷的「減緩」做法？","A":"發展太陽能發電","B":"加高堤防","C":"建造滯洪池","D":"培育耐旱稻米","answer":"A","explanation":"再生能源減少溫室氣體排放。","image":""},{"id":"N-09-02","isl":"N","lv":1,"stem":"下列何者屬於「調適」？","A":"騎腳踏車上學","B":"植樹造林","C":"減少用電","D":"建立豪雨預警系統","answer":"D","explanation":"預警系統降低災害衝擊。","image":""},{"id":"N-09-03","isl":"N","lv":2,"stem":"「淨零排放」的意思是？","A":"完全不排放任何氣體","B":"只排放氧氣","C":"排放的溫室氣體與移除的量相互抵銷","D":"排放量減少一半","answer":"C","explanation":"排放與移除抵銷，淨值為零。","image":""},{"id":"N-09-04","isl":"N","lv":2,"stem":"產品上的碳足跡標籤主要告訴消費者什麼？","A":"產品的價格","B":"產品生命週期中排放的溫室氣體量","C":"產品的重量","D":"產品的保存期限","answer":"B","explanation":"碳足跡：產品一生的溫室氣體排放量。","image":""},{"id":"N-09-05","isl":"N","lv":3,"stem":"為什麼因應氣候變遷需要減緩與調適同時進行？","A":"減緩見效慢，需靠調適；不減緩衝擊更大","B":"兩者完全相同","C":"調適可以讓暖化停止","D":"只要減緩就不會有任何衝擊","answer":"A","explanation":"減緩處理原因，調適面對已發生的衝擊。","image":""},{"id":"N-10-01","isl":"N","lv":1,"stem":"下列何者不是化石燃料？","A":"煤","B":"石油","C":"木炭","D":"天然氣","answer":"C","explanation":"木炭是現代木材燒製的，不是化石燃料。","image":""},{"id":"N-10-02","isl":"N","lv":1,"stem":"為什麼化石燃料屬於不可再生能源？","A":"數量無限","B":"形成需要數百萬年以上","C":"只能用一次的瓶子裝","D":"價格太貴","answer":"B","explanation":"人類的使用速度遠快於形成速度。","image":""},{"id":"N-10-03","isl":"N","lv":2,"stem":"煤主要是由下列何者經長時間埋藏形成的？","A":"古代沼澤森林的植物","B":"海水中的鹽","C":"火山熔岩","D":"恐龍的骨頭","answer":"A","explanation":"煤由古代植物遺骸形成。","image":""},{"id":"N-10-04","isl":"N","lv":2,"stem":"燃燒煤可能造成酸雨，主要是因為產生了？","A":"氧氣","B":"水蒸氣","C":"氮氣","D":"二氧化硫等硫氧化物","answer":"D","explanation":"硫氧化物溶於雨水形成酸雨。","image":""},{"id":"N-10-05","isl":"N","lv":3,"stem":"為什麼說化石燃料中的能量最初來自太陽？","A":"太陽直接把石油送到地球","B":"化石燃料會發光","C":"古代生物行光合作用或攝食，儲存了太陽的能量","D":"地球內部有太陽","answer":"C","explanation":"植物把光能轉為化學能，再被埋藏保存。","image":""},{"id":"N-11-01","isl":"N","lv":1,"stem":"下列何者不是再生能源？","A":"天然氣","B":"太陽能","C":"風能","D":"地熱","answer":"A","explanation":"天然氣是化石燃料。","image":""},{"id":"N-11-02","isl":"N","lv":1,"stem":"太陽能電池把太陽能直接轉換成什麼能？","A":"核能","B":"化學能","C":"聲能","D":"電能","answer":"D","explanation":"光電板把光能轉為電能。","image":""},{"id":"N-11-03","isl":"N","lv":2,"stem":"臺灣海峽適合發展離岸風力發電，主要原因是？","A":"海水很深","B":"附近有火山","C":"冬季東北季風強而穩定","D":"日照最長","answer":"C","explanation":"季風強是風力的好條件。","image":""},{"id":"N-11-04","isl":"N","lv":2,"stem":"關於再生能源的限制，下列何者正確？","A":"再生能源會用完","B":"太陽能和風力發電量受天氣影響","C":"發電時排放大量二氧化碳","D":"完全不需要土地","answer":"B","explanation":"發電較不穩定，需要儲能搭配。","image":""},{"id":"N-11-05","isl":"N","lv":3,"stem":"某地有溫泉和火山地形，最適合優先評估發展哪一種再生能源？","A":"地熱發電","B":"潮汐發電","C":"離岸風電","D":"水力發電","answer":"A","explanation":"溫泉與火山代表地底熱能豐富。","image":""},{"id":"N-12-01","isl":"N","lv":1,"stem":"下列何者屬於生質能源？","A":"煤","B":"天然氣","C":"用廢食用油製成的生質柴油","D":"核能","answer":"C","explanation":"生質柴油來自生物油脂。","image":""},{"id":"N-12-02","isl":"N","lv":1,"stem":"養豬場的豬糞經微生物分解產生的沼氣，主要成分是？","A":"氧氣","B":"甲烷","C":"氮氣","D":"氦氣","answer":"B","explanation":"沼氣主要是甲烷。","image":""},{"id":"N-12-03","isl":"N","lv":2,"stem":"甘蔗製成生質酒精，主要利用哪一個過程？","A":"發酵","B":"光合作用","C":"蒸發","D":"燃燒","answer":"A","explanation":"酵母菌把糖發酵成酒精。","image":""},{"id":"N-12-04","isl":"N","lv":2,"stem":"大量用玉米生產生質酒精，可能造成什麼問題？","A":"玉米變得更便宜","B":"完全沒有影響","C":"空氣變乾淨所以沒問題","D":"與糧食爭地，糧價上漲","answer":"D","explanation":"能源作物可能排擠糧食生產。","image":""},{"id":"N-12-05","isl":"N","lv":3,"stem":"為什麼生質能被認為比化石燃料更有助於減少二氧化碳的淨排放？","A":"生質能燃燒不需要氧氣","B":"生質能不會燃燒","C":"原料植物生長時會吸收二氧化碳","D":"生質能來自地底","answer":"C","explanation":"燃燒釋放的碳，大致是植物生長時吸收的碳。","image":""},{"id":"N-13-01","isl":"N","lv":1,"stem":"油電混合動力車在煞車時，可以把哪一種能量轉回電能？","A":"動能","B":"核能","C":"光能","D":"聲能","answer":"A","explanation":"煞車回充回收動能。","image":""},{"id":"N-13-02","isl":"N","lv":1,"stem":"氫燃料電池發電時，主要的產物是？","A":"二氧化碳","B":"二氧化硫","C":"煤灰","D":"水","answer":"D","explanation":"氫和氧反應生成水。","image":""},{"id":"N-13-03","isl":"N","lv":2,"stem":"「汽電共生」提高能源使用效率的方法是？","A":"用汽車發電","B":"晚上關掉電廠","C":"發電時產生的廢熱再拿來利用","D":"只用太陽能","answer":"C","explanation":"把廢熱再利用，減少浪費。","image":""},{"id":"N-13-04","isl":"N","lv":2,"stem":"太陽能飛機能在夜間持續飛行，主要是因為？","A":"月光也能發電","B":"白天把多餘的電存進電池","C":"夜間改燒煤","D":"機翼會吸收風能","answer":"B","explanation":"白天充電，夜間用電池。","image":""},{"id":"N-13-05","isl":"N","lv":3,"stem":"關於新興能源科技，下列敘述何者正確？","A":"核融合發電目前仍在研究階段","B":"燃料電池需要燃燒氫氣","C":"油電混合車完全不用汽油","D":"汽電共生會浪費更多能源","answer":"A","explanation":"核融合仍在研究，其他敘述都錯。","image":""},{"id":"N-14-01","isl":"N","lv":1,"stem":"臺灣的能源主要來源是？","A":"全部自己生產","B":"全部來自太陽能","C":"大部分仰賴進口","D":"全部來自核能","answer":"C","explanation":"臺灣九成七以上能源仰賴進口。","image":""},{"id":"N-14-02","isl":"N","lv":1,"stem":"近年臺灣發電量占比最高的兩種是？","A":"風力與水力","B":"燃氣與燃煤","C":"地熱與太陽能","D":"核能與生質能","answer":"B","explanation":"燃氣、燃煤合計約八成。","image":""},{"id":"N-14-03","isl":"N","lv":2,"stem":"下列哪一項是燃煤發電的主要缺點？","A":"空氣汙染與二氧化碳排放多","B":"晚上無法發電","C":"會產生核廢料","D":"完全不穩定","answer":"A","explanation":"燃煤汙染較多。","image":""},{"id":"N-14-04","isl":"N","lv":2,"stem":"下列關於太陽能發電的敘述，何者正確？","A":"會產生大量二氧化碳","B":"必須進口燃料","C":"晚上發電量最高","D":"受天氣與日夜影響，需要儲能搭配","answer":"D","explanation":"太陽能乾淨但不穩定。","image":""},{"id":"N-14-05","isl":"N","lv":3,"stem":"評估一種能源是否適合，下列哪一種做法最恰當？","A":"只看哪一種最便宜","B":"只聽網路謠言","C":"依據證據比較安全、環境、成本與供應穩定性","D":"選名字最好聽的","answer":"C","explanation":"能源決策需要多面向、依證據評估。","image":""},{"id":"N-21-01","isl":"N","lv":1,"stem":"地球水資源中，容易取用的淡水大約占多少？","A":"約 70%","B":"不到 1%","C":"約 50%","D":"約 90%","answer":"B","explanation":"地球水資源約 97% 是海水，淡水又大多在冰川與地下深處，容易取用的不到 1%。","image":""},{"id":"N-21-02","isl":"N","lv":1,"stem":"下列哪一種做法可以節約用水？","A":"邊刷牙邊開水龍頭","B":"長時間沖澡","C":"用洗米水澆花","D":"每天洗車","answer":"C","explanation":"一水多用可以減少水的浪費。","image":""},{"id":"N-21-03","isl":"N","lv":2,"stem":"水庫的主要功能是？","A":"儲水、供水與防洪","B":"發射衛星","C":"製造降雨","D":"增加氧氣","answer":"A","explanation":"水庫可以儲存雨水、供應用水，也能調節洪水。","image":""},{"id":"N-21-04","isl":"N","lv":2,"stem":"臺灣水資源不容易保存，主要原因之一是？","A":"沒有河川","B":"完全沒有雨","C":"雨量集中、地勢陡峭，水容易流入海","D":"沒有山","answer":"C","explanation":"臺灣河短流急，下雨集中，水很快流入大海。","image":""},{"id":"N-21-05","isl":"N","lv":3,"stem":"海水淡化的缺點是？","A":"會增加雨量","B":"耗能高、成本高","C":"水量太多","D":"淡化後不能喝","answer":"B","explanation":"海水淡化要消耗大量能源，成本也較高。","image":""},{"id":"N-22-01","isl":"N","lv":1,"stem":"太陽能發電是利用什麼？","A":"核燃料","B":"太陽光","C":"煤","D":"石油","answer":"B","explanation":"太陽能板把光能轉換成電能。","image":""},{"id":"N-22-02","isl":"N","lv":1,"stem":"風力發電是把什麼能轉換成電能？","A":"熱能","B":"化學能","C":"光能","D":"風的動能","answer":"D","explanation":"風推動葉片轉動，帶動發電機。","image":""},{"id":"N-22-03","isl":"N","lv":2,"stem":"太陽能發電的缺點是？","A":"會排放大量二氧化碳","B":"受天氣與日夜影響","C":"燃料昂貴","D":"會產生核廢料","answer":"B","explanation":"陰天或夜晚發電量會減少。","image":""},{"id":"N-22-04","isl":"N","lv":2,"stem":"風力發電的優點是？","A":"完全沒有噪音","B":"發電量永遠穩定","C":"完全不受風速影響","D":"發電時不排放二氧化碳","answer":"D","explanation":"風能是再生能源，發電過程不排放二氧化碳。","image":""},{"id":"N-22-05","isl":"N","lv":3,"stem":"下列哪一種屬於再生能源？","A":"石油","B":"煤","C":"天然氣","D":"地熱","answer":"D","explanation":"地熱來自地球內部的熱，可持續利用。","image":""},{"id":"N-23-01","isl":"N","lv":1,"stem":"核能發電利用的是？","A":"核分裂","B":"光合作用","C":"燃燒","D":"摩擦","answer":"A","explanation":"核能電廠目前利用重原子核分裂釋放的能量。","image":""},{"id":"N-23-02","isl":"N","lv":1,"stem":"核能發電廠的燃料常用？","A":"鈾","B":"瓦斯","C":"木材","D":"煤","answer":"A","explanation":"核能發電使用鈾做燃料。","image":""},{"id":"N-23-03","isl":"N","lv":2,"stem":"核能發電的優點是？","A":"完全沒有廢料","B":"發電時不排放二氧化碳","C":"完全沒有風險","D":"不需要燃料","answer":"B","explanation":"核能發電過程中不排放二氧化碳，但仍有核廢料與安全問題。","image":""},{"id":"N-23-04","isl":"N","lv":2,"stem":"核能發電最需要妥善處理的是？","A":"二氧化碳","B":"廢紙","C":"灰燼","D":"核廢料","answer":"D","explanation":"核廢料具有放射性，需要長期安全存放。","image":""},{"id":"N-23-05","isl":"N","lv":3,"stem":"核分裂是指？","A":"原子被燃燒","B":"兩個輕原子核結合","C":"重原子核分裂成較小的原子核並釋放能量","D":"原子核變成電子","answer":"C","explanation":"重原子核分裂成較小的原子核，並釋放大量能量。","image":""},{"id":"N-24-01","isl":"N","lv":1,"stem":"PM2.5 是指？","A":"2.5 公里的距離","B":"2.5 度的溫度","C":"重 2.5 克的物體","D":"直徑小於 2.5 微米的懸浮微粒","answer":"D","explanation":"PM2.5 是非常細小的懸浮微粒，可以進入肺部。","image":""},{"id":"N-24-02","isl":"N","lv":1,"stem":"下列哪一種是空氣汙染物？","A":"氬氣","B":"氧氣","C":"氮氣","D":"二氧化硫","answer":"D","explanation":"二氧化硫是燃燒含硫燃料產生的汙染物。","image":""},{"id":"N-24-03","isl":"N","lv":2,"stem":"戴口罩主要可以減少吸入哪一類汙染物？","A":"氧氣","B":"水蒸氣","C":"懸浮微粒","D":"氮氣","answer":"C","explanation":"口罩可過濾部分懸浮微粒。","image":""},{"id":"N-24-04","isl":"N","lv":2,"stem":"汽機車排放的廢氣中含有？","A":"純氧","B":"純氮","C":"氦氣","D":"一氧化碳與氮氧化物","answer":"D","explanation":"燃料不完全燃燒會產生一氧化碳，高溫下氮與氧反應生成氮氧化物。","image":""},{"id":"N-24-05","isl":"N","lv":3,"stem":"要改善空氣品質，下列哪一項最有效？","A":"多搭乘大眾運輸","B":"增加私家車","C":"露天焚燒垃圾","D":"增加燃煤","answer":"A","explanation":"減少燃料燃燒就能減少汙染物排放。","image":""},{"id":"N-25-01","isl":"N","lv":1,"stem":"溫室效應主要由大氣中哪類氣體增加造成？","A":"氬氣","B":"二氧化碳等溫室氣體","C":"氮氣","D":"氧氣","answer":"B","explanation":"二氧化碳、甲烷等溫室氣體增加，使地球保留更多熱量。","image":""},{"id":"N-25-02","isl":"N","lv":1,"stem":"溫室氣體的特性是？","A":"能吸收並保留地表放出的熱","B":"能製造雨","C":"能反射所有陽光","D":"能吸收二氧化碳","answer":"A","explanation":"溫室氣體讓熱量不易散失到太空。","image":""},{"id":"N-25-03","isl":"N","lv":2,"stem":"適度的溫室效應對地球？","A":"完全有害","B":"有益，能使地表維持適合生物的溫度","C":"沒有影響","D":"使地球結冰","answer":"B","explanation":"沒有溫室效應，地球會冷得多；問題是溫室氣體過多。","image":""},{"id":"N-25-04","isl":"N","lv":2,"stem":"下列哪一種氣體也是溫室氣體？","A":"氬","B":"甲烷","C":"氦","D":"氖","answer":"B","explanation":"甲烷是溫室氣體，主要來自畜牧、稻田與垃圾掩埋。","image":""},{"id":"N-25-05","isl":"N","lv":3,"stem":"全球暖化可能造成什麼結果？","A":"颱風消失","B":"雨量固定不變","C":"北極變得更冷","D":"冰川融化、海平面上升","answer":"D","explanation":"暖化使冰川融化、海水膨脹，海平面上升。","image":""},{"id":"N-26-01","isl":"N","lv":1,"stem":"回收的廢紙可以再製成？","A":"塑膠","B":"電池","C":"再生紙","D":"玻璃","answer":"C","explanation":"廢紙回收後可再製成紙張。","image":""},{"id":"N-26-02","isl":"N","lv":1,"stem":"用完的電池應該如何處理？","A":"丟一般垃圾","B":"埋在土裡","C":"丟進水溝","D":"送到回收站","answer":"D","explanation":"電池含重金屬，應交給回收單位處理。","image":""},{"id":"N-26-03","isl":"N","lv":2,"stem":"垃圾焚化的優點是？","A":"減少垃圾體積，還能利用熱發電","B":"不用處理灰渣","C":"不耗能源","D":"完全不產生汙染","answer":"A","explanation":"焚化可減少垃圾體積，並利用熱能發電，但仍須處理廢氣與灰渣。","image":""},{"id":"N-26-04","isl":"N","lv":2,"stem":"寶特瓶回收後，常見的再製品是？","A":"玻璃杯","B":"纖維布料","C":"紙張","D":"金屬罐","answer":"B","explanation":"寶特瓶可以再製成聚酯纖維，做成衣服等。","image":""},{"id":"N-26-05","isl":"N","lv":3,"stem":"垃圾減量，下列哪一個順序最符合環保原則？","A":"減量、重複使用、回收、處理","B":"處理、回收、重複使用、減量","C":"重複使用、處理、減量、回收","D":"回收、處理、減量、重複使用","answer":"A","explanation":"最好的方式是先減少產生，再重複使用，接著回收，最後才是處理。","image":""},{"id":"N-27-01","isl":"N","lv":1,"stem":"永續發展是指？","A":"只追求經濟成長","B":"滿足現在需求，也不損害後代的需求","C":"停止所有發展","D":"只保護環境不發展","answer":"B","explanation":"永續發展要兼顧現在與未來。","image":""},{"id":"N-27-02","isl":"N","lv":1,"stem":"聯合國永續發展目標的英文縮寫是？","A":"SDGs","B":"DNA","C":"GPS","D":"LED","answer":"A","explanation":"聯合國提出 17 項永續發展目標（SDGs）。","image":""},{"id":"N-27-03","isl":"N","lv":2,"stem":"永續發展通常包含哪三個面向？","A":"農、工、商","B":"過去、現在、未來","C":"環境、社會、經濟","D":"海、陸、空","answer":"C","explanation":"永續發展要同時考慮環境保護、社會公平與經濟發展。","image":""},{"id":"N-27-04","isl":"N","lv":2,"stem":"下列哪一項做法符合永續發展？","A":"無限制抽取地下水","B":"使用再生能源","C":"大量砍伐森林","D":"濫捕魚類","answer":"B","explanation":"再生能源可持續使用，減少環境負擔。","image":""},{"id":"N-27-05","isl":"N","lv":3,"stem":"聯合國永續發展目標（SDGs）共有幾項？","A":"30 項","B":"10 項","C":"17 項","D":"7 項","answer":"C","explanation":"SDGs 共 17 項目標。","image":""},{"id":"N-28-01","isl":"N","lv":1,"stem":"下列哪一種燈最省電？","A":"白熾燈泡","B":"三種都一樣","C":"鎢絲燈泡","D":"LED 燈","answer":"D","explanation":"LED 燈的發光效率高，比傳統燈泡省電。","image":""},{"id":"N-28-02","isl":"N","lv":1,"stem":"離開房間時隨手關燈，屬於？","A":"增加碳排放","B":"浪費能源","C":"增加用電","D":"節能減碳","answer":"D","explanation":"隨手關燈能節省用電，減少碳排放。","image":""},{"id":"N-28-03","isl":"N","lv":2,"stem":"「碳足跡」是指？","A":"腳印","B":"碳的重量","C":"煤的使用量","D":"產品或活動產生的溫室氣體總量","answer":"D","explanation":"碳足跡衡量某個產品或行為產生的溫室氣體排放。","image":""},{"id":"N-28-04","isl":"N","lv":2,"stem":"冷氣設定在 26～28℃，主要目的是？","A":"增加用電","B":"節省電能","C":"縮短冷氣壽命","D":"讓人感冒","answer":"B","explanation":"設定溫度提高，冷氣耗電減少。","image":""},{"id":"N-28-05","isl":"N","lv":3,"stem":"下列哪一種方式最能減少碳排放？","A":"開大排氣量汽車","B":"騎腳踏車或步行","C":"多開冷氣","D":"使用一次性餐具","answer":"B","explanation":"不使用化石燃料的交通方式，排放量最少。","image":""},{"id":"Q-01-01","isl":"Q","lv":1,"stem":"摩擦起電時，在物體間轉移的是？","A":"電子","B":"質子","C":"中子","D":"原子核","answer":"A","explanation":"只有電子會轉移。","image":""},{"id":"Q-01-02","isl":"Q","lv":1,"stem":"甲、乙兩物帶同性電，靠近時會？","A":"互相吸引","B":"沒有作用","C":"先吸後斥","D":"互相排斥","answer":"D","explanation":"同性電互相排斥。","image":""},{"id":"Q-01-03","isl":"Q","lv":2,"stem":"玻璃棒和絲綢摩擦後，玻璃棒帶正電，表示玻璃棒？","A":"得到電子","B":"得到質子","C":"失去電子","D":"失去質子","answer":"C","explanation":"失去電子的物體帶正電。","image":""},{"id":"Q-01-04","isl":"Q","lv":2,"stem":"用帶電的梳子靠近碎紙片，紙片被吸起來，主要原因是？","A":"紙片原本帶異性電","B":"感應使紙片靠近的一端帶異性電","C":"梳子有磁性","D":"空氣流動","answer":"B","explanation":"感應起電讓紙片靠近梳子的一端帶異性電，所以被吸引。","image":""},{"id":"Q-01-05","isl":"Q","lv":3,"stem":"甲、乙摩擦後，甲帶 3 個單位負電，乙帶多少電？","A":"3 個單位正電","B":"3 個單位負電","C":"6 個單位正電","D":"不帶電","answer":"A","explanation":"電荷守恆：摩擦後兩物帶等量異性電。","image":""},{"id":"Q-02-01","isl":"Q","lv":1,"stem":"測量電流的安培計應該如何連接？","A":"和用電器並聯","B":"直接接在電池兩端","C":"和用電器串聯","D":"怎麼接都可以","answer":"C","explanation":"安培計要串聯。","image":""},{"id":"Q-02-02","isl":"Q","lv":1,"stem":"電壓的單位是？","A":"安培","B":"伏特","C":"歐姆","D":"瓦特","answer":"B","explanation":"電壓單位是伏特（V）。","image":""},{"id":"Q-02-03","isl":"Q","lv":2,"stem":"兩個燈泡串聯，其中一個燒壞，另一個會？","A":"熄滅","B":"更亮","C":"一樣亮","D":"閃爍","answer":"A","explanation":"串聯只有一條路，斷了就全部不亮。","image":""},{"id":"Q-02-04","isl":"Q","lv":2,"stem":"三顆 1.5 V 乾電池串聯，總電壓是？","A":"1.5 V","B":"3 V","C":"0.5 V","D":"4.5 V","answer":"D","explanation":"電池串聯，電壓相加：1.5 × 3 = 4.5 V。","image":""},{"id":"Q-02-05","isl":"Q","lv":3,"stem":"下列關於並聯電路的敘述，何者正確？","A":"各支路電流一定相同","B":"總電流比任一支路小","C":"各支路電壓相同","D":"一個燈壞了全部熄滅","answer":"C","explanation":"並聯時各支路兩端電壓相同。","image":""},{"id":"Q-03-01","isl":"Q","lv":1,"stem":"歐姆定律的式子是？","A":"V = I × R","B":"V = I + R","C":"V = I ÷ R","D":"V = R ÷ I","answer":"A","explanation":"V = I × R。","image":""},{"id":"Q-03-02","isl":"Q","lv":2,"stem":"一個電阻兩端電壓 6 V，通過電流 0.3 A，電阻是？","A":"1.8 Ω","B":"2 Ω","C":"0.05 Ω","D":"20 Ω","answer":"D","explanation":"R = V ÷ I = 6 ÷ 0.3 = 20 Ω。","image":""},{"id":"Q-03-03","isl":"Q","lv":2,"stem":"20 Ω 的電阻接 4 V 電壓，電流是？","A":"80 A","B":"5 A","C":"0.2 A","D":"0.5 A","answer":"C","explanation":"I = V ÷ R = 4 ÷ 20 = 0.2 A。","image":""},{"id":"Q-03-04","isl":"Q","lv":2,"stem":"甲、乙兩電阻的 V–I 圖（縱軸 V）中，甲的直線比乙陡，表示？","A":"乙電阻較大","B":"甲電阻較大","C":"兩者相同","D":"無法判斷","answer":"B","explanation":"斜率 = V ÷ I = 電阻，越陡電阻越大。","image":""},{"id":"Q-03-05","isl":"Q","lv":3,"stem":"同材料的導線，下列哪一條電阻最大？","A":"長而細","B":"短而粗","C":"短而細","D":"長而粗","answer":"A","explanation":"越長、越細，電阻越大。","image":""},{"id":"Q-04-01","isl":"Q","lv":1,"stem":"電鍋煮飯主要利用電流的哪一種效應？","A":"磁效應","B":"化學效應","C":"熱效應","D":"光效應","answer":"C","explanation":"電流通過電熱線發熱，是熱效應。","image":""},{"id":"Q-04-02","isl":"Q","lv":1,"stem":"1 度電等於？","A":"1 瓦特","B":"1 千瓦小時","C":"1 千瓦","D":"1 焦耳","answer":"B","explanation":"1 度 = 1 kWh。","image":""},{"id":"Q-04-03","isl":"Q","lv":2,"stem":"一台 1500 W 的吹風機使用 20 分鐘，用電幾度？","A":"0.5 度","B":"30 度","C":"3 度","D":"0.3 度","answer":"A","explanation":"1.5 kW × (1/3) 小時 = 0.5 度。","image":""},{"id":"Q-04-04","isl":"Q","lv":2,"stem":"電器接 110 V，通過電流 5 A，電功率是？","A":"22 W","B":"115 W","C":"105 W","D":"550 W","answer":"D","explanation":"P = I × V = 5 × 110 = 550 W。","image":""},{"id":"Q-04-05","isl":"Q","lv":3,"stem":"家裡的延長線不建議同時接電暖器、電鍋和吹風機，主要原因是？","A":"電壓會變高","B":"電阻會變成 0","C":"總電流太大使電線過熱","D":"會產生靜電","answer":"C","explanation":"並聯的大功率電器同時使用，總電流很大，電線發熱可能起火。","image":""},{"id":"Q-05-01","isl":"Q","lv":1,"stem":"磁場方向是指？","A":"小磁針 N 極所指的方向","B":"小磁針 S 極所指的方向","C":"電流方向","D":"重力方向","answer":"A","explanation":"小磁針 N 極所指的方向就是磁場方向。","image":""},{"id":"Q-05-02","isl":"Q","lv":1,"stem":"條形磁鐵哪裡的磁力最強？","A":"中間","B":"各處一樣","C":"只有 N 極","D":"兩端","answer":"D","explanation":"磁鐵兩端（磁極）磁力最強。","image":""},{"id":"Q-05-03","isl":"Q","lv":2,"stem":"關於磁力線，下列何者正確？","A":"磁力線會相交","B":"磁鐵外部由 S 到 N","C":"越密磁場越強","D":"磁力線真實存在","answer":"C","explanation":"磁力線越密，磁場越強。","image":""},{"id":"Q-05-04","isl":"Q","lv":2,"stem":"把一根條形磁鐵從中間切斷，會得到？","A":"一個 N 極、一個 S 極","B":"兩個都有 N、S 極的磁鐵","C":"兩根沒有磁性的鐵棒","D":"兩個 N 極","answer":"B","explanation":"磁極不能單獨存在。","image":""},{"id":"Q-05-05","isl":"Q","lv":3,"stem":"指北針的 N 極指向地理北方，表示地理北極附近是地磁的？","A":"S 極","B":"N 極","C":"沒有磁極","D":"赤道","answer":"A","explanation":"異極相吸，所以地理北極附近是地磁的 S 極。","image":""},{"id":"Q-06-01","isl":"Q","lv":1,"stem":"最早發現電流會產生磁場的科學家是？","A":"牛頓","B":"歐姆","C":"厄斯特","D":"伽利略","answer":"C","explanation":"厄斯特發現電流的磁效應。","image":""},{"id":"Q-06-02","isl":"Q","lv":1,"stem":"下列何者不能增強電磁鐵的磁力？","A":"增加線圈圈數","B":"改變電流方向","C":"增大電流","D":"放入鐵芯","answer":"B","explanation":"改變電流方向只會讓磁極對調。","image":""},{"id":"Q-06-03","isl":"Q","lv":2,"stem":"直導線通電後，周圍的磁力線形狀是？","A":"以導線為中心的同心圓","B":"平行直線","C":"放射狀直線","D":"沒有磁力線","answer":"A","explanation":"直導線周圍的磁力線是同心圓。","image":""},{"id":"Q-06-04","isl":"Q","lv":2,"stem":"線圈通電時，用右手四指沿電流方向彎曲，大拇指所指的是？","A":"S 極","B":"電流方向","C":"電子流方向","D":"N 極","answer":"D","explanation":"螺線管右手定則：大拇指指向 N 極。","image":""},{"id":"Q-06-05","isl":"Q","lv":3,"stem":"電磁起重機用電磁鐵而不用永久磁鐵，主要原因是？","A":"電磁鐵比較便宜","B":"電磁鐵比較輕","C":"可以用開關控制吸放","D":"永久磁鐵吸不起鐵","answer":"C","explanation":"電磁鐵通電吸、斷電放，可以控制。","image":""},{"id":"Q-07-01","isl":"Q","lv":1,"stem":"電動機是把哪一種能轉換成動能？","A":"電能","B":"熱能","C":"化學能","D":"光能","answer":"A","explanation":"電動機：電能 → 動能。","image":""},{"id":"Q-07-02","isl":"Q","lv":1,"stem":"電動機中，每轉半圈改變一次線圈電流方向的裝置是？","A":"磁鐵","B":"電池","C":"開關","D":"電刷與半圓形集電環","answer":"D","explanation":"電刷每轉半圈改接另一片半圓形集電環，線圈中的電流方向就自動改變。","image":""},{"id":"Q-07-03","isl":"Q","lv":2,"stem":"下列何種做法會使馬達反轉？","A":"增加電池數量","B":"同時對調電池和磁鐵","C":"只把磁鐵兩極對調","D":"增加線圈圈數","answer":"C","explanation":"只改變一個方向（磁場），受力方向就相反。","image":""},{"id":"Q-07-04","isl":"Q","lv":2,"stem":"載流導線在磁場中，何時受力最大？","A":"導線和磁場平行時","B":"導線和磁場垂直時","C":"電流為零時","D":"受力和方向無關","answer":"B","explanation":"電流方向和磁場垂直時受力最大。","image":""},{"id":"Q-07-05","isl":"Q","lv":3,"stem":"要讓同一個馬達轉得更快，可以？","A":"換更強的磁鐵","B":"減少電池","C":"拿掉電刷","D":"讓電流和磁場平行","answer":"A","explanation":"磁場越強，受力越大，轉得越快。","image":""},{"id":"Q-08-01","isl":"Q","lv":1,"stem":"發現電磁感應的科學家是？","A":"厄斯特","B":"牛頓","C":"法拉第","D":"歐姆","answer":"C","explanation":"法拉第發現電磁感應。","image":""},{"id":"Q-08-02","isl":"Q","lv":1,"stem":"發電機的主要能量轉換是？","A":"電能 → 動能","B":"動能 → 電能","C":"電能 → 熱能","D":"光能 → 電能","answer":"B","explanation":"發電機把動能轉成電能。","image":""},{"id":"Q-08-03","isl":"Q","lv":2,"stem":"下列哪一種情況，線圈中沒有感應電流？","A":"磁鐵靜止在線圈中","B":"磁鐵插入線圈","C":"磁鐵拔出線圈","D":"線圈靠近磁鐵","answer":"A","explanation":"磁場沒有變化，就沒有感應電流。","image":""},{"id":"Q-08-04","isl":"Q","lv":2,"stem":"要讓檢流計的指針偏轉更大，可以？","A":"把磁鐵慢慢插入","B":"減少線圈圈數","C":"讓磁鐵靜止","D":"把磁鐵快速插入","answer":"D","explanation":"磁場變化越快，感應電流越大。","image":""},{"id":"Q-08-05","isl":"Q","lv":3,"stem":"下列哪一項沒有利用電磁感應？","A":"發電機","B":"電磁爐","C":"電鍋的電熱線","D":"悠遊卡感應","answer":"C","explanation":"電熱線利用的是電流熱效應。","image":""},{"id":"Q-21-01","isl":"Q","lv":1,"stem":"兩個帶同種電荷的物體會？","A":"互相吸引","B":"合併成一個","C":"沒有作用","D":"互相排斥","answer":"D","explanation":"同性電荷相斥，異性電荷相吸。","image":""},{"id":"Q-21-02","isl":"Q","lv":1,"stem":"帶正電的物體與帶負電的物體會？","A":"互相排斥","B":"互相抵消","C":"不受力","D":"互相吸引","answer":"D","explanation":"異性電荷互相吸引。","image":""},{"id":"Q-21-03","isl":"Q","lv":2,"stem":"毛巾摩擦塑膠尺後，尺能吸起小紙片，是因為？","A":"帶電體能吸引輕小物體","B":"彈力","C":"磁力","D":"重力","answer":"A","explanation":"摩擦後塑膠尺帶電，能吸引不帶電的小紙片。","image":""},{"id":"Q-21-04","isl":"Q","lv":2,"stem":"下列哪一種是良導體？","A":"塑膠","B":"橡膠","C":"玻璃","D":"銅","answer":"D","explanation":"金屬如銅導電性好。","image":""},{"id":"Q-21-05","isl":"Q","lv":3,"stem":"驗電器的金屬箔片張開，表示？","A":"被磁化","B":"金屬箔帶異種電荷","C":"金屬箔帶同種電荷而互相排斥","D":"沒有帶電","answer":"C","explanation":"兩片金屬箔帶同種電荷，互相排斥而張開。","image":""},{"id":"Q-22-01","isl":"Q","lv":1,"stem":"串聯電路中，電流的路徑有幾條？","A":"1 條","B":"2 條","C":"很多條","D":"沒有","answer":"A","explanation":"串聯電路只有一條路徑。","image":""},{"id":"Q-22-02","isl":"Q","lv":1,"stem":"家中電器是以哪一種方式連接的？","A":"不連接","B":"串聯","C":"無法判斷","D":"並聯","answer":"D","explanation":"並聯讓每個電器都能獨立使用。","image":""},{"id":"Q-22-03","isl":"Q","lv":2,"stem":"兩個串聯的燈泡，其中一個燒壞，另一個會？","A":"變得更亮","B":"也熄滅","C":"不受影響","D":"變暗","answer":"B","explanation":"串聯電路中，一處斷路，整個電路不通。","image":""},{"id":"Q-22-04","isl":"Q","lv":2,"stem":"並聯電路中，各支路的電壓？","A":"為零","B":"相等","C":"愈遠愈大","D":"不相等","answer":"B","explanation":"並聯的各支路電壓相同。","image":""},{"id":"Q-22-05","isl":"Q","lv":3,"stem":"串聯電路中，通過各電阻的電流？","A":"各不相同","B":"相等","C":"愈後面愈大","D":"愈後面愈小","answer":"B","explanation":"串聯電路只有一條路，電流處處相等。","image":""},{"id":"Q-23-01","isl":"Q","lv":1,"stem":"電阻的單位是？","A":"安培","B":"伏特","C":"瓦特","D":"歐姆","answer":"D","explanation":"電阻單位是歐姆（Ω）。","image":""},{"id":"Q-23-02","isl":"Q","lv":1,"stem":"同材質、同粗細的導線，越長電阻？","A":"不變","B":"越小","C":"越大","D":"為零","answer":"C","explanation":"導線越長，電阻越大。","image":""},{"id":"Q-23-03","isl":"Q","lv":2,"stem":"同材質、同長度的導線，截面積越大，電阻？","A":"變成無限大","B":"不變","C":"越大","D":"越小","answer":"D","explanation":"截面積越大，電子越容易通過，電阻越小。","image":""},{"id":"Q-23-04","isl":"Q","lv":2,"stem":"金屬導線的溫度升高，電阻通常？","A":"變為零","B":"變小","C":"變大","D":"不變","answer":"C","explanation":"金屬溫度升高，電阻增加。","image":""},{"id":"Q-23-05","isl":"Q","lv":3,"stem":"兩條同材質、同截面積的導線，長度比為 1：2，電阻比是？","A":"1：1","B":"2：1","C":"1：2","D":"1：4","answer":"C","explanation":"電阻與長度成正比。","image":""},{"id":"Q-24-01","isl":"Q","lv":1,"stem":"伏特計是用來測量？","A":"電阻","B":"電流","C":"功率","D":"電壓","answer":"D","explanation":"伏特計測量電壓。","image":""},{"id":"Q-24-02","isl":"Q","lv":1,"stem":"伏特計在電路中應該如何連接？","A":"先串聯後並聯","B":"串聯","C":"不接","D":"並聯","answer":"D","explanation":"伏特計要與被測元件並聯。","image":""},{"id":"Q-24-03","isl":"Q","lv":2,"stem":"電路中，開關的作用是？","A":"儲存電能","B":"增加電流","C":"控制電路的通與斷","D":"增加電壓","answer":"C","explanation":"開關可以接通或切斷電路。","image":""},{"id":"Q-24-04","isl":"Q","lv":2,"stem":"電路符號中，電池較長的那條線代表？","A":"正極","B":"電阻","C":"開關","D":"負極","answer":"A","explanation":"長線為正極，短線為負極。","image":""},{"id":"Q-24-05","isl":"Q","lv":3,"stem":"把安培計誤接成並聯在電池兩端，可能發生？","A":"變成串聯","B":"一切正常","C":"量到電壓","D":"電流過大、儀器損壞","answer":"D","explanation":"安培計內阻很小，並聯會造成短路。","image":""},{"id":"Q-25-01","isl":"Q","lv":1,"stem":"並聯的電阻愈多，總電阻會？","A":"變成零","B":"不變","C":"愈大","D":"愈小","answer":"D","explanation":"並聯增加電流通路，總電阻變小。","image":""},{"id":"Q-25-02","isl":"Q","lv":1,"stem":"兩個 10 Ω 的電阻串聯，總電阻是？","A":"10 Ω","B":"5 Ω","C":"100 Ω","D":"20 Ω","answer":"D","explanation":"串聯總電阻等於各電阻相加。","image":""},{"id":"Q-25-03","isl":"Q","lv":2,"stem":"電壓 6 V、電阻 3 Ω，電流是多少？","A":"18 A","B":"0.5 A","C":"9 A","D":"2 A","answer":"D","explanation":"I＝V÷R＝6÷3＝2 A。","image":""},{"id":"Q-25-04","isl":"Q","lv":2,"stem":"電流 0.5 A 通過 20 Ω 的電阻，電阻兩端電壓是多少？","A":"0.025 V","B":"40 V","C":"20.5 V","D":"10 V","answer":"D","explanation":"V＝IR＝0.5×20＝10 V。","image":""},{"id":"Q-25-05","isl":"Q","lv":3,"stem":"3 Ω 與 6 Ω 的電阻串聯，接上 9 V 電池，電流是多少？","A":"2 A","B":"1 A","C":"3 A","D":"0.5 A","answer":"B","explanation":"總電阻 9 Ω，I＝9÷9＝1 A。","image":""},{"id":"Q-26-01","isl":"Q","lv":1,"stem":"磁鐵上磁性最強的部位是？","A":"側面中央","B":"各處都一樣","C":"正中間","D":"兩極","answer":"D","explanation":"磁極處磁性最強。","image":""},{"id":"Q-26-02","isl":"Q","lv":1,"stem":"兩個同名磁極靠近時會？","A":"合在一起","B":"互相排斥","C":"互相吸引","D":"沒有作用","answer":"B","explanation":"同名磁極相斥，異名磁極相吸。","image":""},{"id":"Q-26-03","isl":"Q","lv":2,"stem":"可以自由轉動的磁針，N 極會指向地理上的？","A":"西方","B":"東方","C":"南方","D":"北方","answer":"D","explanation":"磁針 N 極指向地球的地理北方（地磁南極）。","image":""},{"id":"Q-26-04","isl":"Q","lv":2,"stem":"磁鐵能吸引下列哪一種物質？","A":"鋁","B":"鐵","C":"銅","D":"塑膠","answer":"B","explanation":"鐵、鈷、鎳是容易被磁鐵吸引的金屬。","image":""},{"id":"Q-26-05","isl":"Q","lv":3,"stem":"把一塊磁鐵切成兩半，每一半會？","A":"都有 N 極和 S 極","B":"只有 S 極","C":"只有 N 極","D":"失去磁性","answer":"A","explanation":"磁極不能單獨存在，切開後每一塊都有 N、S 極。","image":""},{"id":"Q-27-01","isl":"Q","lv":1,"stem":"電流通過導線，導線周圍會產生？","A":"聲音","B":"磁場","C":"光","D":"重力","answer":"B","explanation":"電流會產生磁場，這是厄斯特發現的。","image":""},{"id":"Q-27-02","isl":"Q","lv":1,"stem":"電磁鐵通電時有磁性，斷電後？","A":"磁性不變","B":"磁性變強","C":"磁性變弱但仍在","D":"磁性消失","answer":"D","explanation":"電磁鐵的磁性可以用電流控制。","image":""},{"id":"Q-27-03","isl":"Q","lv":2,"stem":"要增強電磁鐵的磁性，可以？","A":"減少匝數","B":"增加線圈匝數與電流","C":"減少電流","D":"拿掉鐵心","answer":"B","explanation":"匝數越多、電流越大，磁性越強。","image":""},{"id":"Q-27-04","isl":"Q","lv":2,"stem":"電磁鐵中放入鐵心，作用是？","A":"增加電阻","B":"使線圈絕緣","C":"減少電流","D":"增強磁場","answer":"D","explanation":"鐵心會被磁化，使磁場增強。","image":""},{"id":"Q-27-05","isl":"Q","lv":3,"stem":"電鈴發出聲音，是利用？","A":"摩擦起電","B":"靜電","C":"太陽能","D":"電磁鐵反覆通電與斷電","answer":"D","explanation":"電鈴利用電磁鐵吸引、放開小槌，反覆敲擊鈴。","image":""},{"id":"Q-28-01","isl":"Q","lv":1,"stem":"發電機是把什麼能轉換成電能？","A":"光能","B":"電能","C":"核能","D":"動能","answer":"D","explanation":"發電機把轉動的動能轉換成電能。","image":""},{"id":"Q-28-02","isl":"Q","lv":1,"stem":"發電機的工作原理是？","A":"光電效應","B":"電磁感應","C":"靜電感應","D":"摩擦起電","answer":"B","explanation":"線圈在磁場中轉動，產生感應電流。","image":""},{"id":"Q-28-03","isl":"Q","lv":2,"stem":"家庭用電是哪一種電流？","A":"直流電","B":"交流電","C":"沒有電流","D":"靜電","answer":"B","explanation":"家用插座提供的是交流電。","image":""},{"id":"Q-28-04","isl":"Q","lv":2,"stem":"變壓器可以改變？","A":"磁極","B":"電阻","C":"交流電的電壓","D":"直流電的電壓","answer":"C","explanation":"變壓器利用電磁感應，改變交流電的電壓。","image":""},{"id":"Q-28-05","isl":"Q","lv":3,"stem":"發電廠把電升高電壓再輸送，目的是？","A":"使電流變大","B":"讓電更好看","C":"增加損失","D":"減少輸電時的能量損失","answer":"D","explanation":"提高電壓可降低電流，減少電線發熱損失。","image":""},{"id":"Q-29-01","isl":"Q","lv":1,"stem":"通電的導線放在磁場中，會受到？","A":"熱的作用","B":"沒有作用","C":"力的作用","D":"光的作用","answer":"C","explanation":"通電導線在磁場中會受力。","image":""},{"id":"Q-29-02","isl":"Q","lv":1,"stem":"電動機轉動的原理是？","A":"電磁感應","B":"靜電","C":"摩擦起電","D":"通電導線在磁場中受力","answer":"D","explanation":"電動機利用通電線圈在磁場中受力而轉動。","image":""},{"id":"Q-29-03","isl":"Q","lv":2,"stem":"要改變電動機的轉動方向，可以？","A":"增加零件","B":"增大電流","C":"增大電阻","D":"把電流方向反過來","answer":"D","explanation":"電流方向反過來，受力方向也反過來。","image":""},{"id":"Q-29-04","isl":"Q","lv":2,"stem":"喇叭能發聲，利用的是？","A":"熱","B":"靜電","C":"通電線圈在磁場中受力振動","D":"光線","answer":"C","explanation":"聲音訊號使線圈中的電流變化，線圈在磁場中來回振動。","image":""},{"id":"Q-29-05","isl":"Q","lv":3,"stem":"想讓電動機轉得更快，可以？","A":"斷電","B":"增大電流","C":"減小電流","D":"拿掉磁鐵","answer":"B","explanation":"電流越大，磁場中的受力越大，轉得越快。","image":""},{"id":"BT-001","isl":"E","lv":3,"stem":"探討「溫度是否影響糖溶解速率」時，下列哪一項是操縱變因？","A":"溶解所需的時間","B":"糖的質量","C":"水溫","D":"水的體積","answer":"C","explanation":"操縱變因是實驗者刻意改變的條件，這裡是水溫。","image":""},{"id":"BT-002","isl":"E","lv":3,"stem":"在實驗前，依據已知知識對結果所做的預測，稱為什麼？","A":"假說","B":"結論","C":"測量值","D":"控制組","answer":"A","explanation":"假說是可以被實驗檢驗的預測，實驗後再判斷是否成立。","image":""},{"id":"BT-003","isl":"E","lv":3,"stem":"實驗設計中，對照組的主要功能是什麼？","A":"取代重複實驗","B":"增加樣本數量","C":"與實驗組比較，判斷變因造成的效果","D":"保證實驗結果一定相同","answer":"C","explanation":"對照組不施加被測變因，用來比較實驗組的差異。","image":""},{"id":"BT-004","isl":"E","lv":3,"stem":"重複實驗多次的主要目的是什麼？","A":"減少偶然誤差，提高結果的可信度","B":"增加實驗中的變因數量","C":"縮短實驗的總時間","D":"讓數據符合原本的假說","answer":"A","explanation":"多次測量可以降低偶然因素造成的影響。","image":""},{"id":"BT-005","isl":"E","lv":3,"stem":"下列哪一個描述最符合操作型定義？","A":"糖溶得很快","B":"實驗做得很仔細","C":"水加熱至 60 ℃ 後，記錄糖完全溶解所需的時間","D":"水要比較熱","answer":"C","explanation":"操作型定義要能被測量或重複執行，例如明確的溫度與時間。","image":""},{"id":"BT-006","isl":"E","lv":3,"stem":"實驗中只改變一個變因、其餘條件都相同，這個做法稱為什麼原則？","A":"比例放大原則","B":"單一變因原則","C":"隨機抽樣原則","D":"盲測原則","answer":"B","explanation":"單一變因原則能讓結果的差異歸因於被改變的那一個條件。","image":""},{"id":"BT-007","isl":"E","lv":3,"stem":"某同學只做一次實驗就下結論，最主要的問題是什麼？","A":"樣本數不足，無法排除偶然因素","B":"沒有使用彩色圖表","C":"沒有把假說寫得很長","D":"沒有使用昂貴的儀器","answer":"A","explanation":"單次實驗容易受偶然因素影響，結論可信度不足。","image":""},{"id":"BT-008","isl":"I","lv":3,"stem":"在北半球，風從高氣壓吹向低氣壓時，受科氏力影響會怎樣偏轉？","A":"完全不偏轉","B":"向左偏","C":"向右偏","D":"垂直向上","answer":"C","explanation":"北半球的風受科氏力影響，會向右偏轉。","image":""},{"id":"BT-009","isl":"I","lv":3,"stem":"天氣圖上，等壓線越密集，代表什麼？","A":"降雨量一定很大","B":"水平氣壓差越大，風通常越強","C":"氣壓越低","D":"氣溫一定越高","answer":"B","explanation":"等壓線越密，氣壓梯度越大，風速通常越快。","image":""},{"id":"BT-010","isl":"I","lv":3,"stem":"一般而言，低氣壓區域的天氣特徵是什麼？","A":"空氣上升，容易形成雲雨","B":"溫度一定最高","C":"風力微弱且無雲","D":"空氣下沉，天氣晴朗","answer":"A","explanation":"低氣壓區空氣上升冷卻，水氣凝結，容易成雲致雨。","image":""},{"id":"BT-011","isl":"I","lv":3,"stem":"海拔越高，大氣壓力通常會怎樣變化？","A":"越小","B":"不變","C":"越大","D":"先變大再變小","answer":"A","explanation":"海拔越高，上方的空氣柱越短，壓力越小。","image":""},{"id":"BT-012","isl":"I","lv":3,"stem":"在北半球，颱風中心附近低層的空氣流動方向是什麼？","A":"逆時針向外流出","B":"順時針向中心旋入","C":"順時針向外流出","D":"逆時針向中心旋入","answer":"D","explanation":"北半球颱風的低層空氣逆時針向中心輻合上升。","image":""},{"id":"BT-013","isl":"I","lv":3,"stem":"1 標準大氣壓約等於多少百帕（hPa）？","A":"100 hPa","B":"1013 hPa","C":"1 hPa","D":"760 hPa","answer":"B","explanation":"1 標準大氣壓約為 1013 百帕，760 mmHg 是另一種表示法。","image":""},{"id":"BT-014","isl":"I","lv":3,"stem":"風向的定義是什麼？","A":"風的溫度","B":"風的速度","C":"風吹來的方向","D":"風吹去的方向","answer":"C","explanation":"風向以風吹來的方向為準，例如東風是從東方吹來。","image":""},{"id":"BT-015","isl":"J","lv":3,"stem":"下列哪一項會使化學反應速率變快？","A":"降低反應溫度","B":"增加反應物的濃度","C":"減少反應物的表面積","D":"移除觸媒","answer":"B","explanation":"反應物濃度增加，單位體積內的粒子碰撞機會增加。","image":""},{"id":"BT-016","isl":"J","lv":3,"stem":"將相同質量的塊狀大理石換成粉末，與相同濃度的鹽酸反應，反應速率會如何改變？","A":"變慢，因為接觸面積減少","B":"變慢，因為產生的氣體變少","C":"變快，因為接觸面積增加","D":"不變，因為質量相同","answer":"C","explanation":"粉末的表面積大，與鹽酸接觸的機會增加，反應加快。","image":""},{"id":"BT-017","isl":"J","lv":3,"stem":"催化劑加快反應速率的原理是什麼？","A":"改變生成物的總量","B":"提高反應溫度","C":"降低反應所需的活化能，反應後本身質量不變","D":"會被反應消耗掉","answer":"C","explanation":"催化劑降低活化能，本身不被消耗，反應後質量與化學性質不變。","image":""},{"id":"BT-018","isl":"J","lv":3,"stem":"溫度升高會使反應速率加快，主要原因是什麼？","A":"生成物變多","B":"粒子動能增加，有效碰撞次數增加","C":"反應物的質量增加","D":"活化能變大","answer":"B","explanation":"溫度升高，粒子運動加快，碰撞的能量與次數都增加。","image":""},{"id":"BT-019","isl":"J","lv":3,"stem":"下列哪一實驗最能說明「濃度」影響反應速率？","A":"相同質量的鎂帶分別放入濃度不同的鹽酸中，比較產生氣泡的速度","B":"相同的鹽酸放入不同溫度的燒杯中","C":"比較不同形狀的鎂帶與相同濃度的鹽酸反應","D":"比較不同顏色的鹽酸","answer":"A","explanation":"只改變鹽酸濃度，其餘條件相同，才能單獨觀察濃度的影響。","image":""},{"id":"BT-020","isl":"J","lv":3,"stem":"實驗室中，為了加快過氧化氫分解產生氧氣的速率，常加入的物質是什麼？","A":"酒精","B":"食鹽","C":"蔗糖","D":"二氧化錳","answer":"D","explanation":"二氧化錳是此反應的催化劑，可降低活化能而不被消耗。","image":""},{"id":"BT-021","isl":"J","lv":3,"stem":"下列哪一個變化會使反應速率變慢？","A":"加入催化劑","B":"增加反應物的表面積","C":"增加反應物的濃度","D":"降低反應溫度","answer":"D","explanation":"溫度降低使粒子動能下降，有效碰撞減少，反應變慢。","image":""},{"id":"BT-022","isl":"J","lv":3,"stem":"鐵在潮濕空氣中生鏽時，鐵原子會發生什麼變化？","A":"失去電子，被氧化","B":"轉變成氧氣","C":"得到電子，被還原","D":"不參與反應","answer":"A","explanation":"鐵失去電子形成鐵離子，屬於氧化反應。","image":""},{"id":"BT-023","isl":"J","lv":3,"stem":"在氧化還原反應中，被還原的物質會怎樣？","A":"得到電子","B":"失去電子","C":"只提供氧原子","D":"質量一定增加","answer":"A","explanation":"還原是得到電子，氧化是失去電子。","image":""},{"id":"BT-024","isl":"J","lv":3,"stem":"在電池中，發生氧化反應的電極稱為什麼？","A":"中性極","B":"正極","C":"陰極","D":"負極","answer":"D","explanation":"電池的負極發生氧化反應，會釋放電子。","image":""},{"id":"BT-025","isl":"J","lv":3,"stem":"電解水時，在會發生氧化反應的電極上產生的氣體是什麼？","A":"二氧化碳","B":"氯氣","C":"氧氣","D":"氫氣","answer":"C","explanation":"電解水時，氧在氧化反應的電極產生，氫在另一極產生。","image":""},{"id":"BT-026","isl":"J","lv":3,"stem":"電解水的產物中，氫氣與氧氣的體積比約為多少？","A":"3:1","B":"1:2","C":"1:1","D":"2:1","answer":"D","explanation":"水分子為 H₂O，產生的氫氣與氧氣體積比約為 2:1。","image":""},{"id":"BT-027","isl":"J","lv":3,"stem":"下列哪一個變化屬於氧化反應？","A":"銅在空氣中逐漸變黑","B":"食鹽溶於水","C":"冰塊逐漸融化","D":"酒精逐漸揮發","answer":"A","explanation":"銅與氧結合形成氧化銅，屬於氧化。","image":""},{"id":"BT-028","isl":"J","lv":3,"stem":"在反應 Zn + Cu²⁺ → Zn²⁺ + Cu 中，哪一種物質被還原？","A":"Cu","B":"Zn","C":"Zn²⁺","D":"Cu²⁺","answer":"D","explanation":"Cu²⁺ 得到電子變成 Cu，所以被還原。","image":""},{"id":"BT-029","isl":"D","lv":3,"stem":"人體中，將含氧較多的血液從肺送回心臟的血管是什麼？","A":"上腔靜脈","B":"主動脈","C":"肺靜脈","D":"肺動脈","answer":"C","explanation":"肺靜脈運送含氧血液回到左心房。","image":""},{"id":"BT-030","isl":"D","lv":3,"stem":"下列哪一種血管管壁較厚、彈性較大，能承受心臟輸出的高壓血液？","A":"微血管","B":"靜脈","C":"毛細血管","D":"動脈","answer":"D","explanation":"動脈承受心室收縮的高壓，管壁厚且有彈性。","image":""},{"id":"BT-031","isl":"D","lv":3,"stem":"血液中主要負責運送氧氣的成分是什麼？","A":"血小板","B":"紅血球","C":"血漿中的水分","D":"白血球","answer":"B","explanation":"紅血球含血紅素，可以與氧結合並運送。","image":""},{"id":"BT-032","isl":"D","lv":3,"stem":"血液中哪一種成分主要負責凝血？","A":"紅血球","B":"白血球","C":"血漿中的水分","D":"血小板","answer":"D","explanation":"血小板聚集並參與凝血過程，防止出血。","image":""},{"id":"BT-033","isl":"D","lv":3,"stem":"人類心臟中，哪一個心室的壁最厚？","A":"左心房","B":"右心房","C":"右心室","D":"左心室","answer":"D","explanation":"左心室需要把血液送往全身，所需壓力最大，因此壁最厚。","image":""},{"id":"BT-034","isl":"D","lv":3,"stem":"血液流經肺部後，血液中的含氧量會如何變化？","A":"增加","B":"轉變成二氧化碳","C":"減少","D":"不變","answer":"A","explanation":"肺部進行氣體交換，血液從空氣中獲得氧氣。","image":""},{"id":"BT-035","isl":"D","lv":3,"stem":"哪一條血管負責將含氧血液從左心室送往全身？","A":"肺靜脈","B":"上腔靜脈","C":"肺動脈","D":"主動脈","answer":"D","explanation":"主動脈從左心室發出，把含氧血液輸送到全身。","image":""},{"id":"BT-036","isl":"F","lv":3,"stem":"農曆初一時，從地球上看到的月相是什麼？","A":"滿月","B":"下弦月","C":"新月","D":"上弦月","answer":"C","explanation":"初一時月球位於太陽與地球之間，朝向地球的一面幾乎不亮。","image":""},{"id":"BT-037","isl":"F","lv":3,"stem":"月食發生時，月球進入地球的哪一個區域？","A":"地球的表面","B":"本影","C":"太陽的本影","D":"月球的半影區","answer":"B","explanation":"月食時地球遮住太陽光，月球進入地球的本影區。","image":""},{"id":"BT-038","isl":"F","lv":3,"stem":"日食通常發生在哪一種月相？","A":"上弦月","B":"下弦月","C":"新月","D":"滿月","answer":"C","explanation":"新月時月球位於太陽與地球之間，才可能遮住太陽。","image":""},{"id":"BT-039","isl":"F","lv":3,"stem":"月相變化主要是因為什麼？","A":"地球的影子每天遮住月亮","B":"月球本身的發光程度不斷改變","C":"月球被太陽照亮的部分，從地球看到的角度不斷改變","D":"月球自轉速度不斷改變","answer":"C","explanation":"月球本身不發光，我們看到的是被太陽照亮部分的不同角度。","image":""},{"id":"BT-040","isl":"F","lv":3,"stem":"農曆十五前後，月相通常是什麼？","A":"新月","B":"下弦月","C":"滿月","D":"上弦月","answer":"C","explanation":"農曆十五時月球與太陽分居地球兩側，看到完整亮面，即滿月。","image":""},{"id":"BT-041","isl":"F","lv":3,"stem":"在北半球，上弦月時月亮的亮面位於哪一側？","A":"上方","B":"左側","C":"下方","D":"右側","answer":"D","explanation":"上弦月時，從北半球看去，月亮的右半邊被照亮。","image":""},{"id":"BT-042","isl":"F","lv":3,"stem":"日全食發生時，地球上哪一區域能看到全食？","A":"月球半影掃過的範圍","B":"太陽本影掃過的範圍","C":"月球本影掃過的範圍","D":"地球的夜半球","answer":"C","explanation":"只有位於月球本影中的地區才會看到日全食，半影區只會看到日偏食。","image":""},{"id":"BT-043","isl":"A","lv":3,"stem":"密度的定義是什麼？","A":"單位面積的重量","B":"單位體積的質量","C":"單位時間的質量","D":"單位質量的體積","answer":"B","explanation":"密度 = 質量 ÷ 體積。","image":""},{"id":"BT-044","isl":"A","lv":3,"stem":"某物體質量 60 g，體積 20 cm³，其密度是多少？","A":"3 g/cm³","B":"1/3 g/cm³","C":"1200 g/cm³","D":"80 g/cm³","answer":"A","explanation":"密度 = 60 ÷ 20 = 3 g/cm³。","image":""},{"id":"BT-045","isl":"A","lv":3,"stem":"50 cm³ 的水（密度 1 g/cm³）質量約為多少？","A":"0.5 g","B":"500 g","C":"5 g","D":"50 g","answer":"D","explanation":"質量 = 密度 × 體積 = 1 × 50 = 50 g。","image":""},{"id":"BT-046","isl":"A","lv":3,"stem":"用量筒測量不規則固體的體積，主要利用哪一種方法？","A":"估計法","B":"排水法","C":"直接秤重法","D":"比例法","answer":"B","explanation":"將固體放入水中，增加的水體積就是固體的體積。","image":""},{"id":"BT-047","isl":"A","lv":3,"stem":"某鋁塊體積為 2 cm³，密度為 2.7 g/cm³，其質量約為多少？","A":"0.74 g","B":"2.7 g","C":"5.4 g","D":"27 g","answer":"C","explanation":"質量 = 2.7 × 2 = 5.4 g。","image":""},{"id":"BT-048","isl":"A","lv":3,"stem":"兩物體體積相同，質量較大的那一個，其密度會如何？","A":"相同","B":"無法比較","C":"較小","D":"較大","answer":"D","explanation":"體積相同時，質量越大，密度越大。","image":""},{"id":"BT-049","isl":"A","lv":3,"stem":"某液體 100 mL 的質量為 80 g，此液體的密度是多少？","A":"1.25 g/cm³","B":"0.8 g/cm³","C":"0.08 g/cm³","D":"8 g/cm³","answer":"B","explanation":"1 mL = 1 cm³，密度 = 80 ÷ 100 = 0.8 g/cm³。","image":""},{"id":"BT-050","isl":"G","lv":3,"stem":"若黃色（Y）對綠色（y）為顯性，黃色豌豆的純合子基因型是什麼？","A":"yy","B":"YY","C":"Yy","D":"Y","answer":"B","explanation":"純合子的兩個對偶基因相同，黃色純合子為 YY。","image":""},{"id":"BT-051","isl":"G","lv":3,"stem":"Aa × Aa 的子代中，顯性性狀與隱性性狀的比例約為多少？","A":"9:3:3:1","B":"1:1","C":"3:1","D":"1:2:1","answer":"C","explanation":"Aa × Aa 的表現型比例為 3:1，基因型比例為 1:2:1。","image":""},{"id":"BT-052","isl":"G","lv":3,"stem":"子代出現隱性性狀，表示其基因型一定是什麼？","A":"純合顯性","B":"純合隱性","C":"雜合子","D":"無法判斷","answer":"B","explanation":"隱性性狀只有在兩個對偶基因都是隱性時才會表現。","image":""},{"id":"BT-053","isl":"G","lv":3,"stem":"某個體的基因型為 Aa（A 為顯性），其表現型為什麼？","A":"介於兩者之間的中間型","B":"顯性性狀","C":"隱性性狀","D":"無法確定","answer":"B","explanation":"只要有一個顯性對偶基因，在完全顯性下就會表現顯性性狀。","image":""},{"id":"BT-054","isl":"G","lv":3,"stem":"親代都是雜合子 Bb，子代為 bb 的機率是多少？","A":"1/4","B":"1/8","C":"3/4","D":"1/2","answer":"A","explanation":"Bb × Bb 的子代中，bb 占 1/4。","image":""},{"id":"BT-055","isl":"G","lv":3,"stem":"親代為 AA 與 aa，子代的基因型會是什麼？","A":"全部為 aa","B":"AA：Aa：aa = 1：2：1","C":"全部為 Aa","D":"全部為 AA","answer":"C","explanation":"每個子代都從親代各得一個 A 與一個 a，所以全部為 Aa。","image":""},{"id":"BT-056","isl":"G","lv":3,"stem":"在遺傳學中，同一基因位置上成對的不同形式（如 A 與 a）稱為什麼？","A":"表現型","B":"對偶基因","C":"基因型","D":"突變","answer":"B","explanation":"對偶基因是位於同源染色體相同位置、控制同一性狀的不同形式。","image":""},{"id":"BT-057","isl":"E","lv":3,"stem":"等速直線運動的 v-t 圖形是什麼？","A":"水平直線","B":"拋物線","C":"垂直線","D":"斜直線","answer":"A","explanation":"等速時速度不變，v-t 圖為水平線。","image":""},{"id":"BT-058","isl":"E","lv":3,"stem":"v-t 圖中，圖形與時間軸所圍的面積代表什麼？","A":"功","B":"加速度","C":"速率的變化量","D":"位移","answer":"D","explanation":"速度乘以時間等於位移，因此面積代表位移。","image":""},{"id":"BT-059","isl":"E","lv":3,"stem":"一物體從靜止開始以 2 m/s² 做等加速直線運動，3 秒後的速度是多少？","A":"9 m/s","B":"12 m/s","C":"6 m/s","D":"3 m/s","answer":"C","explanation":"v = at = 2 × 3 = 6 m/s。","image":""},{"id":"BT-060","isl":"E","lv":3,"stem":"平均速率與平均速度的主要差異是什麼？","A":"速率一定為零","B":"速率只考慮路程，速度考慮位移與方向","C":"速率有方向，速度沒有方向","D":"兩者的單位不同","answer":"B","explanation":"速率 = 路程 ÷ 時間，速度 = 位移 ÷ 時間，速度具有方向性。","image":""},{"id":"BT-061","isl":"E","lv":3,"stem":"某人向東走 4 m，再向西走 1 m，其位移為多少？","A":"向東 5 m","B":"向西 3 m","C":"向東 3 m","D":"5 m","answer":"C","explanation":"位移是始點到終點的直線距離與方向：向東 4 − 1 = 3 m。","image":""},{"id":"BT-062","isl":"E","lv":3,"stem":"物體做等減速直線運動時，v-t 圖的斜率為什麼？","A":"零","B":"正值","C":"負值","D":"無法判斷","answer":"C","explanation":"速度越來越小，斜率（加速度）為負。","image":""},{"id":"BT-063","isl":"E","lv":3,"stem":"物體做等速直線運動時，其加速度為多少？","A":"零","B":"固定不為零","C":"越來越大","D":"越來越小","answer":"A","explanation":"速度不變，加速度為零。","image":""},{"id":"BT-064","isl":"D","lv":3,"stem":"植物細胞具有、可進行光合作用的胞器是什麼？","A":"粒線體","B":"葉綠體","C":"核糖體","D":"高基氏體","answer":"B","explanation":"葉綠體含葉綠素，是光合作用的場所。","image":""},{"id":"BT-065","isl":"D","lv":3,"stem":"細胞中負責進行呼吸作用、產生大部分能量（ATP）的胞器是什麼？","A":"液泡","B":"粒線體","C":"內質網","D":"葉綠體","answer":"B","explanation":"粒線體是細胞進行細胞呼吸、產生能量的主要場所。","image":""},{"id":"BT-066","isl":"D","lv":3,"stem":"下列哪一項是植物細胞具有、動物細胞沒有的構造？","A":"細胞核","B":"細胞膜","C":"細胞壁","D":"粒線體","answer":"C","explanation":"細胞壁位於細胞膜外，為植物細胞所特有。","image":""},{"id":"BT-067","isl":"D","lv":3,"stem":"控制細胞活動，並含有遺傳物質的構造是什麼？","A":"細胞核","B":"細胞質","C":"細胞膜","D":"核糖體","answer":"A","explanation":"細胞核內有染色體（DNA），負責控制細胞活動。","image":""},{"id":"BT-068","isl":"D","lv":3,"stem":"下列哪一個構造負責合成蛋白質？","A":"液泡","B":"中心粒","C":"核糖體","D":"溶酶體","answer":"C","explanation":"核糖體是蛋白質合成的場所。","image":""},{"id":"BT-069","isl":"D","lv":3,"stem":"細胞膜的主要功能是什麼？","A":"控制物質進出細胞","B":"進行光合作用","C":"製造細胞的能量","D":"儲存遺傳物質","answer":"A","explanation":"細胞膜具有選擇性通透的功能，控制物質出入。","image":""},{"id":"BT-070","isl":"D","lv":3,"stem":"成熟植物細胞中，通常佔據很大體積、可調節細胞膨壓的胞器是什麼？","A":"液泡","B":"葉綠體","C":"粒線體","D":"核仁","answer":"A","explanation":"成熟植物細胞的液泡大，液泡內的水分可維持細胞膨壓。","image":""},{"id":"BT-071","isl":"B","lv":3,"stem":"光合作用進行的主要場所是什麼？","A":"液泡","B":"細胞核","C":"粒線體","D":"葉綠體","answer":"D","explanation":"光合作用在含葉綠素的葉綠體中進行。","image":""},{"id":"BT-072","isl":"B","lv":3,"stem":"光合作用的主要反應物是什麼？","A":"葡萄糖與水","B":"氧氣與葡萄糖","C":"二氧化碳與水","D":"二氧化碳與氧氣","answer":"C","explanation":"光合作用利用光能，把二氧化碳與水轉變為葡萄糖與氧氣。","image":""},{"id":"BT-073","isl":"B","lv":3,"stem":"光合作用所產生的氣體是什麼？","A":"二氧化碳","B":"氧氣","C":"氮氣","D":"氫氣","answer":"B","explanation":"水在光反應中被分解，釋放氧氣。","image":""},{"id":"BT-074","isl":"B","lv":3,"stem":"細胞呼吸作用主要在哪裡進行？","A":"葉綠體","B":"高基氏體","C":"核糖體","D":"粒線體","answer":"D","explanation":"細胞呼吸主要發生在粒線體，釋放能量。","image":""},{"id":"BT-075","isl":"B","lv":3,"stem":"下列哪一項是細胞呼吸作用的主要產物？","A":"氮氣與氫氣","B":"二氧化碳與水","C":"氧氣與葡萄糖","D":"葡萄糖與水","answer":"B","explanation":"細胞呼吸分解葡萄糖，產生二氧化碳、水與能量。","image":""},{"id":"BT-076","isl":"B","lv":3,"stem":"白天光線充足時，植物葉片中的光合作用與呼吸作用，下列何者較可能？","A":"只有呼吸作用進行","B":"兩者都完全停止","C":"光合作用速率大於呼吸作用速率","D":"呼吸作用速率大於光合作用速率","answer":"C","explanation":"光照充足時，光合作用旺盛，植物會淨吸收二氧化碳、釋放氧氣。","image":""},{"id":"BT-077","isl":"B","lv":3,"stem":"光合作用與細胞呼吸作用的關係，下列何者正確？","A":"兩者都只在夜晚進行","B":"兩者互不相關","C":"光合作用產生的葡萄糖與氧氣，可供細胞呼吸使用","D":"細胞呼吸產生的氧氣供光合作用使用，光合作用產生的水供細胞呼吸使用","answer":"C","explanation":"光合作用與細胞呼吸互補，產物與反應物相互利用。","image":""},{"id":"BT-078","isl":"J","lv":3,"stem":"含有碳與氫、只由單鍵連接的化合物，稱為什麼？","A":"烷","B":"烯","C":"醇","D":"炔","answer":"A","explanation":"烷類碳與碳之間只有單鍵，例如甲烷。","image":""},{"id":"BT-079","isl":"J","lv":3,"stem":"乙醇的官能基是什麼？","A":"酯基（-COO-）","B":"醛基（-CHO）","C":"羧基（-COOH）","D":"羥基（-OH）","answer":"D","explanation":"醇類的官能基為羥基，乙醇含有 -OH。","image":""},{"id":"BT-080","isl":"J","lv":3,"stem":"醋酸（乙酸）的官能基是什麼？","A":"羧基（-COOH）","B":"醛基（-CHO）","C":"酯基（-COO-）","D":"羥基（-OH）","answer":"A","explanation":"有機酸含羧基，乙酸具有酸性。","image":""},{"id":"BT-081","isl":"J","lv":3,"stem":"醇與有機酸反應，主要會生成什麼物質？","A":"聚合物","B":"烷","C":"酯","D":"醛","answer":"C","explanation":"醇與酸的酯化反應會形成酯與水，酯常有特殊香味。","image":""},{"id":"BT-082","isl":"J","lv":3,"stem":"下列哪一個物質是常見的聚合物？","A":"聚乙烯","B":"乙醇","C":"甲烷","D":"醋酸","answer":"A","explanation":"聚乙烯由許多乙烯單體聚合而成，屬於聚合物。","image":""},{"id":"BT-083","isl":"J","lv":3,"stem":"乙烯（C₂H₄）中碳與碳之間的鍵結是什麼？","A":"單鍵","B":"三鍵","C":"離子鍵","D":"雙鍵","answer":"D","explanation":"乙烯屬於烯類，碳碳之間有雙鍵。","image":""},{"id":"BT-084","isl":"J","lv":3,"stem":"下列哪一種物質屬於有機化合物？","A":"碳酸鈣","B":"二氧化碳","C":"氯化鈉","D":"葡萄糖（C₆H₁₂O₆）","answer":"D","explanation":"有機化合物以碳為骨架，葡萄糖含碳、氫、氧。","image":""},{"id":"BT-085","isl":"G","lv":3,"stem":"生物學中，最大的分類單位是什麼？","A":"門","B":"界","C":"種","D":"綱","answer":"B","explanation":"分類階層由大到小為界、門、綱、目、科、屬、種。","image":""},{"id":"BT-086","isl":"G","lv":3,"stem":"下列哪一項是生物分類中最基本的單位？","A":"種","B":"屬","C":"界","D":"科","answer":"A","explanation":"種是最基本的分類單位，同種生物可以互相交配產生可育後代。","image":""},{"id":"BT-087","isl":"G","lv":3,"stem":"生物的學名通常由哪兩部分組成？","A":"中文名與俗名","B":"屬名與種名","C":"界名與門名","D":"科名與目名","answer":"B","explanation":"雙名法的學名由屬名與種名組成，例如人的學名為 Homo sapiens。","image":""},{"id":"BT-088","isl":"G","lv":3,"stem":"人的學名為 Homo sapiens，其中 Homo 是什麼？","A":"屬名","B":"界名","C":"種名","D":"科名","answer":"A","explanation":"學名第一個字為屬名，第二個字為種名。","image":""},{"id":"BT-089","isl":"G","lv":3,"stem":"學名書寫時，屬名的首字母應如何書寫？","A":"全部大寫","B":"大寫","C":"全部小寫加底線","D":"小寫","answer":"B","explanation":"屬名首字母大寫，種名全部小寫。","image":""},{"id":"BT-090","isl":"G","lv":3,"stem":"下列哪一組生物的親緣關係最近？","A":"不同界的兩種生物","B":"同一界但不同門的兩種生物","C":"同一門但不同綱的兩種生物","D":"同一屬的兩種生物","answer":"D","explanation":"分類階層越小，共同祖先越近，同屬的親緣關係通常最近。","image":""},{"id":"BT-091","isl":"G","lv":3,"stem":"分類時，依據什麼特徵來區分生物，比較能反映親緣關係？","A":"生物的生活地區","B":"生物的顏色","C":"生物的體型大小","D":"共同祖先的演化特徵","answer":"D","explanation":"現代分類以演化關係為主，參考形態、基因等特徵。","image":""},{"id":"BT-092","isl":"J","lv":3,"stem":"化學反應前後，下列何者保持不變？","A":"物質的體積","B":"物質的種類","C":"原子的種類與總數","D":"分子的總數","answer":"C","explanation":"依質量守恆與原子不滅，反應前後原子的種類與數目不變。","image":""},{"id":"BT-093","isl":"J","lv":3,"stem":"平衡化學方程式 H₂ + O₂ → H₂O 時，H₂O 的係數應為多少？","A":"3","B":"4","C":"2","D":"1","answer":"C","explanation":"平衡後為 2H₂ + O₂ → 2H₂O。","image":""},{"id":"BT-094","isl":"J","lv":3,"stem":"碳與氧氣完全燃燒生成二氧化碳，平衡方程式中碳與二氧化碳的係數比為何？","A":"1：1","B":"2：1","C":"1：2","D":"2：3","answer":"A","explanation":"C + O₂ → CO₂，碳與二氧化碳係數皆為 1。","image":""},{"id":"BT-095","isl":"J","lv":3,"stem":"1 莫耳的任何物質，所含的粒子數約為多少？","A":"1 個","B":"6.02 × 10²³ 個","C":"6.02 × 10¹⁹ 個","D":"6.02 × 10⁶ 個","answer":"B","explanation":"阿伏加厥數約為 6.02 × 10²³，為 1 莫耳的粒子數。","image":""},{"id":"BT-096","isl":"J","lv":3,"stem":"水分子 H₂O 的分子量約為多少？（H = 1，O = 16）","A":"16","B":"20","C":"18","D":"17","answer":"C","explanation":"分子量為 2 × 1 + 16 = 18。","image":""},{"id":"BT-097","isl":"J","lv":3,"stem":"某反應 2Mg + O₂ → 2MgO 中，若反應了 2 莫耳的鎂，需要多少莫耳的氧氣？","A":"0.5 莫耳","B":"4 莫耳","C":"2 莫耳","D":"1 莫耳","answer":"D","explanation":"由方程式係數比，Mg：O₂ = 2：1，故需要 1 莫耳氧氣。","image":""},{"id":"BT-098","isl":"J","lv":3,"stem":"在化學反應中，若只改變反應物的量而不改變方程式係數，會發生什麼？","A":"原子會消失","B":"方程式的係數比不會改變，但產物量隨反應物的量而變","C":"係數會隨之改變","D":"化學方程式會自動改變","answer":"B","explanation":"係數代表莫耳比，與實際用量無關，用量變化會使產物量按比例變化。","image":""},{"id":"BT-099","isl":"E","lv":3,"stem":"牛頓第一運動定律又稱為什麼？","A":"慣性定律","B":"加速度定律","C":"作用力與反作用力定律","D":"萬有引力定律","answer":"A","explanation":"第一定律說明物體保持靜止或等速直線運動的性質，即慣性。","image":""},{"id":"BT-100","isl":"E","lv":3,"stem":"一物體受到合力為 10 N，質量為 2 kg，其加速度為多少？","A":"5 m/s²","B":"0.2 m/s²","C":"20 m/s²","D":"12 m/s²","answer":"A","explanation":"由 F = ma，a = 10 ÷ 2 = 5 m/s²。","image":""},{"id":"BT-101","isl":"E","lv":3,"stem":"作用力與反作用力的關係，下列何者正確？","A":"大小相等，方向相反，作用在不同物體上","B":"大小相等，方向相同，作用在同一物體上","C":"大小不等，方向相反，作用在同一物體上","D":"大小不等，方向相同，作用在不同物體上","answer":"A","explanation":"作用力與反作用力成對出現，分別作用在兩個物體上。","image":""},{"id":"BT-102","isl":"E","lv":3,"stem":"兩個力同方向作用在同一物體上，分別為 3 N 與 4 N，其合力為多少？","A":"5 N","B":"12 N","C":"1 N","D":"7 N，方向與兩力相同","answer":"D","explanation":"同方向的力直接相加，合力為 7 N。","image":""},{"id":"BT-103","isl":"E","lv":3,"stem":"兩個力反方向作用在同一物體上，分別為 6 N 與 2 N，其合力為多少？","A":"6 N","B":"4 N，方向與較大力相同","C":"8 N","D":"2 N，方向與較小力相同","answer":"B","explanation":"反方向的力相減，合力 = 6 − 2 = 4 N，方向與較大的力相同。","image":""},{"id":"BT-104","isl":"E","lv":3,"stem":"一個靜止的物體，若要使它開始運動，必須作用什麼？","A":"大小相等的作用力與反作用力","B":"不為零的合力","C":"零合力","D":"慣性","answer":"B","explanation":"由牛頓第一定律，只有合力不為零時，物體的運動狀態才會改變。","image":""},{"id":"BT-105","isl":"E","lv":3,"stem":"物體的質量越大，其慣性會如何？","A":"越小","B":"越大","C":"不變","D":"與質量無關","answer":"B","explanation":"慣性的大小只與質量有關，質量越大，慣性越大。","image":""},{"id":"BT-106","isl":"H","lv":3,"stem":"在未受擾動的沉積岩層中，哪一層的地層年代最老？","A":"最上層","B":"最底層","C":"中間層","D":"隨機分布","answer":"B","explanation":"依地層疊置原理，越底層的地層越老。","image":""},{"id":"BT-107","isl":"H","lv":3,"stem":"判斷地層相對年代的重要依據之一是什麼？","A":"地層的寬度","B":"地層中所含的標準化石","C":"地層的顏色","D":"地層的硬度","answer":"B","explanation":"標準化石分布的時間短、範圍廣，可用來判斷地層年代。","image":""},{"id":"BT-108","isl":"H","lv":3,"stem":"若某地層被斷層切斷，該斷層形成的時間應如何判斷？","A":"無法判斷","B":"比被切斷的地層年輕","C":"與被切斷的地層同時","D":"比被切斷的地層老","answer":"B","explanation":"斷層切割地層，因此斷層的形成晚於被切斷的地層。","image":""},{"id":"BT-109","isl":"H","lv":3,"stem":"下列哪一種化石最適合用來判斷地層的相對年代？","A":"分布廣、存在時間短的標準化石","B":"分布狹窄、存在時間長的化石","C":"只存在於海洋的軟體動物","D":"不完整的植物葉片","answer":"A","explanation":"標準化石的特徵是時間短、範圍廣、易辨識。","image":""},{"id":"BT-110","isl":"H","lv":3,"stem":"沉積岩中的化石通常是怎麼形成的？","A":"生物直接在岩石內生長","B":"岩漿冷卻後形成","C":"風吹造成的岩石紋路","D":"生物遺骸被沉積物掩埋後，經過長時間的變化而保存","answer":"D","explanation":"沉積物掩埋生物遺骸，經礦化等作用保存下來，形成化石。","image":""},{"id":"BT-111","isl":"H","lv":3,"stem":"地層中若出現某一生物化石，而上下層中都沒有它，表示什麼？","A":"該生物在該時期已經存在","B":"該地層沒有沉積作用","C":"該地層一定比上下層老","D":"該地層一定比上下層年輕","answer":"A","explanation":"化石只代表生物存在過的時間，上下層沒有，不代表其他層的年代。","image":""},{"id":"BT-112","isl":"H","lv":3,"stem":"地層之間若有明顯的缺口，表示什麼？","A":"該地層沒有任何化石","B":"中間可能發生過侵蝕或沒有沉積，地層有缺失","C":"地層都是連續沉積的","D":"該地層年代最新","answer":"B","explanation":"不整合面代表地層缺失的時間段，可能因侵蝕造成。","image":""},{"id":"BT-113","isl":"I","lv":3,"stem":"地震的「規模」與「震度」，下列何者描述地震本身釋放能量的大小？","A":"震度","B":"震央","C":"規模","D":"震源深度","answer":"C","explanation":"規模表示地震釋放的能量，同一次地震只有一個規模值。","image":""},{"id":"BT-114","isl":"I","lv":3,"stem":"震度是描述什麼的物理量？","A":"震央的位置","B":"某地地表震動的強弱程度","C":"地震釋放的總能量","D":"震源的深度","answer":"B","explanation":"震度表示各地受到的震動強弱，同一次地震各地震度可能不同。","image":""},{"id":"BT-115","isl":"I","lv":3,"stem":"同一次地震，下列何者的數值只有一個？","A":"各地的感受程度","B":"地表的破壞程度","C":"規模","D":"震度","answer":"C","explanation":"規模是地震本身的量度，每次地震只有一個規模。","image":""},{"id":"BT-116","isl":"I","lv":3,"stem":"地震的震源是指什麼？","A":"地面正上方的位置","B":"地震波到達的第一個城市","C":"斷層的地表位置","D":"地下岩層開始破裂的位置","answer":"D","explanation":"震源是地下發生破裂、釋放能量的位置。","image":""},{"id":"BT-117","isl":"I","lv":3,"stem":"震央是指什麼？","A":"震源正上方的地表位置","B":"地震波最強的地方","C":"斷層的起點","D":"震源所在的地底深處","answer":"A","explanation":"震央是震源在地表的垂直投影點。","image":""},{"id":"BT-118","isl":"I","lv":3,"stem":"哪一種斷層的上盤相對下降，下盤相對上升？","A":"平移斷層","B":"橫移斷層","C":"逆斷層","D":"正斷層","answer":"D","explanation":"正斷層是受張力作用形成，上盤沿斷面下降。","image":""},{"id":"BT-119","isl":"I","lv":3,"stem":"哪一種斷層形成的主要原因是受到水平擠壓作用？","A":"正斷層與平移斷層都是","B":"逆斷層","C":"平移斷層","D":"正斷層","answer":"B","explanation":"逆斷層在擠壓作用下，上盤沿斷面向上逆衝。","image":""},{"id":"BT-120","isl":"I","lv":3,"stem":"地球自轉造成的現象是什麼？","A":"晝夜交替","B":"月相變化","C":"日食","D":"四季變化","answer":"A","explanation":"地球繞自身軸自轉一圈約一天，造成晝夜交替。","image":""},{"id":"BT-121","isl":"I","lv":3,"stem":"造成四季變化的主要原因是什麼？","A":"地球公轉與地軸傾斜","B":"月球的引力變化","C":"地球與太陽的距離改變","D":"地球自轉速度改變","answer":"A","explanation":"地軸傾斜使太陽直射點南北移動，造成季節變化。","image":""},{"id":"BT-122","isl":"I","lv":3,"stem":"夏至時，北半球的太陽直射點位於什麼位置？","A":"南回歸線","B":"北回歸線","C":"赤道","D":"北極圈","answer":"B","explanation":"夏至約在六月，太陽直射北回歸線。","image":""},{"id":"BT-123","isl":"I","lv":3,"stem":"臺灣在夏季，正午時竿影的方向大致在什麼方向？","A":"南方","B":"東方","C":"西方","D":"北方","answer":"D","explanation":"北半球夏季太陽在南方天空偏高，影子落在北方。","image":""},{"id":"BT-124","isl":"I","lv":3,"stem":"春分與秋分時，太陽直射點位於哪裡？","A":"北極","B":"南回歸線","C":"北回歸線","D":"赤道","answer":"D","explanation":"春分與秋分時，太陽直射赤道，全球晝夜等長。","image":""},{"id":"BT-125","isl":"I","lv":3,"stem":"冬至時，北半球的正午太陽高度角與夏至相比會如何？","A":"較小","B":"無法判斷","C":"相同","D":"較大","answer":"A","explanation":"冬至太陽直射南回歸線，北半球太陽高度角較小。","image":""},{"id":"BT-126","isl":"J","lv":3,"stem":"pH 值小於 7 的水溶液，屬於哪一類？","A":"兩性","B":"酸性","C":"鹼性","D":"中性","answer":"B","explanation":"pH 小於 7 為酸性，等於 7 為中性，大於 7 為鹼性。","image":""},{"id":"BT-127","isl":"J","lv":3,"stem":"酸與鹼完全中和時，溶液通常呈現什麼性質？","A":"強鹼性","B":"接近中性","C":"有大量氣泡產生","D":"強酸性","answer":"B","explanation":"酸與鹼中和，生成鹽與水，若恰好完全反應，溶液接近中性。","image":""},{"id":"BT-128","isl":"J","lv":3,"stem":"紅色石蕊試紙遇到哪一類溶液會變藍？","A":"鹼性溶液","B":"所有溶液","C":"中性溶液","D":"酸性溶液","answer":"A","explanation":"紅色石蕊遇鹼性溶液變為藍色。","image":""},{"id":"BT-129","isl":"J","lv":3,"stem":"鹽酸與氫氧化鈉完全中和後，生成的鹽是什麼？","A":"碳酸鈉","B":"氯化鈉","C":"硝酸鈉","D":"硫酸鈉","answer":"B","explanation":"HCl + NaOH → NaCl + H₂O，生成氯化鈉。","image":""},{"id":"BT-130","isl":"J","lv":3,"stem":"胃酸的主要成分是鹽酸，若胃酸過多，常用哪一類物質來中和？","A":"弱鹼性的制酸劑，例如氫氧化鋁","B":"高濃度的食鹽水","C":"強酸性的醋","D":"強酸性的檸檬汁","answer":"A","explanation":"制酸劑為弱鹼，可與胃酸中和，減少胃酸過多的不適。","image":""},{"id":"BT-131","isl":"J","lv":3,"stem":"下列哪一種物質的水溶液最可能呈鹼性？","A":"醋酸溶液","B":"檸檬汁","C":"鹽酸","D":"小蘇打（碳酸氫鈉）溶液","answer":"D","explanation":"碳酸氫鈉水溶液呈弱鹼性。","image":""},{"id":"BT-132","isl":"J","lv":3,"stem":"酸鹼指示劑的主要作用是什麼？","A":"增加溶液的導電性","B":"改變溶液的酸鹼性","C":"依溶液酸鹼性改變顏色，幫助判斷酸鹼性","D":"加速酸鹼中和反應","answer":"C","explanation":"指示劑在不同 pH 下呈現不同顏色，可作為酸鹼判斷依據。","image":""},{"id":"BT-133","isl":"E","lv":3,"stem":"使用量筒讀取液體體積時，視線應該與什麼位置保持水平？","A":"液面的凹液面最低處","B":"量筒的底部","C":"液面的最高處","D":"量筒的頂端","answer":"A","explanation":"讀數時視線應與凹液面最低處齊平。","image":""},{"id":"BT-134","isl":"E","lv":3,"stem":"使用天平秤量藥品前，應先做什麼？","A":"調整天平歸零","B":"把藥品直接放在托盤上","C":"先加熱天平","D":"以水沖洗天平","answer":"A","explanation":"歸零可以避免零點誤差，使測量結果正確。","image":""},{"id":"BT-135","isl":"E","lv":3,"stem":"使用直尺測量物體長度時，下列哪一項做法最正確？","A":"斜視刻度讀數","B":"隨意選擇刻度線開始讀數","C":"視線與刻度垂直，從零刻度開始測量","D":"只量物體的一端","answer":"C","explanation":"正確測量需從零刻度對齊，並以垂直視線讀取。","image":""},{"id":"BT-136","isl":"E","lv":3,"stem":"酒精燈加熱試管中的液體時，試管口應朝向哪裡？","A":"朝向同學","B":"朝向桌面","C":"朝向自己","D":"朝向無人處","answer":"D","explanation":"加熱時液體可能噴出，試管口應朝向無人處，避免傷害。","image":""},{"id":"BT-137","isl":"E","lv":3,"stem":"測量溫度時，溫度計的感溫泡應該如何放置？","A":"靠在容器壁上","B":"直接接觸火焰","C":"完全浸入待測液體中，且不碰觸容器底部","D":"只露出一小部分","answer":"C","explanation":"感溫泡需完全浸入，並避免碰觸容器底部，以免讀數不準。","image":""},{"id":"BT-138","isl":"E","lv":3,"stem":"用滴管吸取少量液體時，應先做什麼？","A":"先加入藥品再擠壓","B":"先把滴管加熱","C":"先擠壓橡皮頭排出空氣","D":"直接插入液體後放鬆","answer":"C","explanation":"先排空氣，放鬆時才能吸入適量液體。","image":""},{"id":"BT-139","isl":"E","lv":3,"stem":"為減少測量誤差，下列哪一種做法最適當？","A":"只取最大的一次數值","B":"只測量一次","C":"隨意改變測量條件","D":"多次測量後取平均值","answer":"D","explanation":"多次測量取平均可以減少偶然誤差。","image":""},{"id":"BT-140","isl":"A","lv":3,"stem":"原子中，決定元素種類的是什麼？","A":"質子數","B":"電子數","C":"中子數","D":"質量數","answer":"A","explanation":"同一元素的原子質子數相同，質子數不同則是不同元素。","image":""},{"id":"BT-141","isl":"A","lv":3,"stem":"中性原子中，質子數與電子數的關係是什麼？","A":"電子數多於質子數","B":"兩者相等","C":"兩者沒有關係","D":"質子數多於電子數","answer":"B","explanation":"中性原子的正電荷與負電荷數目相同，所以整體不帶電。","image":""},{"id":"BT-142","isl":"A","lv":3,"stem":"鈉原子（質子數 11）失去一個電子形成鈉離子，鈉離子帶何種電荷？","A":"正電","B":"負電","C":"帶 2 個正電","D":"不帶電","answer":"A","explanation":"失去電子後，質子數多於電子數，因此帶正電。","image":""},{"id":"BT-143","isl":"A","lv":3,"stem":"氯原子（質子數 17）得到一個電子形成氯離子，其電子數為多少？","A":"17","B":"19","C":"18","D":"16","answer":"C","explanation":"原子得到一個電子，電子數由 17 變為 18。","image":""},{"id":"BT-144","isl":"A","lv":3,"stem":"原子核是由哪兩種粒子組成？","A":"電子與質子","B":"質子與中子","C":"電子與中子","D":"中子與原子","answer":"B","explanation":"原子核由質子與中子組成，電子在核外運動。","image":""},{"id":"BT-145","isl":"A","lv":3,"stem":"同位素的特徵是什麼？","A":"電子數不同，質子數相同","B":"化學性質完全不同","C":"質子數不同，中子數相同","D":"質子數相同，中子數不同","answer":"D","explanation":"同位素屬於同一種元素，質子數相同，因此化學性質相近。","image":""},{"id":"BT-146","isl":"A","lv":3,"stem":"下列哪一個粒子帶負電，且質量最小？","A":"電子","B":"原子核","C":"質子","D":"中子","answer":"A","explanation":"電子帶負電，質量遠小於質子與中子。","image":""},{"id":"BT-147","isl":"A","lv":3,"stem":"物質由固態變為液態的過程稱為什麼？","A":"熔化","B":"汽化","C":"凝固","D":"凝結","answer":"A","explanation":"固體吸熱後變成液體的過程稱為熔化。","image":""},{"id":"BT-148","isl":"A","lv":3,"stem":"水在標準大氣壓下的沸點約為多少？","A":"50 ℃","B":"100 ℃","C":"200 ℃","D":"0 ℃","answer":"B","explanation":"水在 1 大氣壓下的沸點約為 100 ℃。","image":""},{"id":"BT-149","isl":"A","lv":3,"stem":"純物質在熔化過程中，溫度通常會怎樣變化？","A":"保持不變","B":"先升後降","C":"持續下降","D":"持續上升","answer":"A","explanation":"純物質熔化時，吸收的熱用於破壞固體結構，溫度維持在熔點。","image":""},{"id":"BT-150","isl":"A","lv":3,"stem":"熔點與沸點可以用來做什麼？","A":"計算物體的體積","B":"鑑別物質","C":"決定物質的顏色","D":"測量物體的質量","answer":"B","explanation":"不同物質的熔點與沸點通常不同，可作為鑑別依據。","image":""},{"id":"BT-151","isl":"A","lv":3,"stem":"液體只在表面進行、在任何溫度都可能發生的汽化現象，稱為什麼？","A":"昇華","B":"蒸發","C":"沸騰","D":"凝結","answer":"B","explanation":"蒸發只在液體表面進行，沸騰則發生在整個液體內部。","image":""},{"id":"BT-152","isl":"A","lv":3,"stem":"下列哪一個過程需要吸收熱量？","A":"水蒸氣液化","B":"冰塊融化","C":"水凝固成冰","D":"水蒸氣凝結成水","answer":"B","explanation":"熔化、汽化、昇華都需要吸熱，凝結、凝固、液化則放熱。","image":""},{"id":"BT-153","isl":"A","lv":3,"stem":"固態直接變成氣態的現象稱為什麼？","A":"沸騰","B":"蒸發","C":"凝華","D":"昇華","answer":"D","explanation":"乾冰與樟腦都會發生昇華現象。","image":""},{"id":"BT-154","isl":"I","lv":3,"stem":"地球內部由地殼、地函與地核組成，其中體積最大的是哪一層？","A":"地函","B":"外核","C":"地殼","D":"內核","answer":"A","explanation":"地函厚度約 2900 公里，是地球內部體積最大的一層。","image":""},{"id":"BT-155","isl":"I","lv":3,"stem":"大陸板塊與海洋板塊相撞時，密度較大的板塊會怎樣？","A":"隱沒到大陸板塊下方","B":"漂浮在大陸板塊上","C":"被破壞而消失","D":"不發生任何變化","answer":"A","explanation":"海洋板塊密度較大，會隱沒到大陸板塊之下。","image":""},{"id":"BT-156","isl":"I","lv":3,"stem":"板塊邊界中，兩板塊相互遠離的是哪一種類型？","A":"聚合型邊界","B":"隱沒型邊界","C":"張裂型（離散型）邊界","D":"轉型（錯動）邊界","answer":"C","explanation":"張裂型邊界如大洋中脊，板塊向兩側分開。","image":""},{"id":"BT-157","isl":"I","lv":3,"stem":"臺灣位於哪兩個板塊的交界附近？","A":"太平洋板塊與印度板塊","B":"歐亞板塊與菲律賓海板塊","C":"歐亞板塊與美洲板塊","D":"非洲板塊與南極板塊","answer":"B","explanation":"臺灣位於歐亞板塊與菲律賓海板塊的交界，因此地震活動頻繁。","image":""},{"id":"BT-158","isl":"I","lv":3,"stem":"大洋中脊處，岩漿上升冷卻後形成的是什麼？","A":"大陸地殼","B":"變質岩","C":"沉積岩層","D":"新的海洋地殼","answer":"D","explanation":"大洋中脊是板塊張裂的地方，岩漿上升形成新的海洋地殼。","image":""},{"id":"BT-159","isl":"I","lv":3,"stem":"地震多集中在板塊邊界附近，主要原因是什麼？","A":"板塊內部沒有能量","B":"大氣壓力變化造成","C":"板塊之間相互運動，累積應力並突然釋放","D":"地球自轉速度改變","answer":"C","explanation":"板塊邊界的運動使岩層受力，應力突然釋放就形成地震。","image":""},{"id":"BT-160","isl":"J","lv":3,"stem":"電解水時，為了增加溶液的導電性，常加入少量什麼物質？","A":"酒精","B":"食用油","C":"稀硫酸或氫氧化鈉","D":"蔗糖","answer":"C","explanation":"純水導電性差，加入少量電解質可以增加導電性。","image":""},{"id":"BT-161","isl":"J","lv":3,"stem":"電解氯化銅水溶液時，在陰極會析出什麼物質？","A":"氧氣","B":"銅","C":"氫氣","D":"氯氣","answer":"B","explanation":"銅離子在陰極得到電子，還原為銅單質析出。","image":""},{"id":"BT-162","isl":"J","lv":3,"stem":"電解氯化鈉水溶液時，在陽極產生的氣體是什麼？","A":"氯氣","B":"二氧化碳","C":"氫氣","D":"氧氣","answer":"A","explanation":"氯離子在陽極失去電子形成氯氣。","image":""},{"id":"BT-163","isl":"J","lv":3,"stem":"電鍍時，要鍍上金屬的物品應接在哪一極？","A":"陰極","B":"兩極都要接","C":"中性端","D":"陽極","answer":"A","explanation":"欲鍍物接在陰極，鍍層金屬離子在陰極得到電子而附著。","image":""},{"id":"BT-164","isl":"J","lv":3,"stem":"電鍍時，作為鍍層來源的金屬通常接在哪一極？","A":"陽極","B":"絕緣端","C":"陰極","D":"電解質","answer":"A","explanation":"鍍層金屬放在陽極，會逐漸溶解成離子，再於陰極沉積。","image":""},{"id":"BT-165","isl":"J","lv":3,"stem":"電解質溶液能夠導電，主要原因是什麼？","A":"溶液中有可以自由移動的離子","B":"溶液中有自由移動的電子","C":"溶液本身就是金屬","D":"溶液本身帶有電荷","answer":"A","explanation":"電解質溶解後解離出離子，離子移動即形成電流。","image":""},{"id":"BT-166","isl":"J","lv":3,"stem":"電解時，溶液中的陽離子會移向哪一極？","A":"兩極的中間","B":"容器的側壁","C":"陰極","D":"陽極","answer":"C","explanation":"異性相吸，陽離子向帶負電的陰極移動。","image":""},{"id":"BT-167","isl":"N","lv":3,"stem":"造成溫室效應的主要氣體之一是什麼？","A":"氦氣","B":"二氧化碳","C":"氮氣","D":"氧氣","answer":"B","explanation":"二氧化碳等溫室氣體會吸收並再放出地表輻射，使地表升溫。","image":""},{"id":"BT-168","isl":"N","lv":3,"stem":"下列哪一種能源屬於再生能源？","A":"天然氣","B":"煤","C":"石油","D":"太陽能","answer":"D","explanation":"太陽能可以不斷補充，屬於再生能源；化石燃料則不能短期再生。","image":""},{"id":"BT-169","isl":"N","lv":3,"stem":"水體優養化最主要的原因通常是什麼？","A":"水溫過低","B":"水的鹽分太少","C":"含氮、磷的污染物過多","D":"水中含氧量過多","answer":"C","explanation":"氮、磷營養鹽過多會使藻類大量繁殖，消耗水中氧氣。","image":""},{"id":"BT-170","isl":"N","lv":3,"stem":"生物多樣性降低，最可能造成什麼結果？","A":"生態系統的能量產生增加","B":"生態系統的穩定性下降","C":"物種數量增加","D":"生態系統變得更穩定","answer":"B","explanation":"物種越多，食物網越複雜，生態系統越能抵抗外來干擾。","image":""},{"id":"BT-171","isl":"N","lv":3,"stem":"酸雨形成的主要氣體是什麼？","A":"氫氣與氧氣","B":"二氧化硫與氮氧化物","C":"氮氣與氧氣","D":"氦氣與氬氣","answer":"B","explanation":"硫與氮的氧化物溶於雲雨水中，使降水變成酸性。","image":""},{"id":"BT-172","isl":"N","lv":3,"stem":"下列哪一種物質是造成臭氧層破壞的主要原因？","A":"氟氯碳化物（CFCs）","B":"氧氣","C":"二氧化碳","D":"水蒸氣","answer":"A","explanation":"氟氯碳化物在高空分解出氯原子，會催化破壞臭氧。","image":""},{"id":"BT-173","isl":"N","lv":3,"stem":"減少使用化石燃料，最直接的好處是什麼？","A":"增加酸雨的形成","B":"增加臭氧層的破壞","C":"增加地表的溫度","D":"減少溫室氣體與空氣汙染物的排放","answer":"D","explanation":"化石燃料燃燒會排放二氧化碳與污染物，減少使用可以降低排放。","image":""},{"id":"BT-174","isl":"I","lv":3,"stem":"冬季東北季風的風向大致來自哪個方向？","A":"北方或東北方","B":"南方","C":"東南方","D":"西方","answer":"A","explanation":"東北季風來自大陸高壓，風向為北或東北。","image":""},{"id":"BT-175","isl":"I","lv":3,"stem":"夏季西南季風帶來的天氣特徵，通常是什麼？","A":"帶來寒冷乾燥的北風","B":"天氣乾燥晴朗","C":"不帶任何水氣","D":"風從海洋帶來水氣，常有較多降雨","answer":"D","explanation":"西南季風來自海洋，含有豐富的水氣，因此雨量較多。","image":""},{"id":"BT-176","isl":"I","lv":3,"stem":"冷鋒過境時，通常會出現什麼天氣變化？","A":"冷空氣推進，暖空氣被迫抬升，常有短時間強降雨與降溫","B":"氣團停滯不動，天氣永遠穩定","C":"暖空氣推進，冷空氣被迫下沉，天氣晴朗","D":"兩種氣團完全不接觸，天氣不變","answer":"A","explanation":"冷鋒中冷空氣較重，會楔入暖空氣下方，使暖空氣抬升而形成雲雨。","image":""},{"id":"BT-177","isl":"I","lv":3,"stem":"氣團指的是什麼？","A":"地面上的氣壓分布","B":"高空中的雲層","C":"某一個地點的氣溫","D":"溫度與濕度水平分布大致均勻的大範圍空氣","answer":"D","explanation":"氣團是大範圍、性質相似的空氣團，會影響一地的天氣。","image":""},{"id":"BT-178","isl":"I","lv":3,"stem":"臺灣初夏常見、造成連續多日降雨的鋒面是什麼？","A":"颱風眼","B":"梅雨鋒（滯留鋒）","C":"高壓脊","D":"反氣旋","answer":"B","explanation":"梅雨鋒是冷暖氣團勢均力敵時形成的滯留鋒，常帶來長時間降雨。","image":""},{"id":"BT-179","isl":"I","lv":3,"stem":"海風與陸風形成的主要原因是什麼？","A":"海水的流動帶動空氣","B":"月球引力造成空氣移動","C":"地球自轉造成空氣偏轉","D":"陸地與海洋受熱速度不同，造成氣壓差","answer":"D","explanation":"白天陸地升溫較快，海陸之間的氣壓差使風由海向陸吹。","image":""},{"id":"BT-180","isl":"Q","lv":3,"stem":"奧斯特實驗說明了什麼現象？","A":"電流周圍會產生磁場","B":"磁場只存在於磁鐵內部","C":"磁鐵會吸引電子","D":"電流通過時不會產生任何效應","answer":"A","explanation":"奧斯特發現通電導線能使旁邊的指北針偏轉，證明電流會產生磁場。","image":""},{"id":"BT-181","isl":"Q","lv":3,"stem":"判斷通電直導線周圍磁場方向時，常用哪一種定則？","A":"弗萊明左手定則","B":"歐姆定律","C":"牛頓第二運動定律","D":"安培右手定則","answer":"D","explanation":"安培右手定則：大拇指指電流方向，四指繞行方向即磁場方向。","image":""},{"id":"BT-182","isl":"Q","lv":3,"stem":"產生感應電流的條件是什麼？","A":"導體靜止放在磁場中","B":"磁場強度完全不變","C":"導體與磁場之間有相對運動，使磁通量改變","D":"導體通入直流電","answer":"C","explanation":"磁通量變化才會產生感應電動勢，形成感應電流。","image":""},{"id":"BT-183","isl":"Q","lv":3,"stem":"發電機的工作原理是什麼？","A":"電磁感應","B":"靜電感應","C":"熱電效應","D":"電流的磁效應","answer":"A","explanation":"發電機利用線圈在磁場中旋轉，產生感應電流。","image":""},{"id":"BT-184","isl":"Q","lv":3,"stem":"電動機的工作原理是什麼？","A":"磁場對通電導體產生作用力","B":"靜電感應","C":"電磁感應","D":"光電效應","answer":"A","explanation":"電動機中通電線圈在磁場中受力而轉動。","image":""},{"id":"BT-185","isl":"Q","lv":3,"stem":"想要增加感應電流的大小，下列哪一種做法最有效？","A":"把磁鐵的磁性減弱","B":"減少線圈匝數","C":"讓線圈保持靜止","D":"增加線圈匝數或加快磁場與線圈的相對運動速度","answer":"D","explanation":"匝數增加、磁場變化加快，感應電動勢會增加，電流也隨之增加。","image":""},{"id":"BT-186","isl":"Q","lv":3,"stem":"判斷螺線管內部磁場方向時，常用什麼方法？","A":"螺線管內部沒有磁場","B":"右手四指順著電流方向繞，大拇指指向 N 極","C":"左手四指順著電流方向繞，大拇指指向 N 極","D":"右手大拇指指向電流方向，四指指向 N 極","answer":"B","explanation":"螺線管採用右手螺旋定則，大拇指所指的一端即為 N 極。","image":""},{"id":"BT-187","isl":"B","lv":3,"stem":"酵素的化學本質主要是什麼？","A":"醣類","B":"脂質","C":"蛋白質","D":"礦物質","answer":"C","explanation":"大多數酵素是蛋白質，少數 RNA 也具有催化作用。","image":""},{"id":"BT-188","isl":"B","lv":3,"stem":"酵素的專一性是指什麼？","A":"酵素只存在於一種生物中","B":"一種酵素只能催化特定的受質或一類受質","C":"酵素可以催化任何化學反應","D":"酵素只能在一種溫度下存在","answer":"B","explanation":"酵素與受質的形狀需互相配合，因此具有專一性。","image":""},{"id":"BT-189","isl":"B","lv":3,"stem":"當溫度過高時，酵素的活性會怎樣？","A":"持續增加","B":"變得更具專一性","C":"下降，因為酵素結構改變而失去作用","D":"完全不受影響","answer":"C","explanation":"高溫會使酵素變性，活性喪失。","image":""},{"id":"BT-190","isl":"B","lv":3,"stem":"胃蛋白酶主要分解哪一種養分？","A":"纖維素","B":"脂肪","C":"澱粉","D":"蛋白質","answer":"D","explanation":"胃蛋白酶在胃中將蛋白質分解為較小的胜肽。","image":""},{"id":"BT-191","isl":"B","lv":3,"stem":"唾液中的澱粉酶可以分解哪一種物質？","A":"脂肪","B":"維生素","C":"澱粉","D":"蛋白質","answer":"C","explanation":"澱粉酶在口腔中開始將澱粉分解為麥芽糖。","image":""},{"id":"BT-192","isl":"B","lv":3,"stem":"酵素催化反應後，本身的狀態如何？","A":"變成生成物","B":"被完全消耗","C":"數量不斷增加","D":"不被消耗，可重複使用","answer":"D","explanation":"酵素是催化劑，反應前後質量與數量不變。","image":""},{"id":"BT-193","isl":"B","lv":3,"stem":"功的定義是什麼？","A":"質量與加速度的乘積","B":"力與作用時間的乘積","C":"位移除以時間","D":"力與物體在力方向上移動的距離的乘積","answer":"D","explanation":"功 = 力 × 力方向上的位移。","image":""},{"id":"BT-194","isl":"B","lv":3,"stem":"重力位能的大小與什麼有關？","A":"速度與高度","B":"加速度與時間","C":"質量與高度","D":"速度與質量","answer":"C","explanation":"重力位能 = 質量 × 重力加速度 × 高度。","image":""},{"id":"BT-195","isl":"B","lv":3,"stem":"動能的大小與什麼有關？","A":"質量與時間","B":"質量與速率的平方","C":"質量與高度","D":"速率與高度","answer":"B","explanation":"動能 = ½ × 質量 × 速率²。","image":""},{"id":"BT-196","isl":"B","lv":3,"stem":"忽略摩擦力時，自由落下的物體，其力學能會怎樣？","A":"先增加後減少","B":"保持不變","C":"持續減少","D":"持續增加","answer":"B","explanation":"自由落下時重力位能轉為動能，總和不變。","image":""},{"id":"BT-197","isl":"B","lv":3,"stem":"單擺擺到最高點時，其動能為多少？","A":"無法判斷","B":"零","C":"最大","D":"與最低點相同","answer":"B","explanation":"最高點時速度為零，動能為零，此時重力位能最大。","image":""},{"id":"BT-198","isl":"B","lv":3,"stem":"質量 2 kg 的物體放在離地 5 m 的高度，其重力位能約為多少？（g = 10 m/s²）","A":"10 J","B":"100 J","C":"50 J","D":"20 J","answer":"B","explanation":"位能 = 2 × 10 × 5 = 100 J。","image":""},{"id":"BT-199","isl":"B","lv":3,"stem":"功的單位是什麼？","A":"焦耳（J）","B":"瓦特（W）","C":"公尺每秒（m/s）","D":"牛頓（N）","answer":"A","explanation":"功與能量的 SI 單位都是焦耳。","image":""},{"id":"BT-200","isl":"C","lv":3,"stem":"在一定溫度下，100 g 溶劑中最多能溶解的溶質克數，稱為什麼？","A":"飽和度比例","B":"密度","C":"溶解度","D":"濃度","answer":"C","explanation":"溶解度以每 100 g 溶劑能溶解的克數表示。","image":""},{"id":"BT-201","isl":"C","lv":3,"stem":"大多數固體溶質在水中，溫度升高時，溶解度通常會怎樣？","A":"增加","B":"不變","C":"減少","D":"先增加後減少","answer":"A","explanation":"多數固體的溶解度隨溫度升高而增加，例如硝酸鉀。","image":""},{"id":"BT-202","isl":"C","lv":3,"stem":"氣體在水中的溶解度，溫度升高時會怎樣？","A":"先增加後減少","B":"增加","C":"減少","D":"不變","answer":"C","explanation":"溫度升高，氣體分子動能增加而逸出，溶解度降低。","image":""},{"id":"BT-203","isl":"C","lv":3,"stem":"氣體在水中的溶解度，壓力增加時會怎樣？","A":"減少","B":"與壓力無關","C":"不變","D":"增加","answer":"D","explanation":"壓力增加使更多氣體溶入液體，例如汽水的製作原理。","image":""},{"id":"BT-204","isl":"C","lv":3,"stem":"將 25 g 食鹽溶於 100 g 水中，溶液的重量百分濃度約為多少？","A":"25%","B":"80%","C":"20%","D":"4%","answer":"C","explanation":"濃度 = 25 ÷ (25 + 100) × 100% = 20%。","image":""},{"id":"BT-205","isl":"C","lv":3,"stem":"某溶液含溶質 10 g，溶液總質量為 200 g，其重量百分濃度為多少？","A":"20%","B":"5%","C":"2%","D":"10%","answer":"B","explanation":"濃度 = 10 ÷ 200 × 100% = 5%。","image":""},{"id":"BT-206","isl":"D","lv":3,"stem":"反射弧中，負責接收刺激的部位是什麼？","A":"受器","B":"中間神經元","C":"效應器","D":"腦","answer":"A","explanation":"受器接收刺激並將其轉為神經衝動。","image":""},{"id":"BT-207","isl":"D","lv":3,"stem":"膝跳反射的中樞位於哪裡？","A":"脊髓","B":"小腦","C":"延腦","D":"大腦","answer":"A","explanation":"膝跳反射不經過大腦，由脊髓直接完成。","image":""},{"id":"BT-208","isl":"D","lv":3,"stem":"神經元的主要功能是什麼？","A":"分泌荷爾蒙","B":"消化食物","C":"傳導神經衝動","D":"製造血液","answer":"C","explanation":"神經元的功能是接收、傳導並傳遞神經衝動。","image":""},{"id":"BT-209","isl":"D","lv":3,"stem":"控制心跳、呼吸等不受意志直接控制的神經系統是什麼？","A":"大腦皮質","B":"脊髓","C":"體神經系統","D":"自主神經系統","answer":"D","explanation":"自主神經系統調節內臟器官，使其在無意識下正常運作。","image":""},{"id":"BT-210","isl":"D","lv":3,"stem":"縮手反射的傳遞路徑，正確順序是什麼？","A":"受器→運動神經→脊髓→感覺神經→效應器","B":"腦→受器→效應器→脊髓","C":"效應器→脊髓→受器→大腦","D":"受器→感覺神經→脊髓→運動神經→效應器","answer":"D","explanation":"刺激由受器接收，經感覺神經傳入脊髓，再由運動神經傳至效應器。","image":""},{"id":"BT-211","isl":"D","lv":3,"stem":"反射動作的主要特點是什麼？","A":"一定要經過大腦思考","B":"反應速度比較慢","C":"只在清醒時才會發生","D":"不需經過大腦皮質，反應迅速","answer":"D","explanation":"反射由較低層的中樞完成，因此反應快速。","image":""},{"id":"BT-212","isl":"D","lv":3,"stem":"下列哪一組屬於中樞神經系統？","A":"體神經","B":"腦與脊髓","C":"腦神經與脊神經","D":"自主神經","answer":"B","explanation":"中樞神經系統包括腦與脊髓；腦神經與脊神經屬於周邊神經。","image":""},{"id":"BT-213","isl":"E","lv":3,"stem":"浸在流體中的物體，所受浮力的大小等於什麼？","A":"物體本身的重量","B":"物體的體積","C":"排開流體的重量","D":"物體的密度","answer":"C","explanation":"這就是阿基米德原理。","image":""},{"id":"BT-214","isl":"E","lv":3,"stem":"物體在水中下沉，表示什麼？","A":"浮力大於重力","B":"浮力等於重力","C":"物體的密度為零","D":"浮力小於重力","answer":"D","explanation":"物體下沉時，所受合力向下，重力大於浮力。","image":""},{"id":"BT-215","isl":"E","lv":3,"stem":"物體漂浮在水面時，浮力與重力的關係是什麼？","A":"浮力大於重力","B":"浮力小於重力","C":"無法比較","D":"兩者大小相等","answer":"D","explanation":"漂浮時受力平衡，浮力等於重力。","image":""},{"id":"BT-216","isl":"E","lv":3,"stem":"同一物體分別浸入密度不同的兩種液體，在哪一種液體中浮力較大？","A":"兩者相同","B":"與液體密度無關","C":"密度較小的液體","D":"密度較大的液體","answer":"D","explanation":"浮力 = 液體密度 × 重力加速度 × 排開液體體積，液體密度越大，浮力越大。","image":""},{"id":"BT-217","isl":"E","lv":3,"stem":"鐵塊會沉入水中，但鐵船卻能浮在水面，主要原因是什麼？","A":"鐵船的材料不是鐵","B":"鐵船的平均密度小於水，且排開的水量大","C":"鐵船的質量比鐵塊小","D":"水的表面張力托起鐵船","answer":"B","explanation":"鐵船內部有空氣，平均密度小於水，能排開足夠的水而產生足夠浮力。","image":""},{"id":"BT-218","isl":"E","lv":3,"stem":"物體在空氣中秤重為 10 N，浸入水中時示重為 6 N，則它所受的浮力為多少？","A":"6 N","B":"16 N","C":"4 N","D":"10 N","answer":"C","explanation":"浮力 = 空氣中重量 − 水中示重 = 10 − 6 = 4 N。","image":""},{"id":"BT-219","isl":"I","lv":2,"stem":"岩石因溫度變化、水結冰膨脹而破碎，這種作用稱為什麼？","A":"物理風化","B":"沉積作用","C":"搬運作用","D":"化學風化","answer":"A","explanation":"物理風化只改變岩石的大小與形狀，不改變其化學成分。","image":""},{"id":"BT-220","isl":"I","lv":2,"stem":"河流搬運的泥沙，在河口或平原上停積下來，稱為什麼作用？","A":"崩落作用","B":"侵蝕作用","C":"風化作用","D":"沉積作用","answer":"D","explanation":"搬運能力減弱時，泥沙就會停積，形成沉積作用。","image":""},{"id":"BT-221","isl":"I","lv":2,"stem":"下列哪一種地形主要由河流的沉積作用形成？","A":"海蝕崖","B":"冰斗","C":"沖積扇","D":"V 形谷","answer":"C","explanation":"河流流出山谷後，流速減慢，泥沙堆積形成沖積扇。","image":""},{"id":"BT-222","isl":"I","lv":2,"stem":"海岸的海蝕崖主要是由哪一種作用形成？","A":"侵蝕作用","B":"造山作用","C":"沉積作用","D":"火山噴發","answer":"A","explanation":"海浪不斷沖擊岸邊岩石，將岩石磨蝕後形成海蝕崖。","image":""},{"id":"BT-223","isl":"D","lv":2,"stem":"木本植物莖中，負責運輸水分與無機鹽的組織是什麼？","A":"形成層","B":"表皮","C":"韌皮部","D":"木質部","answer":"D","explanation":"木質部由根向上運輸水分與無機鹽。","image":""},{"id":"BT-224","isl":"D","lv":2,"stem":"韌皮部主要運輸的物質是什麼？","A":"有機養分，例如蔗糖","B":"氧氣","C":"二氧化碳","D":"水分與無機鹽","answer":"A","explanation":"韌皮部把葉片製造的養分運送到植物各部位。","image":""},{"id":"BT-225","isl":"D","lv":2,"stem":"木本植物的莖每年能夠變粗，主要靠哪一層細胞分裂？","A":"木質部","B":"表皮","C":"韌皮部","D":"形成層","answer":"D","explanation":"形成層的細胞不斷分裂，向內形成木質部、向外形成韌皮部。","image":""},{"id":"BT-226","isl":"D","lv":2,"stem":"將樹幹環狀剝除一圈樹皮後，上方的樹皮常會腫大，主要原因是什麼？","A":"木質部被切斷，水分無法向上運輸","B":"氧氣無法進入樹幹","C":"樹幹失去支撐而變粗","D":"韌皮部被切斷，養分無法向下運輸","answer":"D","explanation":"韌皮部被剝除後，養分被阻斷在上方累積，使樹皮腫大。","image":""},{"id":"BT-227","isl":"Q","lv":2,"stem":"兩個相同的電阻串聯，總電阻是單一電阻的幾倍？","A":"1/2 倍","B":"2 倍","C":"4 倍","D":"1 倍","answer":"B","explanation":"串聯總電阻為各電阻相加，兩個相同電阻為 2 倍。","image":""},{"id":"BT-228","isl":"Q","lv":2,"stem":"兩個相同的電阻並聯，總電阻是單一電阻的幾倍？","A":"2 倍","B":"1/2 倍","C":"1 倍","D":"4 倍","answer":"B","explanation":"並聯電阻越並越小，兩個相同電阻並聯為一半。","image":""},{"id":"BT-229","isl":"Q","lv":2,"stem":"串聯電路中，通過各個電阻的電流大小如何？","A":"與電阻成正比","B":"不同","C":"與電阻成反比","D":"相同","answer":"D","explanation":"串聯電路只有一條路徑，電流處處相同。","image":""},{"id":"BT-230","isl":"Q","lv":2,"stem":"並聯電路中，各支路兩端的電壓如何？","A":"加總等於電源電壓","B":"依電阻比例分配","C":"逐段降低","D":"相同，都等於電源電壓","answer":"D","explanation":"並聯各支路跨接在相同的兩點之間，電壓相同。","image":""},{"id":"BT-231","isl":"I","lv":2,"stem":"造成潮汐現象的主要原因是什麼？","A":"洋流的流動","B":"月球與太陽對海水的引力","C":"海底地震","D":"海面上的風力","answer":"B","explanation":"月球引力是潮汐的主因，太陽引力也會影響潮汐的大小。","image":""},{"id":"BT-232","isl":"I","lv":2,"stem":"臺灣沿海一天通常會出現幾次高潮？","A":"1 次","B":"2 次","C":"4 次","D":"3 次","answer":"B","explanation":"大部分地區每天約有兩次高潮與兩次低潮。","image":""},{"id":"BT-233","isl":"I","lv":2,"stem":"農曆初一與十五前後，潮汐通常如何變化？","A":"沒有潮汐現象","B":"大潮，潮差較大","C":"小潮，潮差較小","D":"潮差保持不變","answer":"B","explanation":"此時日、地、月大致成一直線，引力疊加，形成大潮。","image":""},{"id":"BT-234","isl":"I","lv":2,"stem":"農曆初八與二十三前後，潮汐通常稱為什麼？","A":"暴潮","B":"大高潮","C":"大潮","D":"小潮","answer":"D","explanation":"此時日、地、月大致成直角，引力互相抵消，潮差較小。","image":""},{"id":"BT-235","isl":"G","lv":2,"stem":"無性生殖的主要特徵是什麼？","A":"必須經過減數分裂","B":"不經過配子結合，後代基因與親代相同","C":"一定會產生種子","D":"需要兩性配子結合，後代基因多樣","answer":"B","explanation":"無性生殖只由一個親代產生後代，因此後代與親代基因相同。","image":""},{"id":"BT-236","isl":"G","lv":2,"stem":"下列哪一種植物繁殖方式屬於無性生殖？","A":"種子萌發","B":"扦插","C":"花粉粒發芽","D":"授粉後結出種子","answer":"B","explanation":"扦插利用莖或葉的一部分發育成新植株，不經過受精。","image":""},{"id":"BT-237","isl":"G","lv":2,"stem":"花的哪一部分會發育成果實？","A":"子房","B":"花藥","C":"柱頭","D":"花瓣","answer":"A","explanation":"受精後，子房發育成果實，胚珠發育成種子。","image":""},{"id":"BT-238","isl":"G","lv":2,"stem":"花粉從花藥傳送到柱頭的過程，稱為什麼？","A":"授粉","B":"發芽","C":"減數分裂","D":"受精","answer":"A","explanation":"授粉完成後，花粉才會在柱頭上發芽，進而完成受精。","image":""},{"id":"BT-239","isl":"D","lv":2,"stem":"使用顯微鏡時，應先用哪一個物鏡對焦？","A":"低倍物鏡","B":"集光器","C":"目鏡","D":"高倍物鏡","answer":"A","explanation":"低倍物鏡視野大、焦距較長，較容易找到標本。","image":""},{"id":"BT-240","isl":"D","lv":2,"stem":"顯微鏡的總倍率如何計算？","A":"物鏡倍率 − 目鏡倍率","B":"目鏡倍率 × 物鏡倍率","C":"目鏡倍率 + 物鏡倍率","D":"目鏡倍率 ÷ 物鏡倍率","answer":"B","explanation":"總倍率是目鏡與物鏡倍率的乘積。","image":""},{"id":"BT-241","isl":"D","lv":2,"stem":"1 公尺等於多少微米（μm）？","A":"1,000,000 μm","B":"1,000 μm","C":"1,000,000,000 μm","D":"100 μm","answer":"A","explanation":"1 m = 10⁶ μm。","image":""},{"id":"BT-242","isl":"D","lv":2,"stem":"顯微鏡中，用來調節進入鏡筒光線多寡的部件是什麼？","A":"粗調節螺旋","B":"光圈","C":"轉換器","D":"細調節螺旋","answer":"B","explanation":"光圈可以調整進光量，使視野亮度適中。","image":""},{"id":"BT-243","isl":"G","lv":2,"stem":"人類體細胞有 46 條染色體，生殖細胞的染色體數應為多少？","A":"11","B":"46","C":"23","D":"92","answer":"C","explanation":"減數分裂使染色體數減半，因此配子只有 23 條。","image":""},{"id":"BT-244","isl":"G","lv":2,"stem":"有絲分裂完成後，會產生什麼樣的細胞？","A":"四個與親代不同的細胞","B":"一個體積較大的細胞","C":"四個染色體數減半的細胞","D":"兩個染色體數與親代相同的子細胞","answer":"D","explanation":"有絲分裂將一個細胞分成兩個，染色體數維持不變。","image":""},{"id":"BT-245","isl":"G","lv":2,"stem":"減數分裂的主要目的是什麼？","A":"產生染色體數減半的配子","B":"使細胞體積增大","C":"增加細胞數量促進生長","D":"修復受損的細胞","answer":"A","explanation":"配子結合後，染色體數恢復為體細胞的數目。","image":""},{"id":"BT-246","isl":"G","lv":2,"stem":"染色體的複製發生在細胞周期的哪一個時期？","A":"前期","B":"中期","C":"間期","D":"末期","answer":"C","explanation":"間期時 DNA 會先複製，為之後的分裂做準備。","image":""},{"id":"BT-247","isl":"E","lv":2,"stem":"力矩的定義是什麼？","A":"質量乘以距離","B":"力乘以力臂","C":"力乘以時間","D":"力除以力臂","answer":"B","explanation":"力矩 = 力 × 支點到力作用線的垂直距離。","image":""},{"id":"BT-248","isl":"E","lv":2,"stem":"槓桿的支點到施力點距離為 2 m，施力 10 N 且與槓桿垂直，力矩為多少？","A":"5 N·m","B":"12 N·m","C":"0.2 N·m","D":"20 N·m","answer":"D","explanation":"力矩 = 10 × 2 = 20 N·m。","image":""},{"id":"BT-249","isl":"E","lv":2,"stem":"使用槓桿或滑輪組省力時，通常要付出什麼代價？","A":"效率可以達到百分之百","B":"完全不需要做功","C":"做功會變大","D":"施力的距離變長（省力不省功）","answer":"D","explanation":"根據功的原理，省力必定要增加移動距離。","image":""},{"id":"BT-250","isl":"E","lv":2,"stem":"下列哪一種工具屬於省力槓桿？","A":"鑷子","B":"掃把","C":"開瓶器","D":"釣竿","answer":"C","explanation":"開瓶器的施力點到支點距離較長，因此省力。","image":""},{"id":"BT-251","isl":"F","lv":2,"stem":"太陽系中，離太陽最近的行星是哪一顆？","A":"金星","B":"火星","C":"地球","D":"水星","answer":"D","explanation":"水星是距離太陽最近的行星。","image":""},{"id":"BT-252","isl":"F","lv":2,"stem":"太陽屬於哪一類天體？","A":"恆星","B":"衛星","C":"彗星","D":"行星","answer":"A","explanation":"太陽能自行發光發熱，是恆星。","image":""},{"id":"BT-253","isl":"F","lv":2,"stem":"下列哪一種天體本身會發光？","A":"衛星","B":"恆星","C":"月球","D":"行星","answer":"B","explanation":"恆星透過核融合發光，行星與衛星反射太陽光。","image":""},{"id":"BT-254","isl":"F","lv":2,"stem":"太陽系中，體積最大的行星是哪一顆？","A":"木星","B":"地球","C":"土星","D":"海王星","answer":"A","explanation":"木星是太陽系最大的行星。","image":""},{"id":"BT-255","isl":"K","lv":2,"stem":"下列哪一項不屬於聲音的三要素？","A":"音量","B":"音色","C":"音調","D":"速度","answer":"D","explanation":"聲音的三要素是音調、音量與音色。","image":""},{"id":"BT-256","isl":"K","lv":2,"stem":"聲音的音調高低，主要與什麼有關？","A":"音色","B":"傳播的介質","C":"頻率","D":"振幅","answer":"C","explanation":"頻率越高，音調越高。","image":""},{"id":"BT-257","isl":"K","lv":2,"stem":"聲音的音量大小，主要與什麼有關？","A":"振幅","B":"音色","C":"波速","D":"頻率","answer":"A","explanation":"振幅越大，聲音越大聲。","image":""},{"id":"BT-258","isl":"K","lv":2,"stem":"一般人耳能聽見的聲音頻率範圍，大約是多少？","A":"20 到 20000 Hz","B":"20000 到 40000 Hz","C":"0.1 到 10 Hz","D":"1 到 100 Hz","answer":"A","explanation":"人耳的可聽範圍大約是 20 Hz 到 20000 Hz。","image":""},{"id":"BT-259","isl":"B","lv":2,"stem":"比熱的定義是什麼？","A":"單位質量的物質，溫度升高 1 ℃ 所需的熱量","B":"單位時間內的溫度變化","C":"物質的溫度高低","D":"單位體積的物質所含的熱量","answer":"A","explanation":"比熱越大的物質，升溫越慢。","image":""},{"id":"BT-260","isl":"B","lv":2,"stem":"白天陽光照射下，沙灘與海水相比，哪一個升溫較快？","A":"海水會結冰","B":"沙灘","C":"兩者升溫速度相同","D":"海水","answer":"B","explanation":"沙子的比熱比水小，吸收相同熱量時升溫較快，因此形成海風。","image":""},{"id":"BT-261","isl":"B","lv":2,"stem":"質量 100 g 的水，溫度升高 10 ℃，需吸收多少熱量？（水比熱為 1 cal/g·℃）","A":"1000 cal","B":"10000 cal","C":"10 cal","D":"100 cal","answer":"A","explanation":"Q = mcΔT = 100 × 1 × 10 = 1000 cal。","image":""},{"id":"BT-262","isl":"B","lv":2,"stem":"質量相同的兩種物質，吸收相同熱量時，比熱較大的那一種溫度變化會如何？","A":"相同","B":"較小","C":"較大","D":"無法判斷","answer":"B","explanation":"比熱大的物質需要較多熱量才能升溫相同度數，故溫度變化較小。","image":""},{"id":"BT-263","isl":"J","lv":2,"stem":"下列哪一種水溶液能夠導電？","A":"氯化鈉水溶液","B":"蔗糖水溶液","C":"酒精水溶液","D":"蒸餾水","answer":"A","explanation":"氯化鈉溶於水會解離出可自由移動的離子。","image":""},{"id":"BT-264","isl":"J","lv":2,"stem":"硝酸銀溶液與氯化鈉溶液混合後，會產生什麼沉澱？","A":"氫氧化銀","B":"硫化銀","C":"硝酸鈉","D":"氯化銀","answer":"D","explanation":"Ag⁺ 與 Cl⁻ 結合形成難溶的白色氯化銀沉澱。","image":""},{"id":"BT-265","isl":"J","lv":2,"stem":"硫酸鋇是一種難溶物，它的沉澱顏色是什麼？","A":"黑色","B":"紅色","C":"白色","D":"藍色","answer":"C","explanation":"硫酸鋇為白色沉澱，常用於鋇離子的鑑定。","image":""},{"id":"BT-266","isl":"J","lv":2,"stem":"沉澱反應中，溶液中的離子結合後，形成的什麼物質會從溶液中析出？","A":"單質","B":"氣體","C":"難溶性的固體","D":"液態金屬","answer":"C","explanation":"沉澱是溶解度很小的固體，因此會從溶液中析出。","image":""},{"id":"BT-267","isl":"L","lv":2,"stem":"能量沿著食物鏈傳遞時，會有什麼變化？","A":"保持不變","B":"先增加後減少","C":"逐級增加","D":"逐級減少","answer":"D","explanation":"能量在每一階層會以呼吸作用等方式散失，因此逐級減少。","image":""},{"id":"BT-268","isl":"L","lv":2,"stem":"食物鏈的起點通常是哪一類生物？","A":"草食動物","B":"肉食動物","C":"能進行光合作用的生產者","D":"分解者","answer":"C","explanation":"生產者利用光能製造有機物，是食物鏈的起點。","image":""},{"id":"BT-269","isl":"L","lv":2,"stem":"能量塔中，能量最少的是哪一個階層？","A":"次級消費者","B":"最高級消費者","C":"生產者","D":"初級消費者","answer":"B","explanation":"能量金字塔越往上，能量越少。","image":""},{"id":"BT-270","isl":"L","lv":2,"stem":"生物放大現象是指什麼？","A":"生物數量沿食物鏈越來越多","B":"有毒物質沿食物鏈逐級累積，濃度越來越高","C":"有毒物質會逐級被分解","D":"能量沿食物鏈逐級增加","answer":"B","explanation":"有害物質不易被分解，會在較高階層的生物體內累積。","image":""},{"id":"BT-271","isl":"Q","lv":2,"stem":"電功率的定義是什麼？","A":"電壓除以電流","B":"單位面積上通過的電流","C":"電阻乘以時間","D":"單位時間內所消耗的電能","answer":"D","explanation":"電功率 = 電能 ÷ 時間。","image":""},{"id":"BT-272","isl":"Q","lv":2,"stem":"一個 100 W 的燈泡使用 2 小時，消耗的電能約為多少度？","A":"0.2 度","B":"200 度","C":"0.02 度","D":"2 度","answer":"A","explanation":"電能 = 0.1 kW × 2 h = 0.2 kW·h，即 0.2 度。","image":""},{"id":"BT-273","isl":"Q","lv":2,"stem":"電功率 P 與電壓 V、電流 I 之間的關係為何？","A":"P = VI","B":"P = I ÷ V","C":"P = V ÷ I","D":"P = V + I","answer":"A","explanation":"電功率等於電壓乘以電流。","image":""},{"id":"BT-274","isl":"Q","lv":2,"stem":"家中用電的電費通常以什麼單位計算？","A":"安培","B":"伏特","C":"瓦特","D":"度（千瓦時）","answer":"D","explanation":"1 度等於 1 千瓦時的電能。","image":""},{"id":"BT-275","isl":"E","lv":2,"stem":"液體內部的壓力，隨深度增加會如何變化？","A":"先增加後減少","B":"增加","C":"減少","D":"不變","answer":"B","explanation":"液體深度越深，上方液柱越重，壓力越大。","image":""},{"id":"BT-276","isl":"E","lv":2,"stem":"大氣壓力隨海拔升高會如何變化？","A":"不變","B":"減少","C":"增加","D":"先增加後減少","answer":"B","explanation":"海拔越高，上方空氣越少，大氣壓力越小。","image":""},{"id":"BT-277","isl":"E","lv":2,"stem":"壓力的定義是什麼？","A":"單位時間內所受的力","B":"單位體積所受的力","C":"物體的重量","D":"單位面積上所受的垂直作用力","answer":"D","explanation":"壓力 = 垂直作用力 ÷ 受力面積。","image":""},{"id":"BT-278","isl":"E","lv":2,"stem":"在靜止液體內部的同一深度，各個方向的壓力大小如何？","A":"相等","B":"向下最大","C":"向側面最小","D":"向上最大","answer":"A","explanation":"靜止液體在同一深度各方向的壓力相等。","image":""},{"id":"BT-279","isl":"F","lv":2,"stem":"大氣中含量最多的氣體是什麼？","A":"氧氣","B":"氮氣","C":"二氧化碳","D":"氬氣","answer":"B","explanation":"乾燥空氣中氮氣約占 78%，是含量最多的氣體。","image":""},{"id":"BT-280","isl":"F","lv":2,"stem":"與天氣變化關係最密切的大氣層是哪一層？","A":"逸散層","B":"中氣層","C":"平流層","D":"對流層","answer":"D","explanation":"雲、雨與風等天氣現象主要發生在對流層。","image":""},{"id":"BT-281","isl":"F","lv":2,"stem":"臭氧層主要位於大氣的哪一層？","A":"平流層","B":"中氣層","C":"逸散層","D":"對流層","answer":"A","explanation":"臭氧層位於平流層中，能吸收大部分紫外線。","image":""},{"id":"BT-282","isl":"F","lv":2,"stem":"對流層的溫度，一般隨高度升高會如何變化？","A":"降低","B":"先升後降","C":"不變","D":"升高","answer":"A","explanation":"對流層的氣溫隨高度增加而下降，因為空氣主要由地面受熱而來。","image":""},{"id":"BT-283","isl":"L","lv":2,"stem":"同一地區、同一種生物的所有個體總和，稱為什麼？","A":"群集","B":"生態系","C":"群落","D":"族群","answer":"D","explanation":"族群是同種生物的集合，群落則包含不同種的生物。","image":""},{"id":"BT-284","isl":"L","lv":2,"stem":"同一地區所有生物與非生物因素的總和，稱為什麼？","A":"族群","B":"生態系","C":"群集","D":"生物圈","answer":"B","explanation":"生態系包含生物群落與其所處的非生物環境。","image":""},{"id":"BT-285","isl":"L","lv":2,"stem":"在生態金字塔中，數量通常最多的是哪一類生物？","A":"次級消費者","B":"生產者","C":"初級消費者","D":"三級消費者","answer":"B","explanation":"能量與數量都是由下往上逐級減少，因此生產者最多。","image":""},{"id":"BT-286","isl":"L","lv":2,"stem":"族群密度的意義是什麼？","A":"個體的平均年齡","B":"族群的遷入數量","C":"族群的總重量","D":"單位面積或體積內的個體數量","answer":"D","explanation":"族群密度 = 個體數 ÷ 面積或體積。","image":""},{"id":"BT-287","isl":"D","lv":2,"stem":"人體中，將蛋白質分解產生的含氮廢物轉變為尿素的器官是哪一個？","A":"胰臟","B":"腎臟","C":"肝臟","D":"膀胱","answer":"C","explanation":"肝臟把氨轉變為尿素，再由血液送至腎臟排出。","image":""},{"id":"BT-288","isl":"D","lv":2,"stem":"尿液主要在人體的哪一個器官中生成？","A":"尿道","B":"輸尿管","C":"膀胱","D":"腎臟","answer":"D","explanation":"腎臟過濾血液並形成尿液，膀胱只負責儲存。","image":""},{"id":"BT-289","isl":"D","lv":2,"stem":"下列哪一項是腎臟的功能？","A":"分泌消化酶","B":"產生紅血球","C":"製造膽汁","D":"過濾血液，形成尿液","answer":"D","explanation":"腎臟的重要功能是過濾血液、排出廢物並調節水分與鹽分。","image":""},{"id":"BT-290","isl":"D","lv":2,"stem":"人體排出的汗液中，主要含有哪些物質？","A":"葡萄糖與蛋白質","B":"氧氣與二氧化碳","C":"水、無機鹽與尿素","D":"只有水分","answer":"C","explanation":"汗液可以排出少量尿素與無機鹽，並有調節體溫的作用。","image":""},{"id":"BT-291","isl":"K","lv":2,"stem":"波速、波長與頻率之間的關係為何？","A":"波速 = 波長 × 頻率","B":"波速 = 頻率 ÷ 波長","C":"波速 = 波長 ÷ 頻率","D":"波速 = 波長 + 頻率","answer":"A","explanation":"v = fλ 是波動的基本關係式。","image":""},{"id":"BT-292","isl":"K","lv":2,"stem":"頻率為 5 Hz 的波，其週期為多少秒？","A":"0.2 秒","B":"2 秒","C":"5 秒","D":"0.5 秒","answer":"A","explanation":"週期 = 1 ÷ 頻率 = 1 ÷ 5 = 0.2 秒。","image":""},{"id":"BT-293","isl":"K","lv":2,"stem":"波長為 2 m、頻率為 3 Hz 的波，其波速為多少？","A":"5 m/s","B":"1.5 m/s","C":"3 m/s","D":"6 m/s","answer":"D","explanation":"v = fλ = 3 × 2 = 6 m/s。","image":""},{"id":"BT-294","isl":"K","lv":2,"stem":"波的振幅越大，代表什麼意義？","A":"波長越長","B":"能量越大","C":"頻率越高","D":"波速越快","answer":"B","explanation":"振幅代表波攜帶能量的多寡，聲波振幅大時聲音較大。","image":""},{"id":"BT-295","isl":"B","lv":2,"stem":"下列哪一個反應屬於放熱反應？","A":"硝酸銨溶於水","B":"光合作用","C":"碳酸鈣受熱分解","D":"燃燒木柴","answer":"D","explanation":"燃燒會釋放大量熱能，屬於放熱反應。","image":""},{"id":"BT-296","isl":"B","lv":2,"stem":"下列哪一個過程會吸熱？","A":"燃燒酒精","B":"氫氧化鈉溶於水","C":"硝酸銨溶於水","D":"水蒸氣凝結成水","answer":"C","explanation":"硝酸銨溶解時會吸收周圍的熱，使溶液溫度下降。","image":""},{"id":"BT-297","isl":"B","lv":2,"stem":"吸熱反應中，反應物的總能量與生成物相比如何？","A":"較高","B":"無法比較","C":"相同","D":"較低","answer":"D","explanation":"吸熱反應需要吸收能量，生成物儲存的能量較高。","image":""},{"id":"BT-298","isl":"B","lv":2,"stem":"下列哪一個過程屬於放熱？","A":"冰塊融化","B":"乾冰昇華","C":"水蒸氣凝結成水","D":"水的汽化","answer":"C","explanation":"凝結是氣態變液態，會釋放熱量。","image":""},{"id":"BT-299","isl":"L","lv":2,"stem":"寄生者與寄主的關係，屬於哪一種交互作用？","A":"雙方都沒有影響","B":"雙方互相得利","C":"雙方互相搶奪同一資源","D":"一方受益，另一方受害","answer":"D","explanation":"寄生者從寄主獲取養分，對寄主造成傷害。","image":""},{"id":"BT-300","isl":"L","lv":2,"stem":"地衣中，真菌與藻類的關係屬於什麼？","A":"片利共生","B":"競爭","C":"互利共生","D":"寄生","answer":"C","explanation":"真菌提供保護與水分，藻類提供養分，雙方互相得利。","image":""},{"id":"BT-301","isl":"L","lv":2,"stem":"小丑魚與海葵之間的關係，通常屬於哪一種？","A":"互利共生","B":"寄生","C":"捕食","D":"競爭","answer":"A","explanation":"小丑魚受海葵保護，海葵也能從小丑魚獲得食物殘渣等好處。","image":""},{"id":"BT-302","isl":"L","lv":2,"stem":"兩種生物爭奪同一種有限的食物，屬於哪一種關係？","A":"競爭","B":"互利共生","C":"寄生","D":"捕食","answer":"A","explanation":"競爭是兩者爭奪相同資源，雙方都可能受到影響。","image":""},{"id":"BT-303","isl":"G","lv":2,"stem":"天擇的核心概念是什麼？","A":"適應環境的個體較容易生存並留下後代","B":"環境改變會使所有生物立即變化","C":"生物會主動改變自己來適應環境","D":"所有個體的生存機會完全相同","answer":"A","explanation":"環境會選擇較適應的個體，使有利性狀在族群中保留下來。","image":""},{"id":"BT-304","isl":"G","lv":2,"stem":"同一物種中，具有有利變異的個體，通常較容易做什麼？","A":"演化成其他物種","B":"生存並繁殖","C":"死亡","D":"遷離原地","answer":"B","explanation":"有利變異使個體較適應環境，因此能留下更多後代。","image":""},{"id":"BT-305","isl":"G","lv":2,"stem":"生物變異的主要來源是什麼？","A":"基因突變與基因重組","B":"後天環境的改變","C":"獲得性遺傳","D":"用進廢退","answer":"A","explanation":"基因突變與有性生殖中的基因重組，都會產生新的變異。","image":""},{"id":"BT-306","isl":"G","lv":2,"stem":"下列哪一位科學家提出了天擇演化的理論？","A":"拉馬克","B":"達爾文","C":"孟德爾","D":"巴斯德","answer":"B","explanation":"達爾文在《物種起源》中提出天擇學說。","image":""},{"id":"BT-307","isl":"D","lv":1,"stem":"人體中由內分泌腺分泌、經由血液運送到作用部位的化學物質，稱為什麼？","A":"神經傳導物質（僅在神經之間作用）","B":"酵素","C":"荷爾蒙","D":"抗體","answer":"C","explanation":"荷爾蒙由內分泌腺分泌，透過血液運送到標的器官發揮作用。","image":""},{"id":"BT-308","isl":"D","lv":1,"stem":"植物的向光性是因為生長素在莖的哪一側分布較多？","A":"莖頂端","B":"根部","C":"向光側","D":"背光側","answer":"D","explanation":"背光側生長素較多，細胞伸長較快，因而使莖向光彎曲。","image":""},{"id":"BT-309","isl":"K","lv":1,"stem":"光在同一均勻介質中，會沿著什麼方向前進？","A":"螺旋線","B":"隨機方向","C":"曲線","D":"直線","answer":"D","explanation":"光在均勻介質中沿直線傳播，因此形成影子。","image":""},{"id":"BT-310","isl":"K","lv":1,"stem":"光的反射定律中，入射角與反射角的關係為何？","A":"兩者相等","B":"入射角較大","C":"兩者互為餘角","D":"反射角較大","answer":"A","explanation":"入射角等於反射角，兩者都以法線為基準量測。","image":""},{"id":"BT-311","isl":"A","lv":1,"stem":"下列哪一種方法最適合用來分離食鹽水中的水與食鹽？","A":"蒸發","B":"過濾","C":"離心","D":"磁吸","answer":"A","explanation":"加熱使水蒸發，食鹽會留在容器中。","image":""},{"id":"BT-312","isl":"A","lv":1,"stem":"下列哪一項屬於純物質？","A":"空氣","B":"礦泉水","C":"海水","D":"蒸餾水","answer":"D","explanation":"蒸餾水只含一種成分，屬於純物質；其他皆為混合物。","image":""},{"id":"BT-313","isl":"E","lv":1,"stem":"物體在水平面上滑動時，摩擦力的方向與運動方向相比如何？","A":"相反","B":"不一定","C":"垂直","D":"相同","answer":"A","explanation":"動摩擦力總是阻礙物體相對滑動，方向與運動方向相反。","image":""},{"id":"BT-314","isl":"E","lv":1,"stem":"要增加摩擦力，下列哪一種做法最有效？","A":"把接觸面磨得更光滑","B":"增加接觸面的粗糙程度或壓力","C":"增加物體的速率","D":"減少接觸面的壓力","answer":"B","explanation":"摩擦力與壓力及粗糙程度有關。","image":""},{"id":"BT-315","isl":"J","lv":1,"stem":"實驗室中，用來檢驗氧氣的方法是什麼？","A":"加入澄清石灰水，溶液變白濁","B":"將燃燒的木條放入，火焰熄滅","C":"加入石蕊試紙，試紙變紅","D":"將帶有餘燼的木條放入，木條會復燃","answer":"D","explanation":"氧氣能助燃，使帶餘燼的木條復燃。","image":""},{"id":"BT-316","isl":"J","lv":1,"stem":"能使澄清石灰水變混濁的氣體是什麼？","A":"氮氣","B":"氫氣","C":"二氧化碳","D":"氧氣","answer":"C","explanation":"二氧化碳與氫氧化鈣反應生成碳酸鈣白色沉澱。","image":""},{"id":"BT-317","isl":"D","lv":1,"stem":"人體血糖濃度降低時，哪一種荷爾蒙會促進血糖上升？","A":"胰島素","B":"甲狀腺素","C":"腎上腺素（僅與體溫有關）","D":"升糖素","answer":"D","explanation":"血糖低時，胰島 α 細胞分泌升糖素，促進肝醣分解。","image":""},{"id":"BT-318","isl":"D","lv":1,"stem":"人在寒冷環境中，身體會透過什麼方式增加產熱？","A":"血管擴張","B":"減少呼吸","C":"顫抖與增加新陳代謝","D":"增加排汗","answer":"C","explanation":"肌肉顫抖與代謝增加能產生熱量，維持體溫。","image":""},{"id":"BT-319","isl":"D","lv":1,"stem":"植物透過葉片表面的氣孔，將水分以氣態散失的現象稱為什麼？","A":"蒸散作用","B":"呼吸作用","C":"光合作用","D":"滲透作用","answer":"A","explanation":"蒸散作用是水分從植物體以水蒸氣形式散失。","image":""},{"id":"BT-320","isl":"D","lv":1,"stem":"下列哪一項條件會使蒸散作用變快？","A":"溫度降低、濕度升高","B":"沒有風且空氣潮濕","C":"葉片表面覆蓋一層蠟質","D":"溫度升高、濕度降低、風速加大","answer":"D","explanation":"這些條件會使葉片內外的水氣濃度差變大，蒸散加快。","image":""},{"id":"BT-321","isl":"A","lv":1,"stem":"週期表中，同一直行（族）的元素，通常具有相似的什麼性質？","A":"顏色","B":"熔點的大小","C":"密度","D":"化學性質","answer":"D","explanation":"同族元素的價電子數相同，因此化學性質相似。","image":""},{"id":"BT-322","isl":"A","lv":1,"stem":"下列哪一種元素屬於金屬？","A":"鐵","B":"氮","C":"碳","D":"氧","answer":"A","explanation":"鐵是金屬元素，氧、氮、碳都是非金屬。","image":""},{"id":"BT-323","isl":"Q","lv":1,"stem":"用乾燥的絲綢摩擦玻璃棒後，玻璃棒會帶什麼電？","A":"正電","B":"負電","C":"同時帶正負電","D":"不帶電","answer":"A","explanation":"絲綢摩擦玻璃棒時，玻璃棒失去電子而帶正電。","image":""},{"id":"BT-324","isl":"Q","lv":1,"stem":"同種電荷之間的作用力是什麼？","A":"沒有作用力","B":"互相排斥","C":"互相吸引","D":"先吸引後排斥","answer":"B","explanation":"同性電荷相斥，異性電荷相吸。","image":""},{"id":"BT-325","isl":"D","lv":1,"stem":"人體中，主要負責吸收水分與無機鹽的器官是什麼？","A":"胃","B":"小腸","C":"食道","D":"大腸","answer":"D","explanation":"大腸主要吸收水分與無機鹽，小腸則是吸收養分的主要場所。","image":""},{"id":"BT-326","isl":"D","lv":1,"stem":"下列哪一種營養素是人體主要的能量來源？","A":"醣類","B":"水","C":"無機鹽","D":"維生素","answer":"A","explanation":"醣類是人體最主要的能量來源，每克約提供 4 大卡。","image":""},{"id":"BT-327","isl":"A","lv":1,"stem":"下列哪一個變化屬於化學變化？","A":"鐵釘生鏽","B":"冰塊融化","C":"水的沸騰","D":"玻璃被打碎","answer":"A","explanation":"生鏽會產生新的物質，屬於化學變化。","image":""},{"id":"BT-328","isl":"A","lv":1,"stem":"下列哪一項是物質的化學性質？","A":"顏色","B":"密度","C":"熔點","D":"可燃性","answer":"D","explanation":"化學性質是需要透過化學反應才能表現的性質，例如可燃性。","image":""},{"id":"BT-329","isl":"E","lv":1,"stem":"萬有引力的大小與兩物體的質量及什麼有關？","A":"距離的立方","B":"距離的一次方","C":"距離的平方","D":"距離的平方根","answer":"C","explanation":"萬有引力與兩物體距離的平方成反比。","image":""},{"id":"BT-330","isl":"E","lv":1,"stem":"物體做等速率圓周運動時，所受的合力方向是？","A":"指向圓心","B":"背離圓心","C":"與速度方向相同","D":"沿切線方向","answer":"A","explanation":"等速率圓周運動需要向心力，方向指向圓心。","image":""},{"id":"BT-331","isl":"D","lv":1,"stem":"物質分子從濃度高的地方移向濃度低的地方，稱為什麼？","A":"凝結","B":"擴散","C":"滲透","D":"蒸發","answer":"B","explanation":"擴散是粒子依濃度差自然移動的現象。","image":""},{"id":"BT-332","isl":"D","lv":1,"stem":"水分子通過半透膜，由水的濃度高處移向濃度低處，稱為什麼？","A":"蒸散","B":"凝固","C":"擴散","D":"滲透","answer":"D","explanation":"滲透是水分子透過半透膜移動的特殊擴散現象。","image":""},{"id":"BT-333","isl":"M","lv":1,"stem":"家中用電時，為了防止觸電，下列哪一項做法最正確？","A":"同一插座可以同時使用大量電器","B":"電線損壞時用膠帶包好就繼續使用","C":"用電器外殼要保持完好，濕手不接觸插頭","D":"插頭可以用濕布擦拭後直接插入","answer":"C","explanation":"水會導電，電器與電線要保持乾燥、完好才能安全使用。","image":""},{"id":"BT-334","isl":"M","lv":1,"stem":"家中電路中，保險絲或無熔絲開關的主要功能是什麼？","A":"降低電壓","B":"增加電流","C":"儲存電能","D":"電流過大時自動切斷電路，保護電器與人身安全","answer":"D","explanation":"當電流過大時，保險絲熔斷或開關跳脫，防止過熱起火。","image":""},{"id":"BT-335","isl":"K","lv":1,"stem":"紅光、綠光與藍光混合，可以得到什麼光？","A":"白光","B":"黑色","C":"紫光","D":"黃光","answer":"A","explanation":"紅、綠、藍是光的三原色，三者等量混合會形成白光。","image":""},{"id":"BT-336","isl":"K","lv":1,"stem":"一個紅色物體在白光照射下會呈現紅色，主要原因是什麼？","A":"它主要吸收紅光","B":"它會把白光變成紅色","C":"它本身會發出紅光","D":"它主要反射紅光","answer":"D","explanation":"不透明物體的顏色取決於它所反射的色光。","image":""},{"id":"BT-337","isl":"K","lv":1,"stem":"凸透鏡在物體位於焦點以外時，成像的性質為何？","A":"正立的虛像","B":"倒立的實像","C":"倒立的虛像","D":"正立的實像","answer":"B","explanation":"物距大於焦距時，凸透鏡形成倒立的實像。","image":""},{"id":"BT-338","isl":"K","lv":1,"stem":"放大鏡的原理是利用凸透鏡在什麼位置成像？","A":"焦點以外成正立放大的實像","B":"焦點上成像","C":"焦點以內成正立放大的虛像","D":"焦點以外成倒立縮小的實像","answer":"C","explanation":"物體在焦點以內時，凸透鏡形成正立放大的虛像。","image":""},{"id":"BT-339","isl":"B","lv":1,"stem":"熱從高溫物體直接傳給低溫物體，主要是透過哪一種傳熱方式？","A":"對流","B":"輻射","C":"傳導","D":"蒸發","answer":"C","explanation":"傳導靠物體內粒子的碰撞傳遞熱能，常發生在固體之間。","image":""},{"id":"BT-340","isl":"B","lv":1,"stem":"太陽的熱能到達地球，主要是透過哪一種傳熱方式？","A":"蒸發","B":"傳導","C":"對流","D":"輻射","answer":"D","explanation":"太陽與地球之間是真空，熱能靠輻射傳遞。","image":""},{"id":"BT-341","isl":"E","lv":1,"stem":"虎克定律說明彈簧的伸長量與什麼成正比？","A":"彈簧的重量","B":"所受外力的大小","C":"彈簧的顏色","D":"彈簧的長度","answer":"B","explanation":"在彈性限度內，彈簧的伸長量與所受拉力成正比。","image":""},{"id":"BT-342","isl":"E","lv":1,"stem":"彈簧的彈力常數越大，表示什麼？","A":"彈簧的長度越長","B":"彈簧的質量越小","C":"要使彈簧伸長相同長度，需要的力越大","D":"彈簧越容易伸長","answer":"C","explanation":"彈力常數越大，彈簧越硬，同樣的伸長需要較大的力。","image":""},{"id":"BT-343","isl":"D","lv":1,"stem":"吸氣時，肋間肌與橫膈膜的變化為何？","A":"肋間肌舒張，橫膈膜下降，胸腔縮小","B":"肋間肌收縮，橫膈膜下降，胸腔擴大","C":"肋間肌收縮，橫膈膜上升，胸腔縮小","D":"肋間肌舒張，橫膈膜上升，胸腔縮小","answer":"B","explanation":"吸氣時胸腔擴大，肺內氣壓降低，空氣被吸入。","image":""},{"id":"BT-344","isl":"D","lv":1,"stem":"呼吸運動中，肺內的氣壓在吸氣時會如何變化？","A":"低於外界大氣壓","B":"高於外界大氣壓","C":"先高後低","D":"等於外界大氣壓","answer":"A","explanation":"吸氣時胸腔擴大，肺內壓降低，低於外界氣壓，空氣因此流入。","image":""},{"id":"BT-345","isl":"I","lv":1,"stem":"判讀天氣圖時，若等壓線呈封閉的圈狀，且中心氣壓較低，表示什麼？","A":"低氣壓","B":"鋒面","C":"颱風眼","D":"高氣壓","answer":"A","explanation":"中心氣壓較低且四周高的封閉等壓線，表示低氣壓系統。","image":""},{"id":"BT-346","isl":"I","lv":1,"stem":"天氣圖上，風羽（風桿）上的短線越多，通常代表什麼？","A":"氣溫越高","B":"風向越偏北","C":"風速越大","D":"降雨量越大","answer":"C","explanation":"風羽的每一短線約代表固定的風速增量，短線越多風速越大。","image":""},{"id":"BT-347","isl":"J","lv":1,"stem":"可逆反應達到化學平衡時，下列哪一項正確？","A":"生成物的量一定為零","B":"反應完全停止","C":"正反應與逆反應速率相等","D":"反應物已全部消失","answer":"C","explanation":"化學平衡是動態平衡，正逆反應速率相同，各物質濃度維持不變。","image":""},{"id":"BT-348","isl":"J","lv":1,"stem":"在一個封閉容器中的可逆反應達到平衡後，若增加反應物的量，平衡會如何移動？","A":"反應立即停止","B":"向反應物的方向移動","C":"不會移動","D":"向生成物的方向移動","answer":"D","explanation":"依勒沙特列原理，增加反應物會使平衡向生成物方向移動。","image":""},{"id":"BT-349","isl":"M","lv":1,"stem":"實驗室中，看到標示有火焰圖案的藥品標籤，代表該藥品具有什麼危險性？","A":"毒性","B":"易燃性","C":"放射性","D":"腐蝕性","answer":"B","explanation":"火焰圖示代表易燃，腐蝕性、放射性與毒性各有其對應圖示。","image":""},{"id":"BT-350","isl":"M","lv":1,"stem":"實驗中若不慎讓酸液濺到皮膚，應該立即做什麼？","A":"塗抹乾布後等待","B":"用其他化學藥品中和","C":"用力擦拭皮膚","D":"用大量清水沖洗，並告知老師","answer":"D","explanation":"大量清水沖洗可以稀釋並移除化學藥品，同時應立即告知老師。","image":""}];
var ISLANDS = {"A": "物質的組成與特性", "B": "能量的形式、轉換及流動", "C": "結構與功能", "D": "生物體的構造與功能", "E": "物質系統", "F": "地球環境", "G": "演化與延續", "H": "地球的歷史", "I": "變動的地球", "J": "物質的反應、平衡及製造", "K": "波動、聲音與光", "L": "生物與環境", "M": "科學、科技、社會及人文", "N": "資源與永續發展", "Q": "電與磁的交互作用"};
